# ---------------------------------------------------------------------------
# GPU detection WITHOUT initializing CUDA context.
# vLLM v0.16+ uses multiprocessing; if CUDA is initialized in the main
# process it falls back to `spawn` (instead of `fork`), roughly doubling
# the system-RAM required and often triggering the OOM killer on 7B+ models.
# We therefore probe the GPU via nvidia-smi or CUDA_VISIBLE_DEVICES first.
# ---------------------------------------------------------------------------
CUDA_AVAILABLE = False
GPU_NAME = "N/A"
GPU_COUNT = 0

def _detect_gpu_without_cuda_init():
    """Detect GPU info without calling torch.cuda (avoids CUDA context init)."""
    global CUDA_AVAILABLE, GPU_NAME, GPU_COUNT
    import subprocess, os
    # Method 1: nvidia-smi
    try:
        out = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=name,memory.total",
             "--format=csv,noheader,nounits"],
            timeout=5, stderr=subprocess.DEVNULL
        ).decode().strip()
        lines = [l.strip() for l in out.split("\n") if l.strip()]
        if lines:
            CUDA_AVAILABLE = True
            GPU_COUNT = len(lines)
            GPU_NAME = lines[0].split(",")[0].strip()
            return
    except Exception:
        pass
    # Method 2: check CUDA_VISIBLE_DEVICES
    vis = os.environ.get("CUDA_VISIBLE_DEVICES", "")
    if vis and vis != "-1":
        CUDA_AVAILABLE = True
        GPU_NAME = "GPU (nvidia-smi unavailable)"
        GPU_COUNT = len(vis.split(","))

_detect_gpu_without_cuda_init()


def _parse_visible_gpu_ids(visible_devices: Optional[str], tp: int) -> List[int]:
    if visible_devices:
        parsed: List[int] = []
        for item in visible_devices.split(","):
            item = item.strip()
            if not item or item == "-1":
                continue
            try:
                parsed.append(int(item))
            except ValueError:
                continue
        if parsed:
            return parsed[: max(1, int(tp))]
    return list(range(max(0, min(int(tp), GPU_COUNT))))


def _query_gpu_memory_without_cuda_init(
    visible_devices: Optional[str],
    tp: int,
) -> Dict[int, Tuple[int, int]]:
    gpu_ids = _parse_visible_gpu_ids(visible_devices, tp)
    if not gpu_ids:
        return {}
    try:
        out = subprocess.check_output(
            [
                "nvidia-smi",
                "--query-gpu=index,memory.total,memory.free",
                "--format=csv,noheader,nounits",
            ],
            timeout=5,
            stderr=subprocess.DEVNULL,
        ).decode().strip()
    except Exception:
        return {}

    stats: Dict[int, Tuple[int, int]] = {}
    for line in out.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = [part.strip() for part in line.split(",")]
        if len(parts) != 3:
            continue
        try:
            gpu_id = int(parts[0])
            total_mb = int(parts[1])
            free_mb = int(parts[2])
        except ValueError:
            continue
        if gpu_id in gpu_ids:
            stats[gpu_id] = (total_mb, free_mb)
    return stats


def _visible_gpu_min_free_ratio(
    visible_devices: Optional[str],
    tp: int,
) -> Optional[float]:
    stats = _query_gpu_memory_without_cuda_init(visible_devices, tp)
    if not stats:
        return None
    ratios = [free_mb / total_mb for total_mb, free_mb in stats.values() if total_mb > 0]
    if not ratios:
        return None
    return min(ratios)


def _select_adaptive_retry_gpu_util(
    requested_gpu_util: float,
    observed_free_ratio: Optional[float],
) -> float:
    requested = float(requested_gpu_util)
    if observed_free_ratio is None or observed_free_ratio <= 0:
        return requested
    adjusted = min(requested, max(0.50, observed_free_ratio - 0.01))
    return round(adjusted, 2)


def _is_fatal_engine_error_message(message: Any) -> bool:
    """Return whether an engine/runtime error means the runtime is no longer healthy."""
    text = str(message or "").lower()
    fatal_markers = (
        "cuda out of memory",
        "outofmemoryerror",
        "background loop has errored already",
        "enginedeaderror",
        "enginecore encountered",
        "illegal memory access",
        "subprocess_engine_dead",
        "subprocess_engine_empty_response",
        "worker proc",
        "worker died",
        "cuda error",
        "shutting down",
    )
    return any(marker in text for marker in fatal_markers)


def _parse_gpu_memory_mib(text: Any) -> int:
    match = re.search(r"(\d+)", str(text or ""))
    return int(match.group(1)) if match else 0


def _current_process_family_pids(root_pid: Optional[int] = None) -> set[int]:
    root_pid = int(root_pid or os.getpid())
    allowed = {root_pid}
    try:
        import psutil

        root = psutil.Process(root_pid)
        for child in root.children(recursive=True):
            allowed.add(int(child.pid))
    except Exception:
        pass
    return allowed


def _foreign_gpu_consumers_from_rows(
    device_ids: List[int],
    *,
    gpu_uuid_rows: List[str],
    compute_app_rows: List[str],
    allowed_pids: set[int],
    min_used_mib: int = 256,
) -> List[Dict[str, Any]]:
    uuid_to_index: Dict[str, int] = {}
    for row in gpu_uuid_rows:
        parts = [part.strip() for part in str(row or "").split(",")]
        if len(parts) < 2:
            continue
        try:
            gpu_index = int(parts[0])
        except Exception:
            continue
        uuid_to_index[parts[1]] = gpu_index

    device_set = {int(idx) for idx in device_ids}
    offenders: List[Dict[str, Any]] = []
    for row in compute_app_rows:
        parts = [part.strip() for part in str(row or "").split(",")]
        if len(parts) < 4:
            continue
        gpu_uuid = parts[0]
        try:
            pid = int(parts[1])
        except Exception:
            continue
        gpu_index = uuid_to_index.get(gpu_uuid)
        if gpu_index is None or gpu_index not in device_set:
            continue
        if pid in allowed_pids:
            continue
        used_mib = _parse_gpu_memory_mib(parts[3])
        if used_mib < int(min_used_mib):
            continue
        offenders.append(
            {
                "gpu_index": gpu_index,
                "pid": pid,
                "process_name": parts[2],
                "used_mib": used_mib,
            }
        )
    return sorted(offenders, key=lambda item: (item["gpu_index"], item["pid"]))


def _detect_foreign_gpu_consumers(
    device_ids: List[int],
    *,
    root_pid: Optional[int] = None,
    min_used_mib: int = 256,
) -> List[Dict[str, Any]]:
    device_ids = [int(idx) for idx in (device_ids or [])]
    if not device_ids:
        return []
    try:
        gpu_uuid_rows = subprocess.check_output(
            [
                "nvidia-smi",
                "--query-gpu=index,uuid",
                "--format=csv,noheader",
            ],
            text=True,
            stderr=subprocess.DEVNULL,
        ).splitlines()
        compute_app_rows = subprocess.check_output(
            [
                "nvidia-smi",
                "--query-compute-apps=gpu_uuid,pid,process_name,used_gpu_memory",
                "--format=csv,noheader",
            ],
            text=True,
            stderr=subprocess.DEVNULL,
        ).splitlines()
    except Exception:
        return []

    allowed_pids = _current_process_family_pids(root_pid=root_pid)
    return _foreign_gpu_consumers_from_rows(
        device_ids,
        gpu_uuid_rows=gpu_uuid_rows,
        compute_app_rows=compute_app_rows,
        allowed_pids=allowed_pids,
        min_used_mib=min_used_mib,
    )


def _assert_clean_gpu_environment(
    device_ids: List[int],
    *,
    context: str,
    root_pid: Optional[int] = None,
    min_used_mib: int = 256,
) -> None:
    offenders = _detect_foreign_gpu_consumers(
        device_ids,
        root_pid=root_pid,
        min_used_mib=min_used_mib,
    )
    if not offenders:
        return
    detail = ", ".join(
        f"gpu{item['gpu_index']} pid={item['pid']} {item['process_name']} {item['used_mib']}MiB"
        for item in offenders
    )
    raise RuntimeError(f"foreign_gpu_consumer_detected[{context}]: {detail}")


def _check_shm_for_vllm():
    """Warn if /dev/shm is small; EngineCore IPC needs sufficient shared memory (community fix)."""
    try:
        stat = os.statvfs("/dev/shm")
        free_mb = (stat.f_bavail * stat.f_frsize) / (1024 * 1024)
        if free_mb < 400:
            print(
                f"  [WARN] /dev/shm free={free_mb:.0f}MB may be too small for vLLM EngineCore IPC. "
                "Increase to >=512MB (e.g. docker run --shm-size=1g, or mount -o remount,size=1G /dev/shm)."
            )
    except Exception:
        pass


SamplingParams = None
AsyncLLMEngine = None
AsyncEngineArgs = None
LoRARequest = None
VLLM_AVAILABLE = False


def _lazy_import_vllm() -> bool:
    """Import vLLM only when backend=vllm to avoid startup crashes."""
    global SamplingParams, AsyncLLMEngine, AsyncEngineArgs, LoRARequest, VLLM_AVAILABLE
    if VLLM_AVAILABLE:
        return True
    try:
        from vllm import SamplingParams as _SamplingParams
        from vllm.engine.async_llm_engine import AsyncLLMEngine as _AsyncLLMEngine
        from vllm.engine.arg_utils import AsyncEngineArgs as _AsyncEngineArgs
        from vllm.lora.request import LoRARequest as _LoRARequest
        SamplingParams = _SamplingParams
        AsyncLLMEngine = _AsyncLLMEngine
        AsyncEngineArgs = _AsyncEngineArgs
        LoRARequest = _LoRARequest
        VLLM_AVAILABLE = True
        return True
    except Exception:
        VLLM_AVAILABLE = False
        return False


def _is_mistral_nemo_model(model_name: Optional[str]) -> bool:
    normalized = str(model_name or "").lower()
    return "mistral-nemo" in normalized or "mistral_nemo" in normalized


def _resolve_vllm_enforce_eager(model_cfg: Dict[str, Any]) -> bool:
    """Resolve eager/graph mode with an explicit-safe adaptive default.

    ``enforce_eager`` may be a boolean or ``auto``. Explicit booleans always
    win. In auto mode, keep conservative eager execution for known-risk TP or
    Mistral-Nemo paths, and allow CUDA graph on the single-GPU scale-out path
    where graphprobe showed the decode path is substantially faster.
    """
    raw = model_cfg.get("enforce_eager", True)
    if isinstance(raw, bool):
        return raw
    if isinstance(raw, str):
        normalized = raw.strip().lower()
        if normalized in {"1", "true", "yes", "on"}:
            return True
        if normalized in {"0", "false", "no", "off"}:
            return False
        if normalized != "auto":
            raise ValueError(
                "model.enforce_eager must be boolean or 'auto', "
                f"got {raw!r}"
            )
    else:
        raise ValueError(
            "model.enforce_eager must be boolean or 'auto', "
            f"got {type(raw).__name__}"
        )

    model_name = str(model_cfg.get("name", ""))
    tp = int(model_cfg.get("tensor_parallel_size", 1) or 1)
    if tp > 1 or _is_mistral_nemo_model(model_name):
        return True
    return False


def _resolve_vllm_runtime_guards(model_cfg: Dict[str, Any]) -> Dict[str, Any]:
    model_name = str(model_cfg.get("name", ""))
    tokenizer_mode = model_cfg.get("tokenizer_mode")
    enable_chunked_prefill = model_cfg.get("enable_chunked_prefill")
    enable_prefix_caching = model_cfg.get("enable_prefix_caching")
    env_updates: Dict[str, str] = {}

    def _set_env_if_present(cfg_key: str, env_key: str, formatter=str) -> None:
        if cfg_key in model_cfg and model_cfg.get(cfg_key) is not None:
            env_updates[env_key] = formatter(model_cfg[cfg_key])

    _set_env_if_present(
        "vllm_use_v1",
        "VLLM_USE_V1",
        lambda value: "1" if bool(value) else "0",
    )
    _set_env_if_present("vllm_attention_backend", "VLLM_ATTENTION_BACKEND", str)
    _set_env_if_present(
        "vllm_use_flashinfer_sampler",
        "VLLM_USE_FLASHINFER_SAMPLER",
        lambda value: "1" if bool(value) else "0",
    )
    env_updates.setdefault("VLLM_NO_USAGE_STATS", "1")

    # Mistral-Nemo is the only family that repeatedly triggered runtime
    # EngineCore crashes on this host under the default V1 + TP2 + LoRA path.
    # Apply a conservative runtime envelope unless the profile explicitly
    # overrides these knobs.
    if _is_mistral_nemo_model(model_name):
        if tokenizer_mode is None:
            tokenizer_mode = "mistral"
        if enable_chunked_prefill is None:
            enable_chunked_prefill = False
        if enable_prefix_caching is None:
            enable_prefix_caching = False
        env_updates.setdefault("VLLM_USE_V1", "0")
        env_updates.setdefault("VLLM_ATTENTION_BACKEND", "FLASH_ATTN")
        env_updates.setdefault("VLLM_USE_FLASHINFER_SAMPLER", "0")

    return {
        "tokenizer_mode": tokenizer_mode,
        "enable_chunked_prefill": enable_chunked_prefill,
        "enable_prefix_caching": enable_prefix_caching,
        "env_updates": env_updates,
    }


def _push_env_updates(updates: Dict[str, str]) -> Dict[str, Optional[str]]:
    previous: Dict[str, Optional[str]] = {}
    for key, value in updates.items():
        previous[key] = os.environ.get(key)
        os.environ[key] = value
    return previous


def _restore_env_updates(previous: Dict[str, Optional[str]]) -> None:
    for key, value in previous.items():
        if value is None:
            os.environ.pop(key, None)
        else:
            os.environ[key] = value


def _scaleup_affected_request_indices(
    total_requests: int,
    scale_up_events: Optional[List[Dict[str, Any]]],
    window_size: int = 50,
) -> set[int]:
    """Legacy fallback for older results that only recorded scale-up windows."""
    affected: set[int] = set()
    if total_requests <= 0:
        return affected
    def event_request_index(event: Dict[str, Any]) -> int:
        return int(
            event.get(
                "queue_visible_request_count",
                event.get(
                    "arrived_request_count",
                    event.get("submitted_request_count", event.get("request_index", 0)),
                ),
            )
            or 0
        )

    events = sorted(scale_up_events or [], key=event_request_index)
    for idx, event in enumerate(events):
        request_index = event_request_index(event)
        if request_index >= total_requests:
            continue
        next_request_index = (
            event_request_index(events[idx + 1])
            if idx + 1 < len(events)
            else total_requests
        )
        window_end = min(request_index + max(1, int(window_size)), next_request_index, total_requests)
        affected.update(range(request_index, window_end))
    return affected


_LOCAL_COMPARABLE_TIERS = {"gpu", "host", "nvme"}
_BACKBONE_CACHE_TIER = "backbone"


def _has_lora_request(request: Any) -> bool:
    return bool(getattr(request, "adapter_id", None))


def _is_comparable_request(
    request: Any,
    request_index: Optional[int] = None,
    scaleup_affected_indices: Optional[set[int]] = None,
) -> bool:
    """
    Paper-facing comparable TTFT subset.

    Comparable requests should preserve local-tier differences (GPU/HOST/NVMe)
    on LoRA-bearing requests, so the benefit of keeping hot artifacts resident
    is still visible, while excluding the post-scale-up cold window, adapter-
    free backbone traffic, and remote cold fetches.
    """
    if not getattr(request, "success", False):
        return False
    if not _has_lora_request(request):
        return False
    tagged_scaleup = getattr(request, "scaleup_affected", None)
    if tagged_scaleup is None and request_index is not None:
        tagged_scaleup = request_index in (scaleup_affected_indices or set())
    if bool(tagged_scaleup):
        return False
    return str(getattr(request, "cache_tier", "remote") or "remote").lower() in _LOCAL_COMPARABLE_TIERS


def _is_warm_standard_request(
    request: Any,
    request_index: Optional[int] = None,
    scaleup_affected_indices: Optional[set[int]] = None,
) -> bool:
    """
    Standard warm-path TTFT subset for cross-paper dialogue.

    This keeps only successful LoRA-bearing requests that are already GPU-ready
    and not in the post-scale-up cold window. It is still trace-driven, so it
    is not a substitute for a separate fixed-prompt microbenchmark, but it is
    the cleanest paper-facing warm-path TTFT we can derive from current online
    observables without introducing new instrumentation or hidden heuristics.
    """
    if not _is_comparable_request(
        request,
        request_index=request_index,
        scaleup_affected_indices=scaleup_affected_indices,
    ):
        return False
    return str(getattr(request, "cache_tier", "remote") or "remote").lower() == "gpu"

