class AggregateBandwidthLimiter:
    """Process-local aggregate transfer limiter used by frozen local-sim runs.

    Each transfer reserves a contiguous interval on one shared virtual link.  A
    concurrent group therefore consumes ``sum(bytes) / rate`` wall time rather
    than receiving the configured rate independently per request.  A zero rate
    intentionally means no injected delay (the optimistic local upper bound).
    """

    def __init__(self, rate_mib_s: float):
        self.rate_mib_s = max(0.0, float(rate_mib_s or 0.0))
        self._lock = asyncio.Lock()
        self._next_available_at = 0.0
        self._first_reservation_at: Optional[float] = None
        self._last_reservation_at: Optional[float] = None
        self.transfer_count = 0
        self.total_bytes = 0
        self.total_injected_wait_s = 0.0

    async def throttle(self, size_bytes: int) -> float:
        size_bytes = max(0, int(size_bytes or 0))
        if size_bytes <= 0:
            return 0.0
        if self.rate_mib_s <= 0.0:
            # ``no-delay`` means that the application-layer delay injection is
            # disabled, not that no remote transfer took place.  Preserve byte
            # and transfer accounting so the optimistic upper-bound point stays
            # auditable and cannot be confused with an all-cache-hit run.
            async with self._lock:
                now = time.perf_counter()
                if self._first_reservation_at is None:
                    self._first_reservation_at = now
                self._last_reservation_at = now
                self.transfer_count += 1
                self.total_bytes += size_bytes
            return 0.0
        duration_s = (size_bytes / float(1024 ** 2)) / self.rate_mib_s
        async with self._lock:
            now = time.perf_counter()
            start_at = max(now, self._next_available_at)
            finish_at = start_at + duration_s
            self._next_available_at = finish_at
            if self._first_reservation_at is None:
                self._first_reservation_at = start_at
            self._last_reservation_at = finish_at
            self.transfer_count += 1
            self.total_bytes += size_bytes
            wait_s = max(0.0, finish_at - now)
            self.total_injected_wait_s += wait_s
        if wait_s > 0.001:
            await asyncio.sleep(wait_s)
        return wait_s * 1000.0

    def snapshot(self) -> Dict[str, Any]:
        span_s = 0.0
        if self._first_reservation_at is not None and self._last_reservation_at is not None:
            span_s = max(0.0, self._last_reservation_at - self._first_reservation_at)
        achieved_mib_s = (
            (self.total_bytes / float(1024 ** 2)) / span_s if span_s > 0.0 else 0.0
        )
        return {
            "limit_mode": (
                "aggregate_application_layer_local_sim"
                if self.rate_mib_s > 0.0
                else "local_sim_no_delay"
            ),
            "configured_mib_s": self.rate_mib_s,
            "configured_gbit_s": self.rate_mib_s * (1024.0 ** 2) * 8.0 / 1e9,
            "transfer_count": self.transfer_count,
            "total_bytes": self.total_bytes,
            "reservation_span_s": span_s,
            "total_injected_wait_s": self.total_injected_wait_s,
            "achieved_reserved_mib_s": achieved_mib_s,
        }


def _positive_or_fallback(primary: Any, fallback: Any = 0.0) -> float:
    try:
        value = float(primary)
        if value > 0.0:
            return value
    except Exception:
        pass
    try:
        return float(fallback)
    except Exception:
        return 0.0


def _safe_float(value: Any, fallback: float = 0.0) -> float:
    try:
        parsed = float(value)
    except Exception:
        return float(fallback)
    if not math.isfinite(parsed):
        return float(fallback)
    return parsed


def _sha256_file(path_like: Any) -> Optional[str]:
    if path_like in (None, ""):
        return None
    path = Path(str(path_like)).expanduser()
    if not path.is_absolute():
        path = REPO_ROOT / path
    if not path.exists() or not path.is_file():
        return None
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _generation_contract_request_map_sha256(result: "ScenarioResult") -> str:
    rows = [
        {
            "request_id": request.request_id,
            "adapter_id": request.adapter_id,
            "arrival_time_s": getattr(request, "scheduled_arrival_offset_s", None),
            "source_expected_output_tokens": int(
                getattr(request, "source_expected_output_tokens", 0) or 0
            ),
            "requested_completion_tokens": int(
                getattr(request, "requested_completion_tokens", 0) or 0
            ),
            "canonical_prompt_sha256": str(
                getattr(request, "canonical_prompt_sha256", "") or ""
            ),
            "canonical_prompt_tokens": int(
                getattr(request, "canonical_prompt_tokens", 0) or 0
            ),
        }
        for request in result.requests
    ]
    return hashlib.sha256(
        json.dumps(
            rows,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _attach_parent_rpc_breakdown(
    timing: Optional[Dict[str, Any]],
    *,
    channel_acquire_ms: float = 0.0,
    parent_response_read_wall_time: Optional[float] = None,
) -> Dict[str, Any]:
    """Normalize parent/worker RPC timing into comparable sub-phases.

    ``parent_rpc_overhead_ms`` is a useful headline residual, but it mixes:
    1. waiting for a free parent-side RPC channel,
    2. any delay between the worker being ready to respond and the parent event
       loop actually reading that response,
    3. smaller loopback transport / serialization overheads.

    Keeping these as separate diagnostics lets us decide whether the next fix
    should target slot/channel budgeting, parent event-loop starvation, or the
    RPC transport itself.
    """
    # Timing payloads are predominantly numeric, but they also carry audit
    # metadata such as the native completion-token digest and terminal flag.
    # Preserve strings and Booleans across the worker JSON/RPC boundary;
    # numeric consumers below already use
    # ``_safe_float`` defensively.
    normalized = {
        key: value if value is None or isinstance(value, (str, bool)) else _safe_float(value, 0.0)
        for key, value in dict(timing or {}).items()
        if isinstance(key, str)
    }
    normalized["parent_rpc_channel_acquire_ms"] = max(0.0, _safe_float(channel_acquire_ms, 0.0))
    worker_ready_wall_time = _safe_float(
        normalized.get("worker_response_ready_wall_time"),
        0.0,
    )
    if parent_response_read_wall_time is not None and worker_ready_wall_time > 0.0:
        normalized["parent_rpc_response_pickup_delay_ms"] = max(
            0.0,
            (float(parent_response_read_wall_time) - float(worker_ready_wall_time)) * 1000.0,
        )
    else:
        normalized["parent_rpc_response_pickup_delay_ms"] = max(
            0.0,
            _safe_float(normalized.get("parent_rpc_response_pickup_delay_ms"), 0.0),
        )
    return normalized


def _effective_runtime_concurrency_cap(model_cfg: Optional[Dict[str, Any]]) -> int:
    """Return the system-level runtime admission cap that the backend can honor.

    ``runtime_concurrency_cap`` is the capacity seen by the router, dispatcher,
    and subprocess RPC pool. For vLLM/SGLang it must never exceed ``max_num_seqs``:
    otherwise the system admits more online requests than the engine can
    schedule, hiding queueing inside vLLM/RPC and making TTFT attribution
    misleading.
    """
    cfg = model_cfg or {}
    raw_cap = cfg.get("runtime_concurrency_cap", cfg.get("max_num_seqs", 1))
    try:
        cap = max(1, int(raw_cap or 1))
    except Exception:
        cap = 1

    backend = str(cfg.get("backend", "vllm") or "vllm").lower()
    if backend in {"vllm", "sglang"}:
        try:
            max_num_seqs = int(cfg.get("max_num_seqs", cap) or cap)
        except Exception:
            max_num_seqs = cap
        cap = min(cap, max(1, max_num_seqs))
    return max(1, cap)


def _normalize_runtime_concurrency_cap(model_cfg: Dict[str, Any]) -> Dict[str, Any]:
    """Clamp the configured runtime cap to the backend's true scheduling cap."""
    cfg = copy.deepcopy(model_cfg or {})
    requested = cfg.get("requested_runtime_concurrency_cap",
                        cfg.get("runtime_concurrency_cap", cfg.get("max_num_seqs", 1)))
    effective = _effective_runtime_concurrency_cap(cfg)
    cfg["requested_runtime_concurrency_cap"] = requested
    cfg["runtime_concurrency_cap"] = effective
    try:
        requested_int = int(requested or 1)
    except Exception:
        requested_int = effective
    if requested_int != effective:
        max_num_seqs = cfg.get("max_num_seqs")
        print(
            "  [capacity] clamped runtime_concurrency_cap "
            f"from {requested_int} to {effective} "
            f"(backend={cfg.get('backend', 'vllm')}, max_num_seqs={max_num_seqs})",
            flush=True,
        )
    return cfg


def _prepare_scenario_runtime_model_config(model_cfg, workload_cfg, coord_cfg):
    """The shared main/profile boundary for generation and runtime capacity.

    Keep the existing scenario override precedence. Re-applying normalization
    preserves the original requested cap; an explicit scenario cap starts a new
    request. No model initialization, input generation or parameter search.
    """
    configured = copy.deepcopy(model_cfg)
    generation = str(workload_cfg.get('generation_contract', 'legacy') or 'legacy').strip().lower()
    configured['generation_contract'] = generation
    if generation == 'fixed_length_greedy_v1':
        configured['max_input_len'] = max(1, int(workload_cfg.get('fixed_prompt_max_tokens', 759) or 759))
        configured['max_output_tokens_cap'] = max(1, int(workload_cfg.get('fixed_output_max_tokens', 256) or 256))
    overrides = copy.deepcopy(coord_cfg.get('instance_model_overrides', {}))
    if 'runtime_concurrency_cap' in overrides:
        configured.pop('requested_runtime_concurrency_cap', None)
    configured.update(overrides)
    return _normalize_runtime_concurrency_cap(configured)


