@dataclass
class RuntimeRequestReservation:
    """Controller ownership from successful reserve, not just model invocation.

    Adapter/source resolution may change its local variables or raise before
    inference begins. Release still belongs to the original reservation.
    Native references, when enabled, are recorded separately from controller
    slots. An interrupted RPC is not evidence that its native work was undone.
    This object does not claim KV allocation or successful abort.
    """
    request_id: str
    slot: Optional[Any] = None
    adapter_id: Optional[str] = None
    adapter_reserved: bool = False
    inflight_key: Optional[str] = None
    bound: bool = False
    generation_started: bool = False
    native_terminal_observed: bool = False
    released: bool = False
    batch_coordinator: Optional[Any] = None
    batch_input_tokens: int = 0
    batch_output_tokens: int = 0
    batch_started: bool = False
    gpu_reference_engine: Optional[Any] = None
    gpu_reference_evidence: Dict[str, Any] = field(default_factory=dict)
    local_source_owner: Optional[Any] = None
    ieee_routing_evidence: Optional[Dict[str, Any]] = None
    ieee_load_pending: bool = False
    ieee_pending_admission: Optional[Dict[str, Any]] = None
    ieee_observation: Optional[Any] = None
    ieee_native_observer: Optional[Any] = None
    ieee_routing_attempts: List[Dict[str, Any]] = field(default_factory=list)

    def bind(self, slot, adapter_id, adapter_reserved: bool) -> None:
        if self.bound:
            raise RuntimeError('request reservation cannot be rebound')
        self.slot, self.adapter_id = slot, adapter_id
        self.adapter_reserved = adapter_reserved
        self.bound = True

    def retry_known_conflict(self) -> None:
        if not self.released or self.generation_started or self.ieee_observation is not None:
            raise RuntimeError('only fully released pre-admission conflicts may retry selection')
        attempts = self.ieee_routing_attempts
        self.__dict__.update(RuntimeRequestReservation(self.request_id).__dict__)
        self.ieee_routing_attempts = attempts


DEFAULT_TTFT_SLO_MS = 5000.0


def _derive_request_generation_seed(
    base_seed: Optional[int],
    request_id: Optional[str],
) -> Optional[int]:
    """Derive a stable per-request sampling seed from the shared trace id.

    A single global seed makes repeated runs deterministic, while the
    per-request offset keeps different prompts from all sharing an identical
    RNG stream. The shared trace ids are stable across FaaSLoRA and baselines
    (for example req_00042), so this remains cross-system comparable.
    """
    if base_seed is None:
        return None
    try:
        seed = int(base_seed)
    except (TypeError, ValueError):
        return None
    rid = str(request_id or "").strip()
    offset: int
    match = re.search(r"(\d+)$", rid)
    if match:
        offset = int(match.group(1))
    else:
        import hashlib

        digest = hashlib.sha1(rid.encode("utf-8")).hexdigest()
        offset = int(digest[:8], 16)
    return int((seed + offset) % (2**32))


def _assert_official_workload_sources_available(
    *,
    arrival_source: str,
    token_source: str,
    prompt_source: str,
    has_azure: bool,
    has_sgpt: bool,
) -> None:
    missing_sources: List[str] = []
    if str(arrival_source).strip().lower() == "azure_llm" and not has_azure:
        missing_sources.append("arrival_source=azure_llm")
    if str(token_source).strip().lower() == "azure_llm" and not has_azure:
        missing_sources.append("token_source=azure_llm")
    if missing_sources:
        requested = ", ".join(missing_sources)
        raise RuntimeError(
            "Official Azure-trace workload source requested but real Azure LLM trace data "
            f"is unavailable ({requested}). Refusing to fall back to synthetic_poisson or "
            "fixed-default token lengths. For formal experiments, restore "
            "data/azure_llm/*.csv and keep datasets.arrival_source=azure_llm plus "
            "datasets.token_source=azure_llm."
        )

    if str(prompt_source).strip().lower() == "sharegpt_auto" and not has_sgpt:
        raise RuntimeError(
            "Official ShareGPT prompt source requested but real ShareGPT data is unavailable "
            "(prompt_source=sharegpt_auto). Refusing to fall back to embedded prompts. "
            "For formal experiments, restore data/sharegpt/sharegpt_cache.json or ensure "
            "ShareGPT download is available, and keep datasets.prompt_source=sharegpt_auto."
        )


def _classify_workload_timing_mode(
    *,
    use_azure_replay: bool,
    time_scale_factor: float,
) -> str:
    if not use_azure_replay:
        return "poisson_synthetic"
    try:
        scale = float(time_scale_factor)
    except Exception:
        scale = 1.0
    if scale < 1.0:
        return "azure_accelerated_replay"
    if scale > 1.0:
        return "azure_stretched_replay"
    return "azure_real_time"


def _derive_online_hotness_window_s(
    coord_cfg: Optional[Dict[str, Any]] = None,
    preload_cfg: Optional[Dict[str, Any]] = None,
    *,
    ttft_slo_ms: float = DEFAULT_TTFT_SLO_MS,
) -> float:
    coord_cfg = coord_cfg or {}
    preload_cfg = preload_cfg or {}
    explicit = coord_cfg.get(
        "online_hotness_window_s",
        preload_cfg.get("online_hotness_window_s"),
    )
    if explicit is not None:
        try:
            return max(1.0, float(explicit))
        except Exception:
            pass

    arrival_window_s = max(1.0, float(coord_cfg.get("arrival_window_s", 5.0) or 5.0))
    scale_eval_interval_s = max(1.0, float(coord_cfg.get("scale_eval_interval_s", 15.0) or 15.0))
    ttft_slo_s = max(1.0, float(ttft_slo_ms or DEFAULT_TTFT_SLO_MS) / 1000.0)
    return max(arrival_window_s, scale_eval_interval_s, ttft_slo_s)


def _validate_ieee_online_observation_binding(model_cfg, coord_cfg, preload_cfg,
                                              stack, *, runner_window_s):
    """Bind the two uses of IEEE W and the real loading-pressure denominator.

    No defaults or configuration repair here: historical source-only collectors
    do not call this Full integration check. Owners still validate live state.
    """
    profile = model_cfg.get('ieee_admission_profile')
    if not isinstance(profile, dict):
        raise ValueError('IEEE online binding requires native admission initialization')
    window = profile.get('window_s')
    if type(window) not in (int, float) or not math.isfinite(window) or window <= 0:
        raise ValueError('IEEE online binding requires an explicit positive W')
    tracker = getattr(stack, 'hotness_tracker', None)
    windows = dict(configured_demand=coord_cfg.get('online_hotness_window_s'),
                   runner_demand=runner_window_s,
                   actual_demand=getattr(tracker, 'window_seconds', None))
    if 'online_hotness_window_s' in preload_cfg:
        windows['preload_demand'] = preload_cfg['online_hotness_window_s']
    if any(type(value) not in (int, float) or not math.isfinite(value)
           or value != window for value in windows.values()):
        raise ValueError('IEEE demand and native completion must share the same explicit W')
    queue = getattr(getattr(stack, 'preloading_manager', None), 'ieee_movements', None)
    limit = profile.get('transfer_limit')
    limits = dict(configured_movement=coord_cfg.get('max_concurrent_loads'),
                  actual_movement=getattr(queue, 'max_concurrent', None))
    if (type(limit) is not int or limit <= 0
            or any(type(value) is not int or value != limit for value in limits.values())):
        raise ValueError('IEEE transfer pressure limit must match the actual shared movement owner')
    return dict(kind='ieee_online_observation_binding_v1', window_s=float(window),
                demand_windows=windows, transfer_limit=limit, movement_limits=limits,
                admission_profile_id=profile['profile_id'],
                model_backend_id=profile['model_backend_id'])


METRIC_DEF_PRIMARY_TTFT = (
    "scheduled trace arrival to system-observed first generated output token/chunk"
)
METRIC_DEF_PRIMARY_E2E = (
    "scheduled trace arrival to system-observed response completion when available; "
    "otherwise client-observed completion"
)
METRIC_DEF_SERVICE_TTFT = (
    "service-path start to first generated output token/chunk; service-path start "
    "is the system-specific admitted/backend-execution start and excludes scheduled-arrival "
    "and upstream queue/admission wait"
)
METRIC_DEF_SERVICE_E2E = (
    "service-path start to response completion; service-path start is the system-specific "
    "admitted/backend-execution start and excludes scheduled-arrival and upstream "
    "queue/admission wait"
)


def _is_auto_config_value(value: Any) -> bool:
    return isinstance(value, str) and value.strip().lower() in {"auto", "adaptive"}


def _nonnegative_seconds_or_none(value: Any) -> Optional[float]:
    if value is None or _is_auto_config_value(value):
        return None
    try:
        parsed = float(value)
    except Exception:
        return None
    if not math.isfinite(parsed):
        return None
    return max(0.0, parsed)


def _percentile_seconds(values: Sequence[float], percentile: float) -> float:
    finite = sorted(float(v) for v in values if math.isfinite(float(v)))
    if not finite:
        return 0.0
    if len(finite) == 1:
        return finite[0]
    rank = (len(finite) - 1) * (float(percentile) / 100.0)
    lo = int(math.floor(rank))
    hi = int(math.ceil(rank))
    if lo == hi:
        return finite[lo]
    frac = rank - lo
    return finite[lo] * (1.0 - frac) + finite[hi] * frac


