def _kill_stale_gpu_processes():
    """Kill leftover vLLM / CUDA worker processes (using psutil, no pgrep)."""
    if os.environ.get("FAASLORA_TC_LAUNCH_RECEIPT"):
        raise RuntimeError("TC cleanup must use the owned service scope, not global process matching")
    killed = 0
    my_pid = os.getpid()
    patterns = ("vllm.worker", "vllm.v1.worker", "vllm.executor", "EngineCore", "Worker_TP")
    try:
        import psutil
    except ImportError:
        return

    killed += _kill_stale_dedicated_worker_process_groups(psutil=psutil, my_pid=my_pid)

    for proc in psutil.process_iter():
        try:
            if proc.pid == my_pid:
                continue
            cmdline = proc.cmdline()
            cmd_str = " ".join(cmdline) if cmdline else ""
            if any(p in cmd_str for p in patterns):
                try:
                    for child in proc.children(recursive=True):
                        try:
                            child.kill()
                        except (psutil.NoSuchProcess, psutil.AccessDenied):
                            pass
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass
                proc.kill()
                killed += 1
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
    if killed:
        print(f"  [cleanup] Killed {killed} stale GPU worker processes")
        time.sleep(3)
    import gc
    gc.collect()


def _terminate_processes_by_cmdline_marker(
    marker: Path | str,
    *,
    exclude_pids: Optional[Collection[int]] = None,
    grace_s: float = 3.0,
) -> int:
    """Terminate processes whose command line contains an exact ownership marker.

    SGLang launches scheduler/detokenizer children that can outlive the parent
    if the dedicated worker is killed during startup or shutdown.  We keep the
    marker as a worker-owned work directory rather than a broad process name so
    cleanup cannot touch unrelated SGLang baselines running on the same host.
    """
    marker_text = str(marker)
    if not marker_text:
        return 0
    exclude = {int(pid) for pid in (exclude_pids or [])}
    exclude.add(os.getpid())
    try:
        import psutil
    except ImportError:
        return 0

    targets = []
    for proc in psutil.process_iter(["pid", "cmdline"]):
        try:
            pid = int(proc.info.get("pid") or proc.pid)
            if pid in exclude:
                continue
            cmdline = proc.info.get("cmdline") or []
            cmd = " ".join(str(item) for item in cmdline)
            if marker_text in cmd:
                targets.append(proc)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue
        except Exception:
            continue

    for proc in targets:
        try:
            proc.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
    gone, alive = psutil.wait_procs(targets, timeout=max(0.1, float(grace_s)))
    for proc in alive:
        try:
            proc.kill()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
    if alive:
        psutil.wait_procs(alive, timeout=1.0)
    return len(targets)


def _kill_stale_dedicated_worker_process_groups(*, psutil: Any = None, my_pid: Optional[int] = None) -> int:
    """Kill only persisted dedicated-worker process groups from previous runs."""
    killed = 0
    if psutil is None:
        try:
            import psutil as _psutil
        except ImportError:
            return 0
        psutil = _psutil
    my_pid = os.getpid() if my_pid is None else int(my_pid)

    # Dedicated runtime workers are launched in their own process groups under
    # /tmp/faaslora_worker_*. If a previous run crashes before normal shutdown,
    # their descendants (including /app/.venv/bin/python) can outlive the
    # parent worker. Kill those stale groups first using the persisted pgid.
    for process_meta in Path("/tmp").glob("faaslora_worker_*/process.json"):
        try:
            payload = json.loads(process_meta.read_text(encoding="utf-8"))
            pgid = int(payload.get("pgid", 0) or 0)
            pid = int(payload.get("pid", 0) or 0)
        except Exception:
            continue
        if pid == my_pid:
            continue
        try:
            if pid > 0 and psutil.pid_exists(pid):
                os.killpg(pgid or pid, signal.SIGKILL)
                killed += 1
                continue
        except Exception:
            pass
        sglang_marker = process_meta.parent / "sglang"
        if sglang_marker.exists():
            killed += _terminate_processes_by_cmdline_marker(
                sglang_marker,
                exclude_pids={my_pid},
                grace_s=1.0,
            )
    return killed


def _cleanup_distributed_runtime(backend: str) -> None:
    """Best-effort distributed/NCCL cleanup for the selected backend."""
    backend = str(backend or "").lower()
    if backend != "vllm":
        return

    try:
        from vllm.distributed.parallel_state import cleanup_dist_env_and_memory

        cleanup_dist_env_and_memory()
    except Exception:
        pass

    try:
        import torch.distributed as dist

        if dist.is_available() and dist.is_initialized():
            dist.destroy_process_group()
    except Exception:
        pass

    try:
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass

    gc.collect()


async def _maybe_shutdown_engine(target: Any) -> None:
    """Best-effort shutdown helper for mixed sync/async engine wrappers."""
    if target is None:
        return
    shutdown_fn = getattr(target, "shutdown", None)
    if not callable(shutdown_fn):
        return
    try:
        result = shutdown_fn()
        if inspect.isawaitable(result):
            await result
    except Exception:
        pass


async def _maybe_collective_rpc(target: Any, method: str, *args, **kwargs) -> None:
    """Best-effort helper for async/sync collective RPC calls."""
    if target is None:
        return
    rpc_fn = getattr(target, "collective_rpc", None)
    if not callable(rpc_fn):
        return
    try:
        result = rpc_fn(method, *args, **kwargs)
        if inspect.isawaitable(result):
            await result
    except Exception:
        pass


def _engine_mode_info(backend: str) -> str:
    backend = str(backend or "").lower()
    if backend == "vllm":
        return "Real GPU + Real LoRA (vLLM async serving path)"
    if backend == "sglang":
        return "Real GPU + Real LoRA (PrimeLoRA control plane + SGLang native serving path)"
    if backend == "transformers":
        return "Real GPU + Real LoRA (Transformers+PEFT fallback path)"
    return f"Real GPU + Real LoRA ({backend})"


def _avg_success_e2e_ms(raw_list: List[Any]) -> Optional[float]:
    vals: List[float] = []
    for item in raw_list:
        if isinstance(item, RequestResult) and item.success:
            vals.append(_request_overall_e2e_ms(item))
    if not vals:
        return None
    return sum(vals) / len(vals)


def _avg_success_ttft_ms(raw_list: List[Any]) -> Optional[float]:
    vals: List[float] = []
    for item in raw_list:
        if isinstance(item, RequestResult) and item.success:
            vals.append(_request_overall_ttft_ms(item))
    if not vals:
        return None
    return sum(vals) / len(vals)


def _avg_success_dispatch_wait_ms(raw_list: List[Any]) -> Optional[float]:
    vals: List[float] = []
    for item in raw_list:
        if isinstance(item, RequestResult) and item.success:
            vals.append(float(getattr(item, "dispatch_admission_wait_ms", 0.0) or 0.0))
    if not vals:
        return None
    return sum(vals) / len(vals)


class InferenceEngine:
    """
    Wraps vLLM AsyncLLMEngine, SGLang server, or Transformers+PEFT fallback
    with real LoRA.

    Supports three backends via YAML `model.backend`:
      "vllm"          - vLLM V1 async engine (default, fast)
      "sglang"        - SGLang native /generate server with dynamic LoRA
      "transformers"  - HuggingFace Transformers + PEFT (stable fallback)
    """

    def __init__(self, model_cfg: Dict, cost_model: Dict):
        self.model_cfg = model_cfg
        self.cost_model = cost_model
        self.engine: Optional[Any] = None
        self.backend = str(self.model_cfg.get("backend", "vllm")).lower()
        self.device_id = int(self.model_cfg.get("device_id", 0))
        self._counter = 0
        self._ieee_generation_refs = {}
        self._lock = asyncio.Lock()
        self._reinit_lock = asyncio.Lock()
        self._engine_dead = False
        self._lora_in_engine = True
        self._reinit_attempted = False
        self._active_tp = 1
        self._hf_tokenizer = None
        self._prompt_guard_tokenizer = None
        self._hf_base_model = None
        self._hf_peft_model = None
        self._hf_loaded_adapters = set()
        self._hf_adapter_lru: List[str] = []  # LRU order for adapter eviction (transformers backend)
        self._hf_max_adapters_in_memory = 1   # 默认；按场景由 set_hf_max_adapters_for_scenario 覆盖
        self._hf_request_count = 0
        self._hf_executor: Optional[concurrent.futures.ThreadPoolExecutor] = None  # single-thread for GPU
        self.startup_latency_ms: float = 0.0
        self._last_engine_create_error: str = ""
        self.last_timing: Dict[str, Any] = {}
        self._sglang_process: Optional[subprocess.Popen] = None
        self._sglang_base_url: str = ""
        self._sglang_workdir: Optional[Path] = None
        self._sglang_log_path: Optional[Path] = None
        self._sglang_loaded_loras: Dict[str, str] = {}
        self._sglang_lora_lock = asyncio.Lock()

    def _maybe_kill_stale_gpu_processes(self) -> None:
        if os.environ.get("FAASLORA_TC_LAUNCH_RECEIPT"):
            from scripts.ieee_tc_preflight import verify_current_service
            verify_current_service()
            return
        if (self.model_cfg.get("timing_contract") == "ieee_tc_native_v1"
                or self.model_cfg.get("ieee_gpu_references", False)
                or self.model_cfg.get("ieee_worker_observation", False)
                or self.model_cfg.get("ieee_scheduler_observation", False)):
            raise RuntimeError("native TC engine requires the guarded qualification launcher")
        if not bool(self.model_cfg.get("skip_stale_gpu_cleanup", False)):
            _kill_stale_gpu_processes()

    def set_hf_max_adapters_for_scenario(
        self, baseline_type: str, coord_cfg: Optional[Dict] = None, model_cfg: Optional[Dict] = None
    ) -> None:
        """
        按场景设置 GPU 内最多保留的 LoRA 数量，贴近真实系统：
          cold_start: 1（无缓存）
          slora_style, serverlessllm: model.max_loras
          faaslora_*: warm_pool_size
        """
        if self.backend != "transformers":
            return
        coord_cfg = coord_cfg or {}
        model_cfg = model_cfg or self.model_cfg
        if baseline_type == "cold_start":
            self._hf_max_adapters_in_memory = 1
        elif baseline_type in ("slora_style", "serverlessllm", "lru_nvme"):
            self._hf_max_adapters_in_memory = int(model_cfg.get("max_loras", 2))
        elif baseline_type in ("faaslora_nvme", "faaslora_no_coord", "faaslora_full"):
            wp = coord_cfg.get("warm_pool_size", 4)
            self._hf_max_adapters_in_memory = max(2, int(wp))
        else:
            self._hf_max_adapters_in_memory = int(model_cfg.get("max_loras", 2))

    def _get_prompt_guard_tokenizer(self):
        if self._prompt_guard_tokenizer is not None:
            return self._prompt_guard_tokenizer
        from transformers import AutoTokenizer

        self._prompt_guard_tokenizer = AutoTokenizer.from_pretrained(
            self.model_cfg.get("name", "Qwen/Qwen2.5-3B-Instruct"),
            trust_remote_code=True,
        )
        return self._prompt_guard_tokenizer

    def _prepare_vllm_prompt(
        self,
        prompt: str,
        max_tokens: int,
        input_tokens_hint: int,
    ) -> Tuple[str, int, int]:
        fixed = self.model_cfg.get("generation_contract") == "fixed_length_greedy_v1"
        if fixed and (type(max_tokens) is not int or max_tokens <= 0):
            raise ValueError("fixed-output target must be a positive integer")
        declared_target = max_tokens
        max_tokens = self._resolve_request_output_limit(max_tokens)
        if fixed and max_tokens != declared_target:
            raise ValueError("model output cap cannot change the common fixed-output target")
        if fixed and self.model_cfg.get('timing_contract') == 'ieee_tc_native_v1':
            from faaslora.datasets.workload_generator import canonical_fixed_prompt
            prepared = canonical_fixed_prompt(prompt, self._get_prompt_guard_tokenizer(),
                declared_target, max_model_len=int(self.model_cfg.get('max_model_len', 1024)),
                max_input_len=int(self.model_cfg.get('max_input_len', 759) or 759))
            return prepared['prompt'], prepared['canonical_prompt_tokens'], declared_target
        max_len = int(self.model_cfg.get("max_model_len", 2048))
        max_input_len = max(0, int(self.model_cfg.get("max_input_len", 0) or 0))
        reserve = max(32, min(int(max_tokens), 256))
        prompt_budget = max(32, max_len - reserve - 8)
        if max_input_len > 0:
            prompt_budget = min(prompt_budget, max_input_len)
        actual_input_tokens = max(1, int(input_tokens_hint))
        safe_max_tokens = min(max_tokens, max(1, max_len - actual_input_tokens - 8))

        try:
            tokenizer = self._get_prompt_guard_tokenizer()
            token_ids = tokenizer.encode(prompt, add_special_tokens=False)
            if len(token_ids) > prompt_budget:
                token_ids = token_ids[-prompt_budget:]
                prompt = tokenizer.decode(token_ids, skip_special_tokens=False)
            if fixed:
                # A decode at a hard token boundary is not always idempotent:
                # re-encoding the emitted string can produce one or more extra
                # tokens.  The matched-output contract is defined over prompt
                # content tokens (no synthetic BOS), so validate the final
                # string with that exact tokenizer convention.  The baseline
                # replay client applies the same loop before hashing/sending.
                while True:
                    prompt = tokenizer.decode(token_ids, skip_special_tokens=False)
                    reencoded = tokenizer.encode(prompt, add_special_tokens=False)
                    if len(reencoded) <= prompt_budget:
                        token_ids = reencoded
                        break
                    overflow = max(1, len(reencoded) - prompt_budget)
                    if len(token_ids) <= overflow:
                        raise ValueError("canonical prompt cannot satisfy its token budget")
                    token_ids = token_ids[overflow:]
                    prompt = tokenizer.decode(token_ids, skip_special_tokens=False)
            actual_input_tokens = max(1, len(token_ids))
            safe_max_tokens = min(max_tokens, max(1, max_len - actual_input_tokens - 8))
            if fixed:
                if not token_ids or any(type(token) is not int or token < 0 for token in token_ids):
                    raise ValueError("canonical prompt requires real nonempty token IDs")
                if safe_max_tokens != declared_target:
                    raise ValueError("prompt guard cannot reduce the common fixed-output target")
                native_ids = tokenizer.encode(prompt, add_special_tokens=True)
                if not native_ids or len(native_ids) + declared_target > max_len:
                    raise ValueError("canonical prompt plus special tokens and target exceeds context")
            return prompt, actual_input_tokens, safe_max_tokens
        except Exception as exc:
            if fixed:
                raise RuntimeError("fixed-output prompt preparation failed; token/character fallback forbidden") from exc
            max_chars = min(max_len * 4, 8192)
            if len(prompt) > max_chars:
                prompt = prompt[-max_chars:]
            actual_input_tokens = min(max(actual_input_tokens, 1), max_len - 8)
            safe_max_tokens = min(max_tokens, max(1, max_len - actual_input_tokens - 8))
            return prompt, actual_input_tokens, safe_max_tokens

    def _resolve_request_output_limit(self, requested_output_tokens: int) -> int:
        desired_tokens = max(1, int(requested_output_tokens or 0))
        cap = int(self.model_cfg.get("max_output_tokens_cap", 0) or 0)
        if cap > 0:
            desired_tokens = min(desired_tokens, cap)
        return max(1, desired_tokens)

    def _prepare_transformers_prompt(
        self,
        prompt: str,
        max_tokens: int,
        input_tokens_hint: int,
    ) -> Tuple[str, int, int]:
        max_tokens = self._resolve_request_output_limit(max_tokens)
        max_len = max(32, int(self.model_cfg.get("max_model_len", 2048) or 2048))
        max_input_len = max(0, int(self.model_cfg.get("max_input_len", 0) or 0))
        prompt_budget = max(8, max_len - int(max_tokens) - 8)
        if max_input_len > 0:
            prompt_budget = min(prompt_budget, max_input_len)
        actual_input_tokens = max(1, int(input_tokens_hint or 1))
        try:
            tokenizer = self._hf_tokenizer or self._get_prompt_guard_tokenizer()
            token_ids = tokenizer.encode(prompt, add_special_tokens=False)
            if len(token_ids) > prompt_budget:
                token_ids = token_ids[-prompt_budget:]
                prompt = tokenizer.decode(token_ids, skip_special_tokens=False)
            actual_input_tokens = max(1, len(token_ids))
        except Exception:
            actual_input_tokens = min(actual_input_tokens, prompt_budget)
        return prompt, actual_input_tokens, max_tokens

    def _render_chat_messages_prompt(
        self,
        messages: Optional[List[Dict[str, Any]]],
        *,
        fallback_prompt: str,
    ) -> str:
        if not messages:
            return fallback_prompt
        strict = (self.model_cfg.get("generation_contract") == "fixed_length_greedy_v1"
                  and self.model_cfg.get("timing_contract") == "ieee_tc_native_v1")
        renderer = self.model_cfg.get("canonical_prompt_renderer")
        if strict:
            if renderer == "tokenizer_chat_template":
                tokenizer = self._hf_tokenizer or self._get_prompt_guard_tokenizer()
                rendered = tokenizer.apply_chat_template(messages, add_generation_prompt=True, tokenize=False)
                if not isinstance(rendered, str) or not rendered.strip():
                    raise ValueError("frozen chat renderer produced no prompt")
                return rendered
            if renderer != "role_lines_v1":
                raise ValueError("native fixed-output chat input requires a frozen canonical_prompt_renderer")
            # Explicit common rendering recipe, not a fallback after template failure.
            from faaslora.datasets.workload_generator import render_role_lines
            return render_role_lines(messages)
        try:
            tokenizer = self._hf_tokenizer or self._get_prompt_guard_tokenizer()
            rendered = tokenizer.apply_chat_template(
                messages,
                add_generation_prompt=True,
                tokenize=False,
            )
            if isinstance(rendered, str) and rendered.strip():
                return rendered
        except Exception:
            pass
        lines: List[str] = []
        for message in messages:
            item = dict(message or {})
            role = str(item.get("role") or "user").strip().capitalize() or "User"
            content = item.get("content")
            if not isinstance(content, str):
                content = "" if content is None else str(content)
            lines.append(f"{role}: {content}")
        fallback = "\n".join(lines).strip()
        return fallback or fallback_prompt

    def prepare_request(
        self,
        prompt: str,
        requested_output_tokens: int,
        input_tokens_hint: int,
        chat_messages: Optional[List[Dict[str, Any]]] = None,
    ) -> RequestExecutionPlan:
        prompt = self._render_chat_messages_prompt(
            chat_messages,
            fallback_prompt=prompt,
        )
        if self.backend == "transformers":
            prompt, input_tokens, max_tokens = self._prepare_transformers_prompt(
                prompt=prompt,
                max_tokens=requested_output_tokens,
                input_tokens_hint=input_tokens_hint,
            )
        else:
            prompt, input_tokens, max_tokens = self._prepare_vllm_prompt(
                prompt=prompt,
                max_tokens=requested_output_tokens,
                input_tokens_hint=input_tokens_hint,
            )
        return RequestExecutionPlan(
            prompt=prompt,
            input_tokens=max(1, int(input_tokens)),
            max_tokens=max(1, int(max_tokens)),
        )

    def _resolve_vllm_visible_devices(self, tp: int) -> Optional[str]:
        pinned_visible = os.environ.get("FAASLORA_VISIBLE_DEVICES", "").strip()
        if pinned_visible:
            # Dedicated child runtimes are already process-isolated onto an exact
            # physical GPU set. Do not reinterpret child-local visible_device_ids
            # such as [0,1] as host-global GPU ids.
            return pinned_visible
        runtime_gpu_ids = _resolve_runtime_gpu_device_ids(
            self.model_cfg,
            device_id=self.device_id,
        )
        if runtime_gpu_ids:
            return ",".join(str(device_id) for device_id in runtime_gpu_ids)
        return None

    def _resolve_vllm_executor_backend(
        self,
        tp: int,
        visible_devices: Optional[str],
    ) -> Optional[str]:
        configured = self.model_cfg.get("distributed_executor_backend")
        if configured:
            return str(configured)
        if tp <= 1:
            return None
        if visible_devices:
            visible_count = len(
                [item for item in visible_devices.split(",") if item.strip() and item.strip() != "-1"]
            )
            if visible_count >= tp:
                return "mp"
        if GPU_COUNT >= tp:
            return "mp"
        return None

    def _resolve_vllm_runtime_settings(self, model: str) -> Dict[str, Any]:
        settings = _resolve_vllm_runtime_guards(self.model_cfg)
        if _is_mistral_nemo_model(model):
            print("    runtime_guard      = mistral_nemo_safe_path")
        if settings["tokenizer_mode"] is not None:
            print(f"    tokenizer_mode     = {settings['tokenizer_mode']}")
        if settings["enable_chunked_prefill"] is not None:
            print(
                f"    chunked_prefill    = {bool(settings['enable_chunked_prefill'])}"
            )
        if settings["enable_prefix_caching"] is not None:
            print(
                f"    prefix_caching     = {bool(settings['enable_prefix_caching'])}"
            )
        for env_key in (
            "VLLM_USE_V1",
            "VLLM_ATTENTION_BACKEND",
            "VLLM_USE_FLASHINFER_SAMPLER",
        ):
            if env_key in settings["env_updates"]:
                print(f"    {env_key:<18}= {settings['env_updates'][env_key]}")
        return settings

    async def _await_visible_gpu_headroom(
        self,
        tp: int,
        visible_devices: Optional[str],
        desired_gpu_util: float,
        timeout_s: float,
        poll_s: float = 1.0,
    ) -> Optional[float]:
        deadline = time.monotonic() + max(0.0, float(timeout_s))
        best_ratio = _visible_gpu_min_free_ratio(visible_devices, tp)
        while time.monotonic() < deadline:
            current_ratio = _visible_gpu_min_free_ratio(visible_devices, tp)
            if current_ratio is not None:
                if best_ratio is None or current_ratio > best_ratio:
                    best_ratio = current_ratio
                if current_ratio + 1e-6 >= desired_gpu_util:
                    return current_ratio
            await asyncio.sleep(max(0.1, float(poll_s)))
        return best_ratio

    @staticmethod
    def _reserve_loopback_port() -> int:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            sock.bind(("127.0.0.1", 0))
            return int(sock.getsockname()[1])
        finally:
            sock.close()

    def _resolve_sglang_python(self) -> str:
        explicit_python = str(os.environ.get("SGLANG_PYTHON", "") or "").strip()
        if explicit_python:
            return explicit_python
        venv = str(
            os.environ.get(
                "SGLANG_VENV",
                self.model_cfg.get("sglang_venv", "/home/qhq/.venvs/sglang_py310"),
            )
            or ""
        ).strip()
        if venv:
            candidate = Path(venv).expanduser() / "bin" / "python"
            if candidate.exists():
                return str(candidate)
        return sys.executable

    def _build_sglang_launch_spec(self, *, port: int, nccl_port: int) -> Dict[str, Any]:
        max_running = self.model_cfg.get(
            "sglang_max_running_requests",
            self.model_cfg.get("max_num_seqs"),
        )
        max_running_requests = max(1, int(max_running or 1)) if max_running is not None else 0
        max_loras = max(1, int(self.model_cfg.get("max_loras", 4) or 4))
        max_loras_per_batch = max(max_loras, max_running_requests or 1)
        max_cpu_loras = max(
            max_loras_per_batch,
            int(self.model_cfg.get("max_cpu_loras", max(24, max_loras_per_batch)) or max(24, max_loras_per_batch)),
        )
        max_batched_tokens = int(self.model_cfg.get("max_num_batched_tokens", 1024) or 1024)
        chunked = self.model_cfg.get("enable_chunked_prefill")
        chunked_prefill_size = max_batched_tokens if bool(chunked) else -1
        spec: Dict[str, Any] = {
            "model-path": self.model_cfg.get("name", "Qwen/Qwen2.5-3B-Instruct"),
            "host": "127.0.0.1",
            "port": int(port),
            "nccl-port": int(nccl_port),
            "served-model-name": str(self.model_cfg.get("served_model_name") or "primelora-sglang"),
            "trust-remote-code": True,
            "tp": max(1, int(self.model_cfg.get("tensor_parallel_size", 1) or 1)),
            "context-length": int(self.model_cfg.get("max_model_len", 2048) or 2048),
            "mem-fraction-static": float(self.model_cfg.get("gpu_memory_utilization", 0.85) or 0.85),
            "dtype": str(self.model_cfg.get("dtype", "float16") or "float16"),
            "enable-lora": True,
            "max-lora-rank": int(self.model_cfg.get("max_lora_rank", 64) or 64),
            "lora-target-modules": ["all"],
            "max-loras-per-batch": max_loras_per_batch,
            "max-loaded-loras": max_cpu_loras,
            "chunked-prefill-size": int(chunked_prefill_size),
            "enable-metrics": True,
            "enable-request-time-stats-logging": True,
            "log-level": str(os.environ.get("FAASLORA_SGLANG_LOG_LEVEL", "warning") or "warning"),
        }
        lora_backend = str(self.model_cfg.get("sglang_lora_backend") or "").strip()
        if lora_backend:
            spec["lora-backend"] = lora_backend
        if max_running_requests > 0:
            spec["max-running-requests"] = max_running_requests
        if self.model_cfg.get("enable_prefix_caching") is False:
            spec["disable-radix-cache"] = True
        if bool(self.model_cfg.get("sglang_disable_cuda_graph", False)):
            spec["disable-cuda-graph"] = True
        return spec

    async def _wait_for_sglang_ready(self, timeout_s: float) -> None:
        import requests

        deadline = time.monotonic() + max(1.0, float(timeout_s))
        url = f"{self._sglang_base_url.rstrip('/')}/v1/models"
        last_error = ""
        while time.monotonic() < deadline:
            proc = self._sglang_process
            if proc is not None and proc.poll() is not None:
                log_tail = ""
                try:
                    if self._sglang_log_path and self._sglang_log_path.exists():
                        log_tail = "\n".join(self._sglang_log_path.read_text(errors="ignore").splitlines()[-40:])
                except Exception:
                    pass
                raise RuntimeError(
                    f"SGLang server exited during startup (rc={proc.returncode}). "
                    f"Last error: {last_error}. Log tail:\n{log_tail}"
                )
            try:
                resp = await asyncio.to_thread(requests.get, url, timeout=2.0)
                if resp.status_code == 200:
                    return
                last_error = f"HTTP {resp.status_code}: {resp.text[:200]}"
            except Exception as exc:
                last_error = f"{type(exc).__name__}: {exc}"
            await asyncio.sleep(0.75)
        raise TimeoutError(f"SGLang server did not become ready within {timeout_s:.1f}s: {last_error}")

    async def _initialize_sglang(self, init_started_at: float) -> None:
        model = self.model_cfg.get("name", "Qwen/Qwen2.5-3B-Instruct")
        tp = max(1, int(self.model_cfg.get("tensor_parallel_size", 1) or 1))
        visible_devices = self._resolve_vllm_visible_devices(tp)
        port = self._reserve_loopback_port()
        nccl_port = self._reserve_loopback_port()
        workdir_base_raw = str(self.model_cfg.get("sglang_workdir_base", "") or "").strip()
        if workdir_base_raw:
            workdir_base = Path(workdir_base_raw).expanduser()
            workdir_base.mkdir(parents=True, exist_ok=True)
            workdir = Path(tempfile.mkdtemp(prefix="server_", dir=str(workdir_base)))
        else:
            workdir = Path(tempfile.mkdtemp(prefix="faaslora_sglang_", dir="/tmp"))
        metrics_dir = workdir / "metrics"
        metrics_dir.mkdir(parents=True, exist_ok=True)
        launch_spec = self._build_sglang_launch_spec(port=port, nccl_port=nccl_port)
        spec_path = workdir / "launch.yaml"
        log_path = workdir / "sglang_server.log"
        spec_path.write_text(yaml.safe_dump(launch_spec, sort_keys=False), encoding="utf-8")

        sglang_python = self._resolve_sglang_python()
        if not Path(sglang_python).exists():
            raise RuntimeError(f"SGLang python not found: {sglang_python}")

        env = os.environ.copy()
        env.setdefault("PYTHONNOUSERSITE", "1")
        env.setdefault("PYTHONUNBUFFERED", "1")
        env.setdefault("TORCH_FORCE_NO_WEIGHTS_ONLY_LOAD", "1")
        # Do not resolve the venv python symlink here: resolving
        # /path/to/venv/bin/python points to /usr/bin/python3.x and drops the
        # venv bin directory that contains runtime JIT tools such as ninja.
        sglang_bin = str(Path(sglang_python).expanduser().parent)
        env["PATH"] = f"{sglang_bin}:{env.get('PATH', '')}"
        if visible_devices:
            env["CUDA_VISIBLE_DEVICES"] = str(visible_devices)
            env["FAASLORA_VISIBLE_DEVICES"] = str(visible_devices)
        env.update(_build_local_tp_runtime_env_updates(tp=tp, executor_backend="mp" if tp > 1 else None))

        cmd = [
            sglang_python,
            "-m",
            "sglang.launch_server",
            "--config",
            str(spec_path),
            "--export-metrics-to-file",
            "--export-metrics-to-file-dir",
            str(metrics_dir),
        ]
        if bool(self.model_cfg.get("sglang_enable_lora_overlap_loading", False)):
            cmd.append("--enable-lora-overlap-loading")

        log_fh = open(log_path, "w", encoding="utf-8")
        try:
            proc = subprocess.Popen(
                cmd,
                stdout=log_fh,
                stderr=subprocess.STDOUT,
                env=env,
                cwd=str(REPO_ROOT),
                start_new_session=True,
                text=True,
            )
        finally:
            log_fh.close()

        self._sglang_process = proc
        self._sglang_base_url = f"http://127.0.0.1:{port}"
        self._sglang_workdir = workdir
        self._sglang_log_path = log_path
        self._sglang_loaded_loras.clear()
        self._active_tp = tp

        print("  Initialising SGLang server:")
        print(f"    model              = {model}")
        print(f"    GPU                = {GPU_NAME} (x{GPU_COUNT})")
        print(f"    tensor_parallel    = {tp}")
        print(f"    base_url           = {self._sglang_base_url}")
        print(f"    nccl_port          = {nccl_port}")
        print(f"    max_model_len      = {launch_spec['context-length']}")
        if "max-running-requests" in launch_spec:
            print(f"    max_running_reqs   = {launch_spec['max-running-requests']}")
        else:
            print("    max_running_reqs   = SGLang default")
        print(f"    max_loras_per_batch= {launch_spec['max-loras-per-batch']}")
        print(f"    max_loaded_loras   = {launch_spec['max-loaded-loras']}")
        print(f"    max_lora_rank      = {launch_spec['max-lora-rank']}")
        print(f"    dtype              = {launch_spec['dtype']}")
        if visible_devices:
            print(f"    visible_devices    = {visible_devices}")
        print(f"    log                = {log_path}")

        timeout_s = float(os.environ.get("FAASLORA_SGLANG_START_TIMEOUT_S", self.model_cfg.get("sglang_start_timeout_s", 300)) or 300)
        try:
            await self._wait_for_sglang_ready(timeout_s=timeout_s)
        except Exception:
            await self._terminate_sglang_process(force=True)
            raise
        self.startup_latency_ms = max(0.0, (time.perf_counter() - init_started_at) * 1000.0)
        self._engine_dead = False
        print(f"  OK: SGLang server ready (TP={tp}, dynamic LoRA)")

    async def initialize(self):
        policy = self.model_cfg.get('ieee_native_host_allocator_policy')
        marker = os.environ.get('FAASLORA_IEEE_NATIVE_HOST_ALLOCATOR_POLICY')
        if policy is not None or marker:
            expected_env = _ieee_native_allocator_environment(self.model_cfg, os.environ)
            if (marker != policy or any(os.environ.get(key) != expected_env.get(key) for key in
                    ('PYTORCH_ALLOC_CONF', 'PYTORCH_CUDA_ALLOC_CONF', 'PYTORCH_HIP_ALLOC_CONF'))):
                raise RuntimeError('native HOST allocator candidate requires a preconfigured fresh process')
        strict_launch = bool(os.environ.get("FAASLORA_TC_LAUNCH_RECEIPT")) or (
            self.model_cfg.get("timing_contract") == "ieee_tc_native_v1"
            or self.model_cfg.get("ieee_gpu_references", False)
            or self.model_cfg.get("ieee_worker_observation", False)
            or self.model_cfg.get("ieee_scheduler_observation", False))
        if strict_launch:
            from scripts.ieee_tc_preflight import verify_current_service
            self._tc_launch_identity = verify_current_service()
        init_started_at = time.perf_counter()
        self._last_engine_create_error = ""
        if not CUDA_AVAILABLE:
            raise RuntimeError(
                f"Real inference requires CUDA (CUDA={CUDA_AVAILABLE})"
            )

        if self.backend == "transformers":
            await self._initialize_transformers()
            self.startup_latency_ms = max(0.0, (time.perf_counter() - init_started_at) * 1000.0)
            return

        if self.backend == "sglang":
            await self._initialize_sglang(init_started_at)
            return

        model    = self.model_cfg.get("name", "Qwen/Qwen2.5-3B-Instruct")
        tp       = self.model_cfg.get("tensor_parallel_size", 1)
        gpu_util = self.model_cfg.get("gpu_memory_utilization", 0.90)
        max_len  = self.model_cfg.get("max_model_len", 2048)
        max_lr   = self.model_cfg.get("max_loras", 4)
        from faaslora.runtime_configuration import resolve_facade_lora_capacity
        max_cpu_lr = resolve_facade_lora_capacity(self.model_cfg)["max_cpu_loras"]
        self.model_cfg["max_cpu_loras"] = max_cpu_lr
        max_rank = self.model_cfg.get("max_lora_rank", 16)
        eager    = _resolve_vllm_enforce_eager(self.model_cfg)
        visible_devices = self._resolve_vllm_visible_devices(tp)
        executor_backend = self._resolve_vllm_executor_backend(tp, visible_devices)
        runtime_settings = self._resolve_vllm_runtime_settings(model)
        runtime_settings["env_updates"].update(
            _build_local_tp_runtime_env_updates(tp=tp, executor_backend=executor_backend)
        )
        self._vllm_runtime_settings = runtime_settings

        previous_env = _push_env_updates(runtime_settings["env_updates"])
        try:
            if not _lazy_import_vllm():
                raise RuntimeError(
                    f"vLLM backend selected but vLLM is unavailable "
                    f"(CUDA={CUDA_AVAILABLE}, vLLM={VLLM_AVAILABLE})"
                )

            _check_shm_for_vllm()
            self._maybe_kill_stale_gpu_processes()

            print("  Initialising vLLM engine:")
            print(f"    model              = {model}")
            print(f"    GPU                = {GPU_NAME} (x{GPU_COUNT})")
            print(f"    tensor_parallel    = {tp}")
            print(f"    gpu_mem_util       = {gpu_util}")
            print(f"    max_model_len      = {max_len}")
            print(f"    max_num_seqs       = {self.model_cfg.get('max_num_seqs', 8)}")
            print(f"    max_batch_tokens   = {self.model_cfg.get('max_num_batched_tokens', 1024)}")
            print(f"    runtime_conc_cap   = {self.model_cfg.get('runtime_concurrency_cap', 'n/a')}")
            print(f"    max_loras          = {max_lr}")
            print(f"    max_cpu_loras      = {max_cpu_lr}")
            print(f"    max_lora_rank      = {max_rank}")
            print(f"    enforce_eager      = {eager}")
            print(f"    dtype              = {self.model_cfg.get('dtype', 'float16')}")
            print(f"    device_id          = {self.device_id}")
            if visible_devices:
                print(f"    visible_devices    = {visible_devices}")
            if executor_backend:
                print(f"    dist_backend       = {executor_backend}")

            # Try 1: preferred config (now profile/model specific instead of always "all defaults").
            engine = await self._try_create_engine(
                model, tp=tp, gpu_util=gpu_util, max_len=max_len, eager=eager,
                enable_lora=True, max_loras=max_lr, max_lora_rank=max_rank,
                max_cpu_loras=int(max_cpu_lr),
                enable_chunked_prefill=runtime_settings["enable_chunked_prefill"],
                enable_prefix_caching=runtime_settings["enable_prefix_caching"],
                tokenizer_mode=runtime_settings["tokenizer_mode"],
            )

            # Try 2: disable chunked prefill & prefix caching if preferred path was not already there.
            if engine is None and not strict_launch and (
                runtime_settings["enable_chunked_prefill"] is not False
                or runtime_settings["enable_prefix_caching"] is not False
            ):
                print("  [RETRY] vLLM with enable_chunked_prefill=False, enable_prefix_caching=False ...")
                engine = await self._try_create_engine(
                    model, tp=tp, gpu_util=gpu_util, max_len=max_len, eager=eager,
                    enable_lora=True, max_loras=max_lr, max_lora_rank=max_rank,
                    max_cpu_loras=int(max_cpu_lr),
                    enable_chunked_prefill=False, enable_prefix_caching=False,
                    tokenizer_mode=runtime_settings["tokenizer_mode"],
                )

            # Try 3: post-cleanup adaptive retry that preserves the
            # active model profile instead of forcing every model into the same
            # low-memory fallback. This is especially important for TP>1 large
            # models where gpu_util=0.6 can eliminate KV cache headroom.
            if engine is None and not strict_launch:
                self._maybe_kill_stale_gpu_processes()
                try:
                    import torch
                    if torch.cuda.is_available():
                        torch.cuda.empty_cache()
                except Exception:
                    pass
                import gc; gc.collect()

                observed_free_ratio = await self._await_visible_gpu_headroom(
                    tp=tp,
                    visible_devices=visible_devices,
                    desired_gpu_util=gpu_util,
                    timeout_s=8.0 if tp > 1 else 4.0,
                )
                retry_gpu_util = _select_adaptive_retry_gpu_util(
                    requested_gpu_util=gpu_util,
                    observed_free_ratio=observed_free_ratio,
                )
                if observed_free_ratio is not None and retry_gpu_util + 1e-6 < gpu_util:
                    print(
                        f"  [RETRY] vLLM after cleanup with adaptive gpu_util={retry_gpu_util:.2f}, "
                        f"max_loras={max_lr}, no chunked prefill ..."
                    )
                else:
                    print(
                        f"  [RETRY] vLLM after cleanup with gpu_util={retry_gpu_util:.2f}, "
                        f"max_loras={max_lr}, no chunked prefill ..."
                    )
                engine = await self._try_create_engine(
                    model, tp=tp, gpu_util=retry_gpu_util, max_len=max_len, eager=eager,
                    enable_lora=True, max_loras=max_lr, max_lora_rank=max_rank,
                    max_cpu_loras=int(max_cpu_lr),
                    enable_chunked_prefill=False, enable_prefix_caching=False,
                    tokenizer_mode=runtime_settings["tokenizer_mode"],
                )
            if engine is not None:
                self.engine = engine
                self._lora_in_engine = True
                self._active_tp = tp
                self.startup_latency_ms = max(0.0, (time.perf_counter() - init_started_at) * 1000.0)
                print(f"  OK: vLLM engine ready (TP={tp}, real LoRA, max_loras={max_lr})")
                return
        finally:
            _restore_env_updates(previous_env)

        detail = str(getattr(self, "_last_engine_create_error", "") or "").strip()
        if detail:
            raise RuntimeError(
                "vLLM engine creation failed. "
                f"Root cause: {detail}"
            )
        raise RuntimeError(
            "vLLM engine creation failed. Check GPU memory and driver state."
        )

    async def _try_create_engine(
        self, model: str, tp: int, gpu_util: float, max_len: int,
        eager: bool, enable_lora: bool, max_loras: int, max_lora_rank: int,
        max_cpu_loras: Optional[int] = None,
        enable_chunked_prefill: Optional[bool] = None,
        enable_prefix_caching: Optional[bool] = None,
        tokenizer_mode: Optional[str] = None,
    ) -> Optional[AsyncLLMEngine]:
        """Try to create a vLLM engine; return None on failure."""
        if not _lazy_import_vllm():
            return None
        desc = f"TP={tp}, LoRA={'on' if enable_lora else 'off'}"
        try:
            default_batched = self.model_cfg.get("max_num_batched_tokens", 1024)
            # When chunked prefill is disabled, vLLM requires max_num_batched_tokens >= max_model_len
            if enable_chunked_prefill is False:
                default_batched = max(default_batched, max_len)
            kwargs = dict(
                model=model,
                dtype=self.model_cfg.get("dtype", "float16"),
                tensor_parallel_size=tp,
                max_model_len=max_len,
                gpu_memory_utilization=gpu_util,
                trust_remote_code=True,
                disable_log_stats=(self.model_cfg.get("timing_contract", "legacy") != "ieee_tc_native_v1"),
                enforce_eager=eager,
                max_num_seqs=self.model_cfg.get("max_num_seqs", 8),
                max_num_batched_tokens=default_batched,
            )
            if (self.model_cfg.get("ieee_worker_observation", False)
                    or self.model_cfg.get("ieee_gpu_references", False)):
                kwargs["worker_extension_cls"] = "faaslora.memory.gpu_monitor.IEEEWorkerObservationExtension"
            if self.model_cfg.get("ieee_scheduler_observation", False):
                bounds = self.model_cfg["ieee_input_upper_bounds"]
                if (not isinstance(bounds, (list, tuple)) or not bounds
                        or any(type(n) is not int or n <= 0 for n in bounds)
                        or list(bounds) != sorted(set(bounds))):
                    raise ValueError("IEEE scheduler requires explicit sorted prompt upper bounds")
                kwargs["scheduler_cls"] = "faaslora.scheduling.vllm_ieee_scheduler.IEEENativeAsyncScheduler"
                kwargs["async_scheduling"] = True
                kwargs["additional_config"] = {"ieee_tc_scheduler_observation": {
                    "input_upper_bounds": list(bounds)}}
                if self.model_cfg.get('ieee_admission_profile') is not None:
                    if not self.model_cfg.get('ieee_gpu_references', False):
                        raise ValueError('native admission requires native GPU references')
                    limit = self.model_cfg['ieee_admission_profile'].get('transfer_limit')
                    if type(limit) is not int or limit <= 0:
                        raise ValueError('native admission requires explicit positive transfer_limit')
                    kwargs['additional_config']['ieee_tc_admission_profile'] = dict(
                        self.model_cfg['ieee_admission_profile'])
            elif self.model_cfg.get('ieee_admission_profile') is not None:
                raise ValueError('native admission requires the native scheduler owner')
            if tokenizer_mode is not None:
                kwargs["tokenizer_mode"] = tokenizer_mode
            if tp > 1:
                kwargs["disable_custom_all_reduce"] = True
            if enable_lora:
                kwargs["enable_lora"] = True
                kwargs["max_lora_rank"] = max_lora_rank
                kwargs["max_loras"] = max_loras
                if max_cpu_loras is not None:
                    kwargs["max_cpu_loras"] = max(int(max_cpu_loras), int(max_loras))
            if enable_chunked_prefill is not None:
                kwargs["enable_chunked_prefill"] = enable_chunked_prefill
            if enable_prefix_caching is not None:
                kwargs["enable_prefix_caching"] = enable_prefix_caching
            visible_devices = self._resolve_vllm_visible_devices(tp)
            executor_backend = self._resolve_vllm_executor_backend(tp, visible_devices)
            if executor_backend is not None:
                kwargs["distributed_executor_backend"] = executor_backend

            prev_visible = os.environ.get("CUDA_VISIBLE_DEVICES")
            if visible_devices is not None:
                os.environ["CUDA_VISIBLE_DEVICES"] = visible_devices
            try:
                args = AsyncEngineArgs(**kwargs)
                engine_cls = AsyncLLMEngine
                if self.model_cfg.get('ieee_gpu_references', False):
                    if not self.model_cfg.get('ieee_scheduler_observation', False):
                        raise ValueError('native references require scheduler retirement observation')
                    from faaslora.scheduling.vllm_ieee_frontend import IEEENativeAsyncLLM
                    engine_cls = IEEENativeAsyncLLM
                engine = engine_cls.from_engine_args(args)
            finally:
                if prev_visible is None:
                    os.environ.pop("CUDA_VISIBLE_DEVICES", None)
                else:
                    os.environ["CUDA_VISIBLE_DEVICES"] = prev_visible
            self._engine_dead = False
            return engine
        except Exception as exc:
            detail = f"{type(exc).__name__}: {exc}"
            self._last_engine_create_error = detail
            print(f"  [WARN] vLLM engine creation failed ({desc}): {detail[:500]}")
            if (os.environ.get("FAASLORA_TC_LAUNCH_RECEIPT")
                    or self.model_cfg.get("timing_contract") == "ieee_tc_native_v1"
                    or self.model_cfg.get("ieee_scheduler_observation", False)):
                raise RuntimeError(f"TC backend construction failed without config retry: {detail}") from exc
            self._maybe_kill_stale_gpu_processes()
            try:
                import torch
                if torch.cuda.is_available():
                    torch.cuda.empty_cache()
            except Exception:
                pass
            import gc; gc.collect()
            time.sleep(2)
            return None

    async def shutdown(self):
        if self.backend == "transformers":
            if self._hf_executor is not None:
                self._hf_executor.shutdown(wait=True)
                self._hf_executor = None
            self._hf_peft_model = None
            self._hf_base_model = None
            self._hf_tokenizer = None
            try:
                import torch
                if torch.cuda.is_available():
                    torch.cuda.empty_cache()
            except Exception:
                pass
            return
        if self.backend == "sglang":
            await self._terminate_sglang_process(force=False)
            self._sglang_loaded_loras.clear()
            self._sglang_base_url = ""
            self._engine_dead = True
            keep_logs = os.environ.get("FAASLORA_KEEP_SGLANG_LOGS", "").strip().lower() in {"1", "true", "yes", "on"}
            if self._sglang_workdir and not keep_logs:
                shutil.rmtree(self._sglang_workdir, ignore_errors=True)
            return
        if self.engine is not None:
            try:
                inner_engine = getattr(self.engine, "engine", None)
                await _maybe_collective_rpc(inner_engine, "shutdown", timeout=5)
                await _maybe_shutdown_engine(inner_engine)
                model_executor = getattr(inner_engine, "model_executor", None)
                if model_executor is not None and hasattr(model_executor, "shutdown"):
                    model_executor.shutdown()
                if hasattr(self.engine, 'shutdown_background_loop'):
                    self.engine.shutdown_background_loop()
                await _maybe_shutdown_engine(self.engine)
            except Exception:
                pass
        _cleanup_distributed_runtime(self.backend)
        self.engine = None
        self._engine_dead = True

    async def _terminate_sglang_process(self, *, force: bool = False) -> None:
        proc = self._sglang_process
        workdir = self._sglang_workdir
        self._sglang_process = None
        if proc is None:
            if workdir is not None:
                _terminate_processes_by_cmdline_marker(workdir, grace_s=1.0)
            return
        already_exited = False
        try:
            if proc.poll() is not None:
                already_exited = True
        except Exception:
            pass
        if not already_exited:
            sig = signal.SIGKILL if force else signal.SIGTERM
            try:
                pgid = os.getpgid(proc.pid)
                os.killpg(pgid, sig)
            except Exception:
                try:
                    proc.send_signal(sig)
                except Exception:
                    pass
            try:
                await asyncio.to_thread(proc.wait, 5 if force else 15)
            except Exception:
                if not force:
                    try:
                        pgid = os.getpgid(proc.pid)
                        os.killpg(pgid, signal.SIGKILL)
                    except Exception:
                        try:
                            proc.kill()
                        except Exception:
                            pass
                    try:
                        await asyncio.to_thread(proc.wait, 5)
                    except Exception:
                        pass
        if workdir is not None:
            await asyncio.to_thread(
                _terminate_processes_by_cmdline_marker,
                workdir,
                grace_s=1.0 if force else 2.0,
            )

    async def reinitialize(self):
        """Reinitialize engine after a crash."""
        if not CUDA_AVAILABLE:
            return
        if self.backend == "transformers":
            await self.shutdown()
            await asyncio.sleep(1)
            await self._initialize_transformers()
            return
        if self.backend == "sglang":
            await self.shutdown()
            await asyncio.sleep(1)
            await self._initialize_sglang(time.perf_counter())
            return
        if not _lazy_import_vllm():
            return
        self._reinit_attempted = True
        print("  [reinit] Restarting vLLM engine ...")
        self._maybe_kill_stale_gpu_processes()
        try:
            import torch
            if torch.cuda.is_available():
                torch.cuda.empty_cache()
        except Exception:
            pass
        import gc; gc.collect()
        await asyncio.sleep(3)

        model    = self.model_cfg.get("name", "Qwen/Qwen2.5-3B-Instruct")
        tp       = self.model_cfg.get("tensor_parallel_size", 1)
        gpu_util = self.model_cfg.get("gpu_memory_utilization", 0.90)
        max_len  = self.model_cfg.get("max_model_len", 2048)
        max_lr   = self.model_cfg.get("max_loras", 4)
        max_rank = self.model_cfg.get("max_lora_rank", 16)
        eager    = _resolve_vllm_enforce_eager(self.model_cfg)
        runtime_settings = getattr(
            self,
            "_vllm_runtime_settings",
            self._resolve_vllm_runtime_settings(model),
        )
        visible_devices = self._resolve_vllm_visible_devices(tp)
        executor_backend = self._resolve_vllm_executor_backend(tp, visible_devices)
        runtime_settings["env_updates"].update(
            _build_local_tp_runtime_env_updates(tp=tp, executor_backend=executor_backend)
        )
        previous_env = _push_env_updates(runtime_settings["env_updates"])
        try:
            # Reuse the conservative runtime settings that were selected for
            # the model family instead of hard-coding only the no-chunk path.
            engine = await self._try_create_engine(
                model, tp=tp, gpu_util=gpu_util, max_len=max_len, eager=eager,
                enable_lora=True, max_loras=max_lr, max_lora_rank=max_rank,
                enable_chunked_prefill=runtime_settings["enable_chunked_prefill"],
                enable_prefix_caching=runtime_settings["enable_prefix_caching"],
                tokenizer_mode=runtime_settings["tokenizer_mode"],
            )
        finally:
            _restore_env_updates(previous_env)
        if engine is not None:
            self.engine = engine
            self._lora_in_engine = True
            self._active_tp = tp
            self._engine_dead = False
            print(f"  OK: vLLM engine restarted (TP={tp}, real LoRA)")
            return

        print("  [ERROR] Engine restart failed")
        self.engine = None

    async def _initialize_transformers(self):
        """Initialize Transformers + PEFT backend (real model, real LoRA)."""
        model = self.model_cfg.get("name", "Qwen/Qwen2.5-0.5B-Instruct")
        dtype_name = str(self.model_cfg.get("dtype", "float16")).lower()
        print("  Initialising Transformers engine:")
        print(f"    model              = {model}")
        print(f"    GPU                = {GPU_NAME} (x{GPU_COUNT})")
        print("    backend            = transformers + peft")
        print(f"    dtype              = {dtype_name}")
        print(f"    device_id          = {self.device_id}")
        try:
            import torch
            from transformers import AutoModelForCausalLM, AutoTokenizer
            torch_dtype = torch.float16 if dtype_name == "float16" else torch.bfloat16
            device = f"cuda:{self.device_id}"
            # Use single GPU to avoid OOM (auto can split across 2 GPUs and double memory use)
            self._hf_tokenizer = AutoTokenizer.from_pretrained(
                model, trust_remote_code=True
            )
            if self._hf_tokenizer.pad_token is None:
                self._hf_tokenizer.pad_token = self._hf_tokenizer.eos_token
            self._hf_base_model = AutoModelForCausalLM.from_pretrained(
                model,
                torch_dtype=torch_dtype,
                trust_remote_code=True,
                low_cpu_mem_usage=True,
            )
            self._hf_base_model = self._hf_base_model.to(device)
            self._hf_base_model.eval()
            self._hf_peft_model = None
            self._hf_loaded_adapters = set()
            self._engine_dead = False
            self._hf_executor = concurrent.futures.ThreadPoolExecutor(max_workers=1)
            import torch
            if torch.cuda.is_available():
                torch.cuda.empty_cache()
                torch.cuda.synchronize()
            print("  OK: Transformers engine ready (single GPU, real LoRA)")
        except Exception as exc:
            raise RuntimeError(f"Transformers engine init failed: {exc}") from exc

    def _sync_generate_transformers(
        self,
        prompt: str,
        lora_path: Optional[str],
        adapter_id: Optional[str],
        max_tokens: int,
        temperature: float,
        top_p: float,
    ) -> Tuple[float, float, int]:
        """Synchronous HF generate (called from thread pool to avoid blocking event loop)."""
        import torch
        from peft import PeftModel

        if self._hf_tokenizer is None or self._hf_base_model is None:
            raise RuntimeError("Transformers backend is not initialized")

        tokenizer = self._hf_tokenizer
        base_model = self._hf_base_model
        device = f"cuda:{self.device_id}"

        max_input_len = max(0, int(self.model_cfg.get("max_input_len", 0) or 0))
        tokenizer_kwargs: Dict[str, Any] = {"return_tensors": "pt"}
        if max_input_len > 0:
            tokenizer_kwargs.update(truncation=True, max_length=max_input_len)
        inputs = tokenizer(prompt, **tokenizer_kwargs)
        input_ids = inputs["input_ids"].to(device)
        attention_mask = inputs["attention_mask"].to(device)

        model_to_use = base_model
        if lora_path and adapter_id:
            # LRU: keep at most _hf_max_adapters_in_memory to avoid OOM with 6 adapters
            if adapter_id in self._hf_loaded_adapters:
                # move to end of LRU
                if adapter_id in self._hf_adapter_lru:
                    self._hf_adapter_lru.remove(adapter_id)
                self._hf_adapter_lru.append(adapter_id)
            else:
                # 需要加载新 adapter；按 max 分策略，贴近真实系统并避免 PEFT 残留
                max_a = self._hf_max_adapters_in_memory
                to_evict = []
                while (self._hf_peft_model is not None and
                       len(self._hf_loaded_adapters) >= max_a and
                       self._hf_adapter_lru):
                    to_evict.append(self._hf_adapter_lru.pop(0))

                # max>=2: 先 delete 再 load，避免瞬时 3-adapter 显存峰值导致 OOM/已杀死
                if max_a >= 2 and self._hf_peft_model is not None:
                    for evict_id in to_evict:
                        if evict_id in self._hf_loaded_adapters:
                            self._hf_peft_model.delete_adapter(evict_id)
                            self._hf_loaded_adapters.discard(evict_id)
                    gc.collect()
                    if torch.cuda.is_available():
                        torch.cuda.empty_cache()
                    self._hf_peft_model.load_adapter(lora_path, adapter_name=adapter_id)
                    self._hf_loaded_adapters.add(adapter_id)
                    self._hf_adapter_lru.append(adapter_id)
                else:
                    # max==1 (cold_start): 先 delete；若为 0 则 unload 再 from_pretrained
                    for evict_id in to_evict:
                        if evict_id in self._hf_loaded_adapters:
                            self._hf_peft_model.delete_adapter(evict_id)
                            self._hf_loaded_adapters.discard(evict_id)
                    gc.collect()
                    if torch.cuda.is_available():
                        torch.cuda.empty_cache()
                        torch.cuda.synchronize()
                    if self._hf_peft_model is None:
                        self._hf_peft_model = PeftModel.from_pretrained(
                            base_model, lora_path, adapter_name=adapter_id, is_trainable=False
                        )
                        self._hf_loaded_adapters.add(adapter_id)
                        self._hf_adapter_lru.append(adapter_id)
                    elif len(self._hf_loaded_adapters) == 0:
                        clean_base = self._hf_peft_model.unload()
                        self._hf_peft_model = None
                        self._hf_base_model = clean_base
                        self._hf_peft_model = PeftModel.from_pretrained(
                            clean_base, lora_path, adapter_name=adapter_id, is_trainable=False
                        )
                        self._hf_loaded_adapters.add(adapter_id)
                        self._hf_adapter_lru.append(adapter_id)
                    else:
                        self._hf_peft_model.load_adapter(lora_path, adapter_name=adapter_id)
                        self._hf_loaded_adapters.add(adapter_id)
                        self._hf_adapter_lru.append(adapter_id)
            self._hf_peft_model.set_adapter(adapter_id)
            model_to_use = self._hf_peft_model

        cap = self.model_cfg.get("max_output_tokens_cap", 0)
        eff_max = min(max_tokens, cap) if cap and cap > 0 else max_tokens
        t0 = time.perf_counter()
        with torch.inference_mode():
            out = model_to_use.generate(
                input_ids=input_ids,
                attention_mask=attention_mask,
                **_build_hf_generate_kwargs(
                    model_to_use,
                    tokenizer,
                    eff_max,
                    temperature=temperature,
                    top_p=top_p,
                ),
            )
        t1 = time.perf_counter()

        output_tokens = max(int(out.shape[-1] - input_ids.shape[-1]), 1)
        total_ms = (t1 - t0) * 1000.0
        per_token_ms = total_ms / float(output_tokens)
        self.last_timing = {
            "runtime_estimated_e2e_ms": float(total_ms),
            "worker_wall_e2e_ms": float(total_ms),
            "parent_rpc_wall_ms": float(total_ms),
            "parent_rpc_overhead_ms": 0.0,
        }

        # 尽早释放所有张量，降低显存峰值
        del out, input_ids, attention_mask
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

        return per_token_ms, per_token_ms, output_tokens

    async def _generate_transformers(
        self,
        prompt: str,
        lora_path: Optional[str],
        adapter_id: Optional[str],
        max_tokens: int,
        temperature: float,
        top_p: float,
    ) -> Tuple[float, float, int]:
        """Run generate in main thread (no executor) to avoid thread+CUDA driver kills."""
        async with self._lock:
            return self._sync_generate_transformers(
                prompt, lora_path, adapter_id, max_tokens, temperature, top_p,
            )

    def _sglang_post_json_sync(self, endpoint: str, payload: Dict[str, Any], *, timeout_s: float) -> Dict[str, Any]:
        import requests

        url = f"{self._sglang_base_url.rstrip('/')}/{endpoint.lstrip('/')}"
        resp = requests.post(url, json=payload, timeout=max(1.0, float(timeout_s)))
        if resp.status_code != 200:
            raise RuntimeError(f"SGLang {endpoint} failed HTTP {resp.status_code}: {resp.text[:500]}")
        try:
            obj = resp.json()
        except Exception:
            obj = {"raw_text": resp.text}
        if isinstance(obj, dict) and obj.get("error"):
            raise RuntimeError(f"SGLang {endpoint} error: {obj.get('error')}")
        return obj if isinstance(obj, dict) else {"response": obj}

    async def _ensure_sglang_lora_loaded(self, lora_path: Optional[str], adapter_id: Optional[str]) -> Optional[str]:
        if not lora_path or not adapter_id:
            return None
        adapter_name = str(adapter_id)
        adapter_path = str(lora_path)
        timeout_s = float(os.environ.get("FAASLORA_SGLANG_LORA_API_TIMEOUT_S", "120") or 120)
        async with self._sglang_lora_lock:
            if adapter_name in self._sglang_loaded_loras:
                return adapter_name
            try:
                await asyncio.to_thread(
                    self._sglang_post_json_sync,
                    "/load_lora_adapter",
                    {"lora_name": adapter_name, "lora_path": adapter_path},
                    timeout_s=timeout_s,
                )
            except RuntimeError as exc:
                message = str(exc)
                if "already loaded" not in message or adapter_name not in message:
                    raise
            self._sglang_loaded_loras[adapter_name] = adapter_path
        return adapter_name

    @staticmethod
    def _sglang_text_fragment(obj: Any) -> str:
        if not isinstance(obj, dict):
            return ""
        parts: List[str] = []
        text = obj.get("text")
        if isinstance(text, str):
            parts.append(text)
        elif isinstance(text, list):
            parts.extend(str(item) for item in text if isinstance(item, str))
        generated_text = obj.get("generated_text")
        if isinstance(generated_text, str):
            parts.append(generated_text)
        token = obj.get("token")
        if isinstance(token, dict) and isinstance(token.get("text"), str):
            parts.append(token["text"])
        return "".join(parts)

    @staticmethod
    def _sglang_meta_metrics(meta_info: Dict[str, Any]) -> Dict[str, Any]:
        def _latency_ms(start: Any, end: Any) -> Optional[float]:
            try:
                start_f = float(start)
                end_f = float(end)
            except Exception:
                return None
            if not math.isfinite(start_f) or not math.isfinite(end_f) or end_f < start_f:
                return None
            return (end_f - start_f) * 1000.0

        metrics: Dict[str, Any] = {}
        if meta_info.get("prompt_tokens") is not None:
            metrics["prompt_tokens"] = int(meta_info.get("prompt_tokens") or 0)
        if meta_info.get("completion_tokens") is not None:
            metrics["completion_tokens"] = int(meta_info.get("completion_tokens") or 0)
        received = meta_info.get("request_received_ts")
        first = meta_info.get("response_sent_to_client_ts")
        finished = meta_info.get("request_finished_ts")
        ttft_ms = _latency_ms(received, first)
        e2e_ms = _latency_ms(received, finished if finished is not None else first)
        if ttft_ms is not None:
            metrics["ttft_ms"] = ttft_ms
        if e2e_ms is not None:
            metrics["e2e_ms"] = e2e_ms
        decode_tps = _safe_float(meta_info.get("decode_throughput"), 0.0)
        if decode_tps > 0.0:
            metrics["tpot_ms"] = 1000.0 / decode_tps
        return metrics

    def _sync_generate_sglang(
        self,
        *,
        prompt: str,
        lora_name: Optional[str],
        max_tokens: int,
        input_tokens: int,
        temperature: float,
        top_p: float,
        generation_seed: Optional[int],
    ) -> Tuple[float, float, int, Dict[str, float]]:
        import requests

        if not self._sglang_base_url:
            raise RuntimeError("SGLang server is not initialized")
        sampling_params: Dict[str, Any] = {
            "temperature": float(temperature),
            "top_p": float(top_p),
            "max_new_tokens": max(1, int(max_tokens)),
        }
        if generation_seed is not None:
            sampling_params["sampling_seed"] = int(generation_seed)
        actual_input_tokens = max(1, int(input_tokens or 1))
        try:
            tokenizer = self._get_prompt_guard_tokenizer()
            input_ids = tokenizer.encode(prompt, add_special_tokens=False)
            actual_input_tokens = max(1, len(input_ids))
        except Exception:
            input_ids = None
        body: Dict[str, Any] = {
            "sampling_params": sampling_params,
            "stream": True,
        }
        if input_ids is not None:
            body["input_ids"] = input_ids
        else:
            body["text"] = prompt
        if lora_name:
            body["lora_path"] = str(lora_name)

        timeout_s = float(os.environ.get("FAASLORA_SGLANG_GENERATE_TIMEOUT_S", self.model_cfg.get("sglang_generate_timeout_s", 7200)) or 7200)
        url = f"{self._sglang_base_url.rstrip('/')}/generate"
        t0 = time.perf_counter()
        first_t: Optional[float] = None
        text_parts: List[str] = []
        meta_metrics: Dict[str, Any] = {}
        raw_preview = ""
        try:
            with requests.post(url, json=body, stream=True, timeout=timeout_s) as resp:
                raw_chunks: List[str] = []
                for chunk in resp.iter_content(chunk_size=None, decode_unicode=True):
                    if not chunk:
                        continue
                    if first_t is None and str(chunk).strip():
                        first_t = time.perf_counter()
                    raw_chunks.append(str(chunk))
                raw_text = "".join(raw_chunks).strip()
                raw_preview = raw_text[:500]
                if resp.status_code != 200:
                    raise RuntimeError(f"SGLang /generate HTTP {resp.status_code}: {raw_preview}")
                stripped = raw_text.lstrip()
                payloads: List[Any] = []
                if stripped.startswith(("{", "[")):
                    payloads.append(json.loads(raw_text))
                else:
                    for line in raw_text.splitlines():
                        line = line.strip()
                        if not line.startswith("data:"):
                            continue
                        payload = line[len("data:") :].strip()
                        if not payload or payload == "[DONE]":
                            continue
                        try:
                            payloads.append(json.loads(payload))
                        except json.JSONDecodeError:
                            continue
                for obj in payloads:
                    if isinstance(obj, list):
                        for item in obj:
                            fragment = self._sglang_text_fragment(item)
                            if fragment:
                                text_parts.append(fragment)
                            if isinstance(item, dict) and isinstance(item.get("meta_info"), dict):
                                meta_metrics.update(self._sglang_meta_metrics(item["meta_info"]))
                    elif isinstance(obj, dict):
                        fragment = self._sglang_text_fragment(obj)
                        if fragment:
                            text_parts.append(fragment)
                        if isinstance(obj.get("meta_info"), dict):
                            meta_metrics.update(self._sglang_meta_metrics(obj["meta_info"]))
                        if obj.get("error"):
                            raise RuntimeError(f"SGLang /generate error: {obj.get('error')}")
        except Exception as exc:
            raise RuntimeError(f"SGLang generate failed: {exc}; raw={raw_preview}") from exc

        t1 = time.perf_counter()
        wall_ms = max(0.0, (t1 - t0) * 1000.0)
        ttft_ms = _positive_or_fallback(meta_metrics.get("ttft_ms"), (first_t - t0) * 1000.0 if first_t is not None else wall_ms)
        e2e_ms = _positive_or_fallback(meta_metrics.get("e2e_ms"), wall_ms)
        generated_text = "".join(text_parts)
        output_tokens = int(meta_metrics.get("completion_tokens") or 0)
        if output_tokens <= 0:
            try:
                tokenizer = self._get_prompt_guard_tokenizer()
                output_tokens = max(1, len(tokenizer.encode(generated_text, add_special_tokens=False)))
            except Exception:
                output_tokens = max(1, int(max_tokens))
        tpot_ms = _positive_or_fallback(
            meta_metrics.get("tpot_ms"),
            max(0.0, e2e_ms - ttft_ms) / max(output_tokens - 1, 1),
        )
        timing = {
            "runtime_estimated_e2e_ms": float(e2e_ms),
            "worker_wall_e2e_ms": float(wall_ms),
            "parent_rpc_wall_ms": float(wall_ms),
            "parent_rpc_overhead_ms": 0.0,
            "actual_prompt_tokens": float(meta_metrics.get("prompt_tokens") or actual_input_tokens),
            "sglang_api_ttft_ms": float((first_t - t0) * 1000.0 if first_t is not None else ttft_ms),
        }
        return float(ttft_ms), float(tpot_ms), int(output_tokens), timing

    async def _generate_sglang(
        self,
        prompt: str,
        lora_path: Optional[str],
        adapter_id: Optional[str],
        max_tokens: int,
        input_tokens: int,
        temperature: float,
        top_p: float,
        generation_seed: Optional[int],
    ) -> Tuple[float, float, int]:
        proc = self._sglang_process
        if not proc or proc.poll() is not None or self._engine_dead:
            self._engine_dead = True
            raise RuntimeError(f"SGLang server is not running (rc={getattr(proc, 'returncode', None)})")
        lora_name = await self._ensure_sglang_lora_loaded(lora_path, adapter_id)
        ttft_ms, tpot_ms, out_tokens, timing = await asyncio.to_thread(
            self._sync_generate_sglang,
            prompt=prompt,
            lora_name=lora_name,
            max_tokens=max_tokens,
            input_tokens=input_tokens,
            temperature=temperature,
            top_p=top_p,
            generation_seed=generation_seed,
        )
        self.last_timing = dict(timing)
        return ttft_ms, tpot_ms, out_tokens

    @staticmethod
    def _derive_vllm_latency_metrics(
        *,
        request_metrics: Optional[Any],
        perf_started_at: float,
        perf_first_token_at: Optional[float],
        perf_finished_at: float,
        output_tokens: int,
    ) -> Tuple[float, float]:
        """
        Derive TTFT/TPOT from vLLM-native metrics when available.

        Some requests only expose non-empty text on the terminal stream update, which
        makes text-based first-token detection collapse TTFT onto total latency and
        incorrectly drives TPOT to zero. RequestMetrics carries authoritative
        arrival/first-token/finished timestamps, so prefer it over local stream
        heuristics whenever those fields are present.
        """
        ttft_ms: Optional[float] = None
        total_ms: Optional[float] = None

        if request_metrics is not None:
            arrival_time = getattr(request_metrics, "arrival_time", None)
            first_token_time = getattr(request_metrics, "first_token_time", None)
            finished_time = getattr(request_metrics, "finished_time", None)
            last_token_time = getattr(request_metrics, "last_token_time", None)

            if (
                arrival_time is not None
                and first_token_time is not None
                and float(first_token_time) >= float(arrival_time)
            ):
                ttft_ms = (float(first_token_time) - float(arrival_time)) * 1000.0

            terminal_time = finished_time
            if terminal_time is None:
                terminal_time = last_token_time
            if (
                arrival_time is not None
                and terminal_time is not None
                and float(terminal_time) >= float(arrival_time)
            ):
                total_ms = (float(terminal_time) - float(arrival_time)) * 1000.0

        if ttft_ms is None:
            local_first_token = perf_first_token_at if perf_first_token_at is not None else perf_finished_at
            ttft_ms = max(0.0, (float(local_first_token) - float(perf_started_at)) * 1000.0)
        if total_ms is None:
            total_ms = max(0.0, (float(perf_finished_at) - float(perf_started_at)) * 1000.0)

        ttft_ms = min(max(0.0, float(ttft_ms)), max(0.0, float(total_ms)))
        decode_ms = max(float(total_ms) - float(ttft_ms), 0.0)
        tpot_ms = decode_ms / max(int(output_tokens) - 1, 1)
        return float(ttft_ms), float(tpot_ms)

    async def generate(
        self,
        prompt: str,
        lora_path: Optional[str],
        adapter_id: Optional[str],
        max_tokens: int,
        input_tokens: int,
        temperature: float = 0.7,
        top_p: float = 0.9,
        *,
        generation_seed: Optional[int] = None,
        _prepared_request: Optional[RequestExecutionPlan] = None,
        return_timing: bool = False,
        gpu_reference: Optional[Dict[str, Any]] = None,
        native_event_observer: Optional[Callable[[Dict[str, Any]], None]] = None,
        pending_admission_id: Optional[str] = None,
    ) -> Tuple[float, float, int]:
        """Returns (vllm_ttft_ms, tpot_ms, output_tokens[, timing]). Always real inference."""
        timing_contract = self.model_cfg.get("timing_contract", "legacy")
        if native_event_observer is not None and timing_contract != 'ieee_tc_native_v1':
            raise ValueError('service events require the native timing contract')
        if timing_contract not in {"legacy", "ieee_tc_native_v1"}:
            raise ValueError(f"unsupported timing contract: {timing_contract}")
        native_timing = timing_contract == "ieee_tc_native_v1"
        if native_timing and self.backend != "vllm":
            raise ValueError("native V1 timing is only qualified for the vLLM path")
        if self.model_cfg.get("ieee_gpu_references", False) and not native_timing:
            raise ValueError("native GPU references require the native V1 terminal/timing contract")
        if pending_admission_id is not None and (
                not isinstance(pending_admission_id, str) or not pending_admission_id
                or not native_timing or self.model_cfg.get('ieee_admission_profile') is None):
            raise ValueError('pending generation requires an explicit native admission identity/profile')
        async with self._lock:
            self._counter += 1
            req_id = pending_admission_id if pending_admission_id is not None else f"req_{self._counter}"
        if (self.model_cfg.get('ieee_admission_profile') is not None
                and pending_admission_id is None):
            raise ValueError('native proactive admission requires registered controller demand')

        if self.backend == "transformers":
            ttft_ms, tpot_ms, out_tokens = await self._generate_transformers(
                prompt=prompt,
                lora_path=lora_path,
                adapter_id=adapter_id,
                max_tokens=max_tokens,
                temperature=temperature,
                top_p=top_p,
            )
            if return_timing:
                return ttft_ms, tpot_ms, out_tokens, dict(self.last_timing or {})
            return ttft_ms, tpot_ms, out_tokens

        if self.backend == "sglang":
            try:
                if _prepared_request is not None:
                    prompt = _prepared_request.prompt
                    input_tokens = _prepared_request.input_tokens
                    safe_max_tokens = _prepared_request.max_tokens
                else:
                    prompt, input_tokens, safe_max_tokens = self._prepare_vllm_prompt(
                        prompt=prompt,
                        max_tokens=max_tokens,
                        input_tokens_hint=input_tokens,
                    )
                ttft_ms, tpot_ms, out_tokens = await self._generate_sglang(
                    prompt=prompt,
                    lora_path=lora_path,
                    adapter_id=adapter_id,
                    max_tokens=safe_max_tokens,
                    input_tokens=input_tokens,
                    temperature=temperature,
                    top_p=top_p,
                    generation_seed=generation_seed,
                )
                if return_timing:
                    return ttft_ms, tpot_ms, out_tokens, dict(self.last_timing or {})
                return ttft_ms, tpot_ms, out_tokens
            except Exception as exc:
                exc_s = str(exc).lower()
                if _is_fatal_engine_error_message(exc_s) or "server is not running" in exc_s:
                    self._engine_dead = True
                raise RuntimeError(f"SGLang: {exc}") from exc

        if self.engine is None or self._engine_dead:
            raise RuntimeError("vLLM engine is not initialised or dead")

        try:
            if _prepared_request is not None:
                prompt = _prepared_request.prompt
                input_tokens = _prepared_request.input_tokens
                safe_max_tokens = _prepared_request.max_tokens
            else:
                prompt, input_tokens, safe_max_tokens = self._prepare_vllm_prompt(
                    prompt=prompt,
                    max_tokens=max_tokens,
                    input_tokens_hint=input_tokens,
                )
            sampling_kwargs = {
                "temperature": temperature,
                "top_p": top_p,
                "max_tokens": safe_max_tokens,
            }
            generation_contract = str(
                self.model_cfg.get("generation_contract", "legacy") or "legacy"
            ).strip().lower()
            if generation_contract == "fixed_length_greedy_v1":
                sampling_kwargs.update(
                    {
                        "temperature": 0.0,
                        "top_p": 1.0,
                        "ignore_eos": True,
                        "stop": [],
                        "stop_token_ids": [],
                    }
                )
            if generation_seed is not None:
                sampling_kwargs["seed"] = int(generation_seed)
            sp = SamplingParams(**sampling_kwargs)

            lora_req = None
            if self._lora_in_engine and lora_path and adapter_id:
                int_id = self._lora_int_id(adapter_id)
                lora_req = LoRARequest(lora_name=adapter_id, lora_int_id=int_id, lora_path=lora_path)
            if generation_contract == "fixed_length_greedy_v1" and (adapter_id or lora_path) and lora_req is None:
                raise ValueError("fixed-output adapter request cannot fall back to the base model")

            reference_receipt = None
            if self.model_cfg.get("ieee_gpu_references", False) and adapter_id:
                if lora_req is None or not isinstance(gpu_reference, dict):
                    raise ValueError("native adapter generation requires its dispatch reference")
                reference_receipt = await self.ieee_gpu_reference(
                    operation="begin_use", lease_id=gpu_reference['lease_id'],
                    expected_owner_id=gpu_reference['owner_id'],
                    adapter_int_id=int_id, backend_request_id=req_id,
                    lora_name=adapter_id, lora_path=lora_path)
                lease_id = reference_receipt['lease_id']
                if lease_id in self._ieee_generation_refs:
                    raise ValueError('native lease cannot bind a second generation')
                self._ieee_generation_refs[lease_id] = {
                    'owner_id': reference_receipt['owner_id'], 'backend_request_id': req_id}
            elif gpu_reference is not None:
                raise ValueError("dispatch reference supplied outside its native adapter contract")

            t0 = time.perf_counter()
            timeline = None
            if native_timing:
                from faaslora.metrics.metrics_collector import NativeV1TokenTimeline, local_monotonic_clock_id
                timeline = NativeV1TokenTimeline(t0, local_monotonic_clock_id())
            first_t = None
            tok_count = 0
            final_token_ids: List[int] = []
            native_prompt_ids = None
            actual_prompt_tokens = max(1, int(input_tokens or 1))
            last_metrics = None
            backend_terminal = False
            first_event_sent = False

            def emit_service_event(kind: str, timestamp: float, sequence: int) -> None:
                if native_event_observer is None:
                    return
                event = dict(contract='native_service_events_v1', kind=kind,
                             sequence=sequence, backend_request_id=req_id,
                             native_clock_id=timeline.clock_id,
                             timestamp_monotonic_s=timestamp,
                             token_count=len(timeline.token_ids), adapter_id=adapter_id,
                             gpu_reference_owner_id=None, gpu_reference_lease_id=None,
                             gpu_reference_adapter_int_id=None)
                if reference_receipt is not None:
                    event.update(gpu_reference_owner_id=reference_receipt['owner_id'],
                                 gpu_reference_lease_id=reference_receipt['lease_id'],
                                 gpu_reference_adapter_int_id=reference_receipt['adapter_int_id'])
                _notify_native_service_observer(native_event_observer, event)

            outputs = (self.engine.ieee_generate_pending(req_id, prompt, sp, lora_request=lora_req)
                if pending_admission_id is not None else
                self.engine.generate(prompt=prompt, sampling_params=sp, request_id=req_id, lora_request=lora_req))
            async for out in outputs:
                if native_timing and out.finished:
                    # The native frontend can synthesize finished=True on abort;
                    # only ordinary native completion can count as successful work.
                    if (len(out.outputs) != 1
                            or getattr(out.outputs[0], 'finish_reason', None) not in ('length', 'stop')):
                        raise ValueError('non-success native finish reason; reference retained')
                    if generation_contract == 'fixed_length_greedy_v1' and out.outputs[0].finish_reason != 'length':
                        raise ValueError('fixed-output native completion must finish by length')
                metrics = getattr(out, "metrics", None)
                if metrics is not None:
                    last_metrics = metrics
                prompt_token_ids = getattr(out, "prompt_token_ids", None)
                if prompt_token_ids is not None:
                    if native_timing:
                        ids = list(prompt_token_ids)
                        if not ids or any(type(token) is not int or token < 0 for token in ids):
                            raise ValueError("missing/invalid native prompt token IDs")
                        if native_prompt_ids is not None and native_prompt_ids != ids:
                            raise ValueError("native prompt token IDs changed during generation")
                        native_prompt_ids = ids
                    actual_prompt_tokens = max(1, len(prompt_token_ids))
                if out.outputs:
                    if native_timing and len(out.outputs) != 1:
                        raise ValueError("IEEE native timing requires exactly one output sequence")
                    current_output = out.outputs[0]
                    if not native_timing and first_t is None and len(getattr(current_output, "token_ids", []) or []) > 0:
                        first_t = time.perf_counter()
                    if timeline is not None:
                        timeline.observe(metrics, current_output.token_ids, finished=out.finished)
                    tok_count = len(getattr(current_output, "token_ids", []) or [])
                    final_token_ids = [
                        int(token_id)
                        for token_id in (getattr(current_output, "token_ids", []) or [])
                    ]
                elif timeline is not None:
                    timeline.observe(metrics, timeline.token_ids, finished=out.finished)
                if timeline is not None and timeline.first_at is not None and not first_event_sent:
                    emit_service_event('first_token', timeline.first_at, 1)
                    first_event_sent = True
                if reference_receipt is not None and out.finished:
                    await self.ieee_retire_generation(gpu_reference=reference_receipt, abort=False)
                    backend_terminal = True

            t1 = time.perf_counter()
            if reference_receipt is not None and not backend_terminal:
                raise ValueError("backend stream ended without terminal acknowledgement; reference retained")
            native_fields = timeline.finalize(t1) if timeline is not None else {}
            if native_timing:
                if native_prompt_ids is None:
                    raise ValueError("native prompt token IDs required; input hint is not evidence")
                ttft_ms = native_fields["native_ttft_ms"]
                # Tuple transport remains numeric for historical RPC consumers.
                # The auditable native_tpot_ms is null for a single output token.
                tpot_ms = native_fields["native_tpot_ms"] if tok_count > 1 else 0.
                if generation_contract == "fixed_length_greedy_v1" and tok_count != safe_max_tokens:
                    raise ValueError("native output length violates fixed_length_greedy_v1")
                emit_service_event('last_token', timeline.last_at, 2)
            else:
                ttft_ms, tpot_ms = self._derive_vllm_latency_metrics(
                    request_metrics=last_metrics,
                    perf_started_at=t0,
                    perf_first_token_at=first_t,
                    perf_finished_at=t1,
                    output_tokens=tok_count,
                )
            runtime_estimated_e2e_ms = float(ttft_ms) + (
                float(tpot_ms) * max(int(tok_count or 0) - 1, 0)
            )
            worker_wall_e2e_ms = max(0.0, (float(t1) - float(t0)) * 1000.0)
            timing = {
                "runtime_estimated_e2e_ms": max(0.0, runtime_estimated_e2e_ms),
                "worker_wall_e2e_ms": worker_wall_e2e_ms,
                "parent_rpc_wall_ms": worker_wall_e2e_ms,
                "parent_rpc_overhead_ms": 0.0,
                "actual_prompt_tokens": actual_prompt_tokens,
                "completion_token_ids_sha256": hashlib.sha256(
                    json.dumps(final_token_ids, separators=(",", ":")).encode("utf-8")
                ).hexdigest(),
                **native_fields,
            }
            if native_timing:
                timing['backend_request_id'] = req_id
                timing['native_prompt_token_ids_sha256'] = hashlib.sha256(
                    json.dumps(native_prompt_ids, separators=(",", ":")).encode("utf-8")).hexdigest()
            if reference_receipt is not None:
                timing.update(gpu_reference_owner_id=reference_receipt['owner_id'],
                              gpu_reference_lease_id=reference_receipt['lease_id'],
                              gpu_reference_adapter_int_id=reference_receipt['adapter_int_id'],
                              gpu_reference_acquired_monotonic_s=reference_receipt['acquired_monotonic_s'])
            self.last_timing = dict(timing)
            if return_timing:
                return ttft_ms, tpot_ms, tok_count, timing
            return ttft_ms, tpot_ms, tok_count

        except Exception as exc:
            exc_s = str(exc).lower()
            is_dead = _is_fatal_engine_error_message(exc_s) or any(
                k in exc_s for k in ("dead", "cancelled", "died")
            )
            # TC attempts must be visible to the outer lifecycle/retry owner;
            # recursive hidden retries would reset dispatch and erase resource cost.
            allow_reinit = not native_timing and is_dead and not any(
                marker in exc_s for marker in ("cuda out of memory", "background loop has errored already")
            )
            if is_dead:
                self._engine_dead = True
                if allow_reinit:
                    async with self._reinit_lock:
                        if not self._reinit_attempted:
                            self._reinit_attempted = True
                            print(f"\n  [ENGINE DEAD] vLLM engine crashed: {str(exc)[:120]}")
                            print("  Attempting reinitialisation ...")
                            await self.reinitialize()
                    if self.engine is not None and not self._engine_dead:
                        return await self.generate(
                            prompt, lora_path, adapter_id,
                            max_tokens, input_tokens, temperature, top_p,
                            generation_seed=generation_seed,
                        )
            raise RuntimeError(f"vLLM: {exc}") from exc

    async def generate_prepared(
        self,
        *,
        request_plan: RequestExecutionPlan,
        lora_path: Optional[str],
        adapter_id: Optional[str],
        temperature: float = 0.7,
        top_p: float = 0.9,
        generation_seed: Optional[int] = None,
        return_timing: bool = False,
        gpu_reference: Optional[Dict[str, Any]] = None,
        native_event_observer: Optional[Callable[[Dict[str, Any]], None]] = None,
        pending_admission_id: Optional[str] = None,
    ) -> Tuple[float, float, int]:
        return await self.generate(
            prompt=request_plan.prompt,
            lora_path=lora_path,
            adapter_id=adapter_id,
            max_tokens=request_plan.max_tokens,
            input_tokens=request_plan.input_tokens,
            temperature=temperature,
            top_p=top_p,
            generation_seed=generation_seed,
            _prepared_request=request_plan,
            return_timing=return_timing,
            **({"gpu_reference": gpu_reference} if gpu_reference is not None else {}),
            **({"native_event_observer": native_event_observer} if native_event_observer is not None else {}),
            **({'pending_admission_id': pending_admission_id} if pending_admission_id is not None else {}),
        )

    @staticmethod
    def _lora_int_id(adapter_id: str) -> int:
        import hashlib
        return (int(hashlib.md5(adapter_id.encode()).hexdigest(), 16) % 999999) + 1

    async def ieee_worker_observation(self, *, synchronize: bool = False) -> Dict[str, Any]:
        """Strict qualification RPC; unlike shutdown helpers, never swallows errors."""
        if not self.model_cfg.get("ieee_worker_observation", False):
            raise RuntimeError("native worker observation was not enabled at engine creation")
        if self.backend != "vllm" or self.engine is None or self._engine_dead:
            raise RuntimeError("native worker observation requires a live vLLM engine")
        rpc = getattr(self.engine, "collective_rpc", None)
        if not callable(rpc):
            raise RuntimeError("backend lacks native worker collective RPC")
        observations = rpc("ieee_worker_observation", kwargs={"synchronize": synchronize})
        if inspect.isawaitable(observations):
            observations = await observations
        if not isinstance(observations, list) or not observations:
            raise RuntimeError("empty or invalid native worker observations")
        expected = int(self.model_cfg.get("tensor_parallel_size", 1))
        if len(observations) != expected:
            raise RuntimeError("worker observation count differs from configured TP")
        return {"workers": observations, "production_launch_authorized": False}

    async def ieee_scheduler_observation(self) -> Dict[str, Any]:
        """Read the native scheduler owner, never reconstruct KV from worker RAM."""
        if not self.model_cfg.get("ieee_scheduler_observation", False):
            raise RuntimeError("native scheduler observation was not enabled at engine creation")
        if self.backend != "vllm" or self.engine is None or self._engine_dead:
            raise RuntimeError("native scheduler observation requires a live vLLM engine")
        core = getattr(self.engine, "engine_core", None)
        rpc = getattr(core, "call_utility_async", None)
        if not callable(rpc):
            raise RuntimeError("backend lacks qualified native engine-core utility RPC")
        observation = await rpc("ieee_scheduler_observation")
        from faaslora.clock import local_monotonic_clock_id
        if (not isinstance(observation, dict)
                or observation.get("kind") != "ieee_native_scheduler_observation_v1"
                or observation.get("clock_id") != local_monotonic_clock_id()
                or observation.get("admission_reservation") is not False
                or observation.get("production_launch_authorized") is not False):
            raise RuntimeError("invalid native scheduler observation identity/clock/authority")
        return observation

    async def ieee_prepare_host(self, **command) -> Dict[str, Any]:
        """Native E(t) decision and fenced HOST promotion in one owner call.

        The returned reference is a preparation lease, not a request dispatch.
        Callers must settle cancellation/transport uncertainty before releasing
        it. Registered controller demand and native unfinished requests share
        the core's KV prediction set. Cold HOST materialization/all-tier budgets
        remain outside this narrow operation; no Full gate is granted.
        """
        if (self.model_cfg.get('ieee_admission_profile') is None
                or not self.model_cfg.get('ieee_gpu_references', False)
                or not self.model_cfg.get('ieee_scheduler_observation', False)):
            raise RuntimeError('native preparation requires explicit admission profile and owners')
        if self.backend != 'vllm' or self.engine is None or self._engine_dead:
            raise RuntimeError('native preparation requires a live vLLM engine')
        rpc = getattr(getattr(self.engine, 'engine_core', None), 'call_utility_async', None)
        if not callable(rpc):
            raise RuntimeError('backend lacks the native preparation utility')
        result = await rpc('ieee_prepare_host', command)
        from faaslora.clock import local_monotonic_clock_id
        if (not isinstance(result, dict) or type(result.get('acquired')) is not bool
                or result.get('clock_id') != local_monotonic_clock_id()
                or result.get('production_launch_authorized') is not False):
            raise RuntimeError('invalid native preparation acknowledgement')
        return result

    async def ieee_transfer_event(self, **command):
        if (self.model_cfg.get('ieee_admission_profile') is None
                or not self.model_cfg.get('ieee_gpu_references', False)
                or not self.model_cfg.get('ieee_scheduler_observation', False)):
            raise RuntimeError('file transfer pressure requires native admission configuration')
        if self.backend != 'vllm' or self.engine is None or self._engine_dead:
            raise RuntimeError('file transfer pressure requires a live vLLM engine')
        rpc = getattr(getattr(self.engine, 'engine_core', None), 'call_utility_async', None)
        if not callable(rpc):
            raise RuntimeError('backend lacks the native transfer utility')
        result = await rpc('ieee_transfer_event', command)
        if (not isinstance(result, dict) or result.get('kind') != 'ieee_adapter_transfer_event_v1'
                or result.get('transfer_id') != command.get('transfer_id')
                or result.get('state') != {'start': 'active', 'finish': 'finished',
                    'attach_domain': 'attached'}.get(command.get('operation'))):
            raise ValueError('file transfer event lacks matching scheduler acknowledgement')
        return result

    async def ieee_register_pending(self, *, intent_id, prompt, max_tokens, adapter_id):
        if (self.model_cfg.get('ieee_admission_profile') is None
                or self.model_cfg.get('generation_contract') != 'fixed_length_greedy_v1'
                or self.backend != 'vllm' or self.engine is None or self._engine_dead):
            raise ValueError('pending admission requires the configured native fixed-output owner')
        params = SamplingParams(temperature=0., top_p=1., max_tokens=max_tokens,
            ignore_eos=True, stop=[], stop_token_ids=[])
        return await self.engine.ieee_register_pending(intent_id, prompt, params,
            self._lora_int_id(adapter_id) if adapter_id is not None else None)

    async def ieee_close_pending(self, *, intent_id):
        if self.backend != 'vllm' or self.engine is None or self._engine_dead:
            raise ValueError('pending retirement requires its live native owner')
        result = await self.engine.ieee_close_pending(intent_id)
        from faaslora.clock import local_monotonic_clock_id
        if result.get('clock_id') != local_monotonic_clock_id():
            raise ValueError('pending retirement clock mismatch')
        withdrawn = (result.get('kind') == 'ieee_pending_admission_v1'
            and result.get('intent_id') == intent_id and result.get('state') == 'withdrawn')
        retired = (result.get('kind') == 'ieee_native_request_retirement_v1'
            and result.get('external_request_id') == intent_id and result.get('retired') is True)
        if not (withdrawn or retired):
            raise ValueError('pending demand lacks withdrawal or native retirement proof')
        return dict(intent_id=intent_id, closed=True, receipt=result)

    async def ieee_gpu_reference(self, *, operation: str, **kwargs) -> Dict[str, Any]:
        """Forward an explicit native owner operation; no inferred success."""
        if not self.model_cfg.get("ieee_gpu_references", False):
            raise RuntimeError("native GPU reference owner was not enabled")
        if (int(self.model_cfg.get("tensor_parallel_size", 1)) != 1
                or int(self.model_cfg.get("pipeline_parallel_size", 1)) != 1):
            raise RuntimeError("native references currently require TP=PP=1")
        if self.backend != "vllm" or self.engine is None or self._engine_dead:
            raise RuntimeError("native references require a live vLLM engine")
        if operation not in ("snapshot", "source_snapshot", "acquire", "release", "evict", "begin_use", "end_use",
                             "demand_load_and_acquire", "hold_host_source", "release_host_source",
                             "prepare_file_host_and_hold", "configure_host_budget",
                             "register_preparation_plan", "finish_preparation_target", "close_preparation_plan"):
            raise ValueError("unknown GPU reference operation")
        rpc = getattr(self.engine, "collective_rpc", None)
        if not callable(rpc):
            raise RuntimeError("backend lacks native worker collective RPC")
        results = rpc("ieee_gpu_reference", kwargs={"operation": operation, **kwargs})
        if inspect.isawaitable(results):
            results = await results
        if not isinstance(results, list) or len(results) != 1 or not isinstance(results[0], dict):
            raise RuntimeError("invalid single-worker reference acknowledgement")
        return results[0]

    async def ieee_generation_observation(self) -> Dict[str, Any]:
        """Read-only exact frontend IDs; not a native retirement acknowledgement."""
        if not self.model_cfg.get('ieee_gpu_references', False):
            raise ValueError('native generation observation contract required')
        return {'bindings': {lease: {'owner_id': value['owner_id'],
                                     'backend_request_id': value['backend_request_id']}
                             for lease, value in self._ieee_generation_refs.items()},
                'frontend_mapping': {key: list(value) for key, value
                    in self.engine.output_processor.external_req_ids.items()}}

    async def ieee_retire_generation(self, *, gpu_reference: Dict[str, Any], abort: bool) -> Dict[str, Any]:
        """Settle one known request, never equate frontend abort with GPU completion."""
        if not self.model_cfg.get('ieee_gpu_references', False) or type(abort) is not bool:
            raise ValueError('native generation retirement contract required')
        lease = gpu_reference['lease_id']
        bound = self._ieee_generation_refs.get(lease)
        if bound is None or bound['owner_id'] != gpu_reference['owner_id']:
            raise ValueError('unknown native generation binding; reference retained')
        # Normal completion and an external abort can reach this boundary
        # together. One lease has one end-use commit, even with two waiters.
        async with bound.setdefault('retirement_lock', asyncio.Lock()):
            if 'retirement' not in bound:
                retirement = await self.engine.ieee_retire_request(bound['backend_request_id'], abort=abort)
                if (retirement.get('retired') is not True
                        or retirement.get('external_request_id') != bound['backend_request_id']):
                    raise ValueError('retirement did not acknowledge this bound request')
                await self.ieee_gpu_reference(operation='end_use', lease_id=lease,
                    expected_owner_id=bound['owner_id'], backend_request_id=bound['backend_request_id'])
                bound['retirement'] = dict(retirement)
        return {'gpu_reference_owner_id': bound['owner_id'], 'gpu_reference_lease_id': lease,
                'native_retirement': dict(bound['retirement'])}

    async def load_lora_to_gpu_and_measure(self, lora_path: str, adapter_id: str) -> Tuple[float, bool]:
        """
        D1: Trigger vLLM LoRA load and measure time until first token (real load latency).
        Runs a minimal generate (1 token) with this LoRA; TTFT includes vLLM internal load.
        Returns (ttft_ms_including_load, success).
        """
        if self.backend == "sglang":
            if self._engine_dead or self._sglang_process is None:
                return 0.0, False
            try:
                ttft_ms, _, _ = await self.generate(
                    prompt="Hi",
                    lora_path=lora_path,
                    adapter_id=adapter_id,
                    max_tokens=1,
                    input_tokens=2,
                    temperature=0.0,
                    top_p=1.0,
                )
                return ttft_ms, True
            except Exception:
                return 0.0, False
        if self.backend != "vllm" or self.engine is None or self._engine_dead:
            return 0.0, False
        try:
            ttft_ms, _, _ = await self.generate(
                prompt="Hi",
                lora_path=lora_path,
                adapter_id=adapter_id,
                max_tokens=1,
                input_tokens=2,
                temperature=0.0,
                top_p=1.0,
            )
            return ttft_ms, True
        except Exception:
            return 0.0, False

    async def unload_lora_adapter(self, adapter_id: str) -> bool:
        if not adapter_id:
            return True
        if self.model_cfg.get("ieee_gpu_references", False):
            result = await self.ieee_gpu_reference(
                operation="evict", adapter_int_id=self._lora_int_id(adapter_id))
            return result["evicted"] or result["reason"] == "absent"
        if self.backend == "transformers":
            async with self._lock:
                if adapter_id not in self._hf_loaded_adapters:
                    return True
                try:
                    if hasattr(self._hf_peft_model, "delete_adapter"):
                        self._hf_peft_model.delete_adapter(adapter_id)
                    self._hf_loaded_adapters.discard(adapter_id)
                    try:
                        self._hf_adapter_lru.remove(adapter_id)
                    except ValueError:
                        pass
                    if len(self._hf_loaded_adapters) == 0 and hasattr(self._hf_peft_model, "unload"):
                        self._hf_peft_model = self._hf_peft_model.unload()
                    return True
                except Exception:
                    return False
        if self.backend == "sglang":
            try:
                await asyncio.to_thread(
                    self._sglang_post_json_sync,
                    "/unload_lora_adapter",
                    {"lora_name": str(adapter_id)},
                    timeout_s=float(os.environ.get("FAASLORA_SGLANG_LORA_API_TIMEOUT_S", "120") or 120),
                )
                self._sglang_loaded_loras.pop(str(adapter_id), None)
                return True
            except Exception:
                return False
        if self.backend != "vllm" or self.engine is None or self._engine_dead:
            return False
        remove_fn = getattr(self.engine, "remove_lora", None)
        if remove_fn is None:
            return False
        try:
            result = remove_fn(self._lora_int_id(adapter_id))
            if asyncio.iscoroutine(result):
                result = await result
            return bool(result)
        except Exception:
            return False


# Shared newline-JSON wire bound, not a model/workload tuning parameter. Both
# directions enforce it; 8 MiB bounds each message (including full-pool plan
# metadata) without depending on asyncio's unrelated 64 KiB reader default.
_RPC_FRAME_MAX_BYTES = 8 * 1024 * 1024


def _encode_rpc_frame(payload: Dict[str, Any]) -> bytes:
    body = json.dumps(payload, ensure_ascii=True).encode('utf-8')
    if len(body) > _RPC_FRAME_MAX_BYTES:
        raise ValueError('dedicated RPC frame exceeds protocol byte limit')
    return body + b'\n'


@dataclass
class _BlockingRPCChannel:
    sock: socket.socket
    recv_buffer: bytearray = field(default_factory=bytearray)


def _notify_native_service_observer(observer, event) -> None:
    """Callbacks update bounded in-memory state in the owner's event loop."""
    result = observer(event)
    if result is not None:
        if inspect.iscoroutine(result):
            result.close()
        raise TypeError('native service observer must be synchronous and return None')


class SubprocessInferenceEngineProxy:
    """
    Async proxy that talks to a dedicated engine subprocess over loopback RPC.

    This keeps dedicated multi-instance scale-out on a multi-GPU host honest:
    each runtime owns its own process and therefore its own CUDA-visible GPU
    set.
    """

    _startup_cleanup_done: bool = False

    def __init__(
        self,
        *,
        process: subprocess.Popen,
        host: str,
        port: int,
        model_cfg: Dict[str, Any],
        cost_model: Dict[str, Any],
        device_id: Optional[int],
        workdir: Path,
        log_path: Path,
        runtime_gpu_ids: Optional[List[int]] = None,
        startup_latency_ms: float = 0.0,
        physical_allocation=None,
    ) -> None:
        self._process = process
        self._host = host
        self._port = int(port)
        self.model_cfg = copy.deepcopy(model_cfg)
        self._cost_model = copy.deepcopy(cost_model)
        self.device_id = int(device_id) if device_id is not None else 0
        self._runtime_gpu_ids = [
            int(gpu_id) for gpu_id in (runtime_gpu_ids or []) if gpu_id is not None
        ]
        self.backend = str(self.model_cfg.get("backend", "vllm")).lower()
        self.engine = None
        self._engine_dead = False
        self._normal_shutdown_completed = False
        self._physical_allocation = physical_allocation
        self._reinit_attempted = False
        self.last_timing: Dict[str, Any] = {}
        self._prompt_planner: Optional[InferenceEngine] = None
        self._workdir = workdir
        self._log_path = log_path
        self.startup_latency_ms = float(startup_latency_ms or 0.0)
        self._rpc_pool_size = _effective_runtime_concurrency_cap(self.model_cfg)
        self._rpc_channel_queue: Optional[asyncio.Queue] = None
        self._rpc_channel_init_lock = asyncio.Lock()
        self._rpc_channels: List["_BlockingRPCChannel"] = []
        # A lost reply does not prove that the native process died. Keep each
        # uncertain mutation until its exact owner/lease can be reconciled.
        self._native_rpc_uncertain: Dict[str, Dict[str, Any]] = {}

    @staticmethod
    def _worker_script_path() -> Path:
        return Path(__file__).resolve().with_name("dedicated_engine_worker.py")

    @staticmethod
    def _tail_worker_log(log_path: Path, max_chars: int = 4000) -> str:
        try:
            text = log_path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            return ""
        text = text.strip()
        if len(text) <= max_chars:
            return text
        return text[-max_chars:]

    def _with_worker_log_context(self, message: str, max_chars: int = 6000) -> str:
        parts = [
            str(message).rstrip(),
            f"worker_root={self._workdir}",
            f"worker_log={self._log_path}",
        ]
        log_tail = self._tail_worker_log(self._log_path, max_chars=max_chars)
        if log_tail:
            parts.append(f"worker_log_tail:\n{log_tail}")
        return "\n".join(part for part in parts if part)

    def _preserve_worker_workdir(self, reason: str) -> None:
        archive_root = Path(
            os.environ.get("FAASLORA_WORKER_LOG_ARCHIVE_DIR")
            or (REPO_ROOT / "results" / "worker_failures")
        )
        try:
            archive_root.mkdir(parents=True, exist_ok=True)
            safe_reason = "".join(ch if ch.isalnum() or ch in {"-", "_"} else "_" for ch in reason)
            archive_dir = archive_root / f"{self._workdir.name}_{safe_reason}_{int(time.time())}"
            shutil.copytree(self._workdir, archive_dir, dirs_exist_ok=True)
            print(f"[worker-log] preserved dedicated worker workdir: {archive_dir}")
        except Exception as exc:
            print(f"[worker-log] failed to preserve {self._workdir}: {exc}")

    @staticmethod
    def _keep_worker_logs_requested() -> bool:
        raw = os.environ.get("FAASLORA_KEEP_DEDICATED_WORKER_LOGS", "")
        return str(raw).strip().lower() in {"1", "true", "yes", "on"}

    @staticmethod
    def _write_process_meta(workdir: Path, process: subprocess.Popen) -> None:
        try:
            pgid = os.getpgid(process.pid)
        except Exception:
            pgid = process.pid
        try:
            (workdir / "process.json").write_text(
                json.dumps({"pid": int(process.pid), "pgid": int(pgid)}),
                encoding="utf-8",
            )
        except Exception:
            pass

    @classmethod
    async def spawn(
        cls,
        *,
        model_cfg: Dict[str, Any],
        cost_model: Dict[str, Any],
        device_id: Optional[int],
        runtime_gpu_ids: Optional[List[int]] = None,
    ) -> "SubprocessInferenceEngineProxy":
        spawn_started_at = time.perf_counter()
        if not cls._startup_cleanup_done:
            if os.environ.get("FAASLORA_TC_LAUNCH_RECEIPT"):
                from scripts.ieee_tc_preflight import verify_current_service
                verify_current_service()
            else:
                _kill_stale_dedicated_worker_process_groups()
            cls._startup_cleanup_done = True

        requested_device_id = int(device_id) if device_id is not None else None
        local_model_cfg, worker_env_updates = _prepare_dedicated_subprocess_model_cfg(
            model_cfg,
            device_id=requested_device_id,
            runtime_gpu_ids=runtime_gpu_ids,
        )
        worker_env = _ieee_native_allocator_environment(local_model_cfg, os.environ)

        worker_root = Path(tempfile.mkdtemp(prefix="faaslora_worker_", dir="/tmp"))
        if str(local_model_cfg.get("backend", "") or "").lower() == "sglang":
            sglang_workdir_base = worker_root / "sglang"
            sglang_workdir_base.mkdir(parents=True, exist_ok=True)
            local_model_cfg["sglang_workdir_base"] = str(sglang_workdir_base)
        payload_path = worker_root / "payload.json"
        ready_path = worker_root / "ready.json"
        log_path = worker_root / "worker.log"

        payload = {
            "repo_root": str(REPO_ROOT),
            "model_cfg": local_model_cfg,
            "cost_model": copy.deepcopy(cost_model),
            "device_id": local_model_cfg.get("device_id"),
        }
        payload_path.write_text(json.dumps(payload), encoding="utf-8")

        python_bin = os.environ.get("FAASLORA_PYTHON") or sys.executable
        worker_script = cls._worker_script_path()
        worker_env["PYTHONPATH"] = str(REPO_ROOT) + os.pathsep + worker_env.get("PYTHONPATH", "")
        worker_env.update(worker_env_updates)

        log_handle = open(log_path, "ab", buffering=0)
        allocation = None
        if local_model_cfg.get('ieee_physical_allocation', False):
            from scripts.ieee_tc_preflight import (
                verify_current_service, NativeGPUCensus, load_nvml_binding, gpu_process_identity)
            from faaslora.metrics.metrics_collector import PhysicalGPUAllocation
            service = verify_current_service()
            census = NativeGPUCensus(load_nvml_binding(
                Path(os.environ['FAASLORA_TC_NVML_BINDING']), os.environ['FAASLORA_TC_NVML_SHA256']))
            try:
                allocation = PhysicalGPUAllocation(
                    root=Path(os.environ['FAASLORA_TC_LAUNCH_RECEIPT']).parent/'physical_allocations',
                    census=census, service_path=Path(service['service_identity']['path']),
                    device_indices=[int(i) for i in worker_env_updates['CUDA_VISIBLE_DEVICES'].split(',')],
                    owner_identity=gpu_process_identity(os.getpid()))
            except BaseException:
                census.close()
                log_handle.close()
                raise
            # NVML and CUDA ordinals need not have the same order. A fresh worker
            # receives the actual allocated UUIDs before importing either backend.
            visible = ','.join(allocation.gpu_uuids)
            worker_env.update(CUDA_VISIBLE_DEVICES=visible, FAASLORA_VISIBLE_DEVICES=visible)
        try:
            process = subprocess.Popen(
            [
                python_bin,
                str(worker_script),
                "--payload",
                str(payload_path),
                "--ready-file",
                str(ready_path),
            ],
            cwd=str(REPO_ROOT),
            env=worker_env,
            stdout=log_handle,
            stderr=subprocess.STDOUT,
            close_fds=True,
            start_new_session=True,
            )
        except BaseException:
            log_handle.close()
            if allocation is not None:
                allocation.release()
            raise
        cls._write_process_meta(worker_root, process)

        async def _terminate_startup_process() -> None:
            sglang_marker = worker_root / "sglang"
            try:
                if process.poll() is not None:
                    if sglang_marker.exists():
                        await asyncio.to_thread(
                            _terminate_processes_by_cmdline_marker,
                            sglang_marker,
                            grace_s=1.0,
                        )
                    return
            except Exception:
                pass
            try:
                pgid = os.getpgid(process.pid)
                os.killpg(pgid, signal.SIGTERM)
                await asyncio.to_thread(process.wait, 5)
            except Exception:
                pass
            if sglang_marker.exists():
                await asyncio.to_thread(
                    _terminate_processes_by_cmdline_marker,
                    sglang_marker,
                    grace_s=1.0,
                )
            try:
                if process.poll() is None:
                    pgid = os.getpgid(process.pid)
                    os.killpg(pgid, signal.SIGKILL)
                    await asyncio.to_thread(process.wait, 5)
            except Exception:
                pass

        ready: Optional[Dict[str, Any]] = None
        try:
            if allocation is not None:
                allocation.bind_process(process, gpu_process_identity(process.pid))
            startup_timeout_s = float(os.environ.get("FAASLORA_WORKER_START_TIMEOUT_S", "180"))
            startup_timeout_s = max(30.0, startup_timeout_s)
            deadline = time.monotonic() + startup_timeout_s
            while time.monotonic() < deadline:
                if ready_path.exists():
                    try:
                        ready = json.loads(ready_path.read_text(encoding="utf-8"))
                    except Exception:
                        ready = {"status": "error", "error": "invalid_ready_payload"}
                    break
                if process.poll() is not None:
                    break
                await asyncio.sleep(0.2)
        except BaseException:
            try:
                log_handle.close()
            except Exception:
                pass
            await _terminate_startup_process()
            if allocation is not None:
                allocation.release()
            raise
        finally:
            try:
                log_handle.close()
            except Exception:
                pass

        if not isinstance(ready, dict) or ready.get("status") != "ready":
            await _terminate_startup_process()
            if allocation is not None:
                allocation.release()
            error = ready.get("error") if isinstance(ready, dict) else "subprocess_worker_timeout"
            log_tail = cls._tail_worker_log(log_path)
            error = (
                f"{error}\nworker_root={worker_root}\nworker_log={log_path}"
            )
            if log_tail:
                error = f"{error}\nworker_log_tail:\n{log_tail}"
            raise RuntimeError(f"subprocess_engine_start_failed: {error}")

        try:
            from faaslora.runtime_configuration import initialized_worker_configuration
            initialized_cfg = initialized_worker_configuration(ready, local_model_cfg)
        except BaseException:
            await _terminate_startup_process()
            if allocation is not None:
                allocation.release()
            raise

        proxy = cls(
            process=process,
            host=str(ready["host"]),
            port=int(ready["port"]),
            model_cfg=initialized_cfg,
            cost_model=copy.deepcopy(cost_model),
            device_id=requested_device_id,
            workdir=worker_root,
            log_path=log_path,
            runtime_gpu_ids=runtime_gpu_ids,
            startup_latency_ms=max(0.0, (time.perf_counter() - spawn_started_at) * 1000.0),
            physical_allocation=allocation,
        )
        proxy.model_config_source = ready['configuration_contract']
        if allocation is not None:
            try:
                workers = await proxy.ieee_worker_observation()
                allocation.confirm_workers(workers['workers'])
            except BaseException:
                await proxy.shutdown()
                raise
        return proxy

    async def _rpc(self, cmd: str, *, _native_event_observer=None, **kwargs: Any) -> Dict[str, Any]:
        if self._engine_dead or self._process.poll() is not None:
            self._engine_dead = True
            raise RuntimeError(self._with_worker_log_context("subprocess_engine_dead"))
        native = self.model_cfg.get('timing_contract') == 'ieee_tc_native_v1'
        if _native_event_observer is not None and (not native or cmd != 'generate'):
            raise ValueError('service progress requires native generation')
        control = native and cmd != 'generate'
        if native and cmd == 'generate' and self._native_rpc_uncertain:
            raise RuntimeError('native RPC ownership unresolved; new generation withheld')
        attempt_id = uuid.uuid4().hex
        progress_open = True
        progress_events = []
        owner_task = asyncio.current_task()
        loop = asyncio.get_running_loop()

        async def deliver_progress(frame):
            # Run in the owning event loop, never the blocking socket thread.
            if not progress_open or owner_task.cancelling():
                raise RuntimeError('service progress arrived after RPC cancellation')
            if frame.get('native_event_rpc_id') != attempt_id:
                raise ValueError('service progress RPC identity mismatch')
            event = frame.get('native_event')
            index = len(progress_events)
            if (not isinstance(event, dict) or index >= 2
                    or event.get('contract') != 'native_service_events_v1'
                    or type(event.get('sequence')) is not int
                    or event['sequence'] != index + 1
                    or event.get('kind') != ('first_token', 'last_token')[index]):
                raise ValueError('invalid service progress sequence')
            _notify_native_service_observer(_native_event_observer, event)
            progress_events.append(dict(event))

        def receive_progress(frame):
            asyncio.run_coroutine_threadsafe(deliver_progress(frame), loop).result()
        def retain_uncertain() -> None:
            if not native or cmd in ('ieee_worker_observation', 'ieee_scheduler_observation',
                                     'ieee_generation_observation', 'shutdown'):
                return
            if cmd == 'ieee_gpu_reference' and kwargs.get('operation') in ('snapshot', 'source_snapshot'):
                return
            ref = kwargs.get('gpu_reference') or {}
            self._native_rpc_uncertain[attempt_id] = {
                'cmd': cmd, 'operation': kwargs.get('operation'),
                'intent_id': kwargs.get('intent_id'),
                'preparation_plan_id': kwargs.get('preparation_plan_id', kwargs.get('plan_id')),
                'transfer_id': kwargs.get('transfer_id'),
                'owner_id': ref.get('owner_id', kwargs.get('expected_owner_id')),
                'lease_id': ref.get('lease_id', kwargs.get('lease_id'))}

        async def _send_rpc_on_channel(
            channel: _BlockingRPCChannel,
            *,
            rpc_channel_acquire_ms: float,
        ) -> Dict[str, Any]:
            payload = {"cmd": cmd, "kwargs": kwargs}
            if _native_event_observer is not None:
                payload['native_event_rpc_id'] = attempt_id
            payload["client_send_wall_time"] = time.time()
            payload_bytes = _encode_rpc_frame(payload)
            raw, send_flush_ms, wait_response_ms, parent_response_read_wall_time = await asyncio.to_thread(
                self._blocking_rpc_roundtrip,
                channel,
                payload_bytes,
                **({'on_progress': receive_progress} if _native_event_observer is not None else {}),
            )
            parent_roundtrip_resume_wall_time = time.time()
            if not raw:
                raise RuntimeError("subprocess_engine_empty_response")
            response = json.loads(raw.decode("utf-8"))
            if _native_event_observer is not None and response.get('native_event_rpc_id') != attempt_id:
                raise ValueError('service terminal RPC identity mismatch')
            if not response.get("ok"):
                error_text = str(response.get("error", "subprocess_engine_rpc_failed"))
                if _is_fatal_engine_error_message(error_text):
                    self._engine_dead = True
                    await self._terminate_process_tree(force=True)
                    self._preserve_worker_workdir("fatal_rpc")
                    error_text = self._with_worker_log_context(error_text)
                raise RuntimeError(error_text)
            if _native_event_observer is not None and len(progress_events) != 2:
                raise ValueError('successful service reply is missing native progress')
            result = response.get("result", {}) or {}
            if _native_event_observer is not None:
                timing = result.get('timing', {})
                for event, boundary in zip(progress_events, ('first', 'last')):
                    if (event.get('backend_request_id') != timing.get('backend_request_id')
                            or event.get('native_clock_id') != timing.get('native_clock_id')
                            or event.get('timestamp_monotonic_s') != timing.get(
                                f'native_{boundary}_token_monotonic_s')):
                        raise ValueError('service progress differs from native terminal evidence')
                    for field in ('gpu_reference_owner_id', 'gpu_reference_lease_id',
                                  'gpu_reference_adapter_int_id'):
                        if event.get(field) != timing.get(field):
                            raise ValueError('service progress differs from native terminal reference')
                if progress_events[-1]['token_count'] != result.get('output_tokens'):
                    raise ValueError('service progress/terminal token count mismatch')
            if isinstance(result, dict):
                result_timing = _attach_parent_rpc_breakdown(
                    result.get("timing"),
                    channel_acquire_ms=rpc_channel_acquire_ms,
                    parent_response_read_wall_time=parent_response_read_wall_time,
                )
                result_timing["parent_rpc_send_flush_ms"] = send_flush_ms
                result_timing["parent_rpc_request_bytes"] = len(payload_bytes)
                result_timing["parent_rpc_response_bytes"] = len(raw)
                result_timing["parent_rpc_wait_response_ms"] = wait_response_ms
                result_timing["parent_rpc_thread_resume_delay_ms"] = max(
                    0.0,
                    (
                        parent_roundtrip_resume_wall_time
                        - float(parent_response_read_wall_time)
                    )
                    * 1000.0,
                )
                result["timing"] = result_timing
            return result

        channel = None
        try:
            channel_acquire_started_at = time.perf_counter()
            # Reconciliation must not wait behind all outstanding generations.
            # It uses a fresh, one-operation connection, never the lost stream.
            channel = await (self._open_rpc_channel() if control else self._acquire_rpc_channel())
            rpc_channel_acquire_ms = max(
                0.0,
                (time.perf_counter() - channel_acquire_started_at) * 1000.0,
            )
            return await _send_rpc_on_channel(
                channel,
                rpc_channel_acquire_ms=rpc_channel_acquire_ms,
            )
        except asyncio.CancelledError:
            # asyncio.to_thread cancellation does not stop send/recv. This
            # channel still belongs to that roundtrip and cannot serve another
            # request. Withdraw the transport, without claiming native abort.
            if channel is not None:
                abandoned, channel = channel, None
                retain_uncertain()
                if not native:
                    self._engine_dead = True
                await self._drop_rpc_channel(abandoned)
                if native and not control and self._rpc_channel_queue is not None:
                    self._rpc_channel_queue.put_nowait(None)
            raise
        except Exception as first_exc:
            if channel is not None:
                abandoned, channel = channel, None
                retain_uncertain()
                await self._drop_rpc_channel(abandoned)
                if native and not control and self._rpc_channel_queue is not None:
                    self._rpc_channel_queue.put_nowait(None)
            if native:
                # Native generate/begin-use may have committed before the reply
                # was lost. The controller owns the unresolved attempt; neither
                # blind resubmission nor closing the socket proves completion.
                raise RuntimeError(self._with_worker_log_context(
                    f'subprocess_native_rpc_failed_no_retry: {type(first_exc).__name__}: {first_exc}'
                )) from None
            if cmd == "shutdown":
                raise
            if self._process.poll() is None and not self._engine_dead:
                try:
                    channel_acquire_started_at = time.perf_counter()
                    channel = await self._open_rpc_channel()
                    rpc_channel_acquire_ms = max(
                        0.0,
                        (time.perf_counter() - channel_acquire_started_at) * 1000.0,
                    )
                    return await _send_rpc_on_channel(
                        channel,
                        rpc_channel_acquire_ms=rpc_channel_acquire_ms,
                    )
                except Exception as retry_exc:
                    if channel is not None:
                        await self._drop_rpc_channel(channel)
                        channel = None
                    self._engine_dead = True
                    message = (
                        "subprocess_engine_rpc_failed_after_retry: "
                        f"first={type(first_exc).__name__}: {first_exc}; "
                        f"retry={type(retry_exc).__name__}: {retry_exc}"
                    )
                    raise RuntimeError(self._with_worker_log_context(message)) from None
            self._engine_dead = True
            message = f"subprocess_engine_dead: {type(first_exc).__name__}: {first_exc}"
            raise RuntimeError(self._with_worker_log_context(message))
        finally:
            progress_open = False
            if channel is not None:
                if control:
                    await self._drop_rpc_channel(channel)
                elif cmd != "shutdown":
                    await self._release_rpc_channel(channel)

    async def _ensure_rpc_channel_pool(self) -> None:
        if self._rpc_channel_queue is not None:
            return
        async with self._rpc_channel_init_lock:
            if self._rpc_channel_queue is not None:
                return
            queue: asyncio.Queue = asyncio.Queue()
            opened: List[_BlockingRPCChannel] = []
            try:
                for _ in range(self._rpc_pool_size):
                    channel = await self._open_rpc_channel()
                    opened.append(channel)
                    await queue.put(channel)
            except BaseException:
                for channel in opened:
                    await self._drop_rpc_channel(channel)
                raise
            self._rpc_channels = list(opened)
            self._rpc_channel_queue = queue

    def _open_blocking_rpc_channel(self) -> _BlockingRPCChannel:
        sock = socket.create_connection((self._host, self._port), timeout=30.0)
        sock.settimeout(300.0)
        try:
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except Exception:
            pass
        return _BlockingRPCChannel(sock=sock)

    def _blocking_rpc_roundtrip(
        self,
        channel: _BlockingRPCChannel,
        payload_bytes: bytes,
        *,
        on_progress=None,
    ) -> Tuple[bytes, float, float, float]:
        send_flush_started_at = time.perf_counter()
        channel.sock.sendall(payload_bytes)
        send_flush_ms = max(0.0, (time.perf_counter() - send_flush_started_at) * 1000.0)

        wait_response_started_at = time.perf_counter()
        while True:
            newline_idx = channel.recv_buffer.find(b"\n")
            if newline_idx >= 0:
                if newline_idx > _RPC_FRAME_MAX_BYTES:
                    raise ValueError('dedicated RPC frame exceeds protocol byte limit')
                raw = bytes(channel.recv_buffer[: newline_idx + 1])
                del channel.recv_buffer[: newline_idx + 1]
                if on_progress is not None:
                    frame = json.loads(raw.decode('utf-8'))
                    if 'native_event' in frame:
                        on_progress(frame)
                        continue
                parent_response_read_wall_time = time.time()
                wait_response_ms = max(
                    0.0,
                    (time.perf_counter() - wait_response_started_at) * 1000.0,
                )
                return raw, send_flush_ms, wait_response_ms, parent_response_read_wall_time
            if len(channel.recv_buffer) > _RPC_FRAME_MAX_BYTES:
                raise ValueError('dedicated RPC frame exceeds protocol byte limit')
            chunk = channel.sock.recv(65536)
            if not chunk:
                raise RuntimeError("subprocess_engine_empty_response")
            channel.recv_buffer.extend(chunk)

    async def _open_rpc_channel(self) -> _BlockingRPCChannel:
        opening = asyncio.create_task(asyncio.to_thread(self._open_blocking_rpc_channel))
        try:
            return await asyncio.shield(opening)
        except asyncio.CancelledError:
            # Opening a socket in a thread is also not cancelled by cancelling
            # its waiter. Join and close it, rather than leaking a live channel.
            while not opening.done():
                try:
                    await asyncio.shield(opening)
                except asyncio.CancelledError:
                    continue
                except Exception:
                    break
            if not opening.cancelled() and opening.exception() is None:
                await self._drop_rpc_channel(opening.result())
            raise

    async def _acquire_rpc_channel(self) -> _BlockingRPCChannel:
        await self._ensure_rpc_channel_pool()
        assert self._rpc_channel_queue is not None
        channel = await self._rpc_channel_queue.get()
        if channel is None:
            try:
                channel = await self._open_rpc_channel()
                self._rpc_channels.append(channel)
            except BaseException:
                self._rpc_channel_queue.put_nowait(None)
                raise
        return channel

    async def _release_rpc_channel(
        self,
        channel: _BlockingRPCChannel,
    ) -> None:
        queue = self._rpc_channel_queue
        if queue is None:
            await self._drop_rpc_channel(channel)
            return
        await queue.put(channel)

    async def _drop_rpc_channel(
        self,
        channel: _BlockingRPCChannel,
    ) -> None:
        # Wake an outstanding recv/send before closing. close alone need not
        # interrupt another thread blocked on this socket on Linux.
        try:
            channel.sock.shutdown(socket.SHUT_RDWR)
        except (OSError, AttributeError):
            pass
        try:
            await asyncio.to_thread(channel.sock.close)
        except Exception:
            pass
        if channel in self._rpc_channels:
            try:
                self._rpc_channels.remove(channel)
            except ValueError:
                pass

    async def _close_all_rpc_channels(self) -> None:
        queue = self._rpc_channel_queue
        channels = list(self._rpc_channels)
        self._rpc_channel_queue = None
        self._rpc_channels = []
        if queue is not None:
            try:
                while True:
                    queue.get_nowait()
            except asyncio.QueueEmpty:
                pass
        for channel in channels:
            await self._drop_rpc_channel(channel)

    async def _terminate_process_tree(self, *, force: bool = False) -> None:
        proc = self._process
        sglang_marker = self._workdir / "sglang"
        if proc is None:
            if sglang_marker.exists():
                await asyncio.to_thread(
                    _terminate_processes_by_cmdline_marker,
                    sglang_marker,
                    grace_s=1.0,
                )
            return
        try:
            if proc.poll() is not None:
                if sglang_marker.exists():
                    await asyncio.to_thread(
                        _terminate_processes_by_cmdline_marker,
                        sglang_marker,
                        grace_s=1.0,
                    )
                return
        except Exception:
            pass
        try:
            pgid = os.getpgid(proc.pid)
        except Exception:
            pgid = None
        sig = signal.SIGKILL if force else signal.SIGTERM
        try:
            if pgid is not None and pgid > 0:
                os.killpg(pgid, sig)
            else:
                proc.send_signal(sig)
        except Exception:
            pass
        try:
            await asyncio.to_thread(proc.wait, 5 if force else 10)
        except Exception:
            pass
        if sglang_marker.exists():
            await asyncio.to_thread(
                _terminate_processes_by_cmdline_marker,
                sglang_marker,
                grace_s=1.0 if force else 2.0,
            )
        if force:
            return
        try:
            if proc.poll() is None:
                await self._terminate_process_tree(force=True)
        except Exception:
            pass

    async def generate(
        self,
        prompt: str,
        lora_path: Optional[str],
        adapter_id: Optional[str],
        max_tokens: int,
        input_tokens: int,
        temperature: float = 0.7,
        top_p: float = 0.9,
        *,
        generation_seed: Optional[int] = None,
        return_timing: bool = False,
        gpu_reference: Optional[Dict[str, Any]] = None,
        _prepared_request: Optional[RequestExecutionPlan] = None,
        native_event_observer: Optional[Callable[[Dict[str, Any]], None]] = None,
        pending_admission_id: Optional[str] = None,
    ) -> Tuple[float, float, int]:
        rpc_started_at = time.perf_counter()
        result = await self._rpc(
            "generate",
            **({'_native_event_observer': native_event_observer} if native_event_observer is not None else {}),
            prompt=prompt,
            lora_path=lora_path,
            adapter_id=adapter_id,
            max_tokens=max_tokens,
            input_tokens=input_tokens,
            temperature=temperature,
            top_p=top_p,
            generation_seed=generation_seed,
            return_timing=return_timing,
            **({"gpu_reference": gpu_reference} if gpu_reference is not None else {}),
            **({"_prepared_request": {"prompt": _prepared_request.prompt,
                                      "input_tokens": _prepared_request.input_tokens,
                                      "max_tokens": _prepared_request.max_tokens}}
               if _prepared_request is not None else {}),
            **({'pending_admission_id': pending_admission_id} if pending_admission_id is not None else {}),
        )
        parent_rpc_wall_ms = max(0.0, (time.perf_counter() - rpc_started_at) * 1000.0)
        timing = dict(result.get("timing") or {})
        worker_wall_ms = _positive_or_fallback(
            timing.get("worker_rpc_handler_wall_ms"),
            timing.get("worker_wall_e2e_ms", 0.0),
        )
        timing["parent_rpc_wall_ms"] = parent_rpc_wall_ms
        timing["parent_rpc_overhead_ms"] = (
            max(0.0, parent_rpc_wall_ms - worker_wall_ms)
            if worker_wall_ms > 0.0
            else 0.0
        )
        # Auditing also carries token identity and a typed terminal flag.
        # A numeric residual cannot substitute for a native terminal event.
        self.last_timing = {
            key: value if value is None or isinstance(value, (str, bool)) else _safe_float(value, 0.0)
            for key, value in timing.items()
            if isinstance(key, str)
        }
        if return_timing:
            return (
                float(result.get("ttft_ms", 0.0)),
                float(result.get("tpot_ms", 0.0)),
                int(result.get("output_tokens", 0)),
                dict(self.last_timing),
            )
        return (
            float(result.get("ttft_ms", 0.0)),
            float(result.get("tpot_ms", 0.0)),
            int(result.get("output_tokens", 0)),
        )

    def prepare_request(
        self,
        prompt: str,
        requested_output_tokens: int,
        input_tokens_hint: int,
        chat_messages: Optional[List[Dict[str, Any]]] = None,
    ) -> RequestExecutionPlan:
        """Mirror the worker-side prompt guard in the parent process.

        The scheduler and metric path run in the parent process. Dedicated
        scale-out runtimes execute inside subprocesses, so without this mirror
        the parent would account for raw trace token hints while the worker
        silently applies the vLLM prompt guard. That makes resource coordination,
        cost, and reported token statistics diverge from the actual request.
        """
        planner = self._prompt_planner
        if planner is None:
            planner = InferenceEngine(copy.deepcopy(self.model_cfg), copy.deepcopy(self._cost_model))
            self._prompt_planner = planner
        return planner.prepare_request(
            prompt=prompt,
            requested_output_tokens=requested_output_tokens,
            input_tokens_hint=input_tokens_hint,
            chat_messages=chat_messages,
        )

    async def generate_prepared(
        self,
        *,
        request_plan: RequestExecutionPlan,
        lora_path: Optional[str],
        adapter_id: Optional[str],
        temperature: float = 0.7,
        top_p: float = 0.9,
        generation_seed: Optional[int] = None,
        return_timing: bool = False,
        gpu_reference: Optional[Dict[str, Any]] = None,
        native_event_observer: Optional[Callable[[Dict[str, Any]], None]] = None,
        pending_admission_id: Optional[str] = None,
    ) -> Tuple[float, float, int]:
        # Dedicated worker preserves the exact controller/native handoff ID.
        return await self.generate(
            prompt=request_plan.prompt,
            lora_path=lora_path,
            adapter_id=adapter_id,
            max_tokens=request_plan.max_tokens,
            input_tokens=request_plan.input_tokens,
            temperature=temperature,
            top_p=top_p,
            generation_seed=generation_seed,
            return_timing=return_timing,
            _prepared_request=request_plan,
            **({"gpu_reference": gpu_reference} if gpu_reference is not None else {}),
            **({"native_event_observer": native_event_observer} if native_event_observer is not None else {}),
            **({'pending_admission_id': pending_admission_id} if pending_admission_id is not None else {}),
        )

    async def load_lora_to_gpu_and_measure(self, lora_path: str, adapter_id: str) -> Tuple[float, bool]:
        result = await self._rpc(
            "load_lora_to_gpu_and_measure",
            lora_path=lora_path,
            adapter_id=adapter_id,
        )
        return float(result.get("load_ms", 0.0)), bool(result.get("ok", False))

    async def ieee_worker_observation(self, *, synchronize: bool = False) -> Dict[str, Any]:
        return await self._rpc("ieee_worker_observation", synchronize=synchronize)

    async def ieee_scheduler_observation(self) -> Dict[str, Any]:
        return await self._rpc("ieee_scheduler_observation")

    async def ieee_prepare_host(self, **command) -> Dict[str, Any]:
        return await self._rpc('ieee_prepare_host', **command)

    async def ieee_transfer_event(self, **command):
        result = await self._rpc('ieee_transfer_event', **command)
        if (not isinstance(result, dict) or result.get('kind') != 'ieee_adapter_transfer_event_v1'
                or result.get('transfer_id') != command.get('transfer_id')
                or result.get('state') != {'start': 'active', 'finish': 'finished',
                    'attach_domain': 'attached'}.get(command.get('operation'))
                or (command.get('expected_owner_id') is not None
                    and result.get('owner_id') != command['expected_owner_id'])):
            raise ValueError('file transfer event lacks matching worker acknowledgement')
        if result['state'] == 'finished':
            for key, operation in list(self._native_rpc_uncertain.items()):
                if (operation['cmd'] == 'ieee_transfer_event'
                        and operation.get('transfer_id') == result['transfer_id']
                        and operation.get('owner_id') in (None, result.get('owner_id'))):
                    del self._native_rpc_uncertain[key]
        return result

    async def ieee_register_pending(self, **command):
        return await self._rpc('ieee_register_pending', **command)

    async def ieee_close_pending(self, *, intent_id):
        result = await self._rpc('ieee_close_pending', intent_id=intent_id)
        if result.get('closed') is not True or result.get('intent_id') != intent_id:
            raise ValueError('pending retirement lacks matching worker acknowledgement')
        for key, operation in list(self._native_rpc_uncertain.items()):
            if (operation['cmd'] in ('ieee_register_pending', 'ieee_close_pending')
                    and operation.get('intent_id') == intent_id):
                del self._native_rpc_uncertain[key]
        return result

    async def ieee_generation_observation(self) -> Dict[str, Any]:
        return await self._rpc('ieee_generation_observation')

    _lora_int_id = staticmethod(InferenceEngine._lora_int_id)

    async def ieee_retire_generation(self, *, gpu_reference: Dict[str, Any], abort: bool) -> Dict[str, Any]:
        result = await self._rpc('ieee_retire_generation', gpu_reference=gpu_reference, abort=abort)
        if (result.get('gpu_reference_owner_id') != gpu_reference['owner_id']
                or result.get('gpu_reference_lease_id') != gpu_reference['lease_id']
                or result.get('native_retirement', {}).get('retired') is not True):
            raise ValueError('retirement lacks exact native dispatch identity')
        # Only settle generation/retirement exchanges for this exact dispatch.
        # Unknown loads, acquires or releases are not cleared by a request end.
        for key, operation in list(self._native_rpc_uncertain.items()):
            if (operation['cmd'] in ('generate', 'ieee_retire_generation')
                    and operation['owner_id'] == gpu_reference['owner_id']
                    and operation['lease_id'] == gpu_reference['lease_id']):
                del self._native_rpc_uncertain[key]
        return result

    async def ieee_gpu_reference(self, *, operation: str, **kwargs) -> Dict[str, Any]:
        result = await self._rpc("ieee_gpu_reference", operation=operation, **kwargs)
        if operation == 'close_preparation_plan':
            if (result.get('closed') is not True or result.get('plan_id') != kwargs.get('plan_id')
                    or result.get('owner_id') != kwargs.get('expected_owner_id')):
                raise ValueError('preparation close lacks matching native owner proof')
            for key, pending in list(self._native_rpc_uncertain.items()):
                if (pending.get('preparation_plan_id') == result['plan_id']
                        and pending.get('owner_id') == result['owner_id']
                        and (pending['cmd'] == 'ieee_prepare_host' or
                            (pending['cmd'] == 'ieee_gpu_reference' and pending.get('operation') in
                             ('register_preparation_plan', 'finish_preparation_target', 'close_preparation_plan')))):
                    del self._native_rpc_uncertain[key]
        return result

    async def unload_lora_adapter(self, adapter_id: str) -> bool:
        result = await self._rpc("unload_lora_adapter", adapter_id=adapter_id)
        if type(result.get("unloaded")) is not bool:
            raise RuntimeError("missing native unload acknowledgement")
        return result["unloaded"]

    async def shutdown(self) -> None:
        keep_logs = self._keep_worker_logs_requested()
        allocation = getattr(self, '_physical_allocation', None)
        teardown_deadline = time.monotonic() + 60.0
        if self._normal_shutdown_completed and not keep_logs:
            shutil.rmtree(self._workdir, ignore_errors=True)
            self._engine_dead = True
            return
        preserve_logs = bool(self._engine_dead) or keep_logs
        normal_shutdown = False
        channels_closed = False
        try:
            if self._process.poll() is None:
                try:
                    if allocation is not None:
                        # The RPC only initiates worker shutdown. Allow native
                        # teardown to finish, reserving the existing 10+5s TERM/
                        # KILL budget, instead of immediately killing its owner.
                        await asyncio.wait_for(self._rpc('shutdown'), timeout=45.)
                        # Python3.12 Server.wait_closed also waits for accepted
                        # connections. Close the idle RPC pool BEFORE waiting for
                        # the worker, or each side waits for the other to exit.
                        await self._close_all_rpc_channels()
                        channels_closed = True
                        await asyncio.to_thread(self._process.wait,
                            max(0., teardown_deadline - time.monotonic() - 15.))
                    else:
                        await self._rpc("shutdown")
                    normal_shutdown = True
                except Exception:
                    pass
            elif not self._engine_dead and self._process.returncode == 0:
                normal_shutdown = True
        finally:
            if not channels_closed:
                await self._close_all_rpc_channels()
            await self._terminate_process_tree(force=False)
            if allocation is not None:
                # RPC shutdown and an empty LoRA cache are not physical return.
                # Failure keeps the durable lease open and prevents GPU reuse.
                try:
                    await allocation.wait_workers(timeout_s=max(0., teardown_deadline-time.monotonic()))
                    allocation.release()
                except BaseException:
                    self._engine_dead = True
                    self._preserve_worker_workdir('physical_release_unconfirmed')
                    raise
            if normal_shutdown and not keep_logs:
                shutil.rmtree(self._workdir, ignore_errors=True)
                self._normal_shutdown_completed = True
            elif preserve_logs:
                self._preserve_worker_workdir("engine_dead")
            else:
                shutil.rmtree(self._workdir, ignore_errors=True)
                if normal_shutdown:
                    self._normal_shutdown_completed = True
            self._engine_dead = True

    async def reinitialize(self) -> None:
        await self.shutdown()
        replacement = await self.spawn(
            model_cfg=self.model_cfg,
            cost_model=self._cost_model,
            device_id=self.device_id,
            runtime_gpu_ids=self._runtime_gpu_ids,
        )
        self._process = replacement._process
        self._host = replacement._host
        self._port = replacement._port
        self._workdir = replacement._workdir
        self._log_path = replacement._log_path
        self._engine_dead = replacement._engine_dead
        self._physical_allocation = replacement._physical_allocation
        self._reinit_attempted = False


# ==========================================================================
# File I/O helpers
# ==========================================================================

def _dir_size_mb(p: Path) -> float:
    if not p.exists():
        return 0.0
    total = 0
    for child in (p.rglob("*") if p.is_dir() else [p]):
        if child.is_file():
            try: total += child.stat().st_size
            except OSError: pass
    return total / 1024**2


def _path_size_bytes(path: Path) -> int:
    if not path.exists():
        return 0
    total = 0
    children = path.rglob("*") if path.is_dir() else [path]
    for child in children:
        if not child.is_file():
            continue
        try:
            total += int(child.stat().st_size)
        except OSError:
            continue
    return max(0, total)


def copy_with_timing(src: Path, dst: Path) -> Tuple[bool, float]:
    t0 = time.perf_counter()
    try:
        if dst.exists():
            shutil.rmtree(dst) if dst.is_dir() else dst.unlink()
        shutil.copytree(src, dst) if src.is_dir() else shutil.copy2(src, dst)
        return True, (time.perf_counter() - t0) * 1000
    except Exception:
        return False, (time.perf_counter() - t0) * 1000


def linktree_with_timing(src: Path, dst: Path) -> Tuple[bool, float, str]:
    """Mirror a local-sim remote tree without charging disk-copy throughput.

    The aggregate limiter models the Remote->NVMe link.  Hard-linking after the
    reservation matches the ServerlessLLM file:// fetcher and avoids adding a
    second, system-specific full disk copy on top of the configured transfer.
    """
    t0 = time.perf_counter()
    mode = "hardlink"
    try:
        if dst.exists():
            shutil.rmtree(dst) if dst.is_dir() else dst.unlink()
        if src.is_file():
            dst.parent.mkdir(parents=True, exist_ok=True)
            try:
                os.link(src, dst)
            except OSError:
                try:
                    os.symlink(src, dst)
                    mode = "symlink"
                except OSError:
                    shutil.copy2(src, dst)
                    mode = "copy"
            return True, (time.perf_counter() - t0) * 1000.0, mode
        dst.mkdir(parents=True, exist_ok=True)
        for item in src.rglob("*"):
            target = dst / item.relative_to(src)
            if item.is_dir():
                target.mkdir(parents=True, exist_ok=True)
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            if item.is_symlink():
                os.symlink(os.readlink(item), target)
                if mode == "hardlink":
                    mode = "symlink"
                continue
            try:
                os.link(item, target)
            except OSError:
                try:
                    os.symlink(item, target)
                    mode = "symlink"
                except OSError:
                    shutil.copy2(item, target)
                    mode = "copy"
        return True, (time.perf_counter() - t0) * 1000.0, mode
    except Exception:
        return False, (time.perf_counter() - t0) * 1000.0, mode


def _calc_cost(cost_model: Dict, in_tok: int, out_tok: int) -> float:
    base    = float(cost_model.get("base_cost_usd", 0.001))
    in_c    = float(cost_model.get("input_token_cost_usd",  0.0000015)) * in_tok
    out_c   = float(cost_model.get("output_token_cost_usd", 0.000002))  * out_tok
    return base + in_c + out_c


def _gpu_cost_per_second_usd(cost_model: Dict[str, Any]) -> float:
    per_second = cost_model.get("gpu_cost_per_second_usd")
    if per_second is not None:
        try:
            return max(0.0, float(per_second))
        except Exception:
            pass
    per_hour = cost_model.get("gpu_hour_cost_usd")
    if per_hour is not None:
        try:
            return max(0.0, float(per_hour)) / 3600.0
        except Exception:
            pass
    return 0.0008


def _serverless_idle_gpu_cost_factor(cost_model: Dict[str, Any]) -> float:
    for key in (
        "serverless_idle_gpu_cost_factor",
        "idle_gpu_cost_factor",
        "gpu_idle_cost_factor",
    ):
        value = cost_model.get(key)
        if value is None:
            continue
        try:
            parsed = float(value)
        except Exception:
            continue
        if math.isfinite(parsed):
            return min(1.0, max(0.0, parsed))
    # Alibaba Function Compute Tesla GPU CU factors: idle 0.5 / active 2.1.
    return 0.5 / 2.1


def _serverless_invocation_cost_per_request_usd(cost_model: Dict[str, Any]) -> float:
    for key in (
        "serverless_invocation_cost_per_request_usd",
        "invocation_cost_per_request_usd",
        "function_invocation_cost_usd",
    ):
        value = cost_model.get(key)
        if value is None:
            continue
        try:
            parsed = float(value)
        except Exception:
            continue
        if math.isfinite(parsed):
            return max(0.0, parsed)
    return 0.0


def _is_serverful_cost_runtime(lifecycles: Collection[Dict[str, Any]]) -> bool:
    runtime_kinds = [
        str((item or {}).get("runtime_kind", "") or "").lower()
        for item in lifecycles or []
    ]
    return bool(runtime_kinds) and all("static_serverful" in kind for kind in runtime_kinds)


def _cost_model_deployment_idle_tail_s(cost_model: Dict[str, Any]) -> float:
    """Post-workload deployment horizon used for lifecycle GPU billing.

    Serverful systems keep their GPU fleet allocated through this horizon.
    Serverless systems pay for each runtime only until actual scale-down, or
    until the idle-retention bound when the benchmark cleanup stops a still-live
    runtime before it would naturally scale down.
    """
    for key in (
        "deployment_idle_tail_s",
        "deployment_lifecycle_idle_tail_s",
        "post_workload_idle_tail_s",
    ):
        value = cost_model.get(key)
        if value is None:
            continue
        try:
            parsed = float(value)
        except Exception:
            continue
        if math.isfinite(parsed):
            return max(0.0, parsed)
    return 300.0


def _cost_model_serverless_idle_retention_s(cost_model: Dict[str, Any]) -> float:
    for key in (
        "serverless_idle_retention_s",
        "serverless_keepalive_s",
        "function_keepalive_s",
    ):
        value = cost_model.get(key)
        if value is None:
            continue
        try:
            parsed = float(value)
        except Exception:
            continue
        if math.isfinite(parsed):
            return max(0.0, parsed)
    return _cost_model_deployment_idle_tail_s(cost_model)


def _summarize_monetary_cost_from_resource_seconds(
    *,
    cost_model: Dict[str, Any],
    completed_requests: int,
    total_requests: int,
    avg_e2e_ms: float,
    lifecycles: Collection[Dict[str, Any]],
    infra_gpu_seconds_total: float,
    infra_startup_gpu_seconds: float,
    infra_active_gpu_seconds: float,
    infra_idle_ready_gpu_seconds: float,
) -> Dict[str, Any]:
    """Cloud monetary billing with explicit active/idle differential pricing.

    ``infra_*`` remains the resource-normalized audit view where every allocated
    GPU-second has the same price. The monetary view follows GPU serverless idle
    billing semantics: serverful/static runtimes pay full price for all
    lifecycle GPU-seconds; serverless runtimes pay full price while starting or
    executing requests, and a lower idle GPU price while ready-but-idle.
    """
    per_second = _gpu_cost_per_second_usd(cost_model)
    idle_factor = _serverless_idle_gpu_cost_factor(cost_model)
    invocation_cost = _serverless_invocation_cost_per_request_usd(cost_model)
    completed = max(0, int(completed_requests or 0))
    denominator = completed if completed > 0 else max(0, int(total_requests or 0))
    serverful = _is_serverful_cost_runtime(lifecycles)

    total_gpu_s = max(0.0, float(infra_gpu_seconds_total or 0.0))
    startup_gpu_s = max(0.0, float(infra_startup_gpu_seconds or 0.0))
    active_gpu_s = max(0.0, float(infra_active_gpu_seconds or 0.0))
    idle_ready_gpu_s = max(0.0, float(infra_idle_ready_gpu_seconds or 0.0))

    if serverful:
        monetary_equivalent_gpu_seconds = total_gpu_s
        charged_idle_factor = 1.0
        active_charge_gpu_seconds = total_gpu_s
        idle_charge_gpu_seconds = 0.0
    else:
        active_charge_gpu_seconds = startup_gpu_s + active_gpu_s
        idle_charge_gpu_seconds = idle_ready_gpu_s * idle_factor
        monetary_equivalent_gpu_seconds = active_charge_gpu_seconds + idle_charge_gpu_seconds
        charged_idle_factor = idle_factor

    invocation_total = invocation_cost * float(completed)
    total_cost = monetary_equivalent_gpu_seconds * per_second + invocation_total
    per_request = total_cost / float(denominator) if denominator > 0 else 0.0
    avg_e2e_s = max(0.0, float(avg_e2e_ms or 0.0)) / 1000.0
    ce_denom = per_request * avg_e2e_s
    ce = 1.0 / ce_denom if ce_denom > 1e-12 else 0.0
    return {
        "monetary_cost_total_usd": total_cost,
        "monetary_cost_per_request_usd": per_request,
        "monetary_ce": ce,
        "monetary_equivalent_gpu_seconds": monetary_equivalent_gpu_seconds,
        "monetary_active_charge_gpu_seconds": active_charge_gpu_seconds,
        "monetary_idle_charge_gpu_seconds": idle_charge_gpu_seconds,
        "serverless_idle_gpu_cost_factor": charged_idle_factor,
        "serverless_invocation_cost_total_usd": invocation_total,
        "serverless_invocation_cost_per_request_usd": invocation_cost,
        "monetary_pricing_runtime_class": "serverful" if serverful else "serverless",
    }


def _cost_per_million_tokens(total_cost_usd: float, token_count: int) -> float:
    try:
        cost = float(total_cost_usd or 0.0)
        tokens = int(token_count or 0)
    except Exception:
        return 0.0
    if cost <= 0.0 or tokens <= 0:
        return 0.0
    return max(0.0, cost) * 1_000_000.0 / float(tokens)


def _capped_weighted_interval_seconds(
    intervals: Sequence[Tuple[float, float, float]],
    max_weight: Optional[float] = None,
) -> float:
    events: List[Tuple[float, float]] = []
    for start, end, weight in intervals:
        try:
            s = float(start)
            e = float(end)
            w = float(weight)
        except Exception:
            continue
        if not (math.isfinite(s) and math.isfinite(e) and math.isfinite(w)):
            continue
        if e <= s or w <= 0.0:
            continue
        events.append((s, w))
        events.append((e, -w))
    if not events:
        return 0.0
    cap = None
    if max_weight is not None:
        try:
            parsed = float(max_weight)
            if math.isfinite(parsed) and parsed > 0.0:
                cap = parsed
        except Exception:
            cap = None
    total = 0.0
    current = 0.0
    previous: Optional[float] = None
    idx = 0
    events.sort(key=lambda item: item[0])
    while idx < len(events):
        at = events[idx][0]
        if previous is not None and at > previous:
            effective = min(current, cap) if cap is not None else current
            total += (at - previous) * max(0.0, effective)
        while idx < len(events) and events[idx][0] == at:
            current += events[idx][1]
            idx += 1
        previous = at
    return max(0.0, total)


def _summarize_infra_cost_from_lifecycles(
    lifecycles: Collection[Dict[str, Any]],
    *,
    elapsed_sec: float,
    completed_requests: int,
    total_requests: int,
    avg_e2e_ms: float,
    gpu_cost_per_second_usd: float,
    deployment_idle_tail_s: float = 300.0,
    serverless_idle_retention_s: float = 300.0,
    max_billing_gpus: Optional[float] = None,
    pre_replay_startup_s: float = 0.0,
) -> Dict[str, Any]:
    normalized: List[Dict[str, Any]] = []
    total_gpu_seconds = 0.0
    startup_gpu_seconds = 0.0
    ready_gpu_seconds = 0.0
    safe_elapsed = max(0.0, float(elapsed_sec or 0.0))
    safe_tail = max(0.0, float(deployment_idle_tail_s or 0.0))
    safe_retention = max(0.0, float(serverless_idle_retention_s or 0.0))
    safe_pre_replay = max(0.0, float(pre_replay_startup_s or 0.0))
    billing_start_offset = -safe_pre_replay
    billing_end_offset = safe_elapsed + safe_tail
    billing_elapsed = billing_end_offset - billing_start_offset
    lifetime_intervals: List[Tuple[float, float, float]] = []
    startup_intervals: List[Tuple[float, float, float]] = []
    ready_intervals: List[Tuple[float, float, float]] = []

    for raw in lifecycles or []:
        item = dict(raw or {})
        instance_id = str(item.get("instance_id") or "").strip()
        if not instance_id:
            continue
        runtime_kind = str(item.get("runtime_kind") or "").lower()
        remove_reason = str(item.get("remove_reason") or "").lower()
        gpu_count = max(1, int(item.get("gpu_count", 1) or 1))
        created_offset_s = float(item.get("created_offset_s", 0.0) or 0.0)
        ready_offset_s = item.get("ready_offset_s")
        if ready_offset_s is None:
            ready_offset_s = created_offset_s
        ready_offset_s = max(created_offset_s, float(ready_offset_s or 0.0))
        removed_offset_s = item.get("removed_offset_s")
        if removed_offset_s is None:
            removed_offset_s = safe_elapsed
        removed_offset_s = max(ready_offset_s, float(removed_offset_s or 0.0))
        last_finished_offset_s = item.get("last_finished_offset_s")
        try:
            last_finished_offset_s = float(last_finished_offset_s)
        except Exception:
            last_finished_offset_s = None

        created_offset_s = min(
            max(billing_start_offset, created_offset_s), billing_end_offset
        )
        ready_offset_s = min(
            max(created_offset_s, ready_offset_s), billing_end_offset
        )

        if "static_serverful" in runtime_kind:
            billing_removed_offset_s = billing_end_offset
        elif remove_reason == "scale_down":
            billing_removed_offset_s = removed_offset_s
        else:
            # Benchmark cleanup is not a natural serverless scale-down event.
            # Charge still-live serverless runtimes through the idle retention
            # horizon so cost reflects the deployed service lifecycle.
            live_until = max(
                removed_offset_s,
                float(last_finished_offset_s)
                if last_finished_offset_s is not None
                else removed_offset_s,
            )
            billing_removed_offset_s = live_until + safe_retention

        removed_offset_s = min(
            max(ready_offset_s, billing_removed_offset_s), billing_end_offset
        )

        lifetime_sec = max(0.0, removed_offset_s - created_offset_s)
        startup_sec = max(0.0, ready_offset_s - created_offset_s)
        ready_sec = max(0.0, removed_offset_s - ready_offset_s)
        lifetime_gpu_seconds = lifetime_sec * gpu_count
        startup_gpu_seconds_i = startup_sec * gpu_count
        ready_gpu_seconds_i = ready_sec * gpu_count

        total_gpu_seconds += lifetime_gpu_seconds
        startup_gpu_seconds += startup_gpu_seconds_i
        ready_gpu_seconds += ready_gpu_seconds_i
        lifetime_intervals.append((created_offset_s, removed_offset_s, float(gpu_count)))
        startup_intervals.append((created_offset_s, ready_offset_s, float(gpu_count)))
        ready_intervals.append((ready_offset_s, removed_offset_s, float(gpu_count)))

        item.update(
            {
                "created_offset_s": round(created_offset_s, 6),
                "ready_offset_s": round(ready_offset_s, 6),
                "removed_offset_s": round(removed_offset_s, 6),
                "billing_scope": "deployment_lifecycle",
                "deployment_idle_tail_s": round(safe_tail, 6),
                "serverless_idle_retention_s": round(safe_retention, 6),
                "lifetime_sec": round(lifetime_sec, 6),
                "startup_sec": round(startup_sec, 6),
                "ready_sec": round(ready_sec, 6),
                "lifetime_gpu_seconds": round(lifetime_gpu_seconds, 6),
                "startup_gpu_seconds": round(startup_gpu_seconds_i, 6),
                "ready_gpu_seconds": round(ready_gpu_seconds_i, 6),
            }
        )
        normalized.append(item)

    capped_total_gpu_seconds = _capped_weighted_interval_seconds(
        lifetime_intervals,
        max_billing_gpus,
    )
    capped_startup_gpu_seconds = _capped_weighted_interval_seconds(
        startup_intervals,
        max_billing_gpus,
    )
    capped_ready_gpu_seconds = _capped_weighted_interval_seconds(
        ready_intervals,
        max_billing_gpus,
    )
    if max_billing_gpus is not None and float(max_billing_gpus or 0.0) > 0.0:
        total_gpu_seconds = capped_total_gpu_seconds
        startup_gpu_seconds = min(capped_startup_gpu_seconds, total_gpu_seconds)
        ready_gpu_seconds = min(capped_ready_gpu_seconds, total_gpu_seconds)

    infra_cost_total_usd = total_gpu_seconds * max(0.0, float(gpu_cost_per_second_usd or 0.0))
    per_request_denominator = (
        int(completed_requests)
        if int(completed_requests or 0) > 0
        else max(0, int(total_requests or 0))
    )
    infra_cost_per_request_usd = (
        infra_cost_total_usd / per_request_denominator
        if per_request_denominator > 0
        else 0.0
    )
    avg_e2e_s = max(0.0, float(avg_e2e_ms or 0.0)) / 1000.0
    infra_ce_denom = infra_cost_per_request_usd * avg_e2e_s
    infra_ce = 1.0 / infra_ce_denom if infra_ce_denom > 1e-12 else 0.0
    return {
        "instance_lifecycle_log": normalized,
        "infra_gpu_seconds_total": total_gpu_seconds,
        "infra_startup_gpu_seconds": startup_gpu_seconds,
        "infra_ready_gpu_seconds": ready_gpu_seconds,
        "infra_cost_total_usd": infra_cost_total_usd,
        "infra_cost_per_request_usd": infra_cost_per_request_usd,
        "infra_ce": infra_ce,
        "gpu_cost_per_second_usd": max(0.0, float(gpu_cost_per_second_usd or 0.0)),
        "infra_billing_elapsed_sec": billing_elapsed,
        "billing_start_offset_s": billing_start_offset,
        "billing_end_offset_s": billing_end_offset,
        "pre_replay_startup_s": safe_pre_replay,
        "deployment_idle_tail_s": safe_tail,
        "serverless_idle_retention_s": safe_retention,
        "infra_max_billing_gpus": max(0.0, float(max_billing_gpus or 0.0)),
        "billing_scope": "deployment_lifecycle",
    }


def _union_interval_seconds(intervals: Sequence[Tuple[float, float]]) -> float:
    finite = sorted(
        (float(start), float(end))
        for start, end in intervals
        if math.isfinite(float(start)) and math.isfinite(float(end)) and float(end) > float(start)
    )
    if not finite:
        return 0.0
    merged_total = 0.0
    cur_start, cur_end = finite[0]
    for start, end in finite[1:]:
        if start <= cur_end:
            cur_end = max(cur_end, end)
            continue
        merged_total += cur_end - cur_start
        cur_start, cur_end = start, end
    merged_total += cur_end - cur_start
    return max(0.0, merged_total)


def _max_concurrent_from_lifecycles(
    lifecycles: Collection[Dict[str, Any]],
    *,
    elapsed_sec: float,
    ready_only: bool,
    weight_key: Optional[str] = None,
) -> float:
    safe_elapsed = max(0.0, float(elapsed_sec or 0.0))
    events: List[Tuple[float, int, float]] = []
    for raw in lifecycles or []:
        item = dict(raw or {})
        start_key = "ready_offset_s" if ready_only else "created_offset_s"
        start = max(0.0, min(float(item.get(start_key, 0.0) or 0.0), safe_elapsed))
        end = max(start, min(float(item.get("removed_offset_s", safe_elapsed) or safe_elapsed), safe_elapsed))
        if end <= start:
            continue
        weight = float(item.get(weight_key, 1.0) or 1.0) if weight_key else 1.0
        events.append((start, 1, weight))
        events.append((end, -1, weight))
    current = 0.0
    peak = 0.0
    for _, kind, weight in sorted(events, key=lambda ev: (ev[0], ev[1])):
        current += kind * weight
        peak = max(peak, current)
    return max(0.0, peak)


def _summarize_runtime_resource_efficiency(
    lifecycles: Collection[Dict[str, Any]],
    requests: Collection[Any],
    *,
    elapsed_sec: float,
    ttft_slo_ms: float,
    max_allocated_gpus: Optional[float] = None,
    max_allocated_replicas: Optional[float] = None,
) -> Dict[str, float]:
    safe_elapsed = max(0.0, float(elapsed_sec or 0.0))
    normalized_lifecycles = [dict(item or {}) for item in (lifecycles or [])]
    gpu_count_by_instance = {
        str(item.get("instance_id") or ""): max(1, int(item.get("gpu_count", 1) or 1))
        for item in normalized_lifecycles
        if str(item.get("instance_id") or "")
    }
    intervals_by_instance: Dict[str, List[Tuple[float, float]]] = defaultdict(list)
    active_weighted_intervals: List[Tuple[float, float, float]] = []
    completed = 0
    output_tokens = 0
    slo_completed = 0
    slo_output_tokens = 0
    for req in requests or []:
        getter = req.get if isinstance(req, dict) else lambda key, default=None: getattr(req, key, default)
        if not bool(getter("success", False)):
            continue
        completed += 1
        tokens = max(0, int(getter("output_tokens", getter("completion_tokens", 0)) or 0))
        output_tokens += tokens
        overall_ttft_ms = _positive_or_fallback(getter("overall_ttft_ms", 0.0), getter("ttft_ms", 0.0))
        if overall_ttft_ms <= float(ttft_slo_ms or DEFAULT_TTFT_SLO_MS):
            slo_completed += 1
            slo_output_tokens += tokens
        instance_id = str(getter("instance_id", "") or "__unknown_runtime__")
        end_offset = getter("completed_offset_s", getter("completion_offset_s", None))
        service_e2e_ms = _positive_or_fallback(getter("service_e2e_ms", 0.0), getter("e2e_ms", 0.0))
        start_offset = getter("admitted_offset_s", None)
        try:
            end = float(end_offset)
        except Exception:
            continue
        if start_offset is None:
            start = end - max(0.0, float(service_e2e_ms or 0.0)) / 1000.0
        else:
            try:
                start = float(start_offset)
            except Exception:
                start = end - max(0.0, float(service_e2e_ms or 0.0)) / 1000.0
        start = max(0.0, min(start, safe_elapsed))
        end = max(start, min(end, safe_elapsed))
        if end > start:
            intervals_by_instance[instance_id].append((start, end))
            active_weighted_intervals.append(
                (start, end, float(gpu_count_by_instance.get(instance_id, 1)))
            )

    active_gpu_seconds = 0.0
    for instance_id, intervals in intervals_by_instance.items():
        active_seconds = _union_interval_seconds(intervals)
        active_gpu_seconds += active_seconds * gpu_count_by_instance.get(instance_id, 1)
    active_gpu_seconds = _capped_weighted_interval_seconds(
        active_weighted_intervals,
        max_allocated_gpus,
    )

    total_gpu_seconds = _capped_weighted_interval_seconds(
        [
            (
                float(item.get("created_offset_s", 0.0) or 0.0),
                float(item.get("removed_offset_s", 0.0) or 0.0),
                float(item.get("gpu_count", 1) or 1),
            )
            for item in normalized_lifecycles
        ],
        max_allocated_gpus,
    )
    startup_gpu_seconds = _capped_weighted_interval_seconds(
        [
            (
                float(item.get("created_offset_s", 0.0) or 0.0),
                float(item.get("ready_offset_s", 0.0) or 0.0),
                float(item.get("gpu_count", 1) or 1),
            )
            for item in normalized_lifecycles
        ],
        max_allocated_gpus,
    )
    ready_gpu_seconds = _capped_weighted_interval_seconds(
        [
            (
                float(item.get("ready_offset_s", 0.0) or 0.0),
                float(item.get("removed_offset_s", 0.0) or 0.0),
                float(item.get("gpu_count", 1) or 1),
            )
            for item in normalized_lifecycles
        ],
        max_allocated_gpus,
    )
    idle_ready_gpu_seconds = max(0.0, ready_gpu_seconds - active_gpu_seconds)
    summary = {
        "infra_active_gpu_seconds": active_gpu_seconds,
        "infra_idle_ready_gpu_seconds": idle_ready_gpu_seconds,
        "infra_avg_allocated_gpus": total_gpu_seconds / safe_elapsed if safe_elapsed > 1e-12 else 0.0,
        "infra_avg_ready_gpus": ready_gpu_seconds / safe_elapsed if safe_elapsed > 1e-12 else 0.0,
        "infra_max_allocated_gpus": _max_concurrent_from_lifecycles(
            normalized_lifecycles,
            elapsed_sec=safe_elapsed,
            ready_only=False,
            weight_key="gpu_count",
        ),
        "infra_max_ready_gpus": _max_concurrent_from_lifecycles(
            normalized_lifecycles,
            elapsed_sec=safe_elapsed,
            ready_only=True,
            weight_key="gpu_count",
        ),
        "infra_avg_replicas": (
            sum(float(item.get("lifetime_sec", 0.0) or 0.0) for item in normalized_lifecycles) / safe_elapsed
            if safe_elapsed > 1e-12 else 0.0
        ),
        "infra_max_replicas": _max_concurrent_from_lifecycles(
            normalized_lifecycles,
            elapsed_sec=safe_elapsed,
            ready_only=False,
            weight_key=None,
        ),
        "infra_active_gpu_ratio": active_gpu_seconds / total_gpu_seconds if total_gpu_seconds > 1e-12 else 0.0,
        "infra_ready_active_gpu_ratio": active_gpu_seconds / ready_gpu_seconds if ready_gpu_seconds > 1e-12 else 0.0,
        "infra_idle_ready_gpu_ratio": idle_ready_gpu_seconds / total_gpu_seconds if total_gpu_seconds > 1e-12 else 0.0,
        "infra_startup_gpu_ratio": startup_gpu_seconds / total_gpu_seconds if total_gpu_seconds > 1e-12 else 0.0,
        "completed_requests_per_gpu_second": completed / total_gpu_seconds if total_gpu_seconds > 1e-12 else 0.0,
        "output_tokens_per_gpu_second": output_tokens / total_gpu_seconds if total_gpu_seconds > 1e-12 else 0.0,
        "goodput_requests_per_gpu_second": slo_completed / total_gpu_seconds if total_gpu_seconds > 1e-12 else 0.0,
        "goodput_tokens_per_gpu_second": slo_output_tokens / total_gpu_seconds if total_gpu_seconds > 1e-12 else 0.0,
    }
    if max_allocated_gpus is not None and float(max_allocated_gpus or 0.0) > 0.0:
        cap = max(0.0, float(max_allocated_gpus or 0.0))
        summary["infra_max_allocated_gpus"] = min(summary["infra_max_allocated_gpus"], cap)
        summary["infra_max_ready_gpus"] = min(summary["infra_max_ready_gpus"], cap)
    if max_allocated_replicas is not None and float(max_allocated_replicas or 0.0) > 0.0:
        replica_cap = max(0.0, float(max_allocated_replicas or 0.0))
        summary["infra_avg_replicas"] = min(summary["infra_avg_replicas"], replica_cap)
        summary["infra_max_replicas"] = min(summary["infra_max_replicas"], replica_cap)
    return summary


def _build_hf_generate_kwargs(model, tokenizer, max_new_tokens: int, *, temperature: float, top_p: float) -> Dict[str, Any]:
    """Build warning-free HF generate kwargs for either sampling or greedy decoding."""
    kwargs: Dict[str, Any] = {
        "max_new_tokens": max_new_tokens,
        "pad_token_id": tokenizer.eos_token_id,
    }
    if temperature > 0.0:
        kwargs.update(
            do_sample=True,
            temperature=max(float(temperature), 1e-5),
            top_p=min(max(float(top_p), 1e-5), 1.0),
        )
        return kwargs

    generation_config = copy.deepcopy(getattr(model, "generation_config", None))
    if generation_config is not None:
        generation_config.do_sample = False
        if hasattr(generation_config, "temperature"):
            generation_config.temperature = 1.0
        if hasattr(generation_config, "top_p"):
            generation_config.top_p = 1.0
        if hasattr(generation_config, "top_k"):
            generation_config.top_k = 50
        kwargs["generation_config"] = generation_config
    else:
        kwargs["do_sample"] = False
    return kwargs


# ==========================================================================
# Scenario runner ? implements all 6 baseline/ablation scenarios
# ==========================================================================

class ScenarioRunner:
    """
    Runs one scenario.  Handles all 6 baseline_types:

      cold_start         ? always download from remote (bw throttled)
      slora_style        ? S-LoRA: CPU memory, PCIe load, LRU-GPU eviction
      serverlessllm      ? ServerlessLLM: NVMe checkpoint, no preloading
      faaslora_nvme      ? Contribution 1: hit-aware NVME preloading
      faaslora_no_coord  ? Contribution 1+2: preloading + GPU residency, no coordination
      faaslora_full      ? Contribution 1+2+3: full FaaSLoRA with coordination
      backbone_only      ? no LoRA (theoretical lower bound)
    """

    def __init__(
        self,
        name: str,
        baseline_type: str,
        adapter_info: Dict[str, Dict],
        traces: List[RequestTrace],
        remote_dir: Path,
        nvme_dir: Path,
        bandwidth_mbps: float,
        hardware_cfg: Dict,
        cost_model: Dict,
        engine: InferenceEngine,
        preload_cfg: Dict,
        workload_cfg: Dict,
        coord_cfg: Optional[Dict] = None,
        experiment_stack: Optional[Any] = None,
        engine_factory: Optional[Callable[..., Awaitable[Tuple[Any, Any]]]] = None,
        runner_model_cfg: Optional[Dict] = None,
        external_replay: Optional[Any] = None,
        initial_runtime_pending: bool = False,
        physical_deployment: Optional[Any] = None,
    ):
        self.name          = name
        self.baseline_type = baseline_type
        self.adapter_info  = adapter_info
        self.traces        = traces
        self.remote_dir    = remote_dir
        self.nvme_dir      = nvme_dir
        self.bw_mbps       = bandwidth_mbps
        self.hw            = copy.deepcopy(hardware_cfg)
        self.cost_model    = cost_model
        self.engine        = engine
        # Scenario-level control logic must use the runner/global model profile,
        # not a child-runtime local view such as visible_device_ids=[0] inside a
        # dedicated subprocess. Keep local runtime device tracking separate.
        runner_cfg = runner_model_cfg if isinstance(runner_model_cfg, dict) else None
        self.model_cfg     = copy.deepcopy(
            runner_cfg if runner_cfg is not None else (getattr(engine, "model_cfg", {}) or {})
        )
        self.preload_cfg   = preload_cfg
        self.wl_cfg        = workload_cfg
        self.coord_cfg     = coord_cfg or {}
        if type(initial_runtime_pending) is not bool:
            raise ValueError('initial_runtime_pending must be a boolean')
        self._initial_runtime_pending = initial_runtime_pending
        if initial_runtime_pending:
            if (self.coord_cfg.get('routing_policy') != 'ieee_confirmed'
                    or self.coord_cfg.get('instance_mode') not in ('auto', 'dedicated')
                    or not self.model_cfg.get('ieee_gpu_references') or engine_factory is None
                    or not isinstance(engine, InferenceEngine) or engine.backend != 'vllm'
                    or getattr(engine, 'engine', None) is not None):
                raise ValueError('pending IEEE deployment requires an uninitialized descriptor and owned factory')
        self._configure_external_replay(external_replay)
        self._physical_deployment = physical_deployment
        if physical_deployment is not None:
            if (self._external_replay is None or self.model_cfg.get('ieee_physical_allocation') is not True
                    or physical_deployment.allocations.resolve() !=
                    Path(os.environ['FAASLORA_TC_LAUNCH_RECEIPT']).parent.resolve()/'physical_allocations'):
                raise ValueError('physical deployment must cover this exact external replay/runtime factory')
        generation_contract = str(
            self.wl_cfg.get("generation_contract", "legacy") or "legacy"
        ).strip().lower()
        if generation_contract not in {"legacy", "fixed_length_greedy_v1"}:
            raise ValueError(
                f"Unsupported generation_contract={generation_contract!r}; "
                "expected legacy or fixed_length_greedy_v1"
            )
        self._generation_contract = generation_contract
        self.model_cfg["generation_contract"] = generation_contract
        if getattr(self.engine, "model_cfg", None) is not None:
            self.engine.model_cfg["generation_contract"] = generation_contract
        self._service_profiles = self._load_ieee_service_profiles()
        self._preparation_profiles = self._load_ieee_preparation_profiles()
        self._coordination_enabled = bool(
            self.coord_cfg.get("coordination_enabled", baseline_type == "faaslora_full")
        )
        self._scale_up_handoff_enabled = bool(
            self.coord_cfg.get("scale_up_handoff_enabled", True)
        )
        self._hierarchical_residency_enabled = bool(
            self.preload_cfg.get("hierarchical_residency_enabled", True)
        )
        self._stack        = experiment_stack  # full ResidencyManager + PreloadingManager (C1/C2/C3)
        self.engine_factory = engine_factory  # B1: 可选；提供时 scale-up 可 add_instance(新 engine, 新 coordinator)

        # Per-scenario cache state
        self._nvme_cache: Dict[str, str]  = {}
        self._gpu_warmed: set             = set()
        self._lru_order:  List[str]       = []
        self._lru_max:    int             = preload_cfg.get("lru_cache_size", 4)
        self._access_count: Dict[str, int] = defaultdict(int)
        self._remote_artifact_client = None
        self._remote_transfer_evidence: List[Dict[str, Any]] = []
        self._adapter_transfer_pressure_evidence: List[Dict[str, Any]] = []
        self._bandwidth_limiter = AggregateBandwidthLimiter(self.bw_mbps)
        self._remote_materialize_locks: Dict[str, asyncio.Lock] = defaultdict(asyncio.Lock)
        self._local_sim_materialization_mode = (
            "reserve_then_hardlink_v1"
            if str(self.name or "").startswith("v2_")
            else "copy_then_reserve_legacy"
        )
        self._local_sim_materialization_counts: Dict[str, int] = defaultdict(int)
        if _remote_artifact_from_env is not None:
            self._remote_artifact_client = _remote_artifact_from_env()
        if self._remote_artifact_client is not None:
            if self.model_cfg.get('ieee_gpu_references', False):
                manifest_path = self.model_cfg.get('artifact_content_manifest_path')
                if not manifest_path:
                    raise ValueError('native remote transfer requires artifact_content_manifest_path')
                with Path(manifest_path).open(encoding='utf-8') as manifest_file:
                    self._remote_artifact_client.configure_content_manifest(json.load(manifest_file))
            print(
                "    Remote artifact transfer enabled: "
                f"{getattr(self._remote_artifact_client, 'endpoint', '<unknown>')}"
            )

        # Dynamic scaling state (workload-adaptive thresholds)
        cc = self.coord_cfg
        self._dynamic_scaling = bool(cc.get("dynamic_scaling", True))
        self._baseline_rps_ewma_beta = float(cc.get("baseline_rps_ewma_beta", 0.25))
        self._scale_up_alpha = float(cc.get("scale_up_alpha", 0.3))
        self._scale_up_t_min = float(cc.get("scale_up_t_min", 1.0))
        self._scale_down_beta = float(cc.get("scale_down_beta", 0.4))
        scale_down_duration_raw = cc.get("scale_down_duration_s", "auto")
        self._scale_down_duration_auto = _is_auto_config_value(scale_down_duration_raw)
        parsed_scale_down_duration_s = _nonnegative_seconds_or_none(scale_down_duration_raw)
        self._scale_down_duration_s = parsed_scale_down_duration_s if parsed_scale_down_duration_s is not None else 0.0
        scale_down_cooldown_raw = cc.get("scale_down_cooldown_s", cc.get("scale_cooldown_s", "auto"))
        self._scale_down_cooldown_auto = _is_auto_config_value(scale_down_cooldown_raw)
        parsed_scale_down_cooldown_s = _nonnegative_seconds_or_none(scale_down_cooldown_raw)
        self._scale_down_cooldown_s = parsed_scale_down_cooldown_s if parsed_scale_down_cooldown_s is not None else 0.0
        self._scale_down_startup_break_even_s = max(
            0.0,
            float(cc.get("scale_down_startup_break_even_s", 0.0) or 0.0),
        )
        break_even_factor_raw = cc.get("scale_down_break_even_factor", 1.0)
        if break_even_factor_raw is None:
            break_even_factor_raw = 1.0
        self._scale_down_break_even_factor = max(0.0, float(break_even_factor_raw))
        self._dynamic_warm_pool = bool(cc.get("dynamic_warm_pool", True))
        self._warm_pool_gamma = float(cc.get("warm_pool_gamma", 0.2))
        self._warm_pool_min = int(cc.get("warm_pool_min", 2))
        self._warm_pool_max = int(cc.get("warm_pool_max", 8))
        self._routing_policy = str(cc.get("routing_policy", "adapter_affinity")).lower()
        self._ieee_handoff_policy = str(cc.get('ieee_handoff_policy', 'full'))
        if self._ieee_handoff_policy not in ('full', 'no_handoff', 'delayed'):
            raise ValueError('unknown IEEE activation preparation policy')
        if self._routing_policy == 'ieee_confirmed' and self._service_profiles is None:
            raise ValueError('IEEE routing requires measured ieee_service_profile initialization')
        if self._preparation_profiles is not None and self._routing_policy != 'ieee_confirmed':
            raise ValueError('preparation profile requires IEEE source admission, not legacy routing')
        self._ieee_routing_epoch = 0
        self._ieee_scale_controller = None
        self._ieee_control_events = []
        self._ieee_residency_tasks = {}
        self._ieee_residency_epochs = []
        self._ieee_artifact_identities = {}
        self._ieee_nvml_initialized = False
        if self._routing_policy == 'ieee_confirmed':
            if int(self.model_cfg.get('tensor_parallel_size', 1)) != 1:
                raise ValueError('current native ownership qualification requires TP=1')
            if self.adapter_info and self._remote_artifact_client is None:
                raise ValueError('IEEE routing requires the frozen real-remote artifact index')
            for aid in self.adapter_info:
                # Static metadata, not payload materialization. The same config
                # SHA belongs to the actual HTTP download contract.
                self._ieee_artifact_identities[aid] = self._remote_artifact_client.routing_identity(
                    aid, (self.remote_dir / aid / 'adapter_config.json').read_bytes())
        self._arrival_window_s = float(cc.get("arrival_window_s", 5.0))
        self._scale_eval_interval_s = max(0.1, float(cc.get("scale_eval_interval_s", 15.0) or 15.0))
        self._baseline_rps: float = 1.0
        self._low_load_since: Optional[float] = None
        self._active_loras_ewma: float = 0.0
        self._instance_mode = str(self.coord_cfg.get("instance_mode", "shared")).lower()
        if self._service_profiles is not None and self._instance_mode not in ('auto', 'dedicated'):
            raise ValueError('IEEE service profiles require distinct physical runtime replicas')
        self._primary_instance_id: Optional[str] = None
        self._retired_coord_metrics: List[Dict[str, Any]] = []
        self._arrival_base = traces[0].arrival_time if traces else 0.0
        self._scheduled_arrivals = [
            max(0.0, t.arrival_time - self._arrival_base) for t in traces
        ]
        self._trace_scale_down_floor_s = self._derive_trace_scale_down_floor_s()
        if self._scale_down_duration_auto:
            self._scale_down_duration_s = self._trace_scale_down_floor_s
        if self._scale_down_cooldown_auto:
            self._scale_down_cooldown_s = self._trace_scale_down_floor_s
        self._live_progress = bool(self.wl_cfg.get("live_progress", True))
        self._live_progress_interval_s = float(self.wl_cfg.get("live_progress_interval_s", 8.0))
        self._live_progress_every_requests = max(1, int(self.wl_cfg.get("live_progress_every_requests", 25)))
        self._show_instance_panel = bool(self.wl_cfg.get("show_instance_panel", True))
        self._ttft_slo_ms = max(
            0.0,
            float(self.wl_cfg.get("ttft_slo_ms", self.coord_cfg.get("ttft_slo_ms", DEFAULT_TTFT_SLO_MS)) or DEFAULT_TTFT_SLO_MS),
        )
        self._workload_concurrency_limit = max(
            1,
            int(self.wl_cfg.get("concurrency", 1) or 1),
        )
        self._online_hotness_window_s = _derive_online_hotness_window_s(
            self.coord_cfg,
            self.preload_cfg,
            ttft_slo_ms=self._ttft_slo_ms,
        )
        self._ieee_online_observation_binding = None
        if (self._routing_policy == 'ieee_confirmed'
                and self.model_cfg.get('ieee_admission_profile') is not None):
            self._ieee_online_observation_binding = _validate_ieee_online_observation_binding(
                self.model_cfg, self.coord_cfg, self.preload_cfg, self._stack,
                runner_window_s=self._online_hotness_window_s)
        self._live_last_print_time = 0.0
        self._live_last_print_completed = -1
        self._run_started_at = 0.0
        self._initial_preload_wall_s = 0.0
        self._initial_preload_bytes = 0
        self._initial_preload_transfer_count = 0
        self._initial_preload_injected_wait_s = 0.0
        self._initial_preload_gpu_count = self._runtime_gpu_count_for_cfg(self.model_cfg)
        self._primary_engine_initialization_wall_s = 0.0
        self._pre_replay_deployment_wall_s = 0.0
        self._gpu_environment_guard_last_at = 0.0
        self._gpu_environment_guard_interval_s = 30.0
        self._dynamic_forwarding_enabled = bool(self.preload_cfg.get("dynamic_forwarding_enabled", True))
        self._runtime_gpu_forward_tasks: Dict[tuple, asyncio.Task] = {}
        self._runtime_gpu_forward_attempt_count: int = 0
        self._runtime_gpu_forward_success_count: int = 0
        self._live_scale_up_events: List[Dict[str, Any]] = []
        self._observed_scale_up_cold_start_latencies_ms: List[float] = []
        self._observed_scale_up_runtime_startup_latencies_ms: List[float] = []
        self._pending_scale_up_tasks: set[asyncio.Task] = set()
        self._pending_scale_up_device_ids: set[int] = set()
        self._pending_scale_up_sequences: set[int] = set()
        self._failed_runtime_device_ids: set[int] = set()
        self._next_pending_scale_up_sequence: int = 0
        self._scaleup_runtime_instance_ids: set[str] = set()
        self._scaleup_runtime_handoff_plans: Dict[str, Dict[str, Any]] = {}
        self._scaleup_runtime_lora_request_ordinals: Dict[str, int] = {}
        self._live_scale_eval_last_at: float = 0.0
        self._last_live_scale_up_completed_at: float = 0.0
        self._last_live_scale_down_completed_at: float = 0.0
        self._live_scale_overrides: Optional[Dict[str, float]] = None
        self._last_scale_up_preload_budget: Dict[str, Any] = {}
        self._last_scale_up_handoff_plan: Dict[str, Any] = {}
        self._instance_lifecycle_records: Dict[str, Dict[str, Any]] = {}
        self._live_arrived_lora_counts: Dict[str, int] = defaultdict(int)
        self._live_started_lora_counts: Dict[str, int] = defaultdict(int)
        self._live_arrived_lora_first_seen_seq: Dict[str, int] = {}
        self._live_arrived_lora_seq: int = 0
        self._live_waiting_traces_by_id: Dict[str, Any] = {}
        self._background_planning_us: List[float] = []
        self._dispatch_admitted_requests: int = 0
        self._dispatch_admission_condition: Optional[asyncio.Condition] = None
        self._runtime_slot_capacity_condition: Optional[asyncio.Condition] = None
        self._unsettled_runtime_reservations: Dict[str, RuntimeRequestReservation] = {}
        self._active_replay_t0: Optional[float] = None
        self._slot_retire_lock = asyncio.Lock()
        # The replay dispatcher, autoscaler, and subprocess RPC completion all
        # share one asyncio loop. Refreshing per-slot runtime hints on every
        # hot-path request admission can monopolize that loop and make the trace
        # arrival clock itself fall behind. Cache routing hints for a short
        # interval so online dispatch remains reactive without redoing the same
        # synchronous bookkeeping for every request.
        self._runtime_hints_refresh_interval_s = max(
            0.0,
            float(self.coord_cfg.get("runtime_hints_refresh_interval_s", 0.5) or 0.5),
        )
        self._runtime_hints_last_refresh_by_slot: Dict[str, float] = {}

        # Resource coordinator (contribution 3); when _stack is set, coordinator comes from stack
        coord_enabled = (
            baseline_type == "faaslora_full" and self._coordination_enabled
        )
        if self._stack is not None:
            self.coordinator = self._stack.coordinator
        else:
            self.coordinator = ResourceCoordinator(
                config={**coord_cfg, **hardware_cfg},
                coordination_enabled=coord_enabled,
            )
        # B1/B2: 实例池与路由；默认仅启动 min_instances，是否共享/独立 engine 由 instance_mode 控制。
        min_instances = int(self.coord_cfg.get("min_instances", 1))
        max_instances = int(self.coord_cfg.get("max_instances", 2))
        self.instance_pool = None
        self.router = None
        if InstancePool is not None and Router is not None and engine is not None:
            self.instance_pool = InstancePool(min_instances=min_instances, max_instances=max_instances,
                service_profiles=self._service_profiles, preparation_profiles=self._preparation_profiles)
            primary_owns_runtime = self._instance_mode in ("auto", "dedicated")
            if not initial_runtime_pending:
                self._primary_instance_id = self.instance_pool.add_instance(
                    engine,
                    self.coordinator,
                    owns_engine=primary_owns_runtime,
                    owns_coordinator=primary_owns_runtime,
                    device_id=getattr(engine, "device_id", None),
                )
            # shared 模式下，仅按 min_instances 预创建共享-engine 槽位。
            if self._instance_mode == "shared" and min_instances > 1:
                for _ in range(1, min_instances):
                    self.instance_pool.add_instance(
                        engine,
                        self.coordinator,
                        owns_engine=False,
                        owns_coordinator=False,
                        device_id=getattr(engine, "device_id", None),
                    )
            self.router = Router(
                self.instance_pool,
                policy=self._routing_policy,
                runtime_concurrency_cap=self._runtime_forward_capacity_limit(),
                max_active_loras=self._runtime_max_active_loras(),
                service_bin_ms=cc.get('service_bin_ms'),
            )
            for slot in self.instance_pool.get_slots():
                self._prime_slot_cache_view(slot, include_gpu=self._slot_should_include_gpu(slot))
            self._sync_stack_gpu_accounting()

        if self._external_replay is not None:
            self._external_trace_by_id = {trace.request_id: trace for trace in self.traces}
            self._external_replay.subscribe(self._observe_external_ingress)

    def _planned_ieee_runtime_model_config(self):
        """Resolve the same child configuration as the owned runtime factory.

        A pending controller descriptor has no backend yet. Validate its future
        child, including eager-mode resolution and worker cleanup policy, rather
        than dropping those fields from the measured profile identity. Actual
        new workers are independently validated after spawn as before.
        """
        configuration, _ = _prepare_dedicated_subprocess_model_cfg(
            self.model_cfg, device_id=0, runtime_gpu_ids=[0])
        return configuration

    def _ieee_profile_binding_model_config(self):
        if getattr(self, '_initial_runtime_pending', False):
            return self._planned_ieee_runtime_model_config()
        return getattr(self.engine, 'model_cfg', None)

    def _load_ieee_service_profiles(self):
        """Bind measured initialization to this actual runner, never legacy defaults."""
        spec = self.coord_cfg.get('ieee_service_profile')
        if spec is None:
            return None
        if (not isinstance(spec, dict) or set(spec) != {'path', 'sha256', 'context', 'ewma_beta'}
                or not isinstance(spec['path'], str) or not spec['path']
                or not self.model_cfg.get('ieee_gpu_references', False)):
            raise ValueError('invalid IEEE measured service profile configuration')
        from faaslora.experiment.instance_pool import FrozenServiceProfiles
        return FrozenServiceProfiles.load(Path(spec['path']), expected_sha256=spec['sha256'],
            model_config=self._ieee_profile_binding_model_config(),
            expected_context=spec['context'], beta=spec['ewma_beta'])

    def _observe_external_ingress(self, record):
        trace = self._external_trace_by_id[record['request_id']]
        self._observe_live_arrived_lora(trace.adapter_id)
        self._observe_live_waiting_trace(trace)
        if trace.adapter_id and self._stack is not None:
            self._stack.record_arrival(trace.adapter_id, observed_at=record['server_received_s'])

    def _load_ieee_preparation_profiles(self):
        """Use completed-load d initialization, never reinterpret service D."""
        spec = self.coord_cfg.get('ieee_preparation_profile')
        if spec is None:
            return None  # Explicit source-only qualification may collect first measurements.
        if (not isinstance(spec, dict) or set(spec) != {'path', 'sha256', 'context', 'ewma_beta'}
                or not isinstance(spec['path'], str) or not spec['path']
                or not self.model_cfg.get('ieee_gpu_references', False)):
            raise ValueError('invalid IEEE measured preparation profile configuration')
        service_spec = self.coord_cfg.get('ieee_service_profile')
        if service_spec is not None and spec['context'] != service_spec['context']:
            raise ValueError('preparation/service measurement contexts differ')
        from faaslora.preloading.preloading_planner import FrozenPreparationProfiles
        return FrozenPreparationProfiles.load(Path(spec['path']), expected_sha256=spec['sha256'],
            model_config=self._ieee_profile_binding_model_config(),
            expected_context=spec['context'], beta=spec['ewma_beta'])

    def _runtime_gpu_count_for_cfg(self, cfg: Optional[Dict[str, Any]] = None) -> int:
        effective_cfg = cfg if isinstance(cfg, dict) else getattr(self, "model_cfg", {})
        return max(1, int((effective_cfg or {}).get("tensor_parallel_size", 1) or 1))

    def _run_elapsed_offset_s(self, when: Optional[float] = None) -> float:
        run_started_at = float(getattr(self, "_run_started_at", 0.0) or 0.0)
        if run_started_at <= 0.0:
            return 0.0
        reference = time.perf_counter() if when is None else float(when)
        return max(0.0, reference - run_started_at)

    def _control_path_percentile(self, values: Sequence[float], percentile: float) -> float:
        finite = sorted(float(v) for v in values if math.isfinite(float(v)))
        if not finite:
            return 0.0
        if len(finite) == 1:
            return finite[0]
        rank = max(0.0, min(1.0, float(percentile) / 100.0)) * (len(finite) - 1)
        lo = int(math.floor(rank))
        hi = int(math.ceil(rank))
        if lo == hi:
            return finite[lo]
        frac = rank - lo
        return finite[lo] * (1.0 - frac) + finite[hi] * frac

    def _attach_control_path_background_metrics(self, result: ScenarioResult) -> None:
        if getattr(self, 'model_cfg', {}).get('timing_contract') == 'ieee_tc_native_v1':
            result.runtime_request_ownership = {
                'kind': 'native_request_reservation_lifetime_v1',
                'all_native_requests_settled': not self._unsettled_runtime_reservations,
                'unsettled': [
                    {'request_id': key, 'adapter_id': reservation.adapter_id,
                     'instance_id': reservation.slot.instance_id if reservation.slot else None,
                     'generation_started': reservation.generation_started,
                     'native_terminal_observed': reservation.native_terminal_observed,
                     'gpu_reference_evidence': dict(reservation.gpu_reference_evidence),
                     'controller_capacity_released': reservation.released}
                    for key, reservation in sorted(self._unsettled_runtime_reservations.items())],
            }
        values = [
            float(v)
            for v in getattr(self, "_background_planning_us", [])
            if math.isfinite(float(v)) and float(v) >= 0.0
        ]
        result.background_planning_event_count = len(values)
        result.avg_background_planning_us = (
            sum(values) / len(values) if values else 0.0
        )
        result.p95_background_planning_us = (
            self._control_path_percentile(values, 95) if values else 0.0
        )

    def _ensure_instance_lifecycle_record(
        self,
        instance_id: Optional[str],
        *,
        runtime_kind: str,
        gpu_count: int,
        device_id: Optional[int],
        created_offset_s: Optional[float] = None,
        ready_offset_s: Optional[float] = None,
        lifecycle_source: Optional[str] = None,
        model_name: Optional[str] = None,
    ) -> Optional[Dict[str, Any]]:
        if not instance_id:
            return None
        key = str(instance_id)
        records = getattr(self, "_instance_lifecycle_records", None)
        if records is None:
            records = {}
            self._instance_lifecycle_records = records
        model_cfg = getattr(self, "model_cfg", {}) or {}
        record = records.get(key)
        if record is None:
            record = {
                "instance_id": key,
                "runtime_kind": str(runtime_kind or "shared"),
                "gpu_count": max(1, int(gpu_count or 1)),
                "device_id": device_id,
                "model_name": str(model_name or model_cfg.get("name") or ""),
                "lifecycle_source": str(lifecycle_source or ""),
                "created_offset_s": None,
                "ready_offset_s": None,
                "removed_offset_s": None,
                "remove_reason": None,
            }
            records[key] = record
        else:
            record["runtime_kind"] = str(record.get("runtime_kind") or runtime_kind or "shared")
            record["gpu_count"] = max(1, int(record.get("gpu_count", gpu_count) or gpu_count or 1))
            if record.get("device_id") is None and device_id is not None:
                record["device_id"] = device_id
            if not record.get("model_name") and model_name:
                record["model_name"] = str(model_name)
            if lifecycle_source and not record.get("lifecycle_source"):
                record["lifecycle_source"] = str(lifecycle_source)
        if created_offset_s is not None:
            created_value = float(created_offset_s or 0.0)
            if not math.isfinite(created_value):
                raise ValueError("created_offset_s must be finite")
            existing = record.get("created_offset_s")
            if existing is None or created_value < float(existing):
                record["created_offset_s"] = created_value
        if ready_offset_s is not None:
            ready_value = float(ready_offset_s or 0.0)
            if not math.isfinite(ready_value):
                raise ValueError("ready_offset_s must be finite")
            created_value = float(record.get("created_offset_s") or 0.0)
            ready_value = max(created_value, ready_value)
            existing = record.get("ready_offset_s")
            if existing is None or ready_value < float(existing):
                record["ready_offset_s"] = ready_value
        return record

    def _mark_instance_lifecycle_removed(
        self,
        instance_id: Optional[str],
        *,
        removed_offset_s: Optional[float] = None,
        reason: Optional[str] = None,
    ) -> None:
        if not instance_id:
            return
        record = self._instance_lifecycle_records.get(str(instance_id))
        if record is None:
            return
        removed_value = (
            self._run_elapsed_offset_s()
            if removed_offset_s is None
            else max(0.0, float(removed_offset_s or 0.0))
        )
        existing = record.get("removed_offset_s")
        if existing is None or removed_value < float(existing):
            record["removed_offset_s"] = removed_value
        if reason:
            record["remove_reason"] = str(reason)

    def _begin_instance_lifecycle_tracking(self) -> None:
        if getattr(self, "_run_started_at", 0.0) <= 0.0 or getattr(self, "instance_pool", None) is None:
            return
        for slot in self.instance_pool.get_slots():
            instance_id = getattr(slot, "instance_id", None)
            if not instance_id:
                continue
            is_physical_runtime = bool(getattr(slot, "owns_engine", False)) or (
                instance_id == self._primary_instance_id
            )
            if not is_physical_runtime:
                continue
            runtime_kind = (
                "dedicated"
                if bool(getattr(slot, "owns_engine", False)) and instance_id != self._primary_instance_id
                else "shared" if self._instance_mode == "shared" else "dedicated"
            )
            engine = getattr(slot, "engine", None)
            model_cfg = getattr(engine, "model_cfg", None) if engine is not None else None
            self._ensure_instance_lifecycle_record(
                instance_id,
                runtime_kind=runtime_kind,
                gpu_count=self._runtime_gpu_count_for_cfg(model_cfg),
                device_id=getattr(slot, "device_id", None),
                created_offset_s=-max(
                    0.0,
                    float(
                        getattr(self, "_pre_replay_deployment_wall_s", 0.0)
                        or getattr(self, "_initial_preload_wall_s", 0.0)
                        or 0.0
                    ),
                ),
                ready_offset_s=0.0,
                lifecycle_source="initial_preload_then_run_start",
                model_name=(model_cfg or {}).get("name") if isinstance(model_cfg, dict) else None,
            )

    def finalize_runtime_infra_accounting(self, result: ScenarioResult) -> None:
        last_finished_by_instance: Dict[str, float] = {}
        for req in getattr(result, "requests", []) or []:
            if not bool(getattr(req, "success", False)):
                continue
            instance_id = str(getattr(req, "instance_id", "") or "").strip()
            if not instance_id:
                continue
            try:
                completed_offset_s = float(getattr(req, "completed_offset_s", 0.0) or 0.0)
            except Exception:
                continue
            if completed_offset_s > 0.0:
                last_finished_by_instance[instance_id] = max(
                    last_finished_by_instance.get(instance_id, 0.0),
                    completed_offset_s,
                )

        lifecycles = []
        for raw in self._instance_lifecycle_records.values():
            item = dict(raw or {})
            instance_id = str(item.get("instance_id") or "").strip()
            if instance_id in last_finished_by_instance:
                item["last_finished_offset_s"] = last_finished_by_instance[instance_id]
            lifecycles.append(item)

        runtime_gpu_count = max(
            1,
            max(
                (int(item.get("gpu_count", 1) or 1) for item in lifecycles),
                default=self._runtime_gpu_count_for_cfg(getattr(self, "model_cfg", {})),
            ),
        )
        instance_pool = getattr(self, "instance_pool", None)
        configured_max_instances = int(getattr(instance_pool, "max_instances", 0) or 0)
        if configured_max_instances <= 0:
            configured_max_instances = int(self.coord_cfg.get("max_instances", len(lifecycles) or 1) or 1)
        max_billing_gpus = float(max(1, configured_max_instances) * runtime_gpu_count)

        summary = _summarize_infra_cost_from_lifecycles(
            lifecycles,
            elapsed_sec=float(getattr(result, "elapsed_sec", 0.0) or 0.0),
            completed_requests=int(getattr(result, "completed", 0) or 0),
            total_requests=int(getattr(result, "total", 0) or 0),
            avg_e2e_ms=float(getattr(result, "avg_e2e_ms", 0.0) or 0.0),
            gpu_cost_per_second_usd=_gpu_cost_per_second_usd(self.cost_model),
            deployment_idle_tail_s=_cost_model_deployment_idle_tail_s(self.cost_model),
            serverless_idle_retention_s=_cost_model_serverless_idle_retention_s(self.cost_model),
            max_billing_gpus=max_billing_gpus,
            pre_replay_startup_s=float(
                getattr(self, "_pre_replay_deployment_wall_s", 0.0)
                or getattr(self, "_initial_preload_wall_s", 0.0)
                or 0.0
            ),
        )
        result.instance_lifecycle_log = summary["instance_lifecycle_log"]
        result.infra_gpu_seconds_total = summary["infra_gpu_seconds_total"]
        result.infra_startup_gpu_seconds = summary["infra_startup_gpu_seconds"]
        result.infra_ready_gpu_seconds = summary["infra_ready_gpu_seconds"]
        result.infra_cost_total_usd = summary["infra_cost_total_usd"]
        result.infra_cost_per_request_usd = summary["infra_cost_per_request_usd"]
        result.infra_ce = summary["infra_ce"]
        result.infra_billing_elapsed_sec = summary["infra_billing_elapsed_sec"]
        result.infra_max_billing_gpus = summary["infra_max_billing_gpus"]
        result.deployment_idle_tail_s = summary["deployment_idle_tail_s"]
        result.serverless_idle_retention_s = summary["serverless_idle_retention_s"]
        result.initial_preload_wall_s = max(
            0.0, float(getattr(self, "_initial_preload_wall_s", 0.0) or 0.0)
        )
        result.initial_preload_bytes = max(
            0, int(getattr(self, "_initial_preload_bytes", 0) or 0)
        )
        result.initial_preload_transfer_count = max(
            0, int(getattr(self, "_initial_preload_transfer_count", 0) or 0)
        )
        result.initial_preload_injected_wait_s = max(
            0.0,
            float(getattr(self, "_initial_preload_injected_wait_s", 0.0) or 0.0),
        )
        result.initial_preload_gpu_count = max(
            0, int(getattr(self, "_initial_preload_gpu_count", 0) or 0)
        )
        result.initial_preload_gpu_seconds = (
            result.initial_preload_wall_s * result.initial_preload_gpu_count
        )
        result.primary_engine_initialization_wall_s = max(
            0.0,
            float(
                getattr(self, "_primary_engine_initialization_wall_s", 0.0)
                or 0.0
            ),
        )
        result.pre_replay_deployment_wall_s = max(
            result.initial_preload_wall_s,
            float(
                getattr(self, "_pre_replay_deployment_wall_s", 0.0)
                or result.initial_preload_wall_s
            ),
        )
        result.pre_replay_deployment_gpu_seconds = (
            result.pre_replay_deployment_wall_s * result.initial_preload_gpu_count
        )

        resource_summary = _summarize_runtime_resource_efficiency(
            result.instance_lifecycle_log,
            result.requests,
            elapsed_sec=float(summary["infra_billing_elapsed_sec"] or 0.0),
            ttft_slo_ms=float(getattr(result, "ttft_slo_ms", DEFAULT_TTFT_SLO_MS) or DEFAULT_TTFT_SLO_MS),
            max_allocated_gpus=max_billing_gpus,
            max_allocated_replicas=float(max(1, configured_max_instances)),
        )
        for key, value in resource_summary.items():
            if hasattr(result, key):
                setattr(result, key, value)

        monetary_summary = _summarize_monetary_cost_from_resource_seconds(
            cost_model=self.cost_model,
            completed_requests=int(getattr(result, "completed", 0) or 0),
            total_requests=int(getattr(result, "total", 0) or 0),
            avg_e2e_ms=float(getattr(result, "avg_e2e_ms", 0.0) or 0.0),
            lifecycles=result.instance_lifecycle_log,
            infra_gpu_seconds_total=result.infra_gpu_seconds_total,
            infra_startup_gpu_seconds=result.infra_startup_gpu_seconds,
            infra_active_gpu_seconds=result.infra_active_gpu_seconds,
            infra_idle_ready_gpu_seconds=result.infra_idle_ready_gpu_seconds,
        )
        for key, value in monetary_summary.items():
            if hasattr(result, key):
                setattr(result, key, value)

        # Main paper CE uses cloud monetary cost. Keep flat InfraCost/InfraCE as
        # the resource-normalized audit view, and token proxy as legacy pricing
        # diagnostics so the three cost interpretations cannot be mixed silently.
        result.token_avg_cost_usd = result.avg_cost_usd
        result.token_total_cost_usd = result.total_cost_usd
        result.token_ce = result.cost_effectiveness_e2e
        result.avg_cost_usd = result.monetary_cost_per_request_usd
        result.total_cost_usd = result.monetary_cost_total_usd
        result.cost_effectiveness_e2e = result.monetary_ce
        result.qpr = result.monetary_ce
        _apply_result_cost_views(result)

    def _assert_clean_gpu_environment(self, *, context: str, force: bool = False) -> None:
        now = time.perf_counter()
        if not force and (now - self._gpu_environment_guard_last_at) < self._gpu_environment_guard_interval_s:
            return
        _assert_clean_gpu_environment(
            self._available_device_ids(),
            context=context,
            root_pid=os.getpid(),
        )
        self._gpu_environment_guard_last_at = now

    def _trace_input_tokens_hint(self, trace: Any) -> int:
        prompt_tokens = int(getattr(trace, "prompt_input_tokens", 0) or 0)
        if prompt_tokens > 0:
            return prompt_tokens
        return max(1, int(getattr(trace, "expected_input_tokens", 0) or 1))

    def _trace_requested_output_tokens(self, trace: Any, default_max_tokens: int) -> int:
        contract = str((getattr(self, "wl_cfg", {}) or {}).get("generation_contract", "legacy") or "legacy").strip().lower()
        if contract == "fixed_length_greedy_v1":
            source = getattr(trace, "expected_output_tokens", None)
            cap = (getattr(self, "wl_cfg", {}) or {}).get("fixed_output_max_tokens", 256)
            if type(source) is not int or source <= 0 or type(cap) is not int or cap <= 0:
                raise ValueError("fixed-output contract requires positive integer source expected output and cap")
            return min(source, cap)
        requested = int(getattr(trace, "expected_output_tokens", 0) or 0)
        if requested <= 0:
            requested = int(getattr(trace, "prompt_output_tokens", 0) or 0)
        if requested <= 0:
            requested = int(default_max_tokens or 0)
        return max(1, requested)

    def _prepare_request_execution_plan(
        self,
        engine: Any,
        trace: Any,
        default_max_tokens: int,
    ) -> RequestExecutionPlan:
        prompt = str(getattr(trace, "prompt", "") or "")
        chat_messages = getattr(trace, "chat_messages", None)
        input_tokens_hint = self._trace_input_tokens_hint(trace)
        requested_output_tokens = self._trace_requested_output_tokens(
            trace,
            default_max_tokens,
        )
        if hasattr(engine, "prepare_request"):
            try:
                plan = engine.prepare_request(
                    prompt=prompt,
                    requested_output_tokens=requested_output_tokens,
                    input_tokens_hint=input_tokens_hint,
                    chat_messages=chat_messages,
                )
                if isinstance(plan, RequestExecutionPlan):
                    return plan
            except Exception as exc:
                if self._generation_contract == "fixed_length_greedy_v1":
                    raise RuntimeError(
                        "fixed_length_greedy_v1 request preparation failed; "
                        "fallback prompt/token plans are forbidden"
                    ) from exc
            if self._generation_contract == "fixed_length_greedy_v1":
                raise RuntimeError(
                    "fixed_length_greedy_v1 request preparation did not return "
                    "a RequestExecutionPlan; fallback is forbidden"
                )
        if getattr(self, "_generation_contract", "legacy") == "fixed_length_greedy_v1":
            raise RuntimeError("fixed-output contract requires a real prompt/token request preparer")
        model_cfg = getattr(engine, "model_cfg", {}) or {}
        cap = int(model_cfg.get("max_output_tokens_cap", 0) or 0) if isinstance(model_cfg, dict) else 0
        max_tokens = requested_output_tokens
        if cap > 0:
            max_tokens = min(max_tokens, cap)
        max_input_len = int(model_cfg.get("max_input_len", 0) or 0) if isinstance(model_cfg, dict) else 0
        resolved_input_tokens = max(1, input_tokens_hint)
        if max_input_len > 0:
            resolved_input_tokens = min(resolved_input_tokens, max_input_len)
        return RequestExecutionPlan(
            prompt=prompt,
            input_tokens=resolved_input_tokens,
            max_tokens=max(1, max_tokens),
        )

    def _prepare_request_execution_plan_cache(
        self,
        engine: Any,
        traces: Collection[Any],
        default_max_tokens: int,
    ) -> Dict[str, RequestExecutionPlan]:
        """Precompute prompt/token budgets before replay timing starts.

        Baseline replayers already do prompt rendering / prompt-guard tokenization
        before the per-request timing window opens. Keep FaaSLoRA aligned by
        caching the resolved prompt, input-token count, and output-token cap
        outside the hot request path instead of recomputing them after
        dispatch/admission.
        """
        plan_cache: Dict[str, RequestExecutionPlan] = {}
        for trace in traces:
            request_id = str(getattr(trace, "request_id", "") or "")
            if not request_id or request_id in plan_cache:
                raise ValueError('replay requires nonempty unique request IDs')
            plan_cache[request_id] = self._prepare_request_execution_plan(
                engine,
                trace,
                default_max_tokens,
            )
        return plan_cache

    def _observe_dynamic_scaling_rps(
        self, observed_rps: float, observed_at: float
    ) -> Optional[Dict[str, float]]:
        """Refresh dynamic scaling thresholds from a live-observed arrival rate."""
        beta = self._baseline_rps_ewma_beta
        observed_rps = max(0.0, float(observed_rps or 0.0))
        self._baseline_rps = (1.0 - beta) * self._baseline_rps + beta * observed_rps
        t_scale_down = self._baseline_rps * self._scale_down_beta
        if observed_rps < t_scale_down:
            if self._low_load_since is None:
                self._low_load_since = observed_at
        else:
            self._low_load_since = None
        if not self._dynamic_scaling:
            return None
        t_scale_up = max(self._scale_up_t_min, self._baseline_rps * (1.0 + self._scale_up_alpha))
        return {"scale_up_threshold_rps": t_scale_up, "scale_down_threshold_rps": t_scale_down}

    def _update_dynamic_scaling_state(
        self, batch: list, batch_rps: float, batch_end_time: float
    ) -> Optional[Dict[str, float]]:
        """Update dynamic scaling state from completed-batch observations."""
        overrides = self._observe_dynamic_scaling_rps(batch_rps, batch_end_time)
        beta = self._baseline_rps_ewma_beta
        active_batch = len(set(t.adapter_id for t in batch if getattr(t, "adapter_id", None) is not None))
        if self._active_loras_ewma <= 0 and active_batch > 0:
            self._active_loras_ewma = float(active_batch)
        else:
            self._active_loras_ewma = (1.0 - beta) * self._active_loras_ewma + beta * active_batch
        return overrides

    def _current_live_waiting_trace_queue(self) -> List[Any]:
        waiting = getattr(self, "_live_waiting_traces_by_id", None)
        if not waiting:
            return []
        return list(waiting.values())

    def _observe_live_waiting_trace(self, trace: Optional[Any]) -> None:
        request_id = getattr(trace, "request_id", None)
        if not request_id:
            return
        waiting = getattr(self, "_live_waiting_traces_by_id", None)
        if waiting is None:
            waiting = {}
            self._live_waiting_traces_by_id = waiting
        waiting[str(request_id)] = trace

    def _release_live_waiting_trace(self, trace: Optional[Any]) -> None:
        request_id = getattr(trace, "request_id", None)
        if not request_id:
            return
        waiting = getattr(self, "_live_waiting_traces_by_id", None)
        if not waiting:
            return
        waiting.pop(str(request_id), None)

    def _current_live_active_adapter_count(self) -> int:
        active: set[str] = set()
        for trace in self._current_live_waiting_trace_queue():
            adapter_id = getattr(trace, "adapter_id", None)
            if adapter_id:
                active.add(str(adapter_id))
        started_counts = dict(getattr(self, "_live_started_lora_counts", {}) or {})
        for adapter_id, count in started_counts.items():
            if adapter_id and int(count or 0) > 0:
                active.add(str(adapter_id))
        return len(active)

    def _update_dynamic_scaling_live_state(
        self,
        arrival_rps: float,
        observed_at: float,
    ) -> Optional[Dict[str, float]]:
        overrides = self._observe_dynamic_scaling_rps(arrival_rps, observed_at)
        beta = self._baseline_rps_ewma_beta
        active_now = self._current_live_active_adapter_count()
        if self._active_loras_ewma <= 0 and active_now > 0:
            self._active_loras_ewma = float(active_now)
        else:
            self._active_loras_ewma = (1.0 - beta) * self._active_loras_ewma + beta * active_now
        return overrides

    def _should_trigger_scale_down(self) -> bool:
        """True if we should call trigger_scale_down (sustained low load when dynamic, or always when fixed)."""
        if not self._dynamic_scaling:
            return True
        if self._low_load_since is None:
            return False
        return (time.perf_counter() - self._low_load_since) >= self._effective_scale_down_min_idle_s()

    def _derive_trace_scale_down_floor_s(self) -> float:
        """Derive a model-agnostic scale-down floor from the replay arrival shape.

        This is intentionally a lower bound only. The actual scale-down gate is
        later raised to the observed/predicted runtime restart cost, so changing
        base models does not require hand-tuning an idle TTL for each model.
        """
        if getattr(self, '_external_replay', None) is not None:
            # A replay file is not lawful demand history. Only received arrivals
            # may inform this heuristic; before observations use the control period.
            arrivals = self._external_replay.observed_times
        else:
            arrivals = sorted(float(v) for v in (getattr(self, "_scheduled_arrivals", []) or []))
        gaps = [
            max(0.0, float(curr) - float(prev))
            for prev, curr in zip(arrivals, arrivals[1:])
            if float(curr) > float(prev)
        ]
        trace_gap_floor_s = _percentile_seconds(gaps, 90)
        scale_eval_floor_s = max(
            1.0,
            float(getattr(self, "_scale_eval_interval_s", 1.0) or 1.0),
        )
        return max(scale_eval_floor_s, trace_gap_floor_s)

    def _observed_scale_up_restart_seconds(self) -> float:
        """Estimate the restart cost paid if an idle dedicated runtime is removed.

        The live controller should not reclaim a GPU for a short idle gap when
        the next burst would immediately pay a longer cold-start. We prefer the
        observed scale-up cold-start because it includes the runtime becoming
        ready for service; runtime-startup is a fallback for early runs where no
        full cold-start samples have been recorded yet.
        """
        observed_ms = [
            float(v)
            for v in (getattr(self, "_observed_scale_up_cold_start_latencies_ms", []) or [])
            if float(v or 0.0) > 0.0
        ]
        if not observed_ms:
            observed_ms = [
                float(v)
                for v in (getattr(self, "_observed_scale_up_runtime_startup_latencies_ms", []) or [])
                if float(v or 0.0) > 0.0
            ]
        if not observed_ms:
            handoff_plan = dict(getattr(self, "_last_scale_up_handoff_plan", {}) or {})
            predicted_ready_delay_ms = float(handoff_plan.get("ready_delay_ms", 0.0) or 0.0)
            if predicted_ready_delay_ms > 0.0:
                return max(
                    max(0.0, float(getattr(self, "_scale_down_startup_break_even_s", 0.0) or 0.0)),
                    predicted_ready_delay_ms / 1000.0,
                )
        if not observed_ms:
            return max(0.0, float(getattr(self, "_scale_down_startup_break_even_s", 0.0) or 0.0))
        window = observed_ms[-8:]
        observed_s = (sum(window) / len(window)) / 1000.0
        configured_floor = max(
            0.0,
            float(getattr(self, "_scale_down_startup_break_even_s", 0.0) or 0.0),
        )
        return max(configured_floor, observed_s)

    def _effective_scale_down_min_idle_s(self) -> float:
        configured_ttl = max(
            0.0,
            float(getattr(self, "_scale_down_duration_s", 0.0) or 0.0),
        )
        restart_s = self._observed_scale_up_restart_seconds()
        factor_raw = getattr(self, "_scale_down_break_even_factor", 1.0)
        if factor_raw is None:
            factor_raw = 1.0
        factor = max(0.0, float(factor_raw))
        if restart_s <= 0.0 or factor <= 0.0:
            return configured_ttl
        return max(configured_ttl, restart_s * factor)

    def _effective_scale_down_cooldown_s(self) -> float:
        configured = max(
            0.0,
            float(getattr(self, "_scale_down_cooldown_s", 0.0) or 0.0),
        )
        if not bool(getattr(self, "_scale_down_cooldown_auto", False)):
            return configured
        return max(configured, self._effective_scale_down_min_idle_s())

    def _get_dynamic_warm_pool_size(self) -> Optional[int]:
        """When dynamic_warm_pool, return clip(round(active_loras_ewma*(1+gamma)), min, max); else None."""
        if not self._dynamic_warm_pool:
            return None
        n = round(self._active_loras_ewma * (1.0 + self._warm_pool_gamma))
        n = max(self._warm_pool_min, min(self._warm_pool_max, n))
        return n

    def _make_instance_coordinator(self, coord_enabled: bool) -> ResourceCoordinator:
        hw = {**self.hw, **self.coord_cfg}
        runtime_gpu_device_ids = _resolve_runtime_gpu_device_ids(
            self.model_cfg,
            device_id=getattr(self.engine, "device_id", None),
        )
        if runtime_gpu_device_ids:
            hw["gpu_device_ids"] = runtime_gpu_device_ids
        kwargs: Dict[str, Any] = {
            "config": hw,
            "coordination_enabled": coord_enabled,
        }
        if self._stack is not None:
            kwargs["residency_manager"] = self._stack.residency_manager
        return ResourceCoordinator(**kwargs)

    def _runtime_hints_slot_key(self, slot: Optional[Any]) -> Optional[str]:
        if slot is None:
            return None
        instance_id = getattr(slot, "instance_id", None)
        if instance_id is not None:
            return str(instance_id)
        return f"slot_{id(slot)}"

    def _refresh_slot_runtime_hints(
        self,
        slot: Optional[Any],
        *,
        force: bool = False,
    ) -> None:
        if slot is None:
            return
        interval_s = max(
            0.0,
            float(getattr(self, "_runtime_hints_refresh_interval_s", 0.0) or 0.0),
        )
        key = self._runtime_hints_slot_key(slot)
        last_refresh_by_slot = getattr(self, "_runtime_hints_last_refresh_by_slot", None)
        if last_refresh_by_slot is None:
            last_refresh_by_slot = {}
            self._runtime_hints_last_refresh_by_slot = last_refresh_by_slot
        if not force and interval_s > 0.0 and key is not None:
            last_refresh = last_refresh_by_slot.get(key)
            now_mono = time.monotonic()
            if last_refresh is not None and (now_mono - float(last_refresh)) < interval_s:
                return
            last_refresh_by_slot[key] = now_mono
        elif key is not None:
            last_refresh_by_slot[key] = time.monotonic()
        if self._stack is not None:
            sync = getattr(self._stack, "sync_local_tier_paths", None)
            if sync is not None:
                try:
                    sync()
                except Exception:
                    pass
            slot.nvme_cached_adapters = set(getattr(self._stack, "_nvme_paths", {}).keys())
            slot.host_cached_adapters = set(getattr(self._stack, "_host_paths", {}).keys())
        coord = getattr(slot, "coordinator", None)
        try:
            metrics = coord.get_summary_metrics() if coord is not None else {}
        except Exception:
            metrics = {}
        metrics = dict(metrics or {})
        snapshot_fn = getattr(self, "_gpu_runtime_snapshot", None)
        if callable(snapshot_fn) and getattr(slot, "device_id", None) is not None:
            try:
                runtime_snapshot = snapshot_fn(int(slot.device_id))
            except Exception:
                runtime_snapshot = None
            if runtime_snapshot is not None:
                _used_gb, _total_gb, physical_util_pct = runtime_snapshot
                physical_util_pct = float(physical_util_pct or 0.0)
                logical_util_pct = float(metrics.get("current_gpu_utilization_pct", 0.0) or 0.0)
                # Route with the most conservative pressure signal we have: the
                # coordinator's logical estimate should never hide a runtime that
                # is already physically full on its assigned GPU.
                metrics["current_gpu_utilization_pct"] = max(logical_util_pct, physical_util_pct)
                metrics["physical_gpu_utilization_pct"] = physical_util_pct
        resident_keys = None
        get_resident = getattr(coord, "_get_resident_loras", None)
        if callable(get_resident):
            try:
                resident_map = get_resident() or {}
                resident_keys = (
                    set(resident_map.keys())
                    if isinstance(resident_map, dict)
                    else set(resident_map)
                )
            except Exception:
                resident_keys = None
        if resident_keys is not None:
            slot.gpu_resident_adapters = resident_keys
        elif getattr(self, "_instance_mode", None) == "shared":
            slot.gpu_resident_adapters = set(getattr(self, "_gpu_warmed", set()))
        handoff_plan = self._scaleup_runtime_handoff_plan(
            getattr(slot, "instance_id", None)
        )
        planned_adapters = [
            str(adapter_id)
            for adapter_id in list(handoff_plan.get("planned_adapters", []) or [])
            if adapter_id
        ]
        slot.scaleup_handoff_planned_adapters = list(planned_adapters)
        slot.scaleup_handoff_planned_adapter_ranks = {
            adapter_id: idx for idx, adapter_id in enumerate(planned_adapters)
        }
        request_budget = max(
            0, int(handoff_plan.get("first_service_request_count", 0) or 0)
        )
        slot.scaleup_handoff_request_budget = request_budget
        slot.scaleup_handoff_assigned_requests = min(
            request_budget,
            max(
                0,
                int(getattr(slot, "scaleup_handoff_assigned_requests", 0) or 0),
            ),
        )
        if hasattr(slot, "update_runtime_hints"):
            slot.update_runtime_hints(metrics)

    def _refresh_all_slot_runtime_hints(self, *, force: bool = False) -> None:
        if self.instance_pool is None:
            return
        self._sync_stack_gpu_accounting()
        for slot in self.instance_pool.get_slots():
            self._refresh_slot_runtime_hints(slot, force=force)

    def _active_stack_gpu_device_ids(self) -> List[int]:
        device_ids = _resolve_runtime_gpu_device_ids(
            getattr(self.engine, "model_cfg", {}) or {},
            device_id=getattr(self.engine, "device_id", None),
        )
        if device_ids:
            return device_ids
        available = self._available_device_ids()
        if available:
            return [available[0]]
        return []

    def _sync_stack_gpu_accounting(self) -> None:
        if self._stack is None:
            return
        residency_manager = getattr(self._stack, "residency_manager", None)
        if residency_manager is None:
            return
        setter = getattr(residency_manager, "set_tracked_gpu_device_ids", None)
        if callable(setter):
            setter(self._active_stack_gpu_device_ids())
        sync = getattr(residency_manager, "_sync_gpu_capacity_once", None)
        if callable(sync):
            try:
                sync()
            except Exception:
                pass

    def _runtime_forward_task_key(self, slot: Optional[Any]) -> Optional[tuple]:
        if slot is None or not hasattr(slot, "runtime_group_key"):
            return None
        try:
            return tuple(slot.runtime_group_key())
        except Exception:
            return None

    def _runtime_forward_capacity_limit(self) -> int:
        model_cfg = getattr(self, "model_cfg", None)
        if not isinstance(model_cfg, dict) or not model_cfg:
            model_cfg = getattr(getattr(self, "engine", None), "model_cfg", {}) or {}
        return _effective_runtime_concurrency_cap(model_cfg)

    def _runtime_max_active_loras(self) -> int:
        model_cfg = getattr(self, "model_cfg", None)
        if not isinstance(model_cfg, dict) or not model_cfg:
            model_cfg = getattr(getattr(self, "engine", None), "model_cfg", {}) or {}
        raw = model_cfg.get("max_loras", 0) if isinstance(model_cfg, dict) else 0
        try:
            return max(0, int(raw or 0))
        except Exception:
            return 0

    def _sample_ieee_gpu_utilization(self, slot, *, device_uuid):
        """Sample actual device busy rate; old memory-percent hints are separate."""
        if (not isinstance(device_uuid, str) or not device_uuid.startswith('GPU-')
                or 'GPU-' + str(uuid.UUID(device_uuid[4:])) != device_uuid):
            raise ValueError('IEEE utilization requires the native worker physical GPU UUID')
        now = time.monotonic()
        previous = slot.ieee_utilization_sample
        interval = self._runtime_hints_refresh_interval_s
        if previous is not None and previous['device_uuid'] != device_uuid:
            raise ValueError('physical GPU changed during replica ownership')
        if previous is not None and now - previous['sampled_monotonic_s'] < interval:
            return dict(previous)
        import pynvml
        if not self._ieee_nvml_initialized:
            pynvml.nvmlInit()
            self._ieee_nvml_initialized = True
        handle = pynvml.nvmlDeviceGetHandleByUUID(device_uuid)
        rate = float(pynvml.nvmlDeviceGetUtilizationRates(handle).gpu)
        if not math.isfinite(rate) or not 0 <= rate <= 100:
            raise ValueError('invalid native GPU utilization sample')
        sample = dict(source='nvmlDeviceGetUtilizationRates.gpu', device_id=slot.device_id,
                      device_uuid=device_uuid,
                      gpu_utilization_pct=rate, sampled_monotonic_s=now)
        slot.ieee_utilization_sample = sample
        return dict(sample)

    async def _ieee_request_snapshot(self, trace, request_plan):
        """Commit received source and live controller state before target selection.

        RPCs collect native observations without pinning candidates. After the
        last await, file-source, counts, profile estimates and membership form one
        received controller view. Selection/reservation follows without yielding;
        selected-copy revalidation remains a separate required transaction.
        """
        from faaslora.clock import local_monotonic_clock_id
        from faaslora.experiment.instance_pool import (
            NativeSourceSnapshot, ReplicaRoutingSnapshot, confirmed_source_class)
        if self._stack is None:
            raise ValueError('IEEE routing requires the actual managed file source owner')
        owner = self._stack.residency_manager.local_source_references
        slots = tuple(self.instance_pool.get_slots())
        native_views = await asyncio.gather(*(slot.engine.ieee_gpu_reference(
            operation='source_snapshot') for slot in slots))
        # Scale-up/removal during RPC collection is not a complete current view.
        if tuple(self.instance_pool.get_slots()) != slots:
            return None
        device_uuids = [view.get('device_uuid') for view in native_views]
        if (any(not isinstance(value, str) for value in device_uuids)
                or len(set(device_uuids)) != len(device_uuids)):
            raise ValueError('IEEE TP=1 replicas require distinct native physical GPU identities')
        clock_id = local_monotonic_clock_id()
        native = [NativeSourceSnapshot.from_native(view, expected_clock_id=clock_id,
            received_monotonic_s=time.monotonic()) for view in native_views]
        adapter_id = trace.adapter_id
        files = owner.source_snapshot(adapter_id) if adapter_id else None
        if files is not None:
            captured = files.get('captured_monotonic_s')
            if (type(captured) not in (int, float) or not math.isfinite(captured)
                    or captured <= 0 or captured > time.monotonic()):
                raise ValueError('file routing view lacks a valid observation time')
        identity = self._ieee_artifact_identities[adapter_id] if adapter_id else None
        self._ieee_routing_epoch += 1
        rows, evidence = [], {}
        capacity, active_limit = self._runtime_forward_capacity_limit(), self._runtime_max_active_loras()
        for slot, state, raw_view in zip(slots, native, native_views):
            if not slot.commit_native_sources(state):
                # Another request can receive a newer native epoch while this
                # collection is awaiting a slower replica. Never rank on the
                # rejected old view or splice it into the newer owner state.
                return None
            admitted = slot.active_requests
            active = frozenset(aid for aid, count in slot.active_adapter_counts.items() if count > 0)
            remaining = max(0, capacity - admitted)
            if slot.runtime_forwarding_active:
                # Historical forwarding does not expose native load ownership.
                # Do not fabricate zero pending work and call it IEEE-qualified.
                raise ValueError('untracked legacy forwarding cannot enter IEEE routing state')
            utilization = self._sample_ieee_gpu_utilization(slot, device_uuid=raw_view.get('device_uuid'))
            key = service = source = None
            feasible = remaining > 0 and (not adapter_id or adapter_id in active or len(active) < active_limit)
            if feasible:
                features = dict(prompt_tokens=request_plan.input_tokens,
                                declared_output_tokens=request_plan.max_tokens,
                                admitted_after_accept=admitted + 1)
                if adapter_id:
                    key, source = confirmed_source_class(native=state, files=files, identity=identity,
                        adapter_int_id=InferenceEngine._lora_int_id(adapter_id),
                        bins=slot.service_class_bins, **features)
                else:
                    key = slot.service_class_bins.classify(tier='backbone', adapter_rank=0,
                        footprint_bytes=0, representation='backbone', **features)
                    source = dict(tier='backbone', native=True, owner_id=state.owner_id, epoch=state.epoch)
                service = slot.service_cost_model.estimate(key)
            rows.append(ReplicaRoutingSnapshot(epoch=self._ieee_routing_epoch,
                request_id=trace.request_id, replica_id=slot.instance_id, adapter_id=adapter_id,
                runtime_ready=True, available_slots=remaining, admitted_requests=admitted,
                active_adapters=active, max_active_loras=active_limit,
                pending_loads=len(slot.ieee_pending_load_ids),
                gpu_utilization_pct=utilization['gpu_utilization_pct'],
                last_dispatch_at=slot.ieee_last_dispatch_at, service_class=key, service=service))
            evidence[slot.instance_id] = dict(source=source,
                native_owner_id=state.owner_id, native_epoch=state.epoch,
                native_captured_monotonic_s=state.captured_monotonic_s,
                file_owner_id=files['owner_id'] if files else None,
                file_epoch=files['epoch'] if files else None,
                file_captured_monotonic_s=files['captured_monotonic_s'] if files else None,
                utilization=utilization)
        return tuple(rows), evidence

    def _slot_can_accept_runtime_request(
        self,
        slot: Optional[Any],
        adapter_id: Optional[str],
    ) -> bool:
        if slot is None:
            return True
        if getattr(slot, 'status', 'running') != 'running':
            return False
        if max(0, int(getattr(slot, "runtime_forwarding_active", 0) or 0)) > 0:
            return False
        active_requests = max(0, int(getattr(slot, "active_requests", 0) or 0))
        if active_requests >= self._runtime_forward_capacity_limit():
            return False
        can_accept = getattr(slot, "can_accept_active_adapter", None)
        if callable(can_accept) and not can_accept(
            adapter_id,
            self._runtime_max_active_loras(),
        ):
            return False
        return True

    def _try_reserve_runtime_request_slot(
        self,
        slot: Optional[Any],
        adapter_id: Optional[str],
    ) -> Tuple[bool, bool]:
        """
        Atomically reserve one execution lane on a slot for the current request.

        Router selection and slot admission both run inside the same asyncio event
        loop, but multiple request coroutines can still interleave between "slot
        looked available" and the later bookkeeping that increments
        ``slot.active_requests``. That race lets several requests enter the same
        runtime on the stale pre-increment view, oversubscribing the runtime and
        shifting the resulting queue into the worker/RPC path. Reserve the lane
        immediately after selection, before any await, so the next coroutine sees
        the updated occupancy.
        """
        if slot is None:
            return True, False
        if getattr(slot, 'status', 'running') != 'running':
            return False, False
        if max(0, int(getattr(slot, "runtime_forwarding_active", 0) or 0)) > 0:
            return False, False
        active_requests = max(0, int(getattr(slot, "active_requests", 0) or 0))
        if active_requests >= self._runtime_forward_capacity_limit():
            return False, False
        can_accept = getattr(slot, "can_accept_active_adapter", None)
        if callable(can_accept) and not can_accept(
            adapter_id,
            self._runtime_max_active_loras(),
        ):
            return False, False
        active_adapter_reserved = False
        if adapter_id and hasattr(slot, "begin_active_adapter"):
            slot.begin_active_adapter(adapter_id)
            active_adapter_reserved = True
        slot.active_requests = active_requests + 1
        slot.last_selected_at = time.time()
        return True, active_adapter_reserved

    def _runtime_total_capacity_after_removal(self, remaining_instances: int) -> int:
        return max(0, int(remaining_instances or 0)) * max(
            1,
            int(self._runtime_forward_capacity_limit() or 1),
        )

    def _slot_idle_seconds(self, slot: Any, *, now_wall: Optional[float] = None) -> float:
        if now_wall is None:
            now_wall = time.time()
        last_idle = float(
            getattr(
                slot,
                "last_idle_at",
                getattr(slot, "last_selected_at", getattr(slot, "created_at", now_wall)),
            )
            or now_wall
        )
        return max(0.0, float(now_wall) - last_idle)

    def _slot_ready_age_seconds(
        self,
        slot: Any,
        *,
        now_wall: Optional[float] = None,
    ) -> float:
        if now_wall is None:
            now_wall = time.time()
        ready_at = float(getattr(slot, "created_at", now_wall) or now_wall)
        return max(0.0, float(now_wall) - ready_at)

    def _live_scale_down_cooldown_open(self, now_monotonic: float) -> bool:
        cooldown_s = max(0.0, float(self._effective_scale_down_cooldown_s()))
        if cooldown_s <= 0.0:
            return True
        last_scale_down_at = max(
            0.0,
            float(getattr(self, "_last_live_scale_down_completed_at", 0.0) or 0.0),
        )
        if last_scale_down_at > 0.0 and (float(now_monotonic) - last_scale_down_at) < cooldown_s:
            return False
        last_scale_up_at = max(
            0.0,
            float(getattr(self, "_last_live_scale_up_completed_at", 0.0) or 0.0),
        )
        if last_scale_up_at > 0.0 and (float(now_monotonic) - last_scale_up_at) < cooldown_s:
            return False
        return True

    def _runtime_forward_has_capacity(self, slot: Optional[Any], coordinator: Optional[Any]) -> bool:
        if slot is None or coordinator is None:
            return False
        capacity_limit = self._runtime_forward_capacity_limit()
        if capacity_limit <= 0:
            return False
        if max(0, int(getattr(slot, "runtime_forwarding_active", 0) or 0)) > 0:
            return False
        # GPU forwarding is an opportunistic background action. If online requests
        # are already waiting in the shared visible queue, inference wins; otherwise
        # the forwarding RPC can hide queueing inside the worker and inflate TPOT/E2E.
        try:
            if self._current_live_waiting_trace_queue():
                return False
        except Exception:
            pass
        active_requests = max(0, int(getattr(slot, "active_requests", 0) or 0))
        # Background GPU forwarding should never compete with an in-flight request's
        # decode path on the same runtime. Only use truly idle windows for proactive
        # warming; otherwise we risk inflating TPOT/E2E while trying to improve
        # future TTFT.
        if active_requests > 0:
            return False
        try:
            stack = getattr(self, "_stack", None)
            pressure_fn = getattr(stack, "_tier_pressure", None)
            cutoff = float(getattr(stack, "_gpu_forward_pressure_cutoff", 0.90) or 0.90)
            if callable(pressure_fn) and pressure_fn(StorageTier.GPU, coordinator=coordinator) >= cutoff:
                return False
        except Exception:
            return False

        queue_depth = max(0, int(getattr(slot, "load_queue_depth", 0) or 0))
        queue_ratio = min(1.0, queue_depth / float(capacity_limit))

        load_ratio = 0.0
        loads_ratio_fn = getattr(coordinator, "_loads_in_flight_ratio", None)
        if callable(loads_ratio_fn):
            try:
                load_ratio = min(1.0, max(0.0, float(loads_ratio_fn())))
            except Exception:
                return False

        service_slack = 1.0
        loading_slack = max(0.0, 1.0 - max(queue_ratio, load_ratio))
        return (service_slack * loading_slack) > 0.0

    async def _cancel_runtime_gpu_forward_tasks(self, key: Optional[tuple] = None) -> None:
        if not self._runtime_gpu_forward_tasks:
            return
        if key is not None:
            items = [(key, self._runtime_gpu_forward_tasks.get(key))]
        else:
            items = list(self._runtime_gpu_forward_tasks.items())
        for task_key, task in items:
            if task is None:
                continue
            if not task.done():
                task.cancel()
                try:
                    await task
                except asyncio.CancelledError:
                    pass
                except Exception:
                    pass
            self._runtime_gpu_forward_tasks.pop(task_key, None)

    async def _run_runtime_gpu_forward(self, slot: Any, candidate: Dict[str, Any]) -> None:
        key = self._runtime_forward_task_key(slot)
        forwarding_marked = False
        try:
            if slot is None or candidate is None or self._stack is None:
                return
            engine = getattr(slot, "engine", None)
            coordinator = getattr(slot, "coordinator", None)
            if engine is None or not hasattr(engine, "load_lora_to_gpu_and_measure"):
                return
            if not self._runtime_forward_has_capacity(slot, coordinator):
                return
            adapter_id = candidate["adapter_id"]
            self._runtime_gpu_forward_attempt_count = int(
                getattr(self, "_runtime_gpu_forward_attempt_count", 0) or 0
            ) + 1
            local_path = candidate["path"]
            source_tier = str(candidate.get("source_tier", "nvme") or "nvme")
            size_mb = float(candidate.get("size_mb", 0.0) or 0.0)
            replace = candidate.get("replace") if isinstance(candidate.get("replace"), dict) else None
            admission_utility = float(candidate.get("admission_utility", 0.0) or 0.0)
            if (
                coordinator is not None
                and bool(
                    getattr(
                        coordinator,
                        "effective_capacity_admission_enabled",
                        True,
                    )
                )
                and getattr(coordinator, "evaluate_gpu_admission", None)
            ):
                decision = coordinator.evaluate_gpu_admission(
                    adapter_id,
                    size_mb,
                    tier=source_tier,
                    utility_override=admission_utility if admission_utility > 0.0 else None,
                )
                if not decision.get("admit", False) and replace is None:
                    return
            semaphore = getattr(coordinator, "_loading_semaphore", None) if coordinator is not None else None

            async def _restore_replaced(resident_state: Optional[Dict[str, Any]]) -> None:
                if not resident_state:
                    return
                restore_id = str(resident_state.get("adapter_id", "") or "")
                restore_path = str(resident_state.get("path", "") or "")
                restore_size_mb = float(resident_state.get("size_mb", 0.0) or 0.0)
                if not restore_id or not restore_path:
                    return
                load_ms, ok = await engine.load_lora_to_gpu_and_measure(restore_path, restore_id)
                if not ok:
                    return
                self._stack.registry.update_artifact(
                    restore_id,
                    {"last_load_time_ms": load_ms, "predicted_load_time_ms": load_ms},
                )
                if coordinator is not None and getattr(coordinator, "_residency_manager", None) is None:
                    await coordinator._mark_resident(restore_id, restore_size_mb)
                else:
                    await self._stack.residency_manager.admit_artifact(
                        restore_id, StorageTier.GPU, force=True
                    )
                self._mark_slot_adapter_tier(slot, restore_id, "gpu")

            async def _demote_replaced() -> Optional[Dict[str, Any]]:
                if replace is None:
                    return None
                replace_id = str(replace.get("adapter_id", "") or "")
                replace_target = str(replace.get("target_tier", "nvme") or "nvme")
                replace_size_mb = float(replace.get("size_mb", 0.0) or 0.0)
                replace_path = (
                    getattr(self._stack, "_host_paths", {}).get(replace_id)
                    or getattr(self._stack, "_nvme_paths", {}).get(replace_id)
                )
                unload_fn = getattr(engine, "unload_lora_adapter", None)
                if not replace_id or not replace_path or not callable(unload_fn):
                    return None
                resident_state = {
                    "adapter_id": replace_id,
                    "path": replace_path,
                    "size_mb": replace_size_mb,
                    "target_tier": replace_target,
                }
                unloaded = unload_fn(replace_id)
                if asyncio.iscoroutine(unloaded):
                    unloaded = await unloaded
                if not unloaded:
                    return None
                if coordinator is not None and getattr(coordinator, "_residency_manager", None) is None:
                    resident_map = getattr(coordinator, "_resident_loras", None)
                    if isinstance(resident_map, dict):
                        resident_map.pop(replace_id, None)
                else:
                    target_enum = StorageTier.HOST if replace_target == "host" else StorageTier.NVME
                    moved = await self._stack.residency_manager.evict_artifact(replace_id, target_enum)
                    if not moved:
                        await _restore_replaced(resident_state)
                        return None
                self._mark_slot_adapter_tier(slot, replace_id, replace_target)
                return resident_state

            async def _load_once() -> bool:
                replaced_state = None
                if replace is not None:
                    replaced_state = await _demote_replaced()
                    if replaced_state is None:
                        return False
                load_ms, ok = await engine.load_lora_to_gpu_and_measure(local_path, adapter_id)
                if not ok:
                    await _restore_replaced(replaced_state)
                    return False
                self._stack.registry.update_artifact(
                    adapter_id,
                    {"last_load_time_ms": load_ms, "predicted_load_time_ms": load_ms},
                )
                if coordinator is not None and getattr(coordinator, "_residency_manager", None) is None:
                    await coordinator._mark_resident(adapter_id, size_mb)
                else:
                    await self._stack.residency_manager.admit_artifact(
                        adapter_id, StorageTier.GPU, force=True
                    )
                self._mark_slot_adapter_tier(slot, adapter_id, "gpu")
                self._runtime_gpu_forward_success_count = int(
                    getattr(self, "_runtime_gpu_forward_success_count", 0) or 0
                ) + 1
                return True

            if semaphore is not None:
                try:
                    if int(getattr(semaphore, "_value", 0) or 0) <= 0:
                        return
                except Exception:
                    return
                async with semaphore:
                    if not self._runtime_forward_has_capacity(slot, coordinator):
                        return
                    if hasattr(slot, "begin_runtime_forwarding"):
                        slot.begin_runtime_forwarding()
                        forwarding_marked = True
                    await _load_once()
            else:
                if not self._runtime_forward_has_capacity(slot, coordinator):
                    return
                if hasattr(slot, "begin_runtime_forwarding"):
                    slot.begin_runtime_forwarding()
                    forwarding_marked = True
                await _load_once()
        except Exception:
            pass
        finally:
            if forwarding_marked and hasattr(slot, "end_runtime_forwarding"):
                try:
                    slot.end_runtime_forwarding()
                except Exception:
                    pass
            if slot is not None:
                self._refresh_slot_runtime_hints(slot)
            if key is not None:
                self._runtime_gpu_forward_tasks.pop(key, None)

    def _schedule_runtime_gpu_forward(self, slot: Optional[Any]) -> bool:
        if getattr(self, '_routing_policy', None) == 'ieee_confirmed':
            # Request-release callbacks cannot introduce a second preparation
            # objective alongside IEEE residency/handoff and owned admission.
            return False
        if not self._dynamic_forwarding_enabled or self._stack is None or slot is None:
            return False
        engine = getattr(slot, "engine", None)
        coordinator = getattr(slot, "coordinator", None)
        if engine is None or coordinator is None or not hasattr(engine, "load_lora_to_gpu_and_measure"):
            return False
        if not self._runtime_forward_has_capacity(slot, coordinator):
            return False
        key = self._runtime_forward_task_key(slot)
        if key is None:
            return False
        task = self._runtime_gpu_forward_tasks.get(key)
        if task is not None and not task.done():
            return False
        current_gpu = set(getattr(slot, "gpu_resident_adapters", set()))
        preferred_gpu = self._runtime_forward_preferred_gpu_adapters(slot)
        if preferred_gpu is not None:
            preferred_gpu = [aid for aid in preferred_gpu if aid not in current_gpu]
            if not preferred_gpu:
                return False
        candidate = self._stack.select_gpu_forward_candidate(
            gpu_resident_adapters=current_gpu,
            coordinator=coordinator,
            preferred_gpu_adapters=preferred_gpu,
        )
        if not candidate:
            return False
        self._runtime_gpu_forward_tasks[key] = asyncio.create_task(
            self._run_runtime_gpu_forward(slot, candidate)
        )
        return True

    def _schedule_all_runtime_gpu_forward(self) -> int:
        """
        Opportunistically advance GPU forwarding on every live runtime.

        Dedicated runtimes can otherwise fall into a self-reinforcing loop:
        the slot that just served a request keeps forwarding more hot adapters,
        while an idle sibling never gets a chance to catch up and remains
        permanently less GPU-ready. Prioritize idle / least-recently-selected
        slots first so forwarding can rebalance hot sets before routing drifts
        too far toward one runtime.
        """
        instance_pool = getattr(self, "instance_pool", None)
        if instance_pool is None:
            return 0

        def _slot_priority(slot: Any) -> tuple:
            return (
                max(0, int(getattr(slot, "active_requests", 0) or 0)),
                float(getattr(slot, "last_selected_at", 0.0) or 0.0),
                float(getattr(slot, "created_at", 0.0) or 0.0),
                str(getattr(slot, "instance_id", "") or ""),
            )

        scheduled = 0
        get_slots = getattr(instance_pool, "get_slots", None)
        if not callable(get_slots):
            return 0

        for slot in sorted(get_slots(), key=_slot_priority):
            if self._schedule_runtime_gpu_forward(slot):
                scheduled += 1
        return scheduled

    def _coordinator_metric_views(self) -> List[Dict[str, Any]]:
        metrics = list(self._retired_coord_metrics)
        if self.instance_pool and self.instance_pool.get_slots():
            seen_coords = set()
            for slot in self.instance_pool.get_slots():
                coord = getattr(slot, "coordinator", None)
                if coord is None or id(coord) in seen_coords:
                    continue
                seen_coords.add(id(coord))
                metrics.append(coord.get_summary_metrics())
        elif self.coordinator is not None:
            metrics.append(self.coordinator.get_summary_metrics())
        return metrics

    def _current_coord_metrics(self) -> Dict[str, Any]:
        views = self._coordinator_metric_views()
        result = (_merge_coordinator_metrics(views) if views else
                  self.coordinator.get_summary_metrics() if self.coordinator else {})
        binding = getattr(self, '_ieee_online_observation_binding', None)
        if binding is not None:
            result['ieee_online_observation_binding'] = copy.deepcopy(binding)
        profiles = getattr(self, '_service_profiles', None)
        if profiles is not None:
            result = {**result, 'ieee_service_profile': profiles.identity()}
        preparation = getattr(self, '_preparation_profiles', None)
        if preparation is not None:
            result = {**result, 'ieee_preparation_profile': preparation.identity()}
        preloading = getattr(getattr(self, '_stack', None), 'preloading_manager', None)
        if preloading is not None and preloading.ieee_movements.bound:
            result = {**result, 'ieee_movements': preloading.ieee_movements.snapshot()}
        if hasattr(self, '_ieee_gpu_preparation_plans'):
            result = {**result, 'ieee_gpu_preparation_plans': copy.deepcopy(self._ieee_gpu_preparation_plans)}
        if hasattr(self, '_ieee_file_preparation_plans'):
            result = {**result, 'ieee_file_preparation_plans': copy.deepcopy(self._ieee_file_preparation_plans),
                'ieee_file_pending_targets': self._stack.residency_manager.local_source_references.file_preparation_snapshot()}
        if hasattr(self, '_ieee_native_host_preparations'):
            result = {**result, 'ieee_native_host_preparations': copy.deepcopy(self._ieee_native_host_preparations)}
        if hasattr(self, '_ieee_activations'):
            result = {**result, 'ieee_activations': copy.deepcopy(self._ieee_activations)}
        if hasattr(self, '_ieee_initial_deployment'):
            result['ieee_initial_deployment'] = copy.deepcopy(self._ieee_initial_deployment)
        if hasattr(self, '_ieee_control_events'):
            result['ieee_control_events'] = copy.deepcopy(self._ieee_control_events)
        if hasattr(self, '_ieee_host_capacity_events'):
            result['ieee_host_capacity_events'] = copy.deepcopy(self._ieee_host_capacity_events)
        if hasattr(self, '_ieee_residency_epochs'):
            result['ieee_residency_epochs'] = copy.deepcopy(self._ieee_residency_epochs)
        if getattr(self, '_ieee_host_budget_members', None) is not None:
            result['ieee_managed_host_budget'] = self._stack.residency_manager.local_source_references.host_budget_snapshot()
            result['ieee_native_host_budget_owners'] = [copy.deepcopy({
                k: v for k, v in member.items() if k not in ('engines', 'pidfd')})
                for member in {id(m): m for m in self._ieee_host_budget_members.values()}.values()]
        if getattr(self, '_shared_file_pressure', None) is not None:
            result = {**result, 'ieee_shared_file_pressure': self._shared_file_pressure.snapshot()}
        return result

    @staticmethod
    def _render_progress_bar(completed: int, total: int, width: int = 28) -> str:
        total = max(1, int(total))
        completed = max(0, min(int(completed), total))
        filled = int(round((completed / total) * width))
        return "[" + "#" * filled + "-" * (width - filled) + "]"

    @staticmethod
    def _format_eta(seconds: float) -> str:
        seconds = max(0, int(seconds))
        minutes, sec = divmod(seconds, 60)
        hours, minutes = divmod(minutes, 60)
        if hours > 0:
            return f"{hours:02d}:{minutes:02d}:{sec:02d}"
        return f"{minutes:02d}:{sec:02d}"

    def _instance_panel_lines(self) -> List[str]:
        if not self._show_instance_panel or self.instance_pool is None:
            return []
        if self._stack is not None and getattr(self._stack, "sync_local_tier_paths", None):
            self._stack.sync_local_tier_paths()
        lines: List[str] = []
        for group in self.instance_pool.get_runtime_groups():
            if not group:
                continue
            primary = group[0]
            label = ",".join(slot.instance_id for slot in group)
            active = sum(max(0, int(getattr(slot, "active_requests", 0))) for slot in group)
            forwarding = sum(max(0, int(getattr(slot, "runtime_forwarding_active", 0) or 0)) for slot in group)
            queue_depth = max(int(getattr(slot, "load_queue_depth", 0)) for slot in group)
            gpu_util = max(float(getattr(slot, "gpu_utilization_pct", 0.0)) for slot in group)
            resident_mb = max(float(getattr(slot, "resident_lora_mb", 0.0)) for slot in group)
            gpu_cached = len(set().union(*(slot.gpu_resident_adapters for slot in group)))
            host_cached = len(set().union(*(slot.host_cached_adapters for slot in group)))
            nvme_cached = len(set().union(*(slot.nvme_cached_adapters for slot in group)))
            lines.append(
                "      "
                f"{label} gpu={getattr(primary, 'device_id', '?')} "
                f"active={active} fwd={forwarding} queue={queue_depth} util={gpu_util:.0f}% "
                f"resident={resident_mb:.0f}MB cache[g/h/n]={gpu_cached}/{host_cached}/{nvme_cached}"
            )
        return lines

    def _gpu_summary_line(self) -> Optional[str]:
        if self._stack is None or getattr(self._stack, "gpu_monitor", None) is None:
            return None
        pool = self.instance_pool.get_slots() if self.instance_pool is not None else []
        device_ids = []
        for slot in pool:
            if getattr(slot, "device_id", None) is not None:
                device_ids.append(int(slot.device_id))
        if not device_ids:
            device_ids = [int(getattr(self.engine, "device_id", 0))]
        seen = []
        for did in device_ids:
            if did not in seen:
                seen.append(did)
        chunks: List[str] = []
        for did in seen:
            snap = self._gpu_runtime_snapshot(did)
            if not snap:
                continue
            used_gb, total_gb, util_pct = snap
            chunks.append(f"gpu{did}={used_gb:.1f}/{total_gb:.1f}GB({util_pct:.0f}%)")
        if not chunks:
            return None
        return "      gpu_mem " + "  ".join(chunks)

    def _adapter_cache_counts(self) -> Dict[str, int]:
        if self.instance_pool is None:
            return {
                "gpu": len(self._gpu_warmed),
                "gpu_replica_sum": len(self._gpu_warmed),
                "host": 0,
                "nvme": len(self._nvme_cache),
            }
        if self._stack is not None and getattr(self._stack, "sync_local_tier_paths", None):
            self._stack.sync_local_tier_paths()
        gpu = set()
        host = set()
        nvme = set()
        gpu_replica_sum = 0
        dedicated = 0
        shared = 0
        runtime_groups = self.instance_pool.get_runtime_groups()
        for group in runtime_groups:
            runtime_gpu = set()
            for slot in group:
                runtime_gpu.update(getattr(slot, "gpu_resident_adapters", set()))
            gpu.update(runtime_gpu)
            gpu_replica_sum += len(runtime_gpu)
        for slot in self.instance_pool.get_slots():
            host.update(getattr(slot, "host_cached_adapters", set()))
            nvme.update(getattr(slot, "nvme_cached_adapters", set()))
            if getattr(slot, "owns_engine", False):
                dedicated += 1
            else:
                shared += 1
        return {
            "gpu": len(gpu),
            "gpu_replica_sum": gpu_replica_sum,
            "host": len(host),
            "nvme": len(nvme),
            "dedicated_instances": dedicated,
            "shared_slots": shared,
        }

    def _scale_up_warmup_preferred_gpu_adapters(self) -> set:
        """
        Preferred scale-up warmup set backed by the current live GPU hotset.

        Keep TODO #3 aligned to the last validated semantics: when a new runtime is
        added, the strongest observable signal is the sibling GPU hotset already
        serving live traffic. Recent local HOST/NVMe working-set expansion regressed
        headline TTFT metrics by shifting too much LoRA traffic onto the slower
        primary runtime, so scale-up warmup falls back to the narrower live-hotset
        definition until a stronger causal model is validated.
        """
        now = time.time()
        preferred: set = set()
        if self.instance_pool is None:
            gpu_warmed = set(getattr(self, "_gpu_warmed", set()))
            recent_gpu_warmed = {
                adapter_id
                for adapter_id in gpu_warmed
                if self._adapter_is_recently_active(adapter_id, now=now)
            }
            return preferred or recent_gpu_warmed or gpu_warmed

        for group in self.instance_pool.get_runtime_groups():
            for slot in group:
                for adapter_id in getattr(slot, "gpu_resident_adapters", set()):
                    if self._adapter_is_recently_active(adapter_id, now=now):
                        preferred.add(adapter_id)
        return preferred

    def _observe_live_arrived_lora(self, adapter_id: Optional[str]) -> None:
        if not adapter_id:
            return
        counts = getattr(self, "_live_arrived_lora_counts", None)
        if counts is None:
            counts = defaultdict(int)
            self._live_arrived_lora_counts = counts
        first_seen = getattr(self, "_live_arrived_lora_first_seen_seq", None)
        if first_seen is None:
            first_seen = {}
            self._live_arrived_lora_first_seen_seq = first_seen
        counts[adapter_id] += 1
        if counts[adapter_id] == 1:
            self._live_arrived_lora_seq = int(getattr(self, "_live_arrived_lora_seq", 0) or 0) + 1
            first_seen[adapter_id] = self._live_arrived_lora_seq

    def _release_live_arrived_lora(self, adapter_id: Optional[str]) -> None:
        if not adapter_id:
            return
        counts = getattr(self, "_live_arrived_lora_counts", None)
        if not counts:
            return
        remaining = max(0, int(counts.get(adapter_id, 0) or 0) - 1)
        if remaining > 0:
            counts[adapter_id] = remaining
            return
        counts.pop(adapter_id, None)
        first_seen = getattr(self, "_live_arrived_lora_first_seen_seq", None)
        if isinstance(first_seen, dict):
            first_seen.pop(adapter_id, None)

    def _observe_live_started_lora(self, adapter_id: Optional[str]) -> None:
        if not adapter_id:
            return
        counts = getattr(self, "_live_started_lora_counts", None)
        if counts is None:
            counts = defaultdict(int)
            self._live_started_lora_counts = counts
        counts[adapter_id] += 1

    def _release_live_started_lora(self, adapter_id: Optional[str]) -> None:
        if not adapter_id:
            return
        counts = getattr(self, "_live_started_lora_counts", None)
        if not counts:
            return
        remaining = max(0, int(counts.get(adapter_id, 0) or 0) - 1)
        if remaining > 0:
            counts[adapter_id] = remaining
            return
        counts.pop(adapter_id, None)

    def _arrived_request_count_at_elapsed_s(self, elapsed_s: float) -> int:
        if getattr(self, '_external_replay', None) is not None:
            return bisect_right(self._external_replay.observed_times,
                                self._external_replay.context['replay_t0_s']+max(0., elapsed_s))
        arrivals = list(getattr(self, "_scheduled_arrivals", []) or [])
        if not arrivals:
            return 0
        return bisect_right(arrivals, max(0.0, float(elapsed_s or 0.0)))

    def _scale_up_bootstrap_latency_ms(self) -> float:
        observed_runtime_startups = [
            max(0.0, float(latency_ms or 0.0))
            for latency_ms in list(
                getattr(self, "_observed_scale_up_runtime_startup_latencies_ms", [])
                or []
            )
            if float(latency_ms or 0.0) > 0.0
        ]
        if observed_runtime_startups:
            return sum(observed_runtime_startups) / float(len(observed_runtime_startups))

        # In dedicated/auto mode, the primary runtime startup path is not
        # comparable to later dedicated subprocess scale-up runtimes. When no
        # dedicated runtime startup has been observed yet, avoid reusing the
        # primary engine's one-off startup latency as a false bootstrap signal.
        if (
            getattr(self, "_instance_mode", None) in ("dedicated", "auto")
            and getattr(self, "engine_factory", None) is not None
        ):
            return 0.0

        latencies: List[float] = []
        seen: set = set()
        if self.instance_pool is not None:
            for slot in self.instance_pool.get_slots():
                engine = getattr(slot, "engine", None)
                if engine is None or id(engine) in seen:
                    continue
                seen.add(id(engine))
                latency_ms = float(getattr(engine, "startup_latency_ms", 0.0) or 0.0)
                if latency_ms > 0.0:
                    latencies.append(latency_ms)
        elif self.engine is not None:
            latency_ms = float(getattr(self.engine, "startup_latency_ms", 0.0) or 0.0)
            if latency_ms > 0.0:
                latencies.append(latency_ms)
        return (sum(latencies) / len(latencies)) if latencies else 0.0

    def _fleet_global_observed_total_busy_ms(self) -> float:
        instance_pool = getattr(self, "instance_pool", None)
        if instance_pool is None:
            return 0.0

        def _bucket_total(bucket_name: str, bucket: Optional[Any]) -> float:
            if bucket is None or int(getattr(bucket, "samples", 0) or 0) <= 0:
                return 0.0
            runtime_ms = float(getattr(bucket, "avg_runtime_ttft_ms", 0.0) or 0.0)
            tail_ms = float(getattr(bucket, "avg_tail_service_ms", 0.0) or 0.0)
            lora_io_ms = (
                float(getattr(bucket, "avg_lora_io_ms", 0.0) or 0.0)
                if bucket_name != "backbone"
                else 0.0
            )
            return max(0.0, lora_io_ms + runtime_ms + tail_ms)

        observed: List[float] = []
        for slot in instance_pool.get_slots():
            for bucket_name, bucket in dict(
                getattr(slot, "observed_request_costs", {}) or {}
            ).items():
                total_ms = _bucket_total(str(bucket_name or ""), bucket)
                if total_ms > 0.0:
                    observed.append(total_ms)
        if not observed:
            return 0.0
        return sum(observed) / float(len(observed))

    def _waiting_visible_trace_queue(
        self,
        visible_traces: Optional[List[Any]] = None,
        submitted_traces: Optional[List[Any]] = None,
    ) -> List[Any]:
        live_waiting_queue = self._current_live_waiting_trace_queue()
        if live_waiting_queue:
            return live_waiting_queue
        candidate_traces = (
            visible_traces if visible_traces is not None else submitted_traces
        )
        live_counts = dict(getattr(self, "_live_arrived_lora_counts", {}) or {})
        started_counts = dict(getattr(self, "_live_started_lora_counts", {}) or {})
        waiting_counts = {
            adapter_id: max(
                0,
                int(live_counts.get(adapter_id, 0) or 0)
                - int(started_counts.get(adapter_id, 0) or 0),
            )
            for adapter_id in set(live_counts) | set(started_counts)
        }
        remaining_waiting = {
            adapter_id: int(count or 0)
            for adapter_id, count in waiting_counts.items()
            if adapter_id and int(count or 0) > 0
        }
        queue: List[Any] = []
        for trace in list(candidate_traces or []):
            adapter_id = getattr(trace, "adapter_id", None)
            if not adapter_id:
                continue
            remaining = int(remaining_waiting.get(adapter_id, 0) or 0)
            if remaining <= 0:
                continue
            queue.append(trace)
            remaining_waiting[adapter_id] = remaining - 1
        return queue

    def _waiting_submitted_trace_queue(
        self,
        submitted_traces: Optional[List[Any]] = None,
    ) -> List[Any]:
        # Backward-compatible alias for substrate_v1 call sites and tests.
        return self._waiting_visible_trace_queue(submitted_traces=submitted_traces)

    def _scale_up_ready_candidate_queue(
        self,
        *,
        replay_t0: Optional[float],
        arrived_request_count: int,
        queue_visible_request_count: Optional[int] = None,
        visible_traces: Optional[List[Any]] = None,
        submitted_count: Optional[int] = None,
        submitted_traces: Optional[List[Any]] = None,
        ready_delay_ms: float = 0.0,
    ) -> Tuple[List[Any], int]:
        visible_request_count = (
            queue_visible_request_count
            if queue_visible_request_count is not None
            else submitted_count
        )
        waiting_queue = self._waiting_visible_trace_queue(
            visible_traces=visible_traces,
            submitted_traces=submitted_traces,
        )
        if getattr(self, '_external_replay', None) is not None:
            # Bootstrap latency is not permission to peek at future adapters.
            return waiting_queue, len(self._external_replay.observed_times)
        traces = list(getattr(self, "traces", []) or [])
        projected_arrived = max(0, int(arrived_request_count or 0))
        if replay_t0 is not None and getattr(self, "_scheduled_arrivals", None):
            elapsed_now = max(0.0, time.perf_counter() - float(replay_t0))
            projected_arrived = max(
                projected_arrived,
                self._arrived_request_count_at_elapsed_s(
                    elapsed_now + max(0.0, float(ready_delay_ms or 0.0)) / 1000.0
                ),
            )
        upper = min(projected_arrived, len(traces))
        lower = min(max(0, int(visible_request_count or 0)), upper)
        return waiting_queue + traces[lower:upper], upper

    def _slot_predicted_service_cost_ms(self, slot: Optional[Any], adapter_id: Optional[str]) -> float:
        if slot is None:
            return 0.0
        size_mb = (
            float(self.adapter_info.get(adapter_id, {}).get("size_mb", 30.0))
            if adapter_id
            else 0.0
        )
        fallback_lora_io_ms = Router._fallback_lora_io_cost_ms(slot, size_mb, adapter_id)
        predictor = getattr(slot, "predicted_request_cost_ms", None)
        if callable(predictor):
            try:
                return max(
                    0.0,
                    float(
                        predictor(
                            adapter_id=adapter_id,
                            fallback_lora_io_ms=fallback_lora_io_ms,
                        )
                        or 0.0
                    ),
                )
            except Exception:
                pass
        return max(0.0, float(fallback_lora_io_ms or 0.0))

    def _slot_observed_total_busy_ms(self, slot: Optional[Any], adapter_id: Optional[str]) -> float:
        if slot is None:
            return 0.0
        observed_costs = dict(getattr(slot, "observed_request_costs", {}) or {})

        def _lora_total(bucket: Optional[Any]) -> float:
            if bucket is None or int(getattr(bucket, "samples", 0) or 0) <= 0:
                return 0.0
            return max(
                0.0,
                float(getattr(bucket, "avg_lora_io_ms", 0.0) or 0.0)
                + float(getattr(bucket, "avg_runtime_ttft_ms", 0.0) or 0.0)
                + float(getattr(bucket, "avg_tail_service_ms", 0.0) or 0.0),
            )

        def _backbone_total(bucket: Optional[Any]) -> float:
            if bucket is None or int(getattr(bucket, "samples", 0) or 0) <= 0:
                return 0.0
            return max(
                0.0,
                float(getattr(bucket, "avg_runtime_ttft_ms", 0.0) or 0.0)
                + float(getattr(bucket, "avg_tail_service_ms", 0.0) or 0.0),
            )

        if not adapter_id:
            exact = _backbone_total(observed_costs.get("backbone"))
            if exact > 0.0:
                return exact
            return max(0.0, float(getattr(slot, "observed_backbone_ttft_ms", 0.0) or 0.0))

        predicted_tier = None
        predictor = getattr(slot, "predicted_cache_tier", None)
        if callable(predictor):
            try:
                predicted_tier = str(predictor(adapter_id) or "")
            except Exception:
                predicted_tier = None
        if predicted_tier:
            exact = _lora_total(observed_costs.get(f"lora_{predicted_tier}"))
            if exact > 0.0:
                return exact

        lora_any = _lora_total(observed_costs.get("lora_any"))
        if lora_any > 0.0:
            return lora_any
        return max(0.0, float(getattr(slot, "observed_runtime_ttft_ms", 0.0) or 0.0))

    def _fleet_observed_total_busy_ms(self, adapter_id: Optional[str]) -> float:
        instance_pool = getattr(self, "instance_pool", None)
        if instance_pool is None:
            return 0.0
        observed = [
            self._slot_observed_total_busy_ms(slot, adapter_id)
            for slot in instance_pool.get_slots()
        ]
        observed = [float(value) for value in observed if float(value or 0.0) > 0.0]
        if not observed:
            return self._fleet_global_observed_total_busy_ms()
        return sum(observed) / float(len(observed))

    def _slot_predicted_tail_service_ms(self, slot: Optional[Any], adapter_id: Optional[str]) -> float:
        if slot is None:
            return 0.0
        predictor = getattr(slot, "predicted_tail_service_ms", None)
        if callable(predictor):
            try:
                return max(0.0, float(predictor(adapter_id=adapter_id) or 0.0))
            except Exception:
                pass
        return 0.0

    def _slot_predicted_total_busy_ms(self, slot: Optional[Any], adapter_id: Optional[str]) -> float:
        service_ms = self._slot_predicted_service_cost_ms(slot, adapter_id)
        tail_ms = self._slot_predicted_tail_service_ms(slot, adapter_id)
        predicted_total = max(service_ms + tail_ms, service_ms, 0.0)
        observed_total = self._slot_observed_total_busy_ms(slot, adapter_id)
        if predicted_total <= 0.0 and observed_total <= 0.0:
            return 0.0
        return max(predicted_total, observed_total)

    def _slot_initial_busy_ms(self, slot: Optional[Any]) -> float:
        if slot is None:
            return 0.0
        observed_costs = dict(getattr(slot, "observed_request_costs", {}) or {})
        for bucket_name in ("lora_any", "backbone"):
            bucket = observed_costs.get(bucket_name)
            if bucket is None:
                continue
            tail_ms = float(getattr(bucket, "avg_tail_service_ms", 0.0) or 0.0)
            if tail_ms > 0.0:
                return tail_ms
            runtime_ms = float(getattr(bucket, "avg_runtime_ttft_ms", 0.0) or 0.0)
            if runtime_ms > 0.0:
                return runtime_ms
        for attr in ("observed_runtime_ttft_ms", "observed_backbone_ttft_ms"):
            value = float(getattr(slot, attr, 0.0) or 0.0)
            if value > 0.0:
                return value
        return 0.0

    def _scale_up_incumbent_started_request_count(
        self,
        *,
        candidate_queue: List[Any],
        ready_delay_ms: float,
    ) -> int:
        if ready_delay_ms <= 0.0 or self.instance_pool is None:
            return 0
        slots = list(self.instance_pool.get_slots())
        if not slots:
            return 0
        runtime_lane_cap = max(1, self._runtime_forward_capacity_limit())
        dispatch_lane_cap = max(1, self._current_dispatch_capacity_limit())
        slot_lane_budget: Dict[str, int] = {}
        slot_ids_in_order: List[str] = []
        lane_ready_at: Dict[str, List[float]] = {}
        slot_by_id: Dict[str, Any] = {}
        total_busy_lanes = 0
        for slot in slots:
            slot_id = str(getattr(slot, "instance_id", "") or f"slot_{id(slot)}")
            slot_by_id[slot_id] = slot
            slot_ids_in_order.append(slot_id)
            busy_lanes = min(
                runtime_lane_cap,
                max(0, int(getattr(slot, "active_requests", 0) or 0)),
            )
            slot_lane_budget[slot_id] = busy_lanes
            total_busy_lanes += busy_lanes
        remaining_dispatch_lanes = max(0, dispatch_lane_cap - total_busy_lanes)
        while remaining_dispatch_lanes > 0:
            progressed = False
            for slot_id in slot_ids_in_order:
                if slot_lane_budget[slot_id] >= runtime_lane_cap:
                    continue
                slot_lane_budget[slot_id] += 1
                remaining_dispatch_lanes -= 1
                progressed = True
                if remaining_dispatch_lanes <= 0:
                    break
            if not progressed:
                break
        for slot_id in slot_ids_in_order:
            slot = slot_by_id[slot_id]
            lane_count = max(0, int(slot_lane_budget.get(slot_id, 0) or 0))
            if lane_count <= 0:
                continue
            lanes = [0.0] * lane_count
            busy_lanes = min(
                lane_count,
                max(0, int(getattr(slot, "active_requests", 0) or 0)),
            )
            initial_busy_ms = self._slot_initial_busy_ms(slot)
            for idx in range(busy_lanes):
                lanes[idx] = initial_busy_ms
            lane_ready_at[slot_id] = lanes

        started = 0
        for trace in candidate_queue:
            adapter_id = getattr(trace, "adapter_id", None)
            best_slot_id: Optional[str] = None
            best_lane_idx = 0
            best_start_ms = 0.0
            best_rank: Optional[tuple] = None
            best_total_busy_ms = 0.0
            for slot_id, lanes in lane_ready_at.items():
                lane_idx, lane_start_ms = min(enumerate(lanes), key=lambda item: item[1])
                slot = slot_by_id[slot_id]
                service_ms = self._slot_predicted_service_cost_ms(slot, adapter_id)
                tail_ms = self._slot_predicted_tail_service_ms(slot, adapter_id)
                observed_total_ms = self._slot_observed_total_busy_ms(slot, adapter_id)
                total_busy_ms = max(
                    service_ms + tail_ms,
                    service_ms,
                    observed_total_ms,
                    0.0,
                )
                if total_busy_ms <= 0.0:
                    continue
                rank = (
                    lane_start_ms + service_ms,
                    lane_start_ms,
                    service_ms,
                    slot_id,
                )
                if best_rank is None or rank < best_rank:
                    best_rank = rank
                    best_slot_id = slot_id
                    best_lane_idx = lane_idx
                    best_start_ms = lane_start_ms
                    best_total_busy_ms = total_busy_ms
            if (
                best_slot_id is None
                or best_total_busy_ms <= 0.0
                or best_start_ms >= ready_delay_ms
            ):
                break
            lane_ready_at[best_slot_id][best_lane_idx] = best_start_ms + best_total_busy_ms
            started += 1
        return started

    @staticmethod
    def _ordered_unique_adapter_ids(traces: List[Any]) -> List[str]:
        ordered: List[str] = []
        seen: set = set()
        for trace in traces:
            adapter_id = getattr(trace, "adapter_id", None)
            if not adapter_id or adapter_id in seen:
                continue
            seen.add(adapter_id)
            ordered.append(adapter_id)
        return ordered

    def _predicted_scale_up_load_ms(
        self,
        adapter_ids: List[str],
        *,
        max_concurrent_loads: int = 1,
    ) -> float:
        stack = getattr(self, "_stack", None)
        coordinator = getattr(self, "coordinator", None)
        if stack is None or not adapter_ids or coordinator is None:
            return 0.0
        metadata_fn = getattr(stack, "_artifact_metadata", None)
        size_fn = getattr(stack, "_artifact_size_mb", None)
        host_paths = dict(getattr(stack, "_host_paths", {}) or {})
        nvme_paths = dict(getattr(stack, "_nvme_paths", {}) or {})
        load_latencies_ms: List[float] = []
        for adapter_id in adapter_ids:
            metadata = metadata_fn(adapter_id) if callable(metadata_fn) else None
            predicted_ms = float(
                getattr(metadata, "predicted_load_time_ms", 0.0) or 0.0
            )
            observed_load_ms = max(
                0.0,
                float(getattr(metadata, "last_load_time_ms", 0.0) or 0.0),
                float(getattr(metadata, "avg_load_time_ms", 0.0) or 0.0),
            )
            size_mb = float(size_fn(adapter_id)) if callable(size_fn) else float(
                (getattr(self, "adapter_info", {}) or {}).get(adapter_id, {}).get("size_mb", 0.0) or 0.0
            )
            source_tier_predicted_ms = 0.0
            if adapter_id in host_paths:
                source_tier_predicted_ms = float(
                    coordinator.compute_faaslora_host_load_ms(size_mb) or 0.0
                )
            elif adapter_id in nvme_paths:
                source_tier_predicted_ms = float(
                    coordinator.compute_faaslora_nvme_load_ms(size_mb) or 0.0
                )
            else:
                bandwidth = float(getattr(self, "cost_model", {}).get("bandwidth_mbps", 0.0) or 0.0)
                source_tier_predicted_ms = float(
                    coordinator.compute_cold_start_load_ms(size_mb, bandwidth) or 0.0
                )
            predicted_ms = max(
                predicted_ms,
                observed_load_ms,
                source_tier_predicted_ms,
            )
            load_latencies_ms.append(max(0.0, predicted_ms))
        if not load_latencies_ms:
            return 0.0
        lane_count = max(1, int(max_concurrent_loads or 1))
        lane_busy_ms = [0.0] * lane_count
        for load_ms in sorted(load_latencies_ms, reverse=True):
            lane_idx = min(range(lane_count), key=lambda idx: lane_busy_ms[idx])
            lane_busy_ms[lane_idx] += load_ms
        return max(lane_busy_ms)

    def _scale_up_materializable_adapter_order(
        self,
        ordered_adapters: Collection[str],
    ) -> List[str]:
        stack = getattr(self, "_stack", None)
        if stack is None:
            return [str(adapter_id) for adapter_id in ordered_adapters if adapter_id]

        sync_paths = getattr(stack, "sync_local_tier_paths", None)
        if callable(sync_paths):
            try:
                sync_paths()
            except Exception:
                pass

        host_paths = dict(getattr(stack, "_host_paths", {}) or {})
        nvme_paths = dict(getattr(stack, "_nvme_paths", {}) or {})
        if not host_paths and not nvme_paths:
            return [str(adapter_id) for adapter_id in ordered_adapters if adapter_id]

        materialized: List[str] = []
        seen: set[str] = set()
        for adapter_id in ordered_adapters:
            adapter_key = str(adapter_id or "")
            if not adapter_key or adapter_key in seen:
                continue
            if adapter_key not in host_paths and adapter_key not in nvme_paths:
                continue
            seen.add(adapter_key)
            materialized.append(adapter_key)
        return materialized

    def _scale_up_adapter_total_bytes(
        self,
        ordered_adapters: Collection[str],
    ) -> int:
        stack = getattr(self, "_stack", None)
        size_fn = getattr(stack, "_artifact_size_mb", None) if stack is not None else None
        total_bytes = 0
        for adapter_id in ordered_adapters:
            adapter_key = str(adapter_id or "")
            if not adapter_key:
                continue
            size_mb = float(size_fn(adapter_key)) if callable(size_fn) else float(
                (getattr(self, "adapter_info", {}) or {}).get(adapter_key, {}).get("size_mb", 0.0) or 0.0
            )
            size_bytes = max(0, int(size_mb * 1024.0 * 1024.0))
            if size_bytes <= 0:
                continue
            total_bytes += size_bytes
        return total_bytes

    def _scale_up_exact_prefix_under_headroom(
        self,
        ordered_adapters: List[str],
        headroom_bytes: int,
    ) -> Tuple[List[str], int]:
        stack = getattr(self, "_stack", None)
        if stack is None or headroom_bytes <= 0:
            return [], 0
        size_fn = getattr(stack, "_artifact_size_mb", None)
        selected: List[str] = []
        total_bytes = 0
        for adapter_id in self._scale_up_materializable_adapter_order(ordered_adapters):
            size_mb = float(size_fn(adapter_id)) if callable(size_fn) else float(
                (getattr(self, "adapter_info", {}) or {}).get(adapter_id, {}).get("size_mb", 0.0) or 0.0
            )
            size_bytes = max(0, int(size_mb * 1024.0 * 1024.0))
            if size_bytes <= 0:
                continue
            if total_bytes + size_bytes > max(0, int(headroom_bytes)):
                break
            selected.append(adapter_id)
            total_bytes += size_bytes
        return selected, total_bytes

    def _scale_up_initial_admission_request_budget(self) -> int:
        runtime_cap = max(1, self._runtime_forward_capacity_limit())
        current_groups = max(0, self._current_runtime_group_count())
        current_capacity = self._dispatch_capacity_limit_for_runtime_groups(current_groups)
        next_capacity = self._dispatch_capacity_limit_for_runtime_groups(
            current_groups + 1
        )
        incremental_capacity = max(0, next_capacity - current_capacity)
        if incremental_capacity > 0:
            return max(1, min(runtime_cap, incremental_capacity))
        # If the workload cap has already saturated the aggregate dispatch budget,
        # a new runtime still needs to be able to take over at least one queued
        # request once dispatch rotates. Keep the initial warmup bounded to one
        # request-class in that case instead of expanding to the full queue.
        return 1

    def _scale_up_effective_initial_warmup_parallelism(
        self,
        queue_at_ready: List[Any],
        *,
        configured_max_concurrent_loads: Optional[int] = None,
    ) -> int:
        max_concurrent_loads = configured_max_concurrent_loads
        if max_concurrent_loads is None:
            max_concurrent_loads = int(
                getattr(self, "coord_cfg", {}).get("max_concurrent_loads", 1) or 1
            )
        max_concurrent_loads = max(1, int(max_concurrent_loads or 1))
        if not queue_at_ready:
            return 1
        return max(
            1,
            min(
                max_concurrent_loads,
                len(queue_at_ready),
            ),
        )

    def _scale_up_trace_total_busy_estimate_ms(self, trace: Optional[Any]) -> float:
        adapter_id = getattr(trace, "adapter_id", None) if trace is not None else None
        observed_total = self._fleet_observed_total_busy_ms(adapter_id)
        if observed_total > 0.0:
            return observed_total
        instance_pool = getattr(self, "instance_pool", None)
        if instance_pool is None:
            return 0.0
        predicted_totals = [
            self._slot_predicted_total_busy_ms(slot, adapter_id)
            for slot in instance_pool.get_slots()
        ]
        predicted_totals = [
            float(value) for value in predicted_totals if float(value or 0.0) > 0.0
        ]
        if not predicted_totals:
            return 0.0
        return min(predicted_totals)

    def _scale_up_simulated_observed_costs(
        self,
    ) -> Tuple[Dict[str, ObservedRequestCost], float, int, float, int]:
        instance_pool = getattr(self, "instance_pool", None)
        if instance_pool is None:
            return {}, 0.0, 0, 0.0, 0
        bucket_totals: Dict[str, Dict[str, float]] = {}
        runtime_weighted_ttft_ms = 0.0
        runtime_samples = 0
        backbone_weighted_ttft_ms = 0.0
        backbone_samples = 0
        for slot in instance_pool.get_slots():
            slot_runtime_samples = max(
                0, int(getattr(slot, "observed_runtime_samples", 0) or 0)
            )
            if slot_runtime_samples > 0:
                runtime_weighted_ttft_ms += slot_runtime_samples * float(
                    getattr(slot, "observed_runtime_ttft_ms", 0.0) or 0.0
                )
                runtime_samples += slot_runtime_samples
            slot_backbone_samples = max(
                0, int(getattr(slot, "observed_backbone_samples", 0) or 0)
            )
            if slot_backbone_samples > 0:
                backbone_weighted_ttft_ms += slot_backbone_samples * float(
                    getattr(slot, "observed_backbone_ttft_ms", 0.0) or 0.0
                )
                backbone_samples += slot_backbone_samples
            for bucket_name, bucket in dict(
                getattr(slot, "observed_request_costs", {}) or {}
            ).items():
                samples = max(0, int(getattr(bucket, "samples", 0) or 0))
                if samples <= 0:
                    continue
                totals = bucket_totals.setdefault(
                    str(bucket_name or ""),
                    {
                        "samples": 0.0,
                        "lora_io_ms": 0.0,
                        "runtime_ttft_ms": 0.0,
                        "tail_service_ms": 0.0,
                    },
                )
                totals["samples"] += float(samples)
                totals["lora_io_ms"] += float(
                    getattr(bucket, "avg_lora_io_ms", 0.0) or 0.0
                ) * float(samples)
                totals["runtime_ttft_ms"] += float(
                    getattr(bucket, "avg_runtime_ttft_ms", 0.0) or 0.0
                ) * float(samples)
                totals["tail_service_ms"] += float(
                    getattr(bucket, "avg_tail_service_ms", 0.0) or 0.0
                ) * float(samples)
        aggregated_buckets: Dict[str, ObservedRequestCost] = {}
        for bucket_name, totals in bucket_totals.items():
            samples = max(0, int(totals["samples"] or 0.0))
            if samples <= 0:
                continue
            aggregated_buckets[bucket_name] = ObservedRequestCost(
                samples=samples,
                avg_lora_io_ms=float(totals["lora_io_ms"]) / float(samples),
                avg_runtime_ttft_ms=float(totals["runtime_ttft_ms"]) / float(samples),
                avg_tail_service_ms=float(totals["tail_service_ms"]) / float(samples),
            )
        runtime_avg_ttft_ms = (
            runtime_weighted_ttft_ms / float(runtime_samples)
            if runtime_samples > 0
            else 0.0
        )
        backbone_avg_ttft_ms = (
            backbone_weighted_ttft_ms / float(backbone_samples)
            if backbone_samples > 0
            else 0.0
        )
        return (
            aggregated_buckets,
            runtime_avg_ttft_ms,
            runtime_samples,
            backbone_avg_ttft_ms,
            backbone_samples,
        )

    def _copy_scale_up_routing_simulation_slot(self, slot: Any) -> Any:
        simulated = copy.copy(slot)
        simulated.gpu_resident_adapters = set(
            getattr(slot, "gpu_resident_adapters", set()) or set()
        )
        simulated.host_cached_adapters = set(
            getattr(slot, "host_cached_adapters", set()) or set()
        )
        simulated.nvme_cached_adapters = set(
            getattr(slot, "nvme_cached_adapters", set()) or set()
        )
        simulated.observed_request_costs = dict(
            getattr(slot, "observed_request_costs", {}) or {}
        )
        return simulated

    def _make_scale_up_routing_simulated_slot(
        self,
        planned_gpu_adapters: Collection[str],
        *,
        request_budget: int = 0,
        instance_id: Optional[str] = None,
    ) -> InstanceSlot:
        (
            observed_buckets,
            runtime_avg_ttft_ms,
            runtime_samples,
            backbone_avg_ttft_ms,
            backbone_samples,
        ) = self._scale_up_simulated_observed_costs()
        simulated = InstanceSlot(
            instance_id=str(instance_id or "__scaleup_sim__"),
            engine=None,
            coordinator=getattr(self, "coordinator", None),
            created_at=time.time(),
        )
        self._prime_slot_cache_view(simulated, include_gpu=False)
        simulated.active_requests = 0
        simulated.load_queue_depth = 0
        simulated.gpu_utilization_pct = 0.0
        simulated.last_selected_at = 0.0
        simulated.observed_request_costs = observed_buckets
        simulated.observed_runtime_ttft_ms = runtime_avg_ttft_ms
        simulated.observed_runtime_samples = runtime_samples
        simulated.observed_backbone_ttft_ms = backbone_avg_ttft_ms
        simulated.observed_backbone_samples = backbone_samples
        planned_adapters = [
            str(adapter_id) for adapter_id in list(planned_gpu_adapters or []) if adapter_id
        ]
        simulated.scaleup_handoff_planned_adapters = list(planned_adapters)
        simulated.scaleup_handoff_planned_adapter_ranks = {
            adapter_id: idx for idx, adapter_id in enumerate(planned_adapters)
        }
        simulated.scaleup_handoff_request_budget = max(0, int(request_budget or 0))
        simulated.scaleup_handoff_assigned_requests = 0
        for adapter_id in planned_gpu_adapters:
            simulated.mark_adapter_tier(adapter_id, "gpu")
        return simulated

    def _route_aware_scale_up_first_service_prefix_state(
        self,
        queue_at_ready: List[Any],
        simulated_slots: List[Any],
        new_slot: Any,
        *,
        request_budget: int,
    ) -> Tuple[List[Any], List[Any], List[Any]]:
        router = getattr(self, "router", None)
        if (
            request_budget <= 0
            or not queue_at_ready
            or router is None
            or not simulated_slots
            or new_slot is None
        ):
            return [], [], list(queue_at_ready or [])

        class _RoutingPool:
            def __init__(self, slots: List[Any]):
                self._slots = slots

            def get_slots(self) -> List[Any]:
                return self._slots

        try:
            fallback_runtime_cap = max(
                1, int(self._runtime_forward_capacity_limit() or 1)
            )
        except Exception:
            fallback_runtime_cap = 1
        sim_router = Router(
            _RoutingPool(simulated_slots),
            policy=str(getattr(router, "policy", "least_connections") or "least_connections"),
            runtime_concurrency_cap=max(
                1,
                int(
                    getattr(
                        router,
                        "runtime_concurrency_cap",
                        fallback_runtime_cap,
                    )
                    or fallback_runtime_cap
                ),
            ),
            max_active_loras=max(
                0,
                int(
                    getattr(
                        router,
                        "max_active_loras",
                        self._runtime_max_active_loras(),
                    )
                    or self._runtime_max_active_loras()
                ),
            ),
        )
        runtime_cap = max(
            1, int(getattr(sim_router, "runtime_concurrency_cap", 1) or 1)
        )
        logical_time = max(
            time.time(),
            max(
                float(getattr(slot, "last_selected_at", 0.0) or 0.0)
                for slot in simulated_slots
            ),
        )
        scanned_traces: List[Any] = []
        routed_prefix: List[Any] = []
        target_instance_id = str(getattr(new_slot, "instance_id", "") or "")

        for trace in list(queue_at_ready):
            scanned_traces.append(trace)
            adapter_id = getattr(trace, "adapter_id", None)
            size_mb = (
                float(self.adapter_info.get(adapter_id, {}).get("size_mb", 30.0))
                if adapter_id
                else 0.0
            )
            selected = sim_router.select_instance(
                adapter_id, adapter_size_mb=size_mb
            )
            if selected is None:
                break
            current_active = max(
                0, int(getattr(selected, "active_requests", 0) or 0)
            )
            if current_active >= runtime_cap:
                selected.load_queue_depth = max(
                    0, int(getattr(selected, "load_queue_depth", 0) or 0)
                ) + 1
            selected.active_requests = current_active + 1
            if adapter_id and hasattr(selected, "begin_active_adapter"):
                try:
                    selected.begin_active_adapter(adapter_id)
                except Exception:
                    pass
            selected.last_selected_at = logical_time
            logical_time += 1e-6
            if adapter_id and hasattr(selected, "mark_adapter_tier"):
                predictor = getattr(selected, "predicted_cache_tier", None)
                predicted_tier = None
                if callable(predictor):
                    try:
                        predicted_tier = str(predictor(adapter_id) or "")
                    except Exception:
                        predicted_tier = None
                if predicted_tier != "gpu":
                    selected.mark_adapter_tier(adapter_id, "gpu")
            if (
                target_instance_id
                and str(getattr(selected, "instance_id", "") or "") == target_instance_id
                and adapter_id
            ):
                routed_prefix.append(trace)
                if len(routed_prefix) >= request_budget:
                    break

        remaining_queue = list((queue_at_ready or [])[len(scanned_traces):])
        return scanned_traces, routed_prefix, remaining_queue

    def _route_aware_scale_up_first_service_prefix_traces(
        self,
        queue_at_ready: List[Any],
        planned_adapters: Collection[str],
        *,
        request_budget: int,
    ) -> List[Any]:
        instance_pool = getattr(self, "instance_pool", None)
        router = getattr(self, "router", None)
        if (
            request_budget <= 0
            or not queue_at_ready
            or instance_pool is None
            or router is None
        ):
            return []
        current_slots = list(instance_pool.get_slots())
        if not current_slots:
            return []

        simulated_slots = [
            self._copy_scale_up_routing_simulation_slot(slot) for slot in current_slots
        ]
        new_slot = self._make_scale_up_routing_simulated_slot(
            planned_adapters,
            request_budget=request_budget,
        )
        simulated_slots.append(new_slot)
        _, routed_prefix, _ = self._route_aware_scale_up_first_service_prefix_state(
            list(queue_at_ready),
            simulated_slots,
            new_slot,
            request_budget=request_budget,
        )
        return routed_prefix

    def _scale_up_first_service_request_budget(
        self,
        queue_at_ready: List[Any],
        *,
        configured_max_concurrent_loads: Optional[int] = None,
    ) -> int:
        initial_budget = max(1, self._scale_up_initial_admission_request_budget())
        if not queue_at_ready:
            return initial_budget
        # Keep the first-service budget pinned to the earliest handoff slice.
        # "How many loads could run in parallel" is still worth recording as a
        # diagnostic, but it must not automatically widen cold-start work.
        # Otherwise the runtime's ready time grows before we have evidence that
        # the extra warmed adapters will actually be the first routed requests.
        return max(1, min(len(queue_at_ready), initial_budget))

    def _consume_scale_up_lora_service_prefix(
        self,
        traces: List[Any],
        *,
        request_budget: int,
    ) -> Tuple[List[Any], List[Any], List[Any]]:
        request_budget = max(1, int(request_budget or 1))
        scanned: List[Any] = []
        selected: List[Any] = []
        for trace in list(traces or []):
            scanned.append(trace)
            if getattr(trace, "adapter_id", None):
                selected.append(trace)
            if len(selected) >= request_budget:
                break
        remaining = list((traces or [])[len(scanned):])
        return scanned, selected, remaining

    def _scale_up_first_service_prefix_traces(
        self,
        queue_at_ready: List[Any],
        *,
        configured_max_concurrent_loads: Optional[int] = None,
    ) -> List[Any]:
        request_budget = max(
            1,
            self._scale_up_first_service_request_budget(
                queue_at_ready,
                configured_max_concurrent_loads=configured_max_concurrent_loads,
            ),
        )
        _, selected, _ = self._consume_scale_up_lora_service_prefix(
            list(queue_at_ready or []),
            request_budget=request_budget,
        )
        return selected

    def _predict_scale_up_handoff_plan(
        self,
        *,
        replay_t0: Optional[float],
        arrived_request_count: int,
        queue_visible_request_count: Optional[int] = None,
        visible_traces: Optional[List[Any]] = None,
        submitted_count: Optional[int] = None,
        submitted_traces: Optional[List[Any]] = None,
        bootstrap_latency_ms_override: Optional[float] = None,
    ) -> Dict[str, Any]:
        if not bool(getattr(self, "_scale_up_handoff_enabled", True)):
            return {}
        planning_started_ns = time.perf_counter_ns()
        headroom_bytes = max(
            0,
            int(self._scale_up_target_runtime_headroom_mb() * 1024.0 * 1024.0),
        )
        bootstrap_latency_ms = (
            max(0.0, float(bootstrap_latency_ms_override or 0.0))
            if bootstrap_latency_ms_override is not None
            else self._scale_up_bootstrap_latency_ms()
        )
        configured_max_concurrent_loads = max(
            1,
            int(getattr(self, "coord_cfg", {}).get("max_concurrent_loads", 1) or 1),
        )
        instance_pool = getattr(self, "instance_pool", None)
        route_aware_enabled = bool(
            instance_pool is not None
            and getattr(self, "router", None) is not None
            and list(instance_pool.get_slots())
        )
        effective_initial_warmup_parallelism = 1

        ready_delay_ms = bootstrap_latency_ms
        projected_arrived_request_count = max(0, int(arrived_request_count or 0))
        incumbent_started_request_count = 0
        queue_at_ready: List[Any] = []
        ordered_handoff_adapters: List[str] = []
        first_service_prefix_traces: List[Any] = []
        first_service_prefix_adapters: List[str] = []
        planned_adapters: List[str] = []
        exact_prefix_bytes = 0
        plan_load_latency_ms = 0.0
        initial_admission_request_budget = self._scale_up_initial_admission_request_budget()

        previous_signature: Optional[tuple] = None
        for _ in range(4):
            candidate_queue, projected_arrived_request_count = self._scale_up_ready_candidate_queue(
                replay_t0=replay_t0,
                arrived_request_count=arrived_request_count,
                queue_visible_request_count=queue_visible_request_count,
                visible_traces=visible_traces,
                submitted_count=submitted_count,
                submitted_traces=submitted_traces,
                ready_delay_ms=ready_delay_ms,
            )
            incumbent_started_request_count = self._scale_up_incumbent_started_request_count(
                candidate_queue=candidate_queue,
                ready_delay_ms=ready_delay_ms,
            )
            queue_at_ready = list(candidate_queue[incumbent_started_request_count:])
            ordered_handoff_adapters = self._ordered_unique_adapter_ids(queue_at_ready)
            effective_initial_warmup_parallelism = (
                self._scale_up_effective_initial_warmup_parallelism(
                    queue_at_ready,
                    configured_max_concurrent_loads=configured_max_concurrent_loads,
                )
            )
            request_budget = self._scale_up_first_service_request_budget(
                queue_at_ready,
                configured_max_concurrent_loads=configured_max_concurrent_loads,
            )
            first_service_prefix_traces = self._scale_up_first_service_prefix_traces(
                queue_at_ready,
                configured_max_concurrent_loads=configured_max_concurrent_loads,
            )
            first_service_prefix_adapters = self._ordered_unique_adapter_ids(
                first_service_prefix_traces
            )
            if not first_service_prefix_adapters and ordered_handoff_adapters:
                first_service_prefix_adapters = list(
                    ordered_handoff_adapters[: max(1, int(request_budget))]
                )
            if not ordered_handoff_adapters:
                ordered_handoff_adapters = sorted(self._scale_up_warmup_preferred_gpu_adapters())
            if not first_service_prefix_adapters:
                first_service_prefix_adapters = list(
                    ordered_handoff_adapters[: max(1, int(request_budget))]
                )
            planned_adapters, exact_prefix_bytes = self._scale_up_exact_prefix_under_headroom(
                first_service_prefix_adapters,
                headroom_bytes,
            )
            routed_first_service_prefix_traces = (
                self._route_aware_scale_up_first_service_prefix_traces(
                    queue_at_ready,
                    planned_adapters,
                    request_budget=request_budget,
                )
            )
            if (
                routed_first_service_prefix_traces
                or request_budget <= 0
                or route_aware_enabled
            ):
                first_service_prefix_traces = list(routed_first_service_prefix_traces)
                first_service_prefix_adapters = self._ordered_unique_adapter_ids(
                    first_service_prefix_traces
                )
                planned_adapters, exact_prefix_bytes = self._scale_up_exact_prefix_under_headroom(
                    first_service_prefix_adapters,
                    headroom_bytes,
                )
            plan_load_latency_ms = self._predicted_scale_up_load_ms(
                planned_adapters,
                max_concurrent_loads=configured_max_concurrent_loads,
            )
            next_ready_delay_ms = bootstrap_latency_ms + plan_load_latency_ms
            signature = (
                tuple(planned_adapters),
                projected_arrived_request_count,
                incumbent_started_request_count,
                round(next_ready_delay_ms, 4),
            )
            if signature == previous_signature:
                ready_delay_ms = next_ready_delay_ms
                break
            previous_signature = signature
            ready_delay_ms = next_ready_delay_ms

        plan = {
            "mode": "dynamic_headroom_exact_handoff_prefix",
            "planned_adapters": planned_adapters,
            "ordered_handoff_adapters": ordered_handoff_adapters,
            "_queue_at_ready_traces": list(queue_at_ready),
            "queue_at_ready_request_count": len(queue_at_ready),
            "queue_at_ready_adapter_count": len(ordered_handoff_adapters),
            "first_service_request_count": len(first_service_prefix_traces),
            "first_service_adapter_count": len(first_service_prefix_adapters),
            "initial_admission_request_budget": initial_admission_request_budget,
            "projected_arrived_request_count": projected_arrived_request_count,
            "incumbent_started_request_count": incumbent_started_request_count,
            "bootstrap_latency_ms": bootstrap_latency_ms,
            "plan_load_latency_ms": plan_load_latency_ms,
            "ready_delay_ms": ready_delay_ms,
            "exact_prefix_bytes": exact_prefix_bytes,
            "target_headroom_bytes": headroom_bytes,
            "configured_max_concurrent_loads": configured_max_concurrent_loads,
            "effective_initial_warmup_parallelism": effective_initial_warmup_parallelism,
        }
        self._background_planning_us.append(
            max(0.0, (time.perf_counter_ns() - planning_started_ns) / 1000.0)
        )
        return plan

    def _refresh_scale_up_runtime_handoff_plan_after_startup(
        self,
        handoff_plan: Optional[Dict[str, Any]],
        *,
        runtime_startup_latency_ms: float,
    ) -> Dict[str, Any]:
        plan = dict(handoff_plan or {})
        if not plan:
            return {}
        runtime_startup_latency_ms = max(
            0.0, float(runtime_startup_latency_ms or 0.0)
        )
        if runtime_startup_latency_ms <= 0.0:
            return plan

        original_planned_adapters = [
            str(adapter_id)
            for adapter_id in list(plan.get("planned_adapters", []) or [])
            if adapter_id
        ]
        original_ordered_handoff = [
            str(adapter_id)
            for adapter_id in list(plan.get("ordered_handoff_adapters", []) or [])
            if adapter_id
        ]
        original_first_service_budget = max(
            0,
            int(
                plan.get("first_service_request_count", 0)
                or plan.get("initial_admission_request_budget", 0)
                or 0
            ),
        )

        replay_t0 = getattr(self, "_active_replay_t0", None)
        if replay_t0 is None:
            plan["bootstrap_latency_ms"] = runtime_startup_latency_ms
            plan["ready_delay_ms"] = runtime_startup_latency_ms + float(
                plan.get("plan_load_latency_ms", 0.0) or 0.0
            )
            return plan

        arrived_request_count = self._arrived_request_count(replay_t0)
        waiting_traces = self._waiting_visible_trace_queue()
        # Startup has already elapsed by the time we refresh the handoff plan.
        # Re-adding startup latency into the planning horizon would project the
        # queue a second time and drift the predicted first-service slice away
        # from the requests the new runtime will actually see next.
        refreshed_base_plan = self._predict_scale_up_handoff_plan(
            replay_t0=replay_t0,
            arrived_request_count=arrived_request_count,
            queue_visible_request_count=arrived_request_count,
            visible_traces=waiting_traces,
            submitted_count=arrived_request_count,
            submitted_traces=waiting_traces,
            bootstrap_latency_ms_override=0.0,
        )
        pending_sequence = plan.get("_pending_scaleup_sequence")
        pending_position = self._pending_scale_up_sequence_index(
            int(pending_sequence) if pending_sequence is not None else None
        )
        if pending_position is not None:
            runtime_plan_index, pending_runtime_count = pending_position
        else:
            runtime_plan_index = max(0, int(plan.get("_runtime_plan_index", 0) or 0))
            pending_runtime_count = runtime_plan_index + 1
        refreshed_runtime_plans = self._build_scale_up_runtime_handoff_plans(
            refreshed_base_plan,
            additional_instances=max(1, pending_runtime_count),
        )
        if runtime_plan_index < len(refreshed_runtime_plans):
            refreshed_plan = dict(refreshed_runtime_plans[runtime_plan_index] or {})
            preserved_planned_prefix = False
            refreshed_planned_adapters = [
                str(adapter_id)
                for adapter_id in list(refreshed_plan.get("planned_adapters", []) or [])
                if adapter_id
            ]
            refreshed_ordered_handoff = [
                str(adapter_id)
                for adapter_id in list(refreshed_plan.get("ordered_handoff_adapters", []) or [])
                if adapter_id
            ]
            refreshed_first_service_budget = max(
                0,
                int(refreshed_plan.get("first_service_request_count", 0) or 0),
            )
            # Startup can take long enough for incumbent runtimes to drain the
            # queue that originally justified a handoff reservation. In that
            # case, keeping the old planned prefix as a hard routing reservation
            # makes the fresh runtime adapter-locked and can leave it idle for
            # most of the replay. Preserve the old prefix only when the refreshed
            # ready-time view still contains a first-service window.
            if refreshed_first_service_budget > 0:
                if not refreshed_planned_adapters and original_planned_adapters:
                    refreshed_planned_adapters = list(original_planned_adapters)
                    refreshed_plan["planned_adapters"] = list(refreshed_planned_adapters)
                    preserved_planned_prefix = True
                if not refreshed_ordered_handoff and original_ordered_handoff:
                    refreshed_ordered_handoff = list(original_ordered_handoff)
                    refreshed_plan["ordered_handoff_adapters"] = list(
                        refreshed_ordered_handoff
                    )
                    preserved_planned_prefix = True
            if refreshed_first_service_budget <= 0 and refreshed_planned_adapters:
                refreshed_first_service_budget = max(1, original_first_service_budget)
                refreshed_plan["first_service_request_count"] = (
                    refreshed_first_service_budget
                )
                refreshed_plan["first_service_adapter_count"] = max(
                    int(refreshed_plan.get("first_service_adapter_count", 0) or 0),
                    len(
                        self._ordered_unique_adapter_ids(
                            refreshed_ordered_handoff or refreshed_planned_adapters
                        )
                    ),
                )
                refreshed_plan["first_service_scanned_request_count"] = max(
                    int(
                        refreshed_plan.get("first_service_scanned_request_count", 0)
                        or 0
                    ),
                    refreshed_first_service_budget,
                )
            if preserved_planned_prefix and refreshed_planned_adapters:
                refreshed_plan["exact_prefix_bytes"] = self._scale_up_adapter_total_bytes(
                    refreshed_planned_adapters
                )
                refreshed_plan["plan_load_latency_ms"] = self._predicted_scale_up_load_ms(
                    refreshed_planned_adapters,
                    max_concurrent_loads=max(
                        1,
                        int(
                            refreshed_plan.get(
                                "configured_max_concurrent_loads",
                                plan.get("configured_max_concurrent_loads", 1),
                            )
                            or 1
                        ),
                    ),
                )
            refreshed_plan["_runtime_plan_index"] = runtime_plan_index
            if pending_sequence is not None:
                refreshed_plan["_pending_scaleup_sequence"] = int(pending_sequence)
            refreshed_plan["bootstrap_latency_ms"] = runtime_startup_latency_ms
            refreshed_plan["ready_delay_ms"] = runtime_startup_latency_ms + float(
                refreshed_plan.get("plan_load_latency_ms", 0.0) or 0.0
            )
            return refreshed_plan

        plan["bootstrap_latency_ms"] = runtime_startup_latency_ms
        plan["ready_delay_ms"] = runtime_startup_latency_ms + float(
            plan.get("plan_load_latency_ms", 0.0) or 0.0
        )
        return plan

    def _live_scale_up_arrived_demand_frontier(
        self,
        *,
        replay_t0: Optional[float] = None,
        arrived_request_count: int,
        queue_visible_request_count: Optional[int] = None,
        visible_traces: Optional[List[Any]] = None,
        submitted_count: Optional[int] = None,
        submitted_traces: Optional[List[Any]] = None,
    ) -> List[str]:
        plan = self._predict_scale_up_handoff_plan(
            replay_t0=replay_t0,
            arrived_request_count=arrived_request_count,
            queue_visible_request_count=queue_visible_request_count,
            visible_traces=visible_traces,
            submitted_count=submitted_count,
            submitted_traces=submitted_traces,
        )
        return list(plan.get("ordered_handoff_adapters", []) or [])

    def _live_scale_up_preferred_gpu_adapters(
        self,
        *,
        replay_t0: Optional[float] = None,
        arrived_request_count: int,
        queue_visible_request_count: Optional[int] = None,
        visible_traces: Optional[List[Any]] = None,
        submitted_count: Optional[int] = None,
        submitted_traces: Optional[List[Any]] = None,
    ) -> List[str]:
        plan = self._predict_scale_up_handoff_plan(
            replay_t0=replay_t0,
            arrived_request_count=arrived_request_count,
            queue_visible_request_count=queue_visible_request_count,
            visible_traces=visible_traces,
            submitted_count=submitted_count,
            submitted_traces=submitted_traces,
        )
        self._last_scale_up_handoff_plan = dict(plan)
        return list(plan.get("planned_adapters", []) or [])

    def _refined_scale_up_target_instances(
        self,
        *,
        current_instances: int,
        decision: Any,
        handoff_plan: Optional[Dict[str, Any]] = None,
    ) -> int:
        instance_pool = getattr(self, "instance_pool", None)
        max_instances = (
            int(getattr(instance_pool, "max_instances", current_instances) or current_instances)
            if instance_pool is not None
            else max(
                current_instances,
                int(getattr(decision, "target_instances", current_instances) or current_instances),
            )
        )
        base_target = max(
            current_instances + 1,
            int(getattr(decision, "target_instances", current_instances + 1) or current_instances + 1),
        )
        if not bool(getattr(self, "coord_cfg", {}).get("scale_up_predictive_target_enabled", True)):
            return min(max_instances, base_target)

        # The autoscaler decides *whether* to scale, while the handoff predictor
        # estimates how much queue will still be waiting when a new runtime is
        # ready. Under bursty traces, only adding one runtime per decision leaves
        # service-ready capacity lagging the predicted queue frontier. Refine the
        # target from that predicted ready-time queue, but keep the result bounded
        # by the physical pool and the normal autoscaler decision.
        queue_at_ready = self._scale_up_handoff_queue_at_ready_count(handoff_plan)
        if queue_at_ready <= 0:
            return min(max_instances, base_target)

        predicted_waiting = self._scale_up_handoff_predicted_waiting_count(
            handoff_plan
        )
        if predicted_waiting <= 0:
            return min(max_instances, base_target)

        runtime_cap = max(1, int(self._runtime_forward_capacity_limit() or 1))
        required_instances = int(math.ceil(predicted_waiting / float(runtime_cap)))
        predictive_target = max(base_target, min(max_instances, required_instances))
        return min(max_instances, predictive_target)

    def _scale_up_handoff_queue_at_ready_count(
        self,
        handoff_plan: Optional[Dict[str, Any]],
    ) -> int:
        plan = dict(handoff_plan or {})
        return max(
            0,
            int(
                plan.get("queue_at_ready_request_count", 0)
                or plan.get("projected_queue_at_ready_request_count", 0)
                or 0
            ),
        )

    def _scale_up_handoff_predicted_waiting_count(
        self,
        handoff_plan: Optional[Dict[str, Any]],
    ) -> int:
        plan = dict(handoff_plan or {})
        queue_at_ready = self._scale_up_handoff_queue_at_ready_count(handoff_plan)
        projected_arrived = max(
            0,
            int(plan.get("projected_arrived_request_count", 0) or 0),
        )
        incumbent_started = max(
            0,
            int(plan.get("incumbent_started_request_count", 0) or 0),
        )
        return max(queue_at_ready, projected_arrived - incumbent_started)

    def _scale_up_capacity_covers_ready_projection(
        self,
        *,
        handoff_plan: Optional[Dict[str, Any]],
        current_instances: int,
        pending_scale_up_instances: int,
        backlog: int,
        active_requests: int,
        busy_ratio: float = 0.0,
    ) -> bool:
        current = max(0, int(current_instances or 0))
        pending = max(0, int(pending_scale_up_instances or 0))
        if current <= 0:
            return False
        queue_at_ready = self._scale_up_handoff_queue_at_ready_count(handoff_plan)
        if queue_at_ready > 0:
            return False
        visible_work = max(
            max(0, int(backlog or 0)),
            max(0, int(active_requests or 0)),
        )
        if visible_work <= 0:
            return True
        # Request-count capacity is not sufficient for token-heavy traces. A
        # single runtime can have only a few visible requests while still being
        # continuously occupied by long prefill/decode work. If the autoscaler
        # already reports service saturation, do not suppress the scale-out
        # pulse solely because the ready-time queue projection is empty.
        try:
            busy = float(busy_ratio or 0.0)
        except Exception:
            busy = 0.0
        if busy >= 0.75:
            return False
        runtime_cap = max(1, int(self._runtime_forward_capacity_limit() or 1))
        covered_capacity = max(1, current) * runtime_cap
        return visible_work <= covered_capacity

    def _build_scale_up_runtime_handoff_plans(
        self,
        base_plan: Optional[Dict[str, Any]],
        *,
        additional_instances: int,
    ) -> List[Dict[str, Any]]:
        if additional_instances <= 0:
            return []
        plan = dict(base_plan or {})
        if not plan:
            return [{} for _ in range(additional_instances)]

        queue_at_ready_traces = list(plan.get("_queue_at_ready_traces", []) or [])
        global_ordered_adapters = [
            str(adapter_id)
            for adapter_id in list(plan.get("ordered_handoff_adapters", []) or [])
            if adapter_id
        ]
        has_explicit_queue = bool(queue_at_ready_traces)
        remaining_queue = list(queue_at_ready_traces)
        consumed_adapters: set[str] = set()
        request_budget = max(
            1,
            int(
                plan.get("first_service_request_count", 0)
                or plan.get("initial_admission_request_budget", 1)
                or 1
            ),
        )
        headroom_bytes = max(0, int(plan.get("target_headroom_bytes", 0) or 0))
        max_concurrent_loads = max(
            1,
            int(plan.get("configured_max_concurrent_loads", 1) or 1),
        )
        bootstrap_latency_ms = float(plan.get("bootstrap_latency_ms", 0.0) or 0.0)

        per_runtime_plans: List[Dict[str, Any]] = []
        instance_pool = getattr(self, "instance_pool", None)
        route_aware_enabled = bool(
            instance_pool is not None
            and getattr(self, "router", None) is not None
            and list(instance_pool.get_slots())
        )
        simulated_slots = (
            [
                self._copy_scale_up_routing_simulation_slot(slot)
                for slot in list(instance_pool.get_slots())
            ]
            if route_aware_enabled
            else []
        )

        for runtime_idx in range(additional_instances):
            scanned_traces: List[Any] = []
            slice_traces: List[Any] = []
            ordered_handoff_adapters: List[str] = []

            if route_aware_enabled and remaining_queue:
                _, seed_slice_traces, _ = self._consume_scale_up_lora_service_prefix(
                    remaining_queue,
                    request_budget=request_budget,
                )
                seed_ordered_adapters = self._ordered_unique_adapter_ids(seed_slice_traces)
                if not seed_ordered_adapters and not has_explicit_queue:
                    seed_ordered_adapters = [
                        adapter_id
                        for adapter_id in global_ordered_adapters
                        if adapter_id not in consumed_adapters
                    ]
                if not seed_ordered_adapters and runtime_idx == 0 and not has_explicit_queue:
                    seed_ordered_adapters = [
                        str(adapter_id)
                        for adapter_id in list(plan.get("planned_adapters", []) or [])
                        if adapter_id
                    ]

                trial_planned_adapters, _ = self._scale_up_exact_prefix_under_headroom(
                    seed_ordered_adapters,
                    headroom_bytes,
                )
                sim_instance_id = f"__scaleup_sim_{runtime_idx}__"
                trial_slots = [
                    self._copy_scale_up_routing_simulation_slot(slot)
                    for slot in simulated_slots
                ]
                trial_new_slot = self._make_scale_up_routing_simulated_slot(
                    trial_planned_adapters,
                    request_budget=request_budget,
                    instance_id=sim_instance_id,
                )
                trial_slots.append(trial_new_slot)
                _, routed_trial_prefix, _ = self._route_aware_scale_up_first_service_prefix_state(
                    remaining_queue,
                    trial_slots,
                    trial_new_slot,
                    request_budget=request_budget,
                )
                if routed_trial_prefix:
                    seed_ordered_adapters = self._ordered_unique_adapter_ids(
                        routed_trial_prefix
                    )

                planned_adapters, exact_prefix_bytes = self._scale_up_exact_prefix_under_headroom(
                    seed_ordered_adapters,
                    headroom_bytes,
                )
                final_slots = [
                    self._copy_scale_up_routing_simulation_slot(slot)
                    for slot in simulated_slots
                ]
                final_new_slot = self._make_scale_up_routing_simulated_slot(
                    planned_adapters,
                    request_budget=request_budget,
                    instance_id=sim_instance_id,
                )
                final_slots.append(final_new_slot)
                scanned_traces, slice_traces, remaining_queue = (
                    self._route_aware_scale_up_first_service_prefix_state(
                        remaining_queue,
                        final_slots,
                        final_new_slot,
                        request_budget=request_budget,
                    )
                )
                if slice_traces:
                    ordered_handoff_adapters = self._ordered_unique_adapter_ids(
                        slice_traces
                    )
                    planned_adapters, exact_prefix_bytes = (
                        self._scale_up_exact_prefix_under_headroom(
                            ordered_handoff_adapters,
                            headroom_bytes,
                        )
                    )
                    final_new_slot.scaleup_handoff_planned_adapters = list(
                        planned_adapters
                    )
                    final_new_slot.scaleup_handoff_planned_adapter_ranks = {
                        adapter_id: idx
                        for idx, adapter_id in enumerate(planned_adapters)
                    }
                    for adapter_id in planned_adapters:
                        final_new_slot.mark_adapter_tier(adapter_id, "gpu")
                else:
                    ordered_handoff_adapters = []
                    planned_adapters = []
                    exact_prefix_bytes = 0
                simulated_slots = final_slots
            else:
                scanned_traces, slice_traces, remaining_queue = (
                    self._consume_scale_up_lora_service_prefix(
                        remaining_queue,
                        request_budget=request_budget,
                    )
                )
                ordered_handoff_adapters = self._ordered_unique_adapter_ids(slice_traces)
                if not ordered_handoff_adapters and not has_explicit_queue:
                    ordered_handoff_adapters = [
                        adapter_id
                        for adapter_id in global_ordered_adapters
                        if adapter_id not in consumed_adapters
                    ]
                if not ordered_handoff_adapters and runtime_idx == 0 and not has_explicit_queue:
                    ordered_handoff_adapters = [
                        str(adapter_id)
                        for adapter_id in list(plan.get("planned_adapters", []) or [])
                        if adapter_id
                    ]
                planned_adapters, exact_prefix_bytes = self._scale_up_exact_prefix_under_headroom(
                    ordered_handoff_adapters,
                    headroom_bytes,
                )

            if planned_adapters:
                consumed_adapters.update(str(adapter_id) for adapter_id in planned_adapters)
            plan_load_latency_ms = self._predicted_scale_up_load_ms(
                planned_adapters,
                max_concurrent_loads=max_concurrent_loads,
            )
            per_runtime_plans.append(
                {
                    "mode": str(plan.get("mode", "dynamic_headroom_exact_handoff_prefix") or ""),
                    "planned_adapters": planned_adapters,
                    "ordered_handoff_adapters": ordered_handoff_adapters,
                    "queue_at_ready_request_count": max(
                        0,
                        int(plan.get("queue_at_ready_request_count", len(queue_at_ready_traces)) or 0),
                    ),
                    "queue_at_ready_adapter_count": max(
                        0,
                        int(plan.get("queue_at_ready_adapter_count", len(global_ordered_adapters)) or 0),
                    ),
                    "first_service_request_count": len(slice_traces),
                    "first_service_adapter_count": len(
                        self._ordered_unique_adapter_ids(slice_traces)
                    ),
                    "first_service_scanned_request_count": len(scanned_traces),
                    "initial_admission_request_budget": max(
                        1,
                        int(plan.get("initial_admission_request_budget", 1) or 1),
                    ),
                    "projected_arrived_request_count": max(
                        0,
                        int(plan.get("projected_arrived_request_count", 0) or 0),
                    ),
                    "incumbent_started_request_count": max(
                        0,
                        int(plan.get("incumbent_started_request_count", 0) or 0),
                    ),
                    "bootstrap_latency_ms": bootstrap_latency_ms,
                    "plan_load_latency_ms": plan_load_latency_ms,
                    "ready_delay_ms": bootstrap_latency_ms + plan_load_latency_ms,
                    "exact_prefix_bytes": exact_prefix_bytes,
                    "target_headroom_bytes": headroom_bytes,
                    "configured_max_concurrent_loads": max_concurrent_loads,
                    "effective_initial_warmup_parallelism": max(
                        1,
                        int(plan.get("effective_initial_warmup_parallelism", 1) or 1),
                    ),
                    "_runtime_plan_index": runtime_idx,
                }
            )
        return per_runtime_plans

    def _scaleup_runtime_handoff_plan(
        self,
        instance_id: Optional[str],
    ) -> Dict[str, Any]:
        instance_key = str(instance_id or "")
        if instance_key:
            plans = getattr(self, "_scaleup_runtime_handoff_plans", {}) or {}
            plan = plans.get(instance_key)
            if isinstance(plan, dict) and plan:
                return dict(plan)
        return dict(getattr(self, "_last_scale_up_handoff_plan", {}) or {})

    def _scaleup_runtime_handoff_tail_adapters(
        self,
        instance_id: Optional[str],
        *,
        sibling_recent_hot_set: Collection[str],
    ) -> List[str]:
        handoff_plan = self._scaleup_runtime_handoff_plan(instance_id)
        ordered_handoff = [
            str(adapter_id)
            for adapter_id in list(handoff_plan.get("ordered_handoff_adapters", []) or [])
            if adapter_id
        ]
        if not ordered_handoff:
            return []
        planned = {
            str(adapter_id)
            for adapter_id in list(handoff_plan.get("planned_adapters", []) or [])
            if adapter_id
        }
        tail_budget = max(1, self._runtime_forward_capacity_limit())
        sibling_recent_hot = {str(adapter_id) for adapter_id in sibling_recent_hot_set if adapter_id}
        tail: List[str] = []
        for adapter_id in ordered_handoff:
            if adapter_id in planned or adapter_id not in sibling_recent_hot:
                continue
            tail.append(adapter_id)
            if len(tail) >= tail_budget:
                break
        return tail

    def _adapter_is_recently_active(self, adapter_id: str, *, now: Optional[float] = None) -> bool:
        """
        Return whether an adapter is still inside the online hotness window.

        Background runtime forwarding should only mirror adapters that are not
        just GPU-resident somewhere else, but are also part of the current live
        working set. Reuse the existing hotness tracker window instead of
        introducing a new forwarding-only heuristic.
        """
        stack = getattr(self, "_stack", None)
        if not adapter_id or stack is None:
            return False
        metadata_fn = getattr(stack, "_artifact_metadata", None)
        metadata = metadata_fn(adapter_id) if callable(metadata_fn) else None
        last_accessed_at = float(getattr(metadata, "last_accessed_at", 0.0) or 0.0)
        if last_accessed_at <= 0.0:
            return False
        tracker = getattr(self._stack, "hotness_tracker", None)
        try:
            window_s = float(
                getattr(
                    tracker,
                    "window_seconds",
                    getattr(self, "_online_hotness_window_s", 15.0),
                )
                or getattr(self, "_online_hotness_window_s", 15.0)
            )
        except Exception:
            window_s = float(getattr(self, "_online_hotness_window_s", 15.0) or 15.0)
        window_s = max(1.0, window_s)
        current_time = time.time() if now is None else float(now)
        return last_accessed_at >= current_time - window_s

    def _adapter_last_accessed_at(self, adapter_id: Optional[str]) -> float:
        stack = getattr(self, "_stack", None)
        if not adapter_id or stack is None:
            return 0.0
        metadata_fn = getattr(stack, "_artifact_metadata", None)
        metadata = metadata_fn(adapter_id) if callable(metadata_fn) else None
        return float(getattr(metadata, "last_accessed_at", 0.0) or 0.0)

    def _adapter_size_mb_for_forwarding(self, adapter_id: Optional[str]) -> float:
        if not adapter_id:
            return 0.0
        stack = getattr(self, "_stack", None)
        if stack is not None:
            size_fn = getattr(stack, "_artifact_size_mb", None)
            if callable(size_fn):
                try:
                    size_mb = float(size_fn(adapter_id) or 0.0)
                    if size_mb > 0.0:
                        return size_mb
                except Exception:
                    pass
            metadata_fn = getattr(stack, "_artifact_metadata", None)
            metadata = metadata_fn(adapter_id) if callable(metadata_fn) else None
            size_bytes = float(getattr(metadata, "size_bytes", 0.0) or 0.0)
            if size_bytes > 0.0:
                return size_bytes / (1024.0 * 1024.0)
        adapter_info = dict(getattr(self, "adapter_info", {}) or {})
        return float(adapter_info.get(str(adapter_id), {}).get("size_mb", 0.0) or 0.0)

    def _adapter_online_hotness(self, adapter_id: Optional[str]) -> float:
        stack = getattr(self, "_stack", None)
        if not adapter_id or stack is None:
            return 0.0
        hotness_fn = getattr(stack, "_online_artifact_hotness", None)
        if callable(hotness_fn):
            try:
                return max(0.0, float(hotness_fn(adapter_id) or 0.0))
            except Exception:
                pass
        return 0.0

    def _live_waiting_adapter_count(self, adapter_id: Optional[str]) -> int:
        if not adapter_id:
            return 0
        live_counts = dict(getattr(self, "_live_arrived_lora_counts", {}) or {})
        started_counts = dict(getattr(self, "_live_started_lora_counts", {}) or {})
        return max(
            0,
            int(live_counts.get(adapter_id, 0) or 0)
            - int(started_counts.get(adapter_id, 0) or 0),
        )

    def _slot_predicted_lora_io_ms(self, slot: Optional[Any], adapter_id: Optional[str]) -> float:
        if slot is None or not adapter_id:
            return 0.0
        size_mb = self._adapter_size_mb_for_forwarding(adapter_id)
        predictor = getattr(slot, "predicted_lora_io_ms", None)
        fallback_lora_io_ms = 0.0
        if not callable(predictor):
            fallback_lora_io_ms = Router._fallback_lora_io_cost_ms(slot, size_mb, adapter_id)
        if callable(predictor):
            try:
                return max(
                    0.0,
                    float(
                        predictor(
                            adapter_id=adapter_id,
                            fallback_lora_io_ms=fallback_lora_io_ms,
                        )
                        or 0.0
                    ),
                )
            except Exception:
                pass
        return max(0.0, float(fallback_lora_io_ms or 0.0))

    def _runtime_forward_adapter_observed_utility(
        self,
        slot: Optional[Any],
        adapter_id: Optional[str],
    ) -> float:
        if slot is None or not adapter_id:
            return 0.0
        size_mb = max(0.1, self._adapter_size_mb_for_forwarding(adapter_id))
        saved_lora_io_ms = self._slot_predicted_lora_io_ms(slot, adapter_id)
        if saved_lora_io_ms <= 0.0:
            return 0.0
        demand_signal = max(
            float(self._live_waiting_adapter_count(adapter_id)),
            self._adapter_online_hotness(adapter_id),
        )
        if demand_signal <= 0.0:
            return 0.0
        return float(demand_signal * saved_lora_io_ms / size_mb)

    def _rank_runtime_forward_adapters(
        self,
        slot: Optional[Any],
        adapter_ids: Collection[str],
    ) -> List[str]:
        unique: List[str] = []
        seen: set[str] = set()
        for adapter_id in adapter_ids:
            adapter_key = str(adapter_id or "")
            if not adapter_key or adapter_key in seen:
                continue
            seen.add(adapter_key)
            unique.append(adapter_key)

        return sorted(
            unique,
            key=lambda adapter_id: self._runtime_forward_adapter_observed_utility(
                slot, adapter_id
            ),
            reverse=True,
        )

    def _runtime_forward_preferred_gpu_adapters(self, slot: Optional[Any]) -> Optional[List[str]]:
        """
        Live sibling hotset for runtime-local background forwarding.

        In multi-runtime mode, opportunistic forward should mirror adapters that
        are most likely to be needed next on this runtime without expanding
        into a global queue-chasing policy. Keep each scale-out runtime anchored
        to its own exact handoff plan, then allow at most one extra lane-width
        of sibling-hot handoff tail before falling back to the live waiting
        queue signal.
        """
        instance_pool = getattr(self, "instance_pool", None)
        if instance_pool is None or slot is None:
            return None
        groups = instance_pool.get_runtime_groups()
        if len(groups) <= 1:
            return None
        slot_key = self._runtime_forward_task_key(slot)
        current_gpu = set(getattr(slot, "gpu_resident_adapters", set()) or set())
        preferred: List[str] = []
        seen: set = set()
        now = time.time()
        sibling_recent_hot: List[str] = []
        sibling_recent_hot_set: set[str] = set()

        def _append(adapter_id: Optional[str], *, require_recent: bool) -> None:
            if not adapter_id:
                return
            adapter_id = str(adapter_id)
            if adapter_id in seen or adapter_id in current_gpu:
                return
            if require_recent and not self._adapter_is_recently_active(adapter_id, now=now):
                return
            seen.add(adapter_id)
            preferred.append(adapter_id)

        for group in groups:
            group_key = self._runtime_forward_task_key(group[0]) if group else None
            if slot_key is not None and group_key == slot_key:
                continue
            for sibling in group:
                for adapter_id in getattr(sibling, "gpu_resident_adapters", set()):
                    adapter_id = str(adapter_id)
                    if adapter_id in sibling_recent_hot_set or adapter_id in current_gpu:
                        continue
                    if not self._adapter_is_recently_active(adapter_id, now=now):
                        continue
                    sibling_recent_hot_set.add(adapter_id)
                    sibling_recent_hot.append(adapter_id)

        instance_id = str(getattr(slot, "instance_id", "") or "")
        if instance_id and instance_id in getattr(self, "_scaleup_runtime_instance_ids", set()):
            handoff_plan = self._scaleup_runtime_handoff_plan(instance_id)
            planned_adapters = list(handoff_plan.get("planned_adapters", []) or [])
            if not planned_adapters:
                planned_adapters = list(
                    handoff_plan.get("ordered_handoff_adapters", []) or []
                )
            for adapter_id in planned_adapters:
                _append(adapter_id, require_recent=False)
            for adapter_id in self._scaleup_runtime_handoff_tail_adapters(
                instance_id,
                sibling_recent_hot_set=sibling_recent_hot_set,
            ):
                _append(adapter_id, require_recent=False)

        waiting_candidates: List[str] = []
        for trace in self._current_live_waiting_trace_queue():
            adapter_id = getattr(trace, "adapter_id", None)
            if adapter_id and str(adapter_id) in sibling_recent_hot_set:
                waiting_candidates.append(str(adapter_id))

        for adapter_id in self._rank_runtime_forward_adapters(slot, waiting_candidates):
            _append(adapter_id, require_recent=False)

        for adapter_id in self._rank_runtime_forward_adapters(slot, sibling_recent_hot):
            _append(adapter_id, require_recent=False)
        return preferred

    def _slot_should_include_gpu(self, slot: Optional[Any]) -> bool:
        if slot is None:
            return self._instance_mode == "shared"
        return self._instance_mode == "shared" or bool(getattr(slot, "owns_engine", False))

    def _autoscaler_gpu_signal(self) -> Optional[float]:
        values: List[float] = []
        if self.instance_pool is not None:
            for group in self.instance_pool.get_runtime_groups():
                group_util = max(float(getattr(slot, "gpu_utilization_pct", 0.0) or 0.0) for slot in group)
                if group_util > 0:
                    values.append(group_util)
        if self._stack is not None and getattr(self._stack, "gpu_monitor", None) is not None:
            device_ids: List[int] = []
            if self.instance_pool is not None:
                for slot in self.instance_pool.get_slots():
                    if getattr(slot, "device_id", None) is not None:
                        device_ids.append(int(slot.device_id))
            elif getattr(self.engine, "device_id", None) is not None:
                device_ids.append(int(self.engine.device_id))
            seen: List[int] = []
            for did in device_ids:
                if did not in seen:
                    seen.append(did)
            for did in seen:
                snap = self._gpu_runtime_snapshot(did)
                if not snap:
                    continue
                _, _, util = snap
                if util > 0:
                    values.append(util)
        if not values:
            return None
        return max(values)

    def _gpu_runtime_snapshot(self, device_id: int) -> Optional[Tuple[float, float, float]]:
        used_gb = total_gb = util_pct = 0.0
        if self._stack is not None and getattr(self._stack, "gpu_monitor", None) is not None:
            try:
                info = self._stack.gpu_monitor.get_current_memory_info(device_id)
            except Exception:
                info = None
            if info and getattr(info, "total_bytes", 0) > 0:
                used_gb = float(getattr(info, "used_bytes", 0) or 0) / (1024 ** 3)
                total_gb = float(getattr(info, "total_bytes", 0) or 0) / (1024 ** 3)
                util_pct = float(getattr(info, "utilization_percent", 0.0) or 0.0)
                if used_gb > 0.05 or util_pct > 0.0:
                    return used_gb, total_gb, util_pct
        try:
            import subprocess
            out = subprocess.check_output(
                [
                    "nvidia-smi",
                    "--query-gpu=memory.used,memory.total,utilization.gpu",
                    "--format=csv,noheader,nounits",
                    "-i",
                    str(device_id),
                ],
                text=True,
                stderr=subprocess.DEVNULL,
                timeout=2,
            ).strip()
            if out:
                used_mb, total_mb, util = [part.strip() for part in out.split(",", 2)]
                return float(used_mb) / 1024.0, float(total_mb) / 1024.0, float(util)
        except Exception:
            pass
        if total_gb > 0:
            return used_gb, total_gb, util_pct
        return None

    def _scale_up_target_runtime_headroom_mb(self) -> float:
        hw = dict(getattr(self, "hw", {}) or {})
        hw.update(dict(getattr(self, "coord_cfg", {}) or {}))

        model_cfg = dict(getattr(self, "model_cfg", {}) or {})
        device_id = getattr(getattr(self, "engine", None), "device_id", None)
        runtime_gpu_device_ids = _resolve_runtime_gpu_device_ids(model_cfg, device_id=device_id)
        if runtime_gpu_device_ids:
            hw["gpu_device_ids"] = runtime_gpu_device_ids

        raw_gpu_ids = hw.get("gpu_device_ids", []) or []
        gpu_device_ids: List[int] = []
        for raw_id in raw_gpu_ids:
            try:
                did = int(raw_id)
            except (TypeError, ValueError):
                continue
            if did not in gpu_device_ids:
                gpu_device_ids.append(did)

        try:
            gpu_budget_per_device_mb = float(hw.get("gpu_budget_mb", 24000) or 24000.0)
        except (TypeError, ValueError):
            gpu_budget_per_device_mb = 24000.0
        total_budget_override = hw.get("gpu_budget_total_mb")
        if total_budget_override is not None:
            try:
                total_budget_mb = float(total_budget_override)
            except (TypeError, ValueError):
                total_budget_mb = gpu_budget_per_device_mb * max(1, len(gpu_device_ids) or 1)
        else:
            total_budget_mb = gpu_budget_per_device_mb * max(1, len(gpu_device_ids) or 1)

        try:
            model_weights_mb = float(hw.get("model_weights_mb", 0.0) or 0.0)
        except (TypeError, ValueError):
            model_weights_mb = 0.0
        try:
            reserve_ratio = float(hw.get("lora_load_reserve_ratio", 0.15) or 0.15)
        except (TypeError, ValueError):
            reserve_ratio = 0.15

        predicted_kv_growth_mb = 0.0
        predicted_kv_fn = getattr(getattr(self, "coordinator", None), "_predicted_kv_growth_mb", None)
        if callable(predicted_kv_fn):
            try:
                predicted_kv_growth_mb = max(0.0, float(predicted_kv_fn()) or 0.0)
            except Exception:
                predicted_kv_growth_mb = 0.0

        reserve_mb = max(total_budget_mb * reserve_ratio, predicted_kv_growth_mb)
        return max(0.0, total_budget_mb - model_weights_mb - reserve_mb)

    def _scale_up_live_hotset_bytes(self, preferred_gpu_adapters: Optional[set] = None) -> int:
        stack = getattr(self, "_stack", None)
        if stack is None:
            return 0
        preferred = set(preferred_gpu_adapters or set())
        if not preferred:
            return 0

        sync_paths = getattr(stack, "sync_local_tier_paths", None)
        if callable(sync_paths):
            try:
                sync_paths()
            except Exception:
                pass

        host_paths = dict(getattr(stack, "_host_paths", {}) or {})
        nvme_paths = dict(getattr(stack, "_nvme_paths", {}) or {})
        size_fn = getattr(stack, "_artifact_size_mb", None)
        total_bytes = 0
        for adapter_id in preferred:
            if adapter_id not in host_paths and adapter_id not in nvme_paths:
                continue
            try:
                size_mb = float(size_fn(adapter_id)) if callable(size_fn) else float(
                    (getattr(self, "adapter_info", {}) or {}).get(adapter_id, {}).get("size_mb", 0.0) or 0.0
                )
            except Exception:
                size_mb = 0.0
            if size_mb <= 0.0:
                continue
            total_bytes += int(size_mb * 1024.0 * 1024.0)
        return total_bytes

    def _scale_up_preload_budget_snapshot(
        self,
        preferred_gpu_adapters: Optional[Collection[str]] = None,
    ) -> Dict[str, Any]:
        preferred_order: List[str] = []
        seen_preferred: set = set()
        for adapter_id in preferred_gpu_adapters or []:
            if not adapter_id or adapter_id in seen_preferred:
                continue
            seen_preferred.add(adapter_id)
            preferred_order.append(adapter_id)
        dynamic_enabled = bool(self.preload_cfg.get("scale_up_dynamic_budget_enabled", True))
        if dynamic_enabled:
            target_headroom_mb = self._scale_up_target_runtime_headroom_mb()
            target_headroom_bytes = max(0, int(target_headroom_mb * 1024.0 * 1024.0))
            live_hotset_bytes = self._scale_up_live_hotset_bytes(set(preferred_order))
            handoff_plan = dict(getattr(self, "_last_scale_up_handoff_plan", {}) or {})
            planned_adapters = list(handoff_plan.get("planned_adapters", []) or [])
            exact_prefix_bytes = 0
            mode = "dynamic_headroom_preferred_prefix"
            snapshot: Dict[str, Any] = {}
            if (
                planned_adapters
                and preferred_order
                and planned_adapters == preferred_order
                and str(handoff_plan.get("mode", "")) == "dynamic_headroom_exact_handoff_prefix"
            ):
                exact_prefix_bytes = max(0, int(handoff_plan.get("exact_prefix_bytes", 0) or 0))
                mode = "dynamic_headroom_exact_handoff_prefix"
                snapshot.update(
                    {
                        "queue_at_ready_request_count": int(
                            handoff_plan.get("queue_at_ready_request_count", 0) or 0
                        ),
                        "queue_at_ready_adapter_count": int(
                            handoff_plan.get("queue_at_ready_adapter_count", 0) or 0
                        ),
                        "first_service_request_count": int(
                            handoff_plan.get("first_service_request_count", 0) or 0
                        ),
                        "first_service_adapter_count": int(
                            handoff_plan.get("first_service_adapter_count", 0) or 0
                        ),
                        "initial_admission_request_budget": int(
                            handoff_plan.get("initial_admission_request_budget", 1) or 1
                        ),
                        "projected_arrived_request_count": int(
                            handoff_plan.get("projected_arrived_request_count", 0) or 0
                        ),
                        "incumbent_started_request_count": int(
                            handoff_plan.get("incumbent_started_request_count", 0) or 0
                        ),
                        "bootstrap_latency_ms": float(
                            handoff_plan.get("bootstrap_latency_ms", 0.0) or 0.0
                        ),
                        "plan_load_latency_ms": float(
                            handoff_plan.get("plan_load_latency_ms", 0.0) or 0.0
                        ),
                        "ready_delay_ms": float(
                            handoff_plan.get("ready_delay_ms", 0.0) or 0.0
                        ),
                        "configured_max_concurrent_loads": int(
                            handoff_plan.get("configured_max_concurrent_loads", 1) or 1
                        ),
                    }
                )
            elif preferred_order and target_headroom_bytes > 0:
                _, exact_prefix_bytes = self._scale_up_exact_prefix_under_headroom(
                    preferred_order,
                    target_headroom_bytes,
                )

            if exact_prefix_bytes > 0 and target_headroom_bytes > 0:
                capacity_bytes = min(exact_prefix_bytes, target_headroom_bytes)
                return {
                    "mode": mode,
                    "capacity_bytes": max(0, int(capacity_bytes)),
                    "live_hotset_bytes": live_hotset_bytes,
                    "exact_prefix_bytes": max(0, int(exact_prefix_bytes)),
                    "recent_working_set_bytes": 0,
                    "target_headroom_bytes": target_headroom_bytes,
                    **snapshot,
                }

        explicit_mb = self.preload_cfg.get("scale_up_preload_mb")
        if explicit_mb is not None:
            return {
                "mode": "legacy_explicit_mb",
                "capacity_bytes": max(64 * 1024 * 1024, int(float(explicit_mb) * 1024 * 1024)),
                "live_hotset_bytes": 0,
                "recent_working_set_bytes": 0,
                "target_headroom_bytes": 0,
            }
        host_capacity_mb = float(self.preload_cfg.get("host_capacity_mb", 4096) or 4096.0)
        derived_mb = max(200.0, min(1024.0, host_capacity_mb * 0.25))
        return {
            "mode": "legacy_host_fraction",
            "capacity_bytes": int(derived_mb * 1024 * 1024),
            "live_hotset_bytes": 0,
            "recent_working_set_bytes": 0,
            "target_headroom_bytes": 0,
        }

    def _scale_up_preload_capacity_bytes(self, preferred_gpu_adapters: Optional[Collection[str]] = None) -> int:
        snapshot = self._scale_up_preload_budget_snapshot(preferred_gpu_adapters)
        self._last_scale_up_preload_budget = dict(snapshot)
        return max(0, int(snapshot.get("capacity_bytes", 0) or 0))

    @staticmethod
    def _live_percentile(values: List[float], p: float) -> float:
        if not values:
            return 0.0
        ordered = sorted(float(v) for v in values)
        if len(ordered) == 1:
            return ordered[0]
        rank = max(0.0, min(1.0, float(p) / 100.0)) * (len(ordered) - 1)
        lo = int(math.floor(rank))
        hi = int(math.ceil(rank))
        if lo == hi:
            return ordered[lo]
        frac = rank - lo
        return ordered[lo] + (ordered[hi] - ordered[lo]) * frac

    def _live_result_stats(self, results_view: Optional[List[Any]], elapsed_sec: float = 1.0) -> Dict[str, Any]:
        if not results_view:
            return {}
        ok = [
            item for item in results_view
            if not isinstance(item, Exception) and getattr(item, "success", False)
        ]
        failed = [
            item for item in results_view
            if isinstance(item, Exception) or not getattr(item, "success", True)
        ]
        stats: Dict[str, Any] = {
            "success": len(ok),
            "failed": len(failed),
        }
        if ok:
            lora_ok = [item for item in ok if _has_lora_request(item)]
            ttft = [_request_overall_ttft_ms(item) for item in ok]
            service_ttft = [_request_service_ttft_ms(item) for item in ok]
            e2e = [_request_overall_e2e_ms(item) for item in ok]
            service_e2e = [_request_service_e2e_ms(item) for item in ok]
            tpot = [
                float(getattr(item, "tpot_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "tpot_ms", 0.0) or 0.0) > 0
                and bool(getattr(item, "tpot_observed", True))
            ]
            tpot_eligible = [
                item for item in ok
                if int(getattr(item, "output_tokens", 0) or 0) > 1
            ]
            in_tokens = [int(getattr(item, "input_tokens", 0) or 0) for item in ok]
            out_tokens = [int(getattr(item, "output_tokens", 0) or 0) for item in ok]
            service_overheads = [
                float(getattr(item, "lora_io_ms", 0.0) or 0.0)
                + float(getattr(item, "contention_ms", 0.0) or 0.0)
                + float(getattr(item, "defer_ms", 0.0) or 0.0)
                for item in ok
            ]
            dispatch_waits = [
                float(getattr(item, "dispatch_admission_wait_ms", 0.0) or 0.0)
                for item in ok
            ]
            dispatch_window_waits = [
                float(getattr(item, "dispatch_window_wait_ms", 0.0) or 0.0)
                for item in ok
            ]
            runtime_slot_waits = [
                float(getattr(item, "runtime_slot_wait_ms", 0.0) or 0.0)
                for item in ok
            ]
            arrival_release_lateness = [
                float(getattr(item, "arrival_release_lateness_ms", 0.0) or 0.0)
                for item in ok
            ]
            overheads = [
                dispatch_wait + service_overhead
                for dispatch_wait, service_overhead in zip(dispatch_waits, service_overheads)
            ]
            runtime_ttft = [
                float(getattr(item, "vllm_ttft_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "vllm_ttft_ms", 0.0) or 0.0) > 0.0
            ]
            runtime_estimated_e2e = [
                float(getattr(item, "runtime_estimated_e2e_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "runtime_estimated_e2e_ms", 0.0) or 0.0) > 0.0
            ]
            worker_wall_e2e = [
                float(getattr(item, "worker_wall_e2e_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "worker_wall_e2e_ms", 0.0) or 0.0) > 0.0
            ]
            worker_rpc_handler_wall = [
                float(getattr(item, "worker_rpc_handler_wall_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "worker_rpc_handler_wall_ms", 0.0) or 0.0) > 0.0
            ]
            worker_engine_shell = [
                float(getattr(item, "worker_engine_shell_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "worker_engine_shell_ms", 0.0) or 0.0) >= 0.0
            ]
            worker_rpc_queue = [
                float(getattr(item, "worker_rpc_queue_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "worker_rpc_queue_ms", 0.0) or 0.0) >= 0.0
            ]
            parent_rpc_overhead = [
                float(getattr(item, "parent_rpc_overhead_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "parent_rpc_overhead_ms", 0.0) or 0.0) >= 0.0
            ]
            parent_rpc_channel_acquire = [
                float(getattr(item, "parent_rpc_channel_acquire_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "parent_rpc_channel_acquire_ms", 0.0) or 0.0) >= 0.0
            ]
            parent_rpc_response_pickup = [
                float(getattr(item, "parent_rpc_response_pickup_delay_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "parent_rpc_response_pickup_delay_ms", 0.0) or 0.0) >= 0.0
            ]
            parent_rpc_thread_resume = [
                float(getattr(item, "parent_rpc_thread_resume_delay_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "parent_rpc_thread_resume_delay_ms", 0.0) or 0.0) >= 0.0
            ]
            service_path_residual = [
                float(getattr(item, "service_path_residual_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "service_path_residual_ms", 0.0) or 0.0) >= 0.0
            ]
            pre_runtime_service_shell = [
                float(getattr(item, "pre_runtime_service_shell_ms", 0.0) or 0.0)
                for item in ok
                if float(getattr(item, "pre_runtime_service_shell_ms", 0.0) or 0.0) >= 0.0
            ]
            gpu_ready_ttft = [
                _request_overall_ttft_ms(item)
                for item in ok
                if getattr(item, "cache_tier", "remote") == "gpu"
            ]
            comparable = [
                _request_overall_ttft_ms(item)
                for item in results_view
                if not isinstance(item, Exception)
                and _is_comparable_request(item)
            ]
            warm_standard = [
                _request_overall_ttft_ms(item)
                for item in results_view
                if not isinstance(item, Exception)
                and _is_warm_standard_request(item)
            ]
            scaleup_ttft = [
                _request_overall_ttft_ms(item)
                for item in ok
                if bool(getattr(item, "scaleup_affected", False))
            ]
            scaleup_runtime_lora = [
                item for item in ok
                if bool(getattr(item, "on_scaleup_runtime", False))
                and _has_lora_request(item)
            ]
            scaleup_runtime_ttft = [
                _request_overall_ttft_ms(item)
                for item in scaleup_runtime_lora
            ]
            scaleup_first_service = [
                item for item in ok
                if bool(getattr(item, "scaleup_first_service", False))
            ]
            scaleup_first_service_ttft = [
                _request_overall_ttft_ms(item)
                for item in scaleup_first_service
            ]
            avg_cost_usd = (
                sum(float(getattr(item, "cost_usd", 0.0) or 0.0) for item in ok) / len(ok)
            )
            total_cost_usd = sum(float(getattr(item, "cost_usd", 0.0) or 0.0) for item in ok)
            total_input_tokens = sum(in_tokens)
            total_output_tokens = sum(out_tokens)
            total_tokens = total_input_tokens + total_output_tokens
            observed_cold_starts = list(
                getattr(self, "_observed_scale_up_cold_start_latencies_ms", []) or []
            )
            stats.update({
                "avg_ttft_ms": sum(ttft) / len(ttft),
                "p95_ttft_ms": self._live_percentile(ttft, 95),
                "p99_ttft_ms": self._live_percentile(ttft, 99),
                "avg_service_ttft_ms": sum(service_ttft) / len(service_ttft),
                "p95_service_ttft_ms": self._live_percentile(service_ttft, 95),
                "p99_service_ttft_ms": self._live_percentile(service_ttft, 99),
                "avg_admitted_service_ttft_ms": (
                    sum(float(getattr(item, "admitted_service_ttft_ms", 0.0) or 0.0) for item in ok) / len(ok)
                ) if ok else 0.0,
                "p95_admitted_service_ttft_ms": self._live_percentile(
                    [float(getattr(item, "admitted_service_ttft_ms", 0.0) or 0.0) for item in ok], 95
                ) if ok else 0.0,
                "p99_admitted_service_ttft_ms": self._live_percentile(
                    [float(getattr(item, "admitted_service_ttft_ms", 0.0) or 0.0) for item in ok], 99
                ) if ok else 0.0,
                "avg_e2e_ms": sum(e2e) / len(e2e),
                "p95_e2e_ms": self._live_percentile(e2e, 95),
                "p99_e2e_ms": self._live_percentile(e2e, 99),
                "avg_service_e2e_ms": sum(service_e2e) / len(service_e2e),
                "p95_service_e2e_ms": self._live_percentile(service_e2e, 95),
                "p99_service_e2e_ms": self._live_percentile(service_e2e, 99),
                "avg_admitted_service_e2e_ms": (
                    sum(float(getattr(item, "admitted_service_e2e_ms", 0.0) or 0.0) for item in ok) / len(ok)
                ) if ok else 0.0,
                "p95_admitted_service_e2e_ms": self._live_percentile(
                    [float(getattr(item, "admitted_service_e2e_ms", 0.0) or 0.0) for item in ok], 95
                ) if ok else 0.0,
                "p99_admitted_service_e2e_ms": self._live_percentile(
                    [float(getattr(item, "admitted_service_e2e_ms", 0.0) or 0.0) for item in ok], 99
                ) if ok else 0.0,
                "avg_tpot_ms": (sum(tpot) / len(tpot)) if tpot else 0.0,
                "cache_hit_ratio": (
                    sum(1 for item in lora_ok if getattr(item, "cache_hit", False)) / len(lora_ok)
                ) if lora_ok else 0.0,
                "total_input_tokens": total_input_tokens,
                "total_output_tokens": total_output_tokens,
                "total_tokens": total_tokens,
                "avg_cost_usd": avg_cost_usd,
                "token_proxy_total_cost_usd": total_cost_usd,
                "token_proxy_avg_cost_usd": avg_cost_usd,
                "token_proxy_cost_per_1m_total_tokens_usd": _cost_per_million_tokens(
                    total_cost_usd,
                    total_tokens,
                ),
                "token_proxy_cost_per_1m_output_tokens_usd": _cost_per_million_tokens(
                    total_cost_usd,
                    total_output_tokens,
                ),
                "slo_attainment": (
                    sum(1 for item in ok if _request_overall_ttft_ms(item) <= self._ttft_slo_ms)
                    / len(ok)
                ),
                "avg_comparable_ttft_ms": (sum(comparable) / len(comparable)) if comparable else 0.0,
                "p95_comparable_ttft_ms": self._live_percentile(comparable, 95),
                "p99_comparable_ttft_ms": self._live_percentile(comparable, 99),
                "avg_warm_standard_ttft_ms": (sum(warm_standard) / len(warm_standard)) if warm_standard else 0.0,
                "p95_warm_standard_ttft_ms": self._live_percentile(warm_standard, 95),
                "p99_warm_standard_ttft_ms": self._live_percentile(warm_standard, 99),
                "avg_serverless_overhead_ms": sum(overheads) / len(overheads) if overheads else 0.0,
                "p95_serverless_overhead_ms": self._live_percentile(overheads, 95) if overheads else 0.0,
                "avg_service_overhead_ms": sum(service_overheads) / len(service_overheads) if service_overheads else 0.0,
                "p95_service_overhead_ms": self._live_percentile(service_overheads, 95) if service_overheads else 0.0,
                "avg_dispatch_admission_wait_ms": sum(dispatch_waits) / len(dispatch_waits) if dispatch_waits else 0.0,
                "p95_dispatch_admission_wait_ms": self._live_percentile(dispatch_waits, 95) if dispatch_waits else 0.0,
                "avg_dispatch_window_wait_ms": (
                    sum(dispatch_window_waits) / len(dispatch_window_waits)
                ) if dispatch_window_waits else 0.0,
                "p95_dispatch_window_wait_ms": self._live_percentile(
                    dispatch_window_waits, 95
                ) if dispatch_window_waits else 0.0,
                "avg_runtime_slot_wait_ms": (
                    sum(runtime_slot_waits) / len(runtime_slot_waits)
                ) if runtime_slot_waits else 0.0,
                "p95_runtime_slot_wait_ms": self._live_percentile(
                    runtime_slot_waits, 95
                ) if runtime_slot_waits else 0.0,
                "avg_ingress_queue_wait_ms": (
                    sum(float(getattr(item, "ingress_queue_wait_ms", 0.0) or 0.0) for item in ok) / len(ok)
                ) if ok else 0.0,
                "avg_arrival_release_lateness_ms": (
                    sum(arrival_release_lateness) / len(arrival_release_lateness)
                ) if arrival_release_lateness else 0.0,
                "p95_ingress_queue_wait_ms": self._live_percentile(
                    [float(getattr(item, "ingress_queue_wait_ms", 0.0) or 0.0) for item in ok], 95
                ) if ok else 0.0,
                "p95_arrival_release_lateness_ms": self._live_percentile(
                    arrival_release_lateness, 95
                ) if arrival_release_lateness else 0.0,
                "avg_runtime_ttft_ms": (sum(runtime_ttft) / len(runtime_ttft)) if runtime_ttft else 0.0,
                "p95_runtime_ttft_ms": self._live_percentile(runtime_ttft, 95) if runtime_ttft else 0.0,
                "avg_runtime_estimated_e2e_ms": (
                    sum(runtime_estimated_e2e) / len(runtime_estimated_e2e)
                ) if runtime_estimated_e2e else 0.0,
                "p95_runtime_estimated_e2e_ms": (
                    self._live_percentile(runtime_estimated_e2e, 95)
                    if runtime_estimated_e2e else 0.0
                ),
                "avg_worker_wall_e2e_ms": (
                    sum(worker_wall_e2e) / len(worker_wall_e2e)
                ) if worker_wall_e2e else 0.0,
                "p95_worker_wall_e2e_ms": (
                    self._live_percentile(worker_wall_e2e, 95)
                    if worker_wall_e2e else 0.0
                ),
                "avg_worker_rpc_handler_wall_ms": (
                    sum(worker_rpc_handler_wall) / len(worker_rpc_handler_wall)
                ) if worker_rpc_handler_wall else 0.0,
                "p95_worker_rpc_handler_wall_ms": (
                    self._live_percentile(worker_rpc_handler_wall, 95)
                    if worker_rpc_handler_wall else 0.0
                ),
                "avg_worker_engine_shell_ms": (
                    sum(worker_engine_shell) / len(worker_engine_shell)
                ) if worker_engine_shell else 0.0,
                "p95_worker_engine_shell_ms": (
                    self._live_percentile(worker_engine_shell, 95)
                    if worker_engine_shell else 0.0
                ),
                "avg_worker_rpc_queue_ms": (
                    sum(worker_rpc_queue) / len(worker_rpc_queue)
                ) if worker_rpc_queue else 0.0,
                "p95_worker_rpc_queue_ms": (
                    self._live_percentile(worker_rpc_queue, 95)
                    if worker_rpc_queue else 0.0
                ),
                "avg_parent_rpc_overhead_ms": (
                    sum(parent_rpc_overhead) / len(parent_rpc_overhead)
                ) if parent_rpc_overhead else 0.0,
                "p95_parent_rpc_overhead_ms": (
                    self._live_percentile(parent_rpc_overhead, 95)
                    if parent_rpc_overhead else 0.0
                ),
                "avg_parent_rpc_channel_acquire_ms": (
                    sum(parent_rpc_channel_acquire) / len(parent_rpc_channel_acquire)
                ) if parent_rpc_channel_acquire else 0.0,
                "p95_parent_rpc_channel_acquire_ms": (
                    self._live_percentile(parent_rpc_channel_acquire, 95)
                    if parent_rpc_channel_acquire else 0.0
                ),
                "avg_parent_rpc_response_pickup_delay_ms": (
                    sum(parent_rpc_response_pickup) / len(parent_rpc_response_pickup)
                ) if parent_rpc_response_pickup else 0.0,
                "p95_parent_rpc_response_pickup_delay_ms": (
                    self._live_percentile(parent_rpc_response_pickup, 95)
                    if parent_rpc_response_pickup else 0.0
                ),
                "avg_parent_rpc_thread_resume_delay_ms": (
                    sum(parent_rpc_thread_resume) / len(parent_rpc_thread_resume)
                ) if parent_rpc_thread_resume else 0.0,
                "p95_parent_rpc_thread_resume_delay_ms": (
                    self._live_percentile(parent_rpc_thread_resume, 95)
                    if parent_rpc_thread_resume else 0.0
                ),
                "avg_service_path_residual_ms": (
                    sum(service_path_residual) / len(service_path_residual)
                ) if service_path_residual else 0.0,
                "p95_service_path_residual_ms": (
                    self._live_percentile(service_path_residual, 95)
                    if service_path_residual else 0.0
                ),
                "avg_pre_runtime_service_shell_ms": (
                    sum(pre_runtime_service_shell) / len(pre_runtime_service_shell)
                ) if pre_runtime_service_shell else 0.0,
                "p95_pre_runtime_service_shell_ms": (
                    self._live_percentile(pre_runtime_service_shell, 95)
                    if pre_runtime_service_shell else 0.0
                ),
                "avg_gpu_ready_ttft_ms": (sum(gpu_ready_ttft) / len(gpu_ready_ttft)) if gpu_ready_ttft else 0.0,
                "avg_scaleup_affected_ttft_ms": (sum(scaleup_ttft) / len(scaleup_ttft)) if scaleup_ttft else 0.0,
                "avg_scaleup_runtime_ttft_ms": (sum(scaleup_runtime_ttft) / len(scaleup_runtime_ttft)) if scaleup_runtime_ttft else 0.0,
                "p95_scaleup_runtime_ttft_ms": self._live_percentile(scaleup_runtime_ttft, 95) if scaleup_runtime_ttft else 0.0,
                "scaleup_runtime_lora_request_count": len(scaleup_runtime_lora),
                "scaleup_runtime_gpu_hit_rate": (
                    sum(1 for item in scaleup_runtime_lora if str(getattr(item, "cache_tier", "") or "").lower() == "gpu")
                    / len(scaleup_runtime_lora)
                ) if scaleup_runtime_lora else 0.0,
                "avg_scaleup_first_service_ttft_ms": (sum(scaleup_first_service_ttft) / len(scaleup_first_service_ttft)) if scaleup_first_service_ttft else 0.0,
                "scaleup_first_service_request_count": len(scaleup_first_service),
                "scaleup_first_service_gpu_hit_rate": (
                    sum(1 for item in scaleup_first_service if str(getattr(item, "cache_tier", "") or "").lower() == "gpu")
                    / len(scaleup_first_service)
                ) if scaleup_first_service else 0.0,
                "scaleup_first_service_planned_match_rate": (
                    sum(1 for item in scaleup_first_service if bool(getattr(item, "scaleup_planned_adapter_match", False)))
                    / len(scaleup_first_service)
                ) if scaleup_first_service else 0.0,
                "avg_cold_start_latency_ms": (
                    sum(observed_cold_starts) / len(observed_cold_starts)
                    if observed_cold_starts else 0.0
                ),
                "p95_cold_start_latency_ms": (
                    self._live_percentile(observed_cold_starts, 95)
                    if observed_cold_starts else 0.0
                ),
                "tpot_observed_request_ratio": (
                    len(tpot) / len(tpot_eligible)
                ) if tpot_eligible else 0.0,
            })
            avg_ttft_s = float(stats["avg_ttft_ms"]) / 1000.0
            legacy_denom = avg_cost_usd * avg_ttft_s
            stats["qpr_tokps_ttft_legacy"] = (
                float(stats["total_output_tokens"]) / max(elapsed_sec, 1e-6) / legacy_denom
                if legacy_denom > 1e-12 else 0.0
            )
            stats["qpr_rps_legacy"] = (
                float(stats["success"]) / max(elapsed_sec, 1e-6) / legacy_denom
                if legacy_denom > 1e-12 else 0.0
            )
            avg_e2e_s = float(stats["avg_e2e_ms"]) / 1000.0
            denom = avg_cost_usd * avg_e2e_s
            stats["cost_effectiveness_e2e"] = 1.0 / denom if denom > 1e-12 else 0.0
            stats["ce"] = stats["cost_effectiveness_e2e"]
            stats["token_proxy_ce"] = stats["cost_effectiveness_e2e"]
        if failed:
            reasons: Dict[str, int] = {}
            for item in failed:
                if isinstance(item, Exception):
                    reason = type(item).__name__
                else:
                    reason = str(getattr(item, "error", "") or "unknown_error")
                reason = reason.strip().split("\n", 1)[0][:48]
                reasons[reason] = reasons.get(reason, 0) + 1
            stats["failure_reasons"] = sorted(reasons.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
        return stats

    def _emit_live_snapshot(
        self,
        *,
        completed: int,
        total: int,
        replay_t0: float,
        failed: int = 0,
        phase_label: Optional[str] = None,
        force: bool = False,
        backlog_override: Optional[int] = None,
        active_override: Optional[int] = None,
        busy_override: Optional[float] = None,
        queue_visible_override: Optional[int] = None,
        arrived_override: Optional[int] = None,
        submitted_override: Optional[int] = None,
        results_view: Optional[List[Any]] = None,
        scale_up_count: Optional[int] = None,
        scale_down_count: Optional[int] = None,
    ) -> None:
        if not self._live_progress:
            return
        now = time.perf_counter()
        if not force:
            enough_time = (now - self._live_last_print_time) >= self._live_progress_interval_s
            enough_progress = (completed - self._live_last_print_completed) >= self._live_progress_every_requests
            if not (enough_time or enough_progress):
                return
        self._assert_clean_gpu_environment(context="live_progress", force=force)
        elapsed = max(0.0, now - self._run_started_at) if self._run_started_at > 0 else 0.0
        eta = 0.0
        if completed > 0 and total > completed:
            eta = elapsed * (total - completed) / max(1, completed)
        done_rps = completed / max(elapsed, 1e-6) if elapsed > 0 else 0.0
        arrival_rps = self._arrival_rps(replay_t0)
        arrived = (
            arrived_override
            if arrived_override is not None
            else queue_visible_override
            if queue_visible_override is not None
            else submitted_override
            if submitted_override is not None
            else self._arrived_request_count(replay_t0)
        )
        queue_visible = (
            queue_visible_override
            if queue_visible_override is not None
            else arrived_override
            if arrived_override is not None
            else submitted_override
            if submitted_override is not None
            else self._arrived_request_count(replay_t0)
        )
        backlog = backlog_override if backlog_override is not None else self._backlog_depth(completed, replay_t0)
        active = active_override if active_override is not None else self._active_request_count()
        busy = busy_override if busy_override is not None else self._busy_instance_ratio()
        instances = self.instance_pool.count() if self.instance_pool is not None else 1
        runtime_groups = len(self.instance_pool.get_runtime_groups()) if self.instance_pool is not None else 1
        cache_counts = self._adapter_cache_counts()
        success = max(0, completed - failed)
        stats = self._live_result_stats(results_view, elapsed)
        if stats:
            success = int(stats.get("success", success))
            failed = int(stats.get("failed", failed))
        prefix = f"    [Live {phase_label}] " if phase_label else "    [Live] "
        print(
            prefix
            + f"{self._render_progress_bar(completed, total)} "
            + f"mode={self._instance_mode} adapters={len(self.adapter_info)} "
            + f"arrived={arrived}/{total} done={completed} ok={success} fail={failed} "
            + f"elapsed={self._format_eta(elapsed)} "
            + f"eta={self._format_eta(eta)} "
            + f"arr={arrival_rps:.2f}/s done={done_rps:.2f}/s "
            + f"backlog={max(0, backlog)} queue_visible={max(0, int(queue_visible or 0))} "
            + f"active={max(0, active)} busy={busy:.2f} "
            + f"inst={instances} runtimes={runtime_groups}",
            flush=True,
        )
        print(
            "      "
            f"shared_slots={cache_counts.get('shared_slots', 0)} "
            f"dedicated_instances={cache_counts.get('dedicated_instances', 0)} "
            f"loaded[g/h/n]={cache_counts.get('gpu', 0)}/{cache_counts.get('host', 0)}/{cache_counts.get('nvme', 0)} "
            f"gpu_replica_sum={cache_counts.get('gpu_replica_sum', cache_counts.get('gpu', 0))} "
            f"scale_up={scale_up_count if scale_up_count is not None else 0} "
            f"scale_down={scale_down_count if scale_down_count is not None else 0}",
            flush=True,
        )
        if stats:
            tokps = float(stats.get("total_output_tokens", 0) or 0.0) / max(elapsed, 1e-6)
            live_rps = success / max(elapsed, 1e-6)
            live_slo_goodput_rps = live_rps * float(stats.get("slo_attainment", 0.0) or 0.0)
            live_slo_goodput_tokps = tokps * float(stats.get("slo_attainment", 0.0) or 0.0)
            live_avg_ttft_s = float(stats.get("avg_ttft_ms", 0.0) or 0.0) / 1000.0
            live_token_proxy_avg_cost_usd = float(
                stats.get("token_proxy_avg_cost_usd", stats.get("avg_cost_usd", 0.0)) or 0.0
            )
            live_qpr_denom = live_token_proxy_avg_cost_usd * live_avg_ttft_s
            live_qpr_legacy = tokps / live_qpr_denom if live_qpr_denom > 1e-12 else 0.0
            live_token_proxy_ce = float(
                stats.get("token_proxy_ce", stats.get("ce", stats.get("cost_effectiveness_e2e", 0.0))) or 0.0
            )
            print(
                "      "
                f"ttft_e2e(avg/p95/p99)={stats.get('avg_ttft_ms', 0.0):.0f}/{stats.get('p95_ttft_ms', 0.0):.0f}/{stats.get('p99_ttft_ms', 0.0):.0f}ms "
                f"ttft_service(avg/p95/p99)={stats.get('avg_service_ttft_ms', 0.0):.0f}/{stats.get('p95_service_ttft_ms', 0.0):.0f}/{stats.get('p99_service_ttft_ms', 0.0):.0f}ms "
                f"tpot={stats.get('avg_tpot_ms', 0.0):.1f}ms "
                f"e2e_e2e(avg/p95/p99)={stats.get('avg_e2e_ms', 0.0):.0f}/{stats.get('p95_e2e_ms', 0.0):.0f}/{stats.get('p99_e2e_ms', 0.0):.0f}ms",
                flush=True,
            )
            print(
                "      "
                f"tok/s={tokps:.2f} "
                f"tokenproxy/req=${live_token_proxy_avg_cost_usd:.6f} "
                f"tokenproxy/1MTok=${float(stats.get('token_proxy_cost_per_1m_total_tokens_usd', 0.0) or 0.0):.2f} "
                f"tokenproxy_ce={live_token_proxy_ce:.3f} "
                f"qpr_legacy={live_qpr_legacy:.1f} "
                f"cold_start(avg/p95)={stats.get('avg_cold_start_latency_ms', 0.0):.0f}/{stats.get('p95_cold_start_latency_ms', 0.0):.0f}ms",
                flush=True,
            )
            print(
                "      "
                f"req/s={done_rps:.2f} tok/s={tokps:.2f} "
                f"slo@{self._ttft_slo_ms:.0f}ms={stats.get('slo_attainment', 0.0):.0%} "
                f"slo_goodput={live_slo_goodput_rps:.2f}rps/{live_slo_goodput_tokps:.2f}tok/s",
                flush=True,
            )
            print(
                "      "
                f"ttft_comp(avg/p95/p99)={stats.get('avg_comparable_ttft_ms', 0.0):.0f}/{stats.get('p95_comparable_ttft_ms', 0.0):.0f}/{stats.get('p99_comparable_ttft_ms', 0.0):.0f}ms "
                f"ttft_warm(avg/p95/p99)={stats.get('avg_warm_standard_ttft_ms', 0.0):.0f}/{stats.get('p95_warm_standard_ttft_ms', 0.0):.0f}/{stats.get('p99_warm_standard_ttft_ms', 0.0):.0f}ms",
                flush=True,
            )
            print(
                "      "
                f"scaleup_ttft={stats.get('avg_scaleup_affected_ttft_ms', 0.0):.0f}ms "
                f"runtime={stats.get('avg_runtime_ttft_ms', 0.0):.0f}ms "
                f"runtime_e2e={stats.get('avg_runtime_estimated_e2e_ms', 0.0):.0f}ms "
                f"worker_wall={stats.get('avg_worker_wall_e2e_ms', 0.0):.0f}ms "
                f"worker_shell={stats.get('avg_worker_engine_shell_ms', 0.0):.0f}ms "
                f"worker_q={stats.get('avg_worker_rpc_queue_ms', 0.0):.0f}ms "
                f"pre_runtime={stats.get('avg_pre_runtime_service_shell_ms', 0.0):.0f}ms "
                f"svc_residual={stats.get('avg_service_path_residual_ms', 0.0):.0f}ms "
                f"rpc_ovh={stats.get('avg_parent_rpc_overhead_ms', 0.0):.0f}ms "
                f"rpc_acq={stats.get('avg_parent_rpc_channel_acquire_ms', 0.0):.0f}ms "
                f"rpc_pickup={stats.get('avg_parent_rpc_response_pickup_delay_ms', 0.0):.0f}ms "
                f"rpc_resume={stats.get('avg_parent_rpc_thread_resume_delay_ms', 0.0):.0f}ms "
                f"gpu_ready={stats.get('avg_gpu_ready_ttft_ms', 0.0):.0f}ms "
                f"diag hit={stats.get('cache_hit_ratio', 0.0):.0%} "
                f"arrival_late={stats.get('avg_arrival_release_lateness_ms', 0.0):.0f}ms "
                f"dispatch_wait={stats.get('avg_dispatch_admission_wait_ms', 0.0):.0f}ms "
                f"overhead(e2e_path)={stats.get('avg_serverless_overhead_ms', 0.0):.0f}ms "
                f"overhead(service_path)={stats.get('avg_service_overhead_ms', 0.0):.0f}ms "
                f"tokenproxy_ce={live_token_proxy_ce:.3f}",
                flush=True,
            )
            failure_reasons = stats.get("failure_reasons") or []
            if failure_reasons:
                reason_line = ", ".join(f"{name}={count}" for name, count in failure_reasons)
                print(f"      fail_reasons {reason_line}", flush=True)
        gpu_line = self._gpu_summary_line()
        if gpu_line:
            print(gpu_line, flush=True)
        for line in self._instance_panel_lines():
            print(line, flush=True)
        self._live_last_print_time = now
        self._live_last_print_completed = completed

    def _available_device_ids(self) -> List[int]:
        hw_cfg = getattr(self, "hw", None)
        hw_gpu_ids = hw_cfg.get("gpu_device_ids") if isinstance(hw_cfg, dict) else None
        runner_model_cfg = getattr(self, "model_cfg", None)
        runner_visible_ids = (
            runner_model_cfg.get("visible_device_ids")
            if isinstance(runner_model_cfg, dict)
            else None
        )
        engine_visible_ids = (
            (self.engine.model_cfg or {}).get("visible_device_ids")
            if self.engine is not None
            else None
        )
        available = _resolve_host_visible_device_ids(
            hw_gpu_ids=hw_gpu_ids,
            runner_visible_ids=runner_visible_ids,
            engine_visible_ids=engine_visible_ids,
            fallback_gpu_count=max(int(GPU_COUNT or 1), 1),
        )
        if available:
            return available
        return list(range(max(int(GPU_COUNT or 1), 1)))

    def _select_dedicated_device_id(self) -> Optional[int]:
        available_device_ids = self._available_device_ids()
        tp = 1
        try:
            tp = max(1, int((getattr(self, "model_cfg", {}) or {}).get("tensor_parallel_size", 1) or 1))
        except (TypeError, ValueError):
            tp = 1
        device_ids = []
        if tp <= 1:
            device_ids = list(available_device_ids)
        else:
            for start in range(0, len(available_device_ids), tp):
                group = available_device_ids[start:start + tp]
                if len(group) < tp:
                    break
                device_ids.append(int(group[0]))
        if not device_ids:
            device_ids = list(available_device_ids)
        if not device_ids:
            return None
        if self.instance_pool is None:
            return device_ids[0]
        used = {
            slot.device_id for slot in self.instance_pool.get_slots()
            if getattr(slot, "device_id", None) is not None
        }
        used.update(
            int(device_id)
            for device_id in getattr(self, "_pending_scale_up_device_ids", set()) or set()
            if device_id is not None
        )
        used.update(
            int(device_id)
            for device_id in getattr(self, "_failed_runtime_device_ids", set()) or set()
            if device_id is not None
        )
        for device_id in device_ids:
            if device_id not in used:
                return device_id
        return None

    def _scheduled_offset(self, trace: RequestTrace) -> float:
        if getattr(self, '_external_replay', None) is not None:
            return self._external_replay_offsets[str(trace.request_id)]
        return max(0.0, trace.arrival_time - self._arrival_base)

    async def _await_trace_arrival(self, trace: RequestTrace, replay_t0: float) -> None:
        if getattr(self, '_external_replay', None) is not None:
            raise RuntimeError('external replay cannot fall back to the service event-loop timer')
        wait = self._scheduled_offset(trace) - (time.perf_counter() - replay_t0)
        if wait > 0:
            await asyncio.sleep(wait)

    def _arrived_request_count(self, replay_t0: float) -> int:
        if getattr(self, '_external_replay', None) is not None:
            return len(self._external_replay.observed_times)
        elapsed = max(0.0, time.perf_counter() - replay_t0)
        return bisect_right(self._scheduled_arrivals, elapsed)

    def _arrival_rps(self, replay_t0: float) -> float:
        if getattr(self, '_external_replay', None) is not None:
            received = self._external_replay.observed_times
            window_s = max(self._arrival_window_s, 1.0)
            lo = bisect_right(received, time.perf_counter()-window_s)
            return (len(received)-lo)/window_s
        if not self._scheduled_arrivals:
            return 0.0
        elapsed = max(0.0, time.perf_counter() - replay_t0)
        window_s = max(self._arrival_window_s, 1.0)
        lo = bisect_right(self._scheduled_arrivals, max(0.0, elapsed - window_s))
        hi = bisect_right(self._scheduled_arrivals, elapsed)
        arrivals = max(0, hi - lo)
        # In continuous-queue v2, arrival rate should reflect only the recent arrival
        # process. Existing queued work is already captured by backlog, so mixing in a
        # cumulative replay average double-counts scale-up pressure.
        return arrivals / window_s

    def _backlog_depth(self, completed_count: int, replay_t0: float) -> int:
        return max(0, self._arrived_request_count(replay_t0) - completed_count)

    def _active_request_count(self) -> int:
        if self.instance_pool is None:
            return 0
        return sum(max(0, int(getattr(slot, "active_requests", 0))) for slot in self.instance_pool.get_slots())

    def _busy_instance_ratio(self) -> float:
        if self.instance_pool is None:
            return 0.0
        groups = self.instance_pool.get_runtime_groups()
        if not groups:
            return 0.0
        busy = 0
        for group in groups:
            if any(int(getattr(slot, "active_requests", 0)) > 0 for slot in group):
                busy += 1
        return busy / float(len(groups))

    def _current_runtime_group_count(self) -> int:
        if self.instance_pool is None:
            return 1 if getattr(self, "engine", None) is not None else 0
        get_groups = getattr(self.instance_pool, "get_runtime_groups", None)
        if callable(get_groups):
            try:
                groups = list(get_groups())
                if groups:
                    return len(groups)
            except Exception:
                pass
        count_fn = getattr(self.instance_pool, "count", None)
        if callable(count_fn):
            try:
                return max(0, int(count_fn() or 0))
            except Exception:
                pass
        return 0

    def _pending_scale_up_count(self) -> int:
        tasks = getattr(self, "_pending_scale_up_tasks", None)
        if not tasks:
            return 0
        live_tasks: set[asyncio.Task] = set()
        for task in list(tasks):
            if task is None:
                continue
            if task.done():
                try:
                    task.result()
                except asyncio.CancelledError:
                    pass
                except Exception as exc:
                    if getattr(self, '_routing_policy', None) == 'ieee_confirmed':
                        self._ieee_scale_failure = exc
                    print(f"    [WARN] Pending scale-up task failed: {exc}", flush=True)
                continue
            live_tasks.add(task)
        self._pending_scale_up_tasks = live_tasks
        return len(live_tasks)

    def _effective_scale_capacity_instance_count(self) -> int:
        actual_instances = 0
        if self.instance_pool is not None:
            actual_instances = max(0, int(self.instance_pool.count() or 0))
        elif getattr(self, "engine", None) is not None:
            actual_instances = 1
        return actual_instances + self._pending_scale_up_count()

    def _background_scale_up_parallelism_limit(
        self,
        *,
        backlog: int,
        active_requests: int,
        busy_ratio: float,
    ) -> int:
        configured_max_concurrent_loads = max(
            1,
            int(getattr(self, "coord_cfg", {}).get("max_concurrent_loads", 1) or 1),
        )
        startup_parallelism_raw = getattr(self, "coord_cfg", {}).get(
            "scale_up_startup_parallelism",
            "auto",
        )
        if not _is_auto_config_value(startup_parallelism_raw):
            try:
                return max(1, int(startup_parallelism_raw or 1))
            except Exception:
                return configured_max_concurrent_loads
        pressure_present = (
            backlog > 0
            or active_requests > 0
            or busy_ratio > 0.0
            or int(getattr(self, "_dispatch_admitted_requests", 0) or 0) > 0
        )
        if not pressure_present:
            return configured_max_concurrent_loads
        try:
            current_dispatch_capacity = max(1, int(self._current_dispatch_capacity_limit() or 1))
        except Exception:
            current_dispatch_capacity = max(1, int(self._runtime_forward_capacity_limit() or 1))
        high_scaleout_pressure = (
            backlog > current_dispatch_capacity
            or active_requests >= current_dispatch_capacity
            or busy_ratio >= 0.75
        )
        if high_scaleout_pressure:
            return configured_max_concurrent_loads
        # Background scale-up is a cold-path consumer that competes with
        # foreground request-triggered loads. Keep at least one lane available
        # for already-admitted online work, and let the remainder drive
        # physical runtime startup in the background.
        return max(1, configured_max_concurrent_loads - 1)

    def _pending_scale_up_sequence_index(
        self,
        sequence_id: Optional[int],
    ) -> Optional[Tuple[int, int]]:
        if sequence_id is None:
            return None
        sequence_ids = sorted(
            int(item)
            for item in getattr(self, "_pending_scale_up_sequences", set()) or set()
        )
        if not sequence_ids or int(sequence_id) not in sequence_ids:
            return None
        return sequence_ids.index(int(sequence_id)), len(sequence_ids)

    def _configured_workload_concurrency(self) -> int:
        raw = getattr(self, "_workload_concurrency_limit", None)
        if raw is None:
            raw = getattr(self, "wl_cfg", {}).get("concurrency", 1)
        try:
            return max(1, int(raw or 1))
        except Exception:
            return 1

    def _dispatch_admission_mode(self) -> str:
        wl_cfg = getattr(self, "wl_cfg", {}) or {}
        arrival_source = str(
            wl_cfg.get("arrival_source", wl_cfg.get("workload_arrival_source", "")) or ""
        ).strip().lower()
        workload_source = str(wl_cfg.get("workload_source", "") or "").strip().lower()
        timing_mode = str(wl_cfg.get("workload_timing_mode", "") or "").strip().lower()
        if (
            arrival_source == "azure_llm"
            or workload_source == "azure_real_trace"
            or timing_mode.startswith("azure_")
        ):
            return "open_loop_trace_replay"
        return "workload_capped"

    def _dispatch_capacity_limit_for_runtime_groups(self, runtime_groups: int) -> int:
        groups = max(0, int(runtime_groups or 0))
        if groups <= 0:
            return 0
        runtime_cap = max(1, self._runtime_forward_capacity_limit())
        aggregate_runtime_capacity = groups * runtime_cap
        if self._dispatch_admission_mode() == "workload_capped":
            workload_limit = self._configured_workload_concurrency()
            return min(workload_limit, aggregate_runtime_capacity)
        # For this replay harness, allowing extra admitted requests beyond the
        # physical runtime capacity increases control-plane contention on the
        # shared event loop faster than it improves routing opportunity. Keep
        # the dispatch gate aligned with the true runtime capacity so open-loop
        # trace replay preserves stable backpressure semantics.
        return aggregate_runtime_capacity

    def _current_dispatch_capacity_limit(self) -> int:
        runtime_groups = max(1, self._current_runtime_group_count())
        return max(
            1,
            self._dispatch_capacity_limit_for_runtime_groups(runtime_groups),
        )

    def _dispatch_admission_cond(self) -> asyncio.Condition:
        cond = getattr(self, "_dispatch_admission_condition", None)
        if cond is None:
            cond = asyncio.Condition()
            self._dispatch_admission_condition = cond
        return cond

    def _runtime_slot_capacity_cond(self) -> asyncio.Condition:
        cond = getattr(self, "_runtime_slot_capacity_condition", None)
        if cond is None:
            cond = asyncio.Condition()
            self._runtime_slot_capacity_condition = cond
        return cond

    async def _notify_dispatch_capacity_changed(
        self,
        *,
        wake_all: bool = False,
        notify_admission: bool = True,
        slot_wake_all: Optional[bool] = None,
    ) -> None:
        admission_cond = getattr(self, "_dispatch_admission_condition", None)
        if notify_admission and admission_cond is not None:
            async with admission_cond:
                if wake_all:
                    admission_cond.notify_all()
                else:
                    admission_cond.notify(1)
        runtime_cond = getattr(self, "_runtime_slot_capacity_condition", None)
        if runtime_cond is None:
            return
        if slot_wake_all is None:
            slot_wake_all = wake_all
        async with runtime_cond:
            if slot_wake_all:
                runtime_cond.notify_all()
            else:
                runtime_cond.notify(1)

    async def _acquire_dispatch_admission(self) -> None:
        cond = self._dispatch_admission_cond()
        async with cond:
            while int(getattr(self, "_dispatch_admitted_requests", 0) or 0) >= self._current_dispatch_capacity_limit():
                await cond.wait()
            self._dispatch_admitted_requests = int(
                getattr(self, "_dispatch_admitted_requests", 0) or 0
            ) + 1

    async def _release_dispatch_admission(self) -> None:
        cond = self._dispatch_admission_cond()
        async with cond:
            self._dispatch_admitted_requests = max(
                0,
                int(getattr(self, "_dispatch_admitted_requests", 0) or 0) - 1,
            )
            cond.notify(1)

    def _live_scale_eval_period_s(self) -> float:
        try:
            return max(0.1, float(getattr(self, "_scale_eval_interval_s", 15.0) or 15.0))
        except Exception:
            pass
        autoscaler = getattr(self._stack, "autoscaler", None) if self._stack is not None else None
        if autoscaler is not None:
            try:
                return max(0.1, float(getattr(autoscaler, "decision_interval", 15.0) or 15.0))
            except Exception:
                pass
        return 15.0

    def _should_attempt_live_scale_control_eval(
        self,
        *,
        now_monotonic: float,
        arrival_rps: float,
        backlog: int,
        active_requests: int,
        busy_ratio: float,
    ) -> bool:
        if (
            self._stack is None
            or self.baseline_type not in ("faaslora_nvme", "faaslora_no_coord", "faaslora_full")
            or ScalingMetrics is None
            or ScalingAction is None
            or self.instance_pool is None
        ):
            return False
        min_instances = max(1, int(getattr(self.instance_pool, "min_instances", 1) or 1))
        max_instances = max(min_instances, int(getattr(self.instance_pool, "max_instances", min_instances) or min_instances))
        actual_instances = max(0, int(self.instance_pool.count() or 0))
        pending_scale_ups = self._pending_scale_up_count()
        effective_instances = actual_instances + pending_scale_ups
        can_scale_up = effective_instances < max_instances and (
            arrival_rps > 0.0 or backlog > 0 or active_requests > 0 or busy_ratio > 0.0
        )
        can_scale_down = pending_scale_ups <= 0 and actual_instances > min_instances
        pressure_present = backlog > 0 or active_requests > 0 or busy_ratio > 0.0
        if not pressure_present and not can_scale_down:
            return False
        if not pressure_present and not self._should_trigger_scale_down():
            return False
        if not can_scale_up and not can_scale_down:
            return False
        return (now_monotonic - self._live_scale_eval_last_at) >= self._live_scale_eval_period_s()

    def _select_scale_down_candidate_slot(
        self,
        *,
        min_idle_s: Optional[float] = None,
    ) -> Optional[Any]:
        if self.instance_pool is None:
            return None
        get_slots = getattr(self.instance_pool, "get_slots", None)
        if not callable(get_slots):
            return None
        min_instances = max(1, int(getattr(self.instance_pool, "min_instances", 1) or 1))
        if self.instance_pool.count() <= min_instances:
            return None
        now_wall = time.time()
        def _slot_drain_safe(slot: Any) -> bool:
            return (
                int(getattr(slot, "active_requests", 0) or 0) <= 0
                and int(getattr(slot, "load_queue_depth", 0) or 0) <= 0
                and max(0, int(getattr(slot, "runtime_forwarding_active", 0) or 0)) <= 0
            )
        candidates = [
            slot
            for slot in get_slots()
            if slot.instance_id != self._primary_instance_id
        ]
        if not candidates:
            return None
        idle_candidates = [
            slot for slot in candidates if _slot_drain_safe(slot)
        ]
        if min_idle_s is not None:
            idle_threshold = max(0.0, float(min_idle_s or 0.0))
            idle_candidates = [
                slot for slot in idle_candidates
                if self._slot_idle_seconds(slot, now_wall=now_wall) >= idle_threshold
            ]
        scale_down_cooldown_s = max(0.0, float(self._effective_scale_down_cooldown_s()))
        if scale_down_cooldown_s > 0.0:
            idle_candidates = [
                slot for slot in idle_candidates
                if self._slot_ready_age_seconds(slot, now_wall=now_wall) >= scale_down_cooldown_s
            ]
        if not idle_candidates:
            return None
        return min(
            idle_candidates,
            key=lambda slot: (
                int(getattr(slot, "active_requests", 0) or 0),
                int(getattr(slot, "load_queue_depth", 0) or 0),
                -self._slot_idle_seconds(slot, now_wall=now_wall),
                float(getattr(slot, "last_selected_at", 0.0) or 0.0),
                float(getattr(slot, "created_at", 0.0) or 0.0),
            ),
        )

    def _can_scale_down_idle_slot_under_visible_pressure(
        self,
        *,
        backlog: int,
        active_requests: int,
        now_monotonic: Optional[float] = None,
    ) -> bool:
        """Allow serverless-style per-replica TTL without waiting for global idle.

        Scale-down must be drain-safe in the formal replay. The guard is
        slot-level rather than globally blocking on any visible request: request
        coroutines reserve a runtime lane before their first await, and
        InstancePool removal makes the slot invisible to later routing. Thus an
        idle sibling can be reclaimed while other runtimes are still serving, as
        long as the remaining runtime lanes cover the visible work.
        """
        if self.instance_pool is None:
            return False
        if now_monotonic is None:
            now_monotonic = time.perf_counter()
        if not self._live_scale_down_cooldown_open(float(now_monotonic)):
            return False
        actual_instances = max(0, int(self.instance_pool.count() or 0))
        min_instances = max(1, int(getattr(self.instance_pool, "min_instances", 1) or 1))
        if actual_instances <= min_instances:
            return False
        if self._pending_scale_up_count() > 0:
            return False
        min_idle_s = self._effective_scale_down_min_idle_s()
        candidate = self._select_scale_down_candidate_slot(
            min_idle_s=min_idle_s,
        )
        if candidate is None:
            return False
        remaining_capacity = self._runtime_total_capacity_after_removal(actual_instances - 1)
        visible_work = max(0, int(backlog or 0)) + max(0, int(active_requests or 0))
        return visible_work <= remaining_capacity

    async def _maybe_run_live_scale_control_evaluation(
        self,
        *,
        result: ScenarioResult,
        coord_enabled: bool,
        replay_t0: float,
        results_view: List[Any],
        backlog: int,
        active_requests: int,
        busy_ratio: float,
        completed_count: int,
        queue_visible_request_count: Optional[int] = None,
        visible_traces: Optional[List[Any]] = None,
        submitted_count: Optional[int] = None,
        submitted_traces: Optional[List[Any]] = None,
    ) -> bool:
        if getattr(self, '_routing_policy', None) == 'ieee_confirmed':
            return await self._evaluate_ieee_live_control(result=result, coord_enabled=coord_enabled,
                replay_t0=replay_t0, results_view=results_view, backlog=backlog,
                active_requests=active_requests, completed_count=completed_count)
        visible_request_count = (
            queue_visible_request_count
            if queue_visible_request_count is not None
            else submitted_count
        )
        candidate_traces = (
            visible_traces if visible_traces is not None else submitted_traces
        )
        now_mono = time.perf_counter()
        arrival_rps = self._arrival_rps(replay_t0)
        if self._dynamic_scaling:
            self._live_scale_overrides = self._update_dynamic_scaling_live_state(
                arrival_rps,
                now_mono,
            )
        if not self._should_attempt_live_scale_control_eval(
            now_monotonic=now_mono,
            arrival_rps=arrival_rps,
            backlog=backlog,
            active_requests=active_requests,
            busy_ratio=busy_ratio,
        ):
            return False

        gpu_util = self._autoscaler_gpu_signal()
        metrics = ScalingMetrics(
            requests_per_second=arrival_rps,
            request_queue_length=max(0, backlog),
            dispatch_admission_wait_ms=_avg_success_dispatch_wait_ms(results_view),
            avg_response_time_ms=_avg_success_e2e_ms(results_view),
            avg_ttft_ms=_avg_success_ttft_ms(results_view),
            gpu_utilization=gpu_util,
            active_requests=active_requests,
            instance_busy_ratio=busy_ratio,
        )
        actual_current_instances = max(0, int(self.instance_pool.count() or 0))
        pending_scale_up_instances = self._pending_scale_up_count()
        current_instances = actual_current_instances + pending_scale_up_instances
        live_overrides = dict(self._live_scale_overrides or {})
        runtime_total_capacity_fn = getattr(self, "_runtime_total_capacity", None)
        if callable(runtime_total_capacity_fn):
            visible_capacity = max(
                1,
                int(runtime_total_capacity_fn(max(1, current_instances)) or 1),
            )
        else:
            runtime_lane_cap = max(1, int(self._runtime_forward_capacity_limit() or 1))
            visible_capacity = max(1, runtime_lane_cap * max(1, current_instances))
        # Queue pressure should be judged against the currently available
        # runtime lanes, not a static backlog=10 heuristic. This keeps the
        # controller adapter/model agnostic while still reacting early when a
        # single runtime is already saturated.
        live_overrides["scale_up_threshold_queue_length"] = float(max(2, visible_capacity))
        live_overrides["scale_down_threshold_queue_length"] = 0.0
        self._live_scale_overrides = live_overrides
        decision = self._stack.autoscaler.make_scaling_decision_with_metrics(
            metrics,
            current_instances=current_instances,
            overrides=live_overrides,
        )
        if decision.action == ScalingAction.SCALE_DOWN:
            if backlog <= 0 and active_requests <= 0 and busy_ratio <= 0.0:
                if not self._live_scale_down_cooldown_open(now_mono):
                    return False
                if not self._should_trigger_scale_down():
                    return False
                scale_down_min_idle_s = self._effective_scale_down_min_idle_s()
                scale_down_event = await self._scale_down_one_instance(
                    require_idle=True,
                    min_idle_s=scale_down_min_idle_s,
                )
                if not scale_down_event:
                    return False
                self._live_scale_eval_last_at = now_mono
                self._last_live_scale_down_completed_at = now_mono
                arrived_request_count = self._arrived_request_count(replay_t0)
                request_index = max(
                    0,
                    int(
                        visible_request_count
                        if visible_request_count is not None
                        else arrived_request_count
                        or 0
                    ),
                )
                result.scale_down_events += 1
                result.scale_down_event_log.append({
                    "timestamp": time.time(),
                    "request_index": request_index,
                    "queue_visible_request_count": request_index,
                    "completed_request_count": max(0, int(completed_count or 0)),
                    "arrived_request_count": max(0, int(arrived_request_count or 0)),
                    "reason": decision.reason,
                    **scale_down_event,
                })
                print(
                    f"    Scale-down decision: reason={decision.reason} "
                    f"instances={current_instances}->{decision.target_instances} "
                    f"arrival_rps={arrival_rps:.2f} backlog={max(0, backlog)} "
                    f"active={active_requests} busy={busy_ratio:.2f}",
                    flush=True,
                )
                return True
        if decision.action != ScalingAction.SCALE_UP:
            if self._can_scale_down_idle_slot_under_visible_pressure(
                backlog=backlog,
                active_requests=active_requests,
                now_monotonic=now_mono,
            ):
                scale_down_min_idle_s = self._effective_scale_down_min_idle_s()
                scale_down_event = await self._scale_down_one_instance(
                    require_idle=True,
                    min_idle_s=scale_down_min_idle_s,
                )
                if scale_down_event:
                    self._live_scale_eval_last_at = now_mono
                    self._last_live_scale_down_completed_at = now_mono
                    arrived_request_count = self._arrived_request_count(replay_t0)
                    request_index = max(
                        0,
                        int(
                            visible_request_count
                            if visible_request_count is not None
                            else arrived_request_count
                            or 0
                        ),
                    )
                    result.scale_down_events += 1
                    result.scale_down_event_log.append({
                        "timestamp": time.time(),
                        "request_index": request_index,
                        "queue_visible_request_count": request_index,
                        "completed_request_count": max(0, int(completed_count or 0)),
                        "arrived_request_count": max(0, int(arrived_request_count or 0)),
                        "reason": "idle_slot_ttl_safe_capacity",
                        **scale_down_event,
                    })
                    print(
                        "    Scale-down decision: reason=idle_slot_ttl_safe_capacity "
                        f"instances={current_instances}->{max(1, actual_current_instances - 1)} "
                        f"arrival_rps={arrival_rps:.2f} backlog={max(0, backlog)} "
                        f"active={active_requests} busy={busy_ratio:.2f}",
                        flush=True,
                    )
                    return True
            if backlog <= 0 and active_requests <= 0 and busy_ratio <= 0.0:
                self._live_scale_eval_last_at = now_mono
            return False

        self._live_scale_eval_last_at = now_mono
        arrived_request_count = self._arrived_request_count(replay_t0)
        request_index = max(0, int(visible_request_count or 0))
        preferred_gpu_adapters = self._live_scale_up_preferred_gpu_adapters(
            replay_t0=replay_t0,
            arrived_request_count=arrived_request_count,
            queue_visible_request_count=visible_request_count,
            visible_traces=candidate_traces,
            submitted_count=submitted_count,
            submitted_traces=candidate_traces,
        )
        handoff_plan = dict(getattr(self, "_last_scale_up_handoff_plan", {}) or {})
        if self._scale_up_capacity_covers_ready_projection(
            handoff_plan=handoff_plan,
            current_instances=current_instances,
            pending_scale_up_instances=pending_scale_up_instances,
            backlog=backlog,
            active_requests=active_requests,
            busy_ratio=busy_ratio,
        ):
            # The current and pending runtime capacity already covers the
            # ready-time queue projection. Suppress busy-ratio scale-out pulses
            # in this state; otherwise a brief busy interval can enqueue extra
            # replicas that spend most of the replay idle.
            self._live_scale_eval_last_at = now_mono
            return False
        refined_target_instances = self._refined_scale_up_target_instances(
            current_instances=current_instances,
            decision=decision,
            handoff_plan=handoff_plan,
        )
        decision.target_instances = refined_target_instances
        additional_instances = max(0, refined_target_instances - current_instances)
        runtime_handoff_plans = self._build_scale_up_runtime_handoff_plans(
            handoff_plan,
            additional_instances=additional_instances,
        )
        startup_parallelism_limit = self._background_scale_up_parallelism_limit(
            backlog=backlog,
            active_requests=active_requests,
            busy_ratio=busy_ratio,
        )
        preload_capacity_bytes = self._scale_up_preload_capacity_bytes(preferred_gpu_adapters)
        preload_budget = dict(getattr(self, "_last_scale_up_preload_budget", {}) or {})
        print(
            f"    Scale-up decision: reason={decision.reason} "
            f"instances={actual_current_instances}"
            f"{f'(+{pending_scale_up_instances} pending)' if pending_scale_up_instances > 0 else ''}"
            f"->{decision.target_instances} "
            f"arrival_rps={arrival_rps:.2f} backlog={max(0, backlog)} "
            f"active={active_requests} busy={busy_ratio:.2f}",
            flush=True,
        )
        if runtime_handoff_plans:
            per_runtime_request_budget = max(
                1,
                int(
                    handoff_plan.get("first_service_request_count", 0)
                    or handoff_plan.get("initial_admission_request_budget", 1)
                    or 1
                ),
            )
            print(
                f"    Scale-up handoff fanout: new_runtimes={len(runtime_handoff_plans)} "
                f"queue_at_ready={int(handoff_plan.get('queue_at_ready_request_count', 0) or 0)} "
                f"per_runtime_first_service={per_runtime_request_budget} "
                f"startup_slots={max(0, startup_parallelism_limit - pending_scale_up_instances)}/"
                f"{startup_parallelism_limit}",
                flush=True,
            )
        if preferred_gpu_adapters:
            preview = ", ".join(preferred_gpu_adapters[:5])
            if len(preferred_gpu_adapters) > 5:
                preview += ", ..."
            print(
                f"    Scale-up initial handoff prefix: {len(preferred_gpu_adapters)} adapters ({preview})",
                flush=True,
            )
        print(
            f"    Scale-up preload budget: mode={preload_budget.get('mode', 'unknown')} "
            f"budget={preload_capacity_bytes / (1024.0 * 1024.0):.1f}MB "
            f"prefix={float(preload_budget.get('exact_prefix_bytes', 0) or 0) / (1024.0 * 1024.0):.1f}MB "
            f"live_hotset={float(preload_budget.get('live_hotset_bytes', 0) or 0) / (1024.0 * 1024.0):.1f}MB "
            f"working_set={float(preload_budget.get('recent_working_set_bytes', 0) or 0) / (1024.0 * 1024.0):.1f}MB "
            f"headroom={float(preload_budget.get('target_headroom_bytes', 0) or 0) / (1024.0 * 1024.0):.1f}MB",
            flush=True,
        )
        if bool(getattr(self, "_scale_up_handoff_enabled", True)) and len(runtime_handoff_plans) <= 1:
            await self._stack.trigger_scaling_preload(
                preload_capacity_bytes,
                preferred_gpu_adapters=preferred_gpu_adapters,
            )
        use_background_scale_up = (
            str(getattr(self, "_instance_mode", "shared") or "shared").lower()
            in ("dedicated", "auto")
            and getattr(self, "engine_factory", None) is not None
        )
        if use_background_scale_up:
            scheduled = self._schedule_background_scale_up_instance_pool(
                result=result,
                coord_enabled=coord_enabled,
                decision=decision,
                current_instances=actual_current_instances,
                pending_scale_up_instances=pending_scale_up_instances,
                request_index=request_index,
                completed_request_count=max(0, int(completed_count or 0)),
                queue_visible_request_count=request_index,
                arrived_request_count=max(0, int(arrived_request_count or 0)),
                target_instances=refined_target_instances,
                runtime_handoff_plans=runtime_handoff_plans,
                startup_parallelism_limit=startup_parallelism_limit,
            )
            return scheduled > 0
        try:
            scale_events = await self._scale_up_instance_pool(
                coord_enabled,
                target_instances=refined_target_instances,
                runtime_handoff_plans=runtime_handoff_plans,
            )
        except TypeError:
            scale_events = await self._scale_up_instance_pool(coord_enabled)
        if not scale_events:
            return False
        if isinstance(scale_events, dict):
            scale_events = [scale_events]
        for scale_event in scale_events:
            self._register_scale_up_event(
                result,
                decision=decision,
                current_instances=actual_current_instances,
                request_index=request_index,
                completed_request_count=max(0, int(completed_count or 0)),
                queue_visible_request_count=request_index,
                submitted_request_count=request_index,
                arrived_request_count=max(0, int(arrived_request_count or 0)),
                scale_event=scale_event,
            )
        return True

    def _ieee_control_owner(self):
        from faaslora.coordination.autoscaler import IEEEReplicaControl
        controller = getattr(self, '_ieee_scale_controller', None)
        if controller is None:
            controller = IEEEReplicaControl(self.coord_cfg.get('ieee_scaling'),
                interval_s=self._scale_eval_interval_s,
                min_instances=self.instance_pool.min_instances, max_instances=self.instance_pool.max_instances)
            self._ieee_scale_controller = controller
        return controller

    async def _evaluate_ieee_live_control(self, *, result, coord_enabled, replay_t0,
                                         results_view, backlog, active_requests, completed_count):
        """The real replay control entry; no legacy forecast, votes or warmup.

        Historical backlog counts *all* unfinished arrivals, including admitted
        requests. Queue depth here removes the admitted set rather than counting
        it both as a queue and as active-request saturation. Only completed TTFT
        actually received by this controller enters the frozen trailing window.
        """
        if self._instance_mode not in ('dedicated', 'auto') or self.engine_factory is None:
            raise ValueError('IEEE control requires physically owned runtime activation')
        self._reap_ieee_residency_tasks()  # Surface failure; do not silently restart the same plan.
        controller = self._ieee_control_owner()
        now = time.monotonic()
        # The continuous replay appends to one result view. Process only its
        # new suffix; do not rescan thousands of completed rows on every poll.
        previous, cursor = getattr(self, '_ieee_ttft_result_cursor', (None, 0))
        if previous is not results_view or len(results_view) < cursor:
            cursor = 0
        for index in range(cursor, len(results_view)):
            item = results_view[index]
            if getattr(item, 'success', False):
                controller.observe_ttft(item.request_id, item.overall_ttft_ms, observed_at=now)
        self._ieee_ttft_result_cursor = (results_view, len(results_view))
        ready = self.instance_pool.count()
        pending = self._pending_scale_up_count()
        failure = getattr(self, '_ieee_scale_failure', None)
        if failure is not None:
            raise RuntimeError('IEEE activation failed; no blind control-loop retry') from failure
        if type(backlog) is not int or backlog < active_requests:
            raise ValueError('unfinished arrivals do not cover the admitted set')
        snapshot = controller.evaluate(now=now, queue_depth=backlog-active_requests,
            active_requests=active_requests, ready_capacity=ready*self._runtime_forward_capacity_limit(),
            ready_instances=ready, pending_instances=pending)
        if snapshot is None:
            return False
        # Sample only actual HOST-capacity waiters on the already-frozen control
        # cadence. Reading allocator counters is not a new loading attempt.
        await self._refresh_ieee_deferred_host_capacity()
        self._live_scale_eval_last_at = now
        record = dict(snapshot, action=snapshot['action'].value, outcome='no_action')
        if not hasattr(self, '_ieee_control_events'):
            self._ieee_control_events = []
        self._ieee_control_events.append(record)
        decision = SimpleNamespace(reason=snapshot['reason'], target_instances=snapshot['target_instances'])
        changed = False
        if snapshot['action'] == ScalingAction.SCALE_UP:
            # One activation per control interval; physical device reservations
            # and the owner budgets, not a prediction of future arrivals, limit it.
            arrived = self._arrived_request_count(replay_t0)
            count = self._schedule_background_scale_up_instance_pool(result=result,
                coord_enabled=coord_enabled, decision=decision, current_instances=ready,
                pending_scale_up_instances=pending, request_index=arrived,
                completed_request_count=completed_count, queue_visible_request_count=arrived,
                arrived_request_count=arrived, target_instances=snapshot['target_instances'],
                runtime_handoff_plans=None, startup_parallelism_limit=pending+1)
            changed = count > 0
            record.update(outcome='activation_scheduled' if changed else 'no_free_device', scheduled=count)
        elif snapshot['action'] == ScalingAction.SCALE_DOWN:
            # The sampled all-low/cooldown condition is already established.
            # Pick an already-drained replica; withdrawal is synchronous before
            # cleanup awaits, so a new router reservation cannot revive it.
            idle = [s for s in self.instance_pool.get_slots()
                    if s.instance_id != self._primary_instance_id
                    and s.active_requests == 0 and s.load_queue_depth == 0
                    and getattr(s, 'runtime_forwarding_active', 0) == 0]
            if idle:
                selected = min(idle, key=lambda s: (s.last_selected_at, s.instance_id))
                removed = self.instance_pool.remove_instance(selected.instance_id)
                await self._cleanup_removed_slot(removed, removal_reason='ieee_all_low_cooldown')
                result.scale_down_events += 1
                result.scale_down_event_log.append(dict(event_type='physical_scale_down',
                    instance_id=selected.instance_id, device_id=selected.device_id,
                    reason=snapshot['reason'], observed_monotonic_s=now,
                    control_event_index=len(self._ieee_control_events)-1))
                changed = True
                record['outcome'] = 'drained_replica_retired'
            else:
                record['outcome'] = 'awaiting_drained_replica'
        # NoHandoff disables only the activating-replica path, not this ready
        # steady-state path. Existing in-flight plans keep their immutable epoch.
        self._schedule_ieee_residency_epochs()
        return changed

    async def _refresh_ieee_deferred_host_capacity(self):
        """Observe asynchronous HOST return without a per-operation retry timer.

        Native allocators don't expose a Python return callback. Refusals keep
        their actual A/X observation. On existing control samples, refresh only
        owners with live byte-pressure waiters; wake only if their measured
        capacity improves. Execution still rechecks all budgets/references/E(t).
        No credit for Python deletion, expected frees, inactive or cached bytes.
        """
        preloading = getattr(getattr(self, '_stack', None), 'preloading_manager', None)
        if preloading is None or not preloading.ieee_movements.bound:
            return
        queue = preloading.ieee_movements
        waits = queue.deferred_observations(target_tier='host',
            reasons=('native_host_tensor_budget', 'native_host_workspace_pressure'))
        if not waits:
            return
        from faaslora.clock import local_monotonic_clock_id
        def measured(value):
            if (not isinstance(value, dict) or value.get('available') is not True
                    or any(type(value.get(k)) is not int or value[k] < 0 for k in
                           ('accounted_tensor_bytes', 'registered_exclusive_storage_bytes'))
                    or value['registered_exclusive_storage_bytes'] > value['accounted_tensor_bytes']):
                raise ValueError('native HOST capacity notification lacks actual storage accounting')
            return value['accounted_tensor_bytes'], value['registered_exclusive_storage_bytes']
        owners = getattr(self, '_ieee_gpu_movement_owners', {})
        for owner_id in sorted({w['key'][0] for w in waits}):
            if owner_id not in owners:
                raise RuntimeError('deferred native HOST capacity has no physical owner')
            group = [w for w in waits if w['key'][0] == owner_id]
            before = []
            for wait in group:
                allocation = wait['observation']
                if not isinstance(allocation, dict) or allocation.get('admitted') is not False:
                    raise ValueError('native HOST capacity refusal lacks its allocation observation')
                before.append(measured(allocation.get('before')))
            reply = await owners[owner_id].ieee_gpu_reference(operation='source_snapshot')
            if reply.get('owner_id') != owner_id or reply.get('clock_id') != local_monotonic_clock_id():
                raise ValueError('native HOST capacity observation owner/clock changed')
            current, exclusive = measured(reply.get('native_host_allocator'))
            # The RPC may overlap cancellation or a genuine release wake. An
            # obsolete refusal cannot wake a later incarnation of the job.
            live_attempts = {w['attempt_id'] for w in queue.deferred_observations(target_tier='host',
                reasons=('native_host_tensor_budget', 'native_host_workspace_pressure'))}
            improved = [w for w, (old, old_exclusive) in zip(group, before)
                if w['attempt_id'] in live_attempts and
                   (current-exclusive < old-old_exclusive
                    if w['reason'] == 'native_host_workspace_pressure' else current < old)]
            if improved:
                queue.wake(owner_id=owner_id, target_tiers=('host',))
                if not hasattr(self, '_ieee_host_capacity_events'):
                    self._ieee_host_capacity_events = []
                self._ieee_host_capacity_events.append(dict(owner_id=owner_id,
                    observed_monotonic_s=time.monotonic(), clock_id=local_monotonic_clock_id(),
                    current_accounted_bytes=current, current_registered_exclusive_bytes=exclusive,
                    refusal_attempt_ids=[w['attempt_id'] for w in improved],
                    capacity_reserved=False))

    def _reap_ieee_residency_tasks(self):
        tasks = getattr(self, '_ieee_residency_tasks', {})
        for key, task in list(tasks.items()):
            if task.done():
                del tasks[key]
                task.result()  # A failed epoch is evidence, not a swallowed warning/retry.

    def _schedule_ieee_residency_epochs(self):
        if not self._hierarchical_residency_enabled:
            return
        if not hasattr(self, '_ieee_residency_tasks'):
            self._ieee_residency_tasks = {}
        if not hasattr(self, '_ieee_residency_epochs'):
            self._ieee_residency_epochs = []
        active_engines = {id(engine) for task, engine in (
            getattr(self, '_ieee_file_plan_engines', {}) |
            getattr(self, '_ieee_gpu_plan_engines', {})).items() if not task.done()}
        for slot in self.instance_pool.get_slots():
            key = id(slot.engine)
            if key in self._ieee_residency_tasks or key in active_engines:
                continue
            record = dict(target_replica=slot.instance_id, state='planning', trigger_reason='residency',
                          started_at=time.monotonic())
            self._ieee_residency_epochs.append(record)
            self._ieee_residency_tasks[key] = asyncio.create_task(self._execute_ieee_residency_epoch(slot, record))

    async def _execute_ieee_residency_epoch(self, slot, record):
        try:
            # Registered before the first await, including source collection.
            result = await self._run_ieee_owned_preparation_plan(slot=slot, mode='residency',
                capacity_only=not self._coordination_enabled)
            record.update(state=result.get('state', 'completed'), plan_sha256=result['plan']['plan_sha256'])
            if record['state'] == 'superseded':
                record['native_registration_rejection'] = result['native_registration_rejection']
            return result
        except BaseException as exc:
            record.update(state='cancelled' if isinstance(exc, asyncio.CancelledError) else 'failed',
                          error_type=type(exc).__name__)
            if not isinstance(exc, asyncio.CancelledError):
                import traceback
                # Reaping and shutdown may raise different failed epochs. Keep
                # each original cause at its actual failure boundary, before a
                # subsequent lookup observes only withdrawn source state.
                record.update(error=str(exc), traceback=traceback.format_exc())
            raise
        finally:
            record['terminal_at'] = time.monotonic()

    async def _maybe_run_live_scale_up_evaluation(
        self,
        *,
        result: ScenarioResult,
        coord_enabled: bool,
        replay_t0: float,
        results_view: List[Any],
        backlog: int,
        active_requests: int,
        busy_ratio: float,
        completed_count: int,
        submitted_count: int,
        submitted_traces: Optional[List[Any]] = None,
    ) -> bool:
        return await self._maybe_run_live_scale_control_evaluation(
            result=result,
            coord_enabled=coord_enabled,
            replay_t0=replay_t0,
            results_view=results_view,
            backlog=backlog,
            active_requests=active_requests,
            busy_ratio=busy_ratio,
            completed_count=completed_count,
            queue_visible_request_count=submitted_count,
            visible_traces=submitted_traces,
            submitted_count=submitted_count,
            submitted_traces=submitted_traces,
        )

    async def _run_batch_observed(
        self,
        batch: List[RequestTrace],
        batch_start_index: int,
        replay_t0: float,
        run_one_fn,
        completed_before_batch: int,
        observe_fn=None,
    ) -> Tuple[List[Any], float, int, int, float]:
        """
        Execute one batch and observe peak backlog / in-flight pressure while it is running.

        Returns:
          raw_results, batch_end_time, peak_backlog, peak_active_requests, peak_busy_ratio
        """
        tasks = [
            asyncio.create_task(run_one_fn(batch_start_index + i, t))
            for i, t in enumerate(batch)
        ]
        observed_done = set()
        observed_raw: List[Any] = []
        peak_backlog = self._backlog_depth(completed_before_batch, replay_t0)
        peak_active_requests = self._active_request_count()
        peak_busy_ratio = self._busy_instance_ratio()

        while True:
            done_count = sum(1 for task in tasks if task.done())
            completed_now = completed_before_batch + done_count
            for idx, task in enumerate(tasks):
                if idx in observed_done or not task.done():
                    continue
                observed_done.add(idx)
                try:
                    observed_raw.append(task.result())
                except Exception as exc:
                    observed_raw.append(exc)
            peak_backlog = max(peak_backlog, self._backlog_depth(completed_now, replay_t0))
            peak_active_requests = max(peak_active_requests, self._active_request_count())
            peak_busy_ratio = max(peak_busy_ratio, self._busy_instance_ratio())
            if observe_fn is not None:
                await observe_fn(
                    completed_now=completed_now,
                    submitted_count=completed_before_batch + len(tasks),
                    observed_raw=list(observed_raw),
                    peak_backlog=peak_backlog,
                    peak_active_requests=peak_active_requests,
                    peak_busy_ratio=peak_busy_ratio,
                )
            if done_count == len(tasks):
                break
            self._emit_live_snapshot(
                completed=completed_now,
                total=len(self.traces),
                replay_t0=replay_t0,
                failed=0,
                force=False,
                backlog_override=peak_backlog,
                active_override=peak_active_requests,
                busy_override=peak_busy_ratio,
                submitted_override=completed_before_batch + len(tasks),
            )
            await asyncio.sleep(0.02)

        raw = []
        for task in tasks:
            try:
                raw.append(await task)
            except Exception as exc:  # should be rare; gather-like fallback
                raw.append(exc)
        return raw, time.perf_counter(), peak_backlog, peak_active_requests, peak_busy_ratio

    def _collect_request_task_result(
        self, task: asyncio.Task, trace: RequestTrace, replay_t0: float,
        request_plan: Optional[RequestExecutionPlan],
    ) -> RequestResult:
        """Bind a finished task to its offered request; never invent a terminal.

        The observation boundary is the controller reading a finished task,
        not the backend finishing GPU work. Global replay cancellation bypasses
        this collector and remains a truncated run, not N individual timeouts.
        """
        if not task.done():
            raise RuntimeError('cannot collect an unfinished request task')
        try:
            item = task.result()
        except (Exception, asyncio.CancelledError) as exc:
            from faaslora.metrics.metrics_collector import local_monotonic_clock_id
            observed_at = time.perf_counter()
            scheduled_offset = self._scheduled_offset(trace)
            if observed_at < replay_t0 + scheduled_offset:
                raise RuntimeError('request failure observed before its offered arrival') from exc
            contract = self._generation_contract
            if contract == 'fixed_length_greedy_v1' and request_plan is None:
                raise RuntimeError('failed fixed-work request lost its prepared input identity') from exc
            external = self._external_replay
            arrival = dict(external.records[trace.request_id]) if external is not None else {}
            item = RequestResult(
                request_id=trace.request_id, adapter_id=trace.adapter_id,
                is_burst=trace.is_burst,
                burst_phase=getattr(trace, '_burst_phase', 'normal'),
                cache_hit=False, cache_tier='unobserved',
                lora_io_ms=None, vllm_ttft_ms=None, ttft_ms=None,
                contention_ms=None, defer_ms=None, tpot_ms=None, e2e_ms=None,
                input_tokens=request_plan.input_tokens if request_plan else None,
                output_tokens=None, cost_usd=None, success=False,
                error=f'{type(exc).__name__}: {exc}',
                tpot_observed=False, output_contract_match=False,
                service_ttft_ms=None, service_e2e_ms=None,
                admitted_service_ttft_ms=None, admitted_service_e2e_ms=None,
                overall_ttft_ms=None, overall_e2e_ms=None,
                scheduled_arrival_offset_s=scheduled_offset,
                generation_contract=contract,
                source_expected_output_tokens=trace.expected_output_tokens,
                requested_completion_tokens=request_plan.max_tokens if request_plan else 0,
                canonical_prompt_sha256=(hashlib.sha256(request_plan.prompt.encode('utf-8')).hexdigest()
                                         if request_plan else ''),
                canonical_prompt_tokens=request_plan.input_tokens if request_plan else 0,
                completion_token_source='unobserved_due_to_task_failure',
                timing_contract=self.model_cfg.get('timing_contract', 'legacy'),
                arrival_contract='external_frozen_trace_v1' if external is not None else 'legacy_internal_timer',
                external_arrival_timing=arrival,
                failure_observation={
                    'kind': 'controller_task_exception_v1',
                    'exception_type': type(exc).__name__,
                    'observed_monotonic_s': observed_at,
                    'observed_offset_s': observed_at - replay_t0,
                    'elapsed_since_offered_ms': (observed_at - replay_t0 - scheduled_offset) * 1000.,
                    'clock_id': local_monotonic_clock_id(),
                    'native_completion_inferred': False,
                    'gpu_release_inferred': False,
                },
            )
        if not isinstance(item, RequestResult) or item.request_id != trace.request_id:
            raise RuntimeError('request task result does not match its offered identity')
        if self._generation_contract == 'fixed_length_greedy_v1' and item.adapter_id != trace.adapter_id:
            raise RuntimeError('fixed-work result changed its offered adapter identity')
        return item

    async def _run_continuous_observed(
        self,
        *,
        traces: List[RequestTrace],
        trace_start_index: int,
        replay_t0: float,
        run_one_fn,
        completed_before_window: int,
        total_requests: int,
        result: ScenarioResult,
        coord_enabled: bool,
        phase_label: Optional[str] = None,
        request_plans: Optional[Dict[str, RequestExecutionPlan]] = None,
    ) -> Tuple[List[Any], float]:
        """
        Execute one trace window with continuous arrivals and a shared waiting queue.

        Unlike substrate_v1's batch runner, request activation remains continuous:
        every trace owns its arrival sleep, enters the shared waiting queue on
        arrival, and the autoscaler/router observe that same online queue state.
        """
        self._active_replay_t0 = replay_t0
        launched_count = 0
        completed_indices: set[int] = set()
        observed_raw: List[Any] = []
        active_tasks: set[asyncio.Task] = set()
        task_to_idx: Dict[asyncio.Task, int] = {}
        results_by_idx: Dict[int, Any] = {}
        interruption = None

        async def _dispatch_traces() -> None:
            nonlocal launched_count
            external = getattr(self, '_external_replay', None)
            if external is not None:
                if trace_start_index != 0 or len(traces) != len(external.plan.entries):
                    raise ValueError('external replay cannot reset at phase/drain boundaries')
                async for local_idx, record in external.receive():
                    task = asyncio.create_task(run_one_fn(local_idx, traces[local_idx],
                        arrival_released_at=record['server_received_s']))
                    active_tasks.add(task)
                    task_to_idx[task] = local_idx
                    launched_count += 1
                return
            for local_idx, trace in enumerate(traces):
                await self._await_trace_arrival(trace, replay_t0)
                arrival_released_at = time.perf_counter()
                task = asyncio.create_task(
                    run_one_fn(
                        trace_start_index + local_idx,
                        trace,
                        arrival_released_at=arrival_released_at,
                    )
                )
                active_tasks.add(task)
                task_to_idx[task] = local_idx
                launched_count += 1

        dispatcher = asyncio.create_task(_dispatch_traces())
        control_poll_s = min(0.1, max(0.02, self._live_scale_eval_period_s() / 20.0))

        try:
            while active_tasks or not dispatcher.done():
                wait_set: set[asyncio.Task] = set(active_tasks)
                if not dispatcher.done():
                    wait_set.add(dispatcher)

                if wait_set:
                    done_now, _ = await asyncio.wait(
                        wait_set,
                        timeout=control_poll_s,
                        return_when=asyncio.FIRST_COMPLETED,
                    )
                else:
                    done_now = set()
                    await asyncio.sleep(control_poll_s)

                if dispatcher in done_now:
                    done_now.remove(dispatcher)
                    await dispatcher

                for task in done_now:
                    if task is dispatcher:
                        continue
                    active_tasks.discard(task)
                    idx = task_to_idx.get(task)
                    if idx is None or idx in completed_indices:
                        continue
                    completed_indices.add(idx)
                    trace = traces[idx]
                    item = self._collect_request_task_result(
                        task, trace, replay_t0,
                        request_plans.get(trace.request_id) if request_plans is not None else None)
                    observed_raw.append(item)
                    results_by_idx[idx] = item
                    del task_to_idx[task]

                completed_now = completed_before_window + len(completed_indices)
                backlog = self._backlog_depth(completed_now, replay_t0)
                active_requests = self._active_request_count()
                busy_ratio = self._busy_instance_ratio()
                arrived_now = self._arrived_request_count(replay_t0)
                waiting_traces = self._waiting_visible_trace_queue()
                await self._maybe_run_live_scale_control_evaluation(
                    result=result,
                    coord_enabled=coord_enabled,
                    replay_t0=replay_t0,
                    results_view=observed_raw,
                    backlog=backlog,
                    active_requests=active_requests,
                    busy_ratio=busy_ratio,
                    completed_count=completed_now,
                    queue_visible_request_count=arrived_now,
                    visible_traces=waiting_traces,
                )
                failed_now = sum(
                    1 for item in observed_raw
                    if isinstance(item, Exception) or not getattr(item, "success", True)
                )
                self._emit_live_snapshot(
                    completed=completed_now,
                    total=total_requests,
                    replay_t0=replay_t0,
                    failed=failed_now,
                    phase_label=phase_label,
                    force=(dispatcher.done() and not active_tasks),
                    backlog_override=backlog,
                    active_override=active_requests,
                    busy_override=busy_ratio,
                    queue_visible_override=arrived_now,
                    arrived_override=arrived_now,
                    results_view=observed_raw,
                    scale_up_count=len(result.scale_up_events),
                    scale_down_count=result.scale_down_events,
                )

            # A fast failed publisher may finish between controller polls.
            # Always retrieve its exception; never manufacture missing results.
            await dispatcher
            if set(results_by_idx) != set(range(len(traces))):
                raise RuntimeError('incomplete replay has no full request outcome set')
            raw = [results_by_idx[idx] for idx in range(len(traces))]
            return raw, time.perf_counter()
        except BaseException as exc:
            interruption = dict(error_type=type(exc).__name__,
                                interrupted_monotonic_s=time.perf_counter())
            raise
        finally:
            self._active_replay_t0 = None
            if not dispatcher.done():
                dispatcher.cancel()
            for task in active_tasks:
                if not task.done():
                    task.cancel()
            await asyncio.gather(dispatcher, *active_tasks, return_exceptions=True)
            if interruption is not None:
                # Preserve only real launched tasks after their terminal join.
                # This is failure evidence, never a successful ScenarioResult;
                # future unsubmitted requests acquire no invented outcomes.
                from dataclasses import asdict
                retained = dict(results_by_idx)
                collection_errors = []
                for task, idx in task_to_idx.items():
                    try:
                        trace = traces[idx]
                        retained[idx] = self._collect_request_task_result(task, trace, replay_t0,
                            request_plans.get(trace.request_id) if request_plans is not None else None)
                    except BaseException as exc:
                        collection_errors.append(dict(request_id=traces[idx].request_id,
                            error_type=type(exc).__name__, error=str(exc)))
                submitted = set(results_by_idx) | set(task_to_idx.values())
                if not hasattr(self, '_interrupted_replay_evidence'):
                    self._interrupted_replay_evidence = []
                self._interrupted_replay_evidence.append(dict(
                    kind='interrupted_continuous_replay_v1', complete=False,
                    planned_request_count=len(traces), submitted_count=launched_count,
                    replay_t0_s=replay_t0, trace_start_index=trace_start_index,
                    requests=[asdict(retained[i]) for i in sorted(retained)],
                    unsubmitted_request_ids=[t.request_id for i,t in enumerate(traces) if i not in submitted],
                    collection_errors=collection_errors, **interruption))

    def _prime_slot_cache_view(self, slot: Any, include_gpu: bool) -> None:
        if slot is None:
            return
        if self._stack is not None:
            sync = getattr(self._stack, "sync_local_tier_paths", None)
            if sync is not None:
                sync()
        slot.nvme_cached_adapters = set(self._nvme_cache.keys())
        if self._stack is not None:
            slot.nvme_cached_adapters.update(getattr(self._stack, "_nvme_paths", {}).keys())
            slot.host_cached_adapters = set(getattr(self._stack, "_host_paths", {}).keys())
        else:
            slot.host_cached_adapters = set()
        if include_gpu:
            slot.gpu_resident_adapters.update(self._gpu_warmed)
        self._refresh_slot_runtime_hints(slot)

    def _mark_slot_adapter_tier(self, slot: Optional[Any], adapter_id: Optional[str], tier: Optional[str]) -> None:
        if slot is None or not adapter_id:
            return
        targets = [slot]
        if self._instance_mode == "shared" and self.instance_pool is not None:
            targets = list(self.instance_pool.get_slots())
        for target in targets:
            self._prime_slot_cache_view(target, include_gpu=self._slot_should_include_gpu(target))
            target.mark_adapter_tier(adapter_id, tier)

    async def _trigger_scale_down_all_instances(self, warm_pool_size: Optional[int]) -> set:
        warm_union: set = set()
        seen_coords = set()
        if self.instance_pool is not None:
            slots = list(self.instance_pool.get_slots())
        else:
            slots = []
        if not slots and self.coordinator is not None:
            slots = [type("_Slot", (), {"coordinator": self.coordinator})()]
        for slot in slots:
            coord = getattr(slot, "coordinator", None)
            if coord is None or id(coord) in seen_coords:
                continue
            seen_coords.add(id(coord))
            warm = await coord.trigger_scale_down(warm_pool_size=warm_pool_size)
            if warm:
                warm_union.update(warm)
        self._refresh_all_slot_runtime_hints(force=True)
        return warm_union

    def _warm_pool_hits_total(self) -> int:
        return sum(m.get("warm_pool_hits", 0) for m in self._coordinator_metric_views())

    @staticmethod
    def _record_gpu_ready_hit(coord: Optional[Any], adapter_id: str) -> None:
        if coord is None:
            return
        recorder = getattr(coord, "record_gpu_ready_hit", None)
        if callable(recorder):
            try:
                recorder(adapter_id)
            except TypeError:
                recorder()
            return
        fallback = getattr(coord, "record_warm_pool_hit", None)
        if callable(fallback):
            try:
                fallback(adapter_id)
            except TypeError:
                fallback()

    async def _cleanup_removed_slot(
        self,
        slot: Optional[Any],
        *,
        removal_reason: Optional[str] = None,
    ) -> None:
        if slot is None:
            return
        residency_failure = None
        instance_id = getattr(slot, "instance_id", None)
        if instance_id:
            self._mark_instance_lifecycle_removed(
                instance_id,
                reason=removal_reason or "removed",
            )
        if instance_id:
            self._scaleup_runtime_instance_ids.discard(instance_id)
            self._scaleup_runtime_handoff_plans.pop(str(instance_id), None)
            self._scaleup_runtime_lora_request_ordinals.pop(str(instance_id), None)
        await self._cancel_runtime_gpu_forward_tasks(self._runtime_forward_task_key(slot))
        if getattr(slot, 'owns_engine', False):
            task = getattr(self, '_ieee_residency_tasks', {}).pop(id(slot.engine), None)
            if task is not None:
                if not task.done():
                    task.cancel()
                outcome = (await asyncio.gather(task, return_exceptions=True))[0]
                if isinstance(outcome, BaseException) and not isinstance(outcome, asyncio.CancelledError):
                    residency_failure = outcome
            # A retired replica must not acquire new proactive work. Join its
            # existing plans before withdrawing from the shared IO domain.
            owned = [task for task, engine in (getattr(self, '_ieee_gpu_plan_engines', {}) |
                                               getattr(self, '_ieee_file_plan_engines', {})).items()
                     if engine is slot.engine and task is not asyncio.current_task() and not task.done()]
            for task in owned:
                task.cancel()
            if owned:
                await asyncio.gather(*owned, return_exceptions=True)
            if getattr(self, '_shared_file_pressure', None) is not None:
                await self._shared_file_pressure.retire(slot.engine)
        try:
            if getattr(slot, "owns_coordinator", False) and getattr(slot, "coordinator", None) is not None:
                self._retired_coord_metrics.append(slot.coordinator.get_summary_metrics())
        except Exception:
            pass
        if getattr(slot, "owns_engine", False) and getattr(slot, "engine", None) is not None:
            try:
                await slot.engine.shutdown()
            except Exception:
                if (self.model_cfg.get('ieee_host_budget_bytes') is not None
                        or self.model_cfg.get('ieee_physical_allocation')):
                    raise  # Retain HOST/GPU ownership on unresolved teardown.
            self._retire_ieee_host_budget(slot.engine)
        self._sync_stack_gpu_accounting()
        await self._notify_dispatch_capacity_changed(wake_all=True)
        if residency_failure is not None:
            raise RuntimeError('retired IEEE replica had a failed residency epoch') from residency_failure

    async def _retire_failed_slot(self, slot: Optional[Any], reason: str) -> bool:
        if slot is None or self.instance_pool is None:
            return False
        instance_id = getattr(slot, "instance_id", None)
        if not instance_id:
            return False
        async with self._slot_retire_lock:
            current = self.instance_pool.get_slot(instance_id)
            if current is None:
                return False
            removed = self.instance_pool.remove_instance(instance_id)
            if removed is None:
                return False
            failed_device_id = getattr(removed, "device_id", None)
            if failed_device_id is not None and getattr(removed, "owns_engine", False):
                failed_devices = getattr(self, "_failed_runtime_device_ids", None)
                if failed_devices is None:
                    failed_devices = set()
                    self._failed_runtime_device_ids = failed_devices
                failed_devices.add(int(failed_device_id))
            if instance_id == self._primary_instance_id:
                remaining = self.instance_pool.get_slots()
                self._primary_instance_id = remaining[0].instance_id if remaining else None
            await self._cleanup_removed_slot(
                removed,
                removal_reason=f"runtime_failed:{reason}",
            )
        print(f"    [runtime-failed] removed {instance_id}: {reason[:160]}", flush=True)
        return True

    async def _shutdown_instance_pool(self) -> None:
        # Initial activation owns startup AND preparation. Join it while the
        # common movement owner is still open; otherwise a late factory result
        # could publish a new slot after shutdown's plan/engine census.
        initial = list(getattr(self, '_ieee_initial_tasks', ()))
        for task in initial:
            if not task.done():
                task.cancel()
        if initial:
            joined = asyncio.gather(*initial, return_exceptions=True)
            while not joined.done():
                try:
                    await asyncio.shield(joined)
                except asyncio.CancelledError:
                    continue
        residency = list(getattr(self, '_ieee_residency_tasks', {}).values())
        for task in residency:
            if not task.done():
                task.cancel()
        residency_outcomes = await asyncio.gather(*residency, return_exceptions=True)
        getattr(self, '_ieee_residency_tasks', {}).clear()
        plans = [task for task in set(getattr(self, '_ieee_gpu_plan_tasks', ())) |
                                   set(getattr(self, '_ieee_file_plan_tasks', ()))
                 if task is not asyncio.current_task() and not task.done()]
        for task in plans:
            task.cancel()
        if plans:
            await asyncio.gather(*plans, return_exceptions=True)
        # Shared writers and their native pressure journals must settle while
        # the engines they refer to still exist. Cancelling a scale-up first
        # could otherwise remove that engine during an owned file operation.
        preloading = getattr(getattr(self, '_stack', None), 'preloading_manager', None)
        if preloading is not None and preloading.ieee_movements.bound:
            await preloading.ieee_movements.close()
        binding = getattr(self, '_ieee_file_change_binding', None)
        if binding is not None:
            self._stack.residency_manager.local_source_references.unsubscribe_file_changes(binding[0])
            self._ieee_file_change_binding = None
        tasks = list(getattr(self, "_pending_scale_up_tasks", set()) or [])
        for task in tasks:
            if task is not None and not task.done():
                task.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        pending_tasks = getattr(self, "_pending_scale_up_tasks", None)
        if pending_tasks is not None:
            pending_tasks.clear()
        pending_device_ids = getattr(self, "_pending_scale_up_device_ids", None)
        if pending_device_ids is not None:
            pending_device_ids.clear()
        pending_sequences = getattr(self, "_pending_scale_up_sequences", None)
        if pending_sequences is not None:
            pending_sequences.clear()
        if self.instance_pool is None:
            return
        cleanup_failures = []
        for slot in list(self.instance_pool.get_slots()):
            instance_id = getattr(slot, "instance_id", None)
            if not instance_id:
                continue
            removed = self.instance_pool.remove_instance(instance_id)
            if removed is None:
                continue
            try:
                await self._cleanup_removed_slot(removed, removal_reason="shutdown")
            except Exception as exc:
                # Still retire the other owned runtimes. Durable physical owner
                # journals retain this failed return; do not turn it into success.
                cleanup_failures.append(exc)
        if getattr(self, '_ieee_nvml_initialized', False):
            import pynvml
            pynvml.nvmlShutdown()
            self._ieee_nvml_initialized = False
        if cleanup_failures:
            raise RuntimeError('instance-pool cleanup has unresolved runtime ownership') from cleanup_failures[0]
        for outcome in residency_outcomes:
            if isinstance(outcome, BaseException) and not isinstance(outcome, asyncio.CancelledError):
                raise RuntimeError('IEEE shutdown preserved a failed residency epoch') from outcome

    async def _prune_dead_instance_slots(self) -> int:
        instance_pool = getattr(self, "instance_pool", None)
        if instance_pool is None:
            return 0
        removed = 0
        for slot in list(instance_pool.get_slots()):
            if not getattr(slot, "owns_engine", False):
                continue
            engine = getattr(slot, "engine", None)
            if engine is None:
                continue
            process = getattr(engine, "_process", None)
            dead = bool(getattr(engine, "_engine_dead", False))
            if process is not None:
                try:
                    dead = dead or (process.poll() is not None)
                except Exception:
                    pass
            if not dead:
                continue
            if await self._retire_failed_slot(slot, "engine_dead"):
                removed += 1
        return removed

    async def _add_shared_instance_slot(self, coord_enabled: bool) -> Optional[Dict[str, Any]]:
        if self.instance_pool is None or self.engine is None:
            return None
        if self.instance_pool.count() >= self.instance_pool.max_instances:
            return None
        await self._attach_ieee_file_pressure(self.engine)
        instance_id = self.instance_pool.add_instance(
            self.engine,
            self.coordinator,
            owns_engine=False,
            owns_coordinator=False,
            device_id=getattr(self.engine, "device_id", None),
        )
        self._prime_slot_cache_view(self.instance_pool.get_slot(instance_id), include_gpu=True)
        self._sync_stack_gpu_accounting()
        self._schedule_all_runtime_gpu_forward()
        await self._notify_dispatch_capacity_changed(wake_all=True)
        print(
            f"    Scale-up: added shared-engine slot "
            f"(instances={self.instance_pool.count()}/{self.instance_pool.max_instances})",
            flush=True,
        )
        return {
            "event_type": "logical_scale_up",
            "instance_id": instance_id,
            "device_id": getattr(self.engine, "device_id", None),
            "runtime_kind": "shared",
        }

    async def _add_dedicated_instance_slot(
        self,
        coord_enabled: bool,
        *,
        handoff_plan: Optional[Dict[str, Any]] = None,
        reserved_device_id: Optional[int] = None,
        activation_kind: str = 'initial',
    ) -> Optional[Dict[str, Any]]:
        if self.instance_pool is None or getattr(self, "engine_factory", None) is None:
            return None
        if self.instance_pool.count() >= self.instance_pool.max_instances:
            return None
        device_id = (
            reserved_device_id
            if reserved_device_id is not None
            else self._select_dedicated_device_id()
        )
        if getattr(self, '_routing_policy', None) == 'ieee_confirmed':
            if handoff_plan:
                raise ValueError('IEEE activation cannot consume a legacy warmup/handoff plan')
            return await self._add_ieee_dedicated_instance(device_id=device_id,
                                                           activation_kind=activation_kind)
        cold_start_started_at = time.perf_counter()
        try:
            new_engine, new_coord = await self.engine_factory(device_id=device_id)
        except Exception as exc:
            print(f"    [WARN] Dedicated instance creation failed: {exc}", flush=True)
            return None
        if self._service_profiles is not None or getattr(self, '_preparation_profiles', None) is not None:
            try:
                for profiles in (self._service_profiles, getattr(self, '_preparation_profiles', None)):
                    if profiles is not None:
                        profiles.validate_runtime(getattr(new_engine, 'model_cfg', None))
            except (ValueError, TypeError):
                # This engine has not entered the pool yet. Do not leak it or
                # perform warmup with a profile measured under another backend.
                await new_engine.shutdown()
                raise
        try:
            # Join shared/preactivation IO before any warmup or pool publication.
            await self._attach_ieee_file_pressure(new_engine)
        except BaseException:
            try:
                domain = getattr(self, '_shared_file_pressure', None)
                member = domain.members.get(id(new_engine)) if domain is not None else None
                # A cancelled join may already be acknowledged by the core.
                # Settle that subscription while the core is still alive; a
                # genuinely unknown attachment remains explicit uncertainty.
                if member is not None and member['state'] == 'attached':
                    await domain.retire(new_engine)
            finally:
                await new_engine.shutdown()
                self._retire_ieee_host_budget(new_engine)
            raise
        runtime_startup_latency_ms = max(
            0.0,
            float(getattr(new_engine, "startup_latency_ms", 0.0) or 0.0),
        )
        active_handoff_plan = dict(
            handoff_plan if handoff_plan is not None else getattr(self, "_last_scale_up_handoff_plan", {}) or {}
        )
        active_handoff_plan = self._refresh_scale_up_runtime_handoff_plan_after_startup(
            active_handoff_plan,
            runtime_startup_latency_ms=runtime_startup_latency_ms,
        )
        if active_handoff_plan:
            self._last_scale_up_handoff_plan = dict(active_handoff_plan)
        planned_warmup_aids = list(active_handoff_plan.get("planned_adapters", []) or [])
        try:
            warmed = await self._warmup_engine_hot_set(
                new_engine,
                coordinator=new_coord,
                planned_aids=planned_warmup_aids,
            )
        except TypeError:
            warmed = await self._warmup_engine_hot_set(new_engine, coordinator=new_coord)
        if active_handoff_plan and planned_warmup_aids:
            warmed_set = {str(adapter_id) for adapter_id in set(warmed or set()) if adapter_id}
            executed_planned_adapters = [
                str(adapter_id)
                for adapter_id in planned_warmup_aids
                if str(adapter_id) in warmed_set
            ]
            if executed_planned_adapters != planned_warmup_aids:
                active_handoff_plan["planned_adapters"] = executed_planned_adapters
                active_handoff_plan["first_service_adapter_count"] = len(
                    executed_planned_adapters
                )
                active_handoff_plan["exact_prefix_bytes"] = self._scale_up_adapter_total_bytes(
                    executed_planned_adapters
                )
                active_handoff_plan["plan_load_latency_ms"] = self._predicted_scale_up_load_ms(
                    executed_planned_adapters,
                    max_concurrent_loads=max(
                        1,
                        int(active_handoff_plan.get("configured_max_concurrent_loads", 1) or 1),
                    ),
                )
                active_handoff_plan["ready_delay_ms"] = float(
                    active_handoff_plan.get("bootstrap_latency_ms", 0.0) or 0.0
                ) + float(active_handoff_plan.get("plan_load_latency_ms", 0.0) or 0.0)
        instance_id = self.instance_pool.add_instance(
            new_engine,
            new_coord,
            owns_engine=True,
            owns_coordinator=True,
            device_id=getattr(new_engine, "device_id", None),
        )
        lifecycle_ready_offset_s = self._run_elapsed_offset_s()
        self._ensure_instance_lifecycle_record(
            instance_id,
            runtime_kind="dedicated",
            gpu_count=self._runtime_gpu_count_for_cfg(getattr(new_engine, "model_cfg", None)),
            device_id=getattr(new_engine, "device_id", None),
            created_offset_s=self._run_elapsed_offset_s(cold_start_started_at),
            ready_offset_s=lifecycle_ready_offset_s,
            lifecycle_source="scale_up",
            model_name=(getattr(new_engine, "model_cfg", {}) or {}).get("name"),
        )
        slot = self.instance_pool.get_slot(instance_id)
        self._prime_slot_cache_view(slot, include_gpu=False)
        if active_handoff_plan:
            plans = getattr(self, "_scaleup_runtime_handoff_plans", None)
            if plans is None:
                plans = {}
                self._scaleup_runtime_handoff_plans = plans
            plans[str(instance_id)] = active_handoff_plan
        if slot is not None:
            for aid in warmed:
                slot.mark_adapter_tier(aid, "gpu")
            self._refresh_slot_runtime_hints(slot, force=True)
        scaleup_ids = getattr(self, "_scaleup_runtime_instance_ids", None)
        if scaleup_ids is None:
            scaleup_ids = set()
            self._scaleup_runtime_instance_ids = scaleup_ids
        scaleup_ids.add(str(instance_id))
        self._sync_stack_gpu_accounting()
        await self._notify_dispatch_capacity_changed(wake_all=True)
        print(
            f"    Scale-up: added dedicated instance "
            f"(instances={self.instance_pool.count()}/{self.instance_pool.max_instances})",
            flush=True,
        )
        if warmed:
            print(f"    New instance warmup: {len(warmed)} adapters loaded", flush=True)
        cold_start_latency_ms = max(0.0, (time.perf_counter() - cold_start_started_at) * 1000.0)
        observed_cold_starts = getattr(
            self, "_observed_scale_up_cold_start_latencies_ms", None
        )
        if observed_cold_starts is None:
            observed_cold_starts = []
            self._observed_scale_up_cold_start_latencies_ms = observed_cold_starts
        observed_cold_starts.append(cold_start_latency_ms)
        observed_runtime_startups = getattr(
            self, "_observed_scale_up_runtime_startup_latencies_ms", None
        )
        if observed_runtime_startups is None:
            observed_runtime_startups = []
            self._observed_scale_up_runtime_startup_latencies_ms = (
                observed_runtime_startups
            )
        if runtime_startup_latency_ms > 0.0:
            observed_runtime_startups.append(runtime_startup_latency_ms)
        event_preload_budget = {}
        if active_handoff_plan:
            exact_prefix_bytes = max(0, int(active_handoff_plan.get("exact_prefix_bytes", 0) or 0))
            target_headroom_bytes = max(0, int(active_handoff_plan.get("target_headroom_bytes", 0) or 0))
            event_preload_budget = {
                "mode": str(active_handoff_plan.get("mode", "") or ""),
                "capacity_bytes": min(exact_prefix_bytes, target_headroom_bytes)
                if target_headroom_bytes > 0
                else exact_prefix_bytes,
                "exact_prefix_bytes": exact_prefix_bytes,
                "live_hotset_bytes": int(
                    getattr(self, "_last_scale_up_preload_budget", {}).get("live_hotset_bytes", 0) or 0
                ),
                "recent_working_set_bytes": int(
                    getattr(self, "_last_scale_up_preload_budget", {}).get("recent_working_set_bytes", 0) or 0
                ),
                "target_headroom_bytes": target_headroom_bytes,
            }
        return {
            "event_type": "physical_scale_up",
            "instance_id": instance_id,
            "device_id": getattr(new_engine, "device_id", None),
            "runtime_kind": "dedicated",
            "warmed_adapters": len(warmed),
            "cold_start_latency_ms": cold_start_latency_ms,
            "runtime_startup_latency_ms": runtime_startup_latency_ms,
            "handoff_plan": active_handoff_plan,
            "preload_budget": event_preload_budget,
        }

    async def _add_ieee_dedicated_instance(self, *, device_id, activation_kind):
        """Actual scale-out entry: freeze -> overlap files/init -> native recheck.

        Runtime readiness does not wait for all proactive work. Unfinished
        targets retain the common queue's ownership and live admission checks.
        The complete Full startup guard remains until its other gates qualify.
        """
        from faaslora.clock import local_monotonic_clock_id
        from faaslora.preloading.preloading_planner import native_activation_layout
        policy = self._ieee_handoff_policy
        if activation_kind not in ('initial', 'natural_scaleout', 'controlled'):
            raise ValueError('activation requires its causal category')
        profiles = self._preparation_profiles
        if (profiles is None or self._stack is None or self._remote_artifact_client is None
                or not self.model_cfg.get('ieee_gpu_references')):
            raise ValueError('IEEE activation needs real owners and frozen measurements')
        profiles.validate_runtime(self._planned_ieee_runtime_model_config())
        layout = profiles.activation_layout()
        activation_id = 'ieee-activation-' + uuid.uuid4().hex
        files = self._stack.residency_manager.local_source_references
        files.configure_host_budget(self.model_cfg['ieee_host_budget_bytes'])
        files.reserve_activation_host(activation_id=activation_id,
            limit_bytes=self.model_cfg['ieee_native_host_tensor_budget_bytes'])
        record = dict(activation_id=activation_id, target_replica=activation_id,
            category=activation_kind, policy=policy, trigger_at=time.monotonic(),
            clock_id=local_monotonic_clock_id(), state='planning', plan_sha256=None)
        if not hasattr(self, '_ieee_activations'):
            self._ieee_activations = []
        self._ieee_activations.append(record)
        initialized = asyncio.get_running_loop().create_future()
        startup = preparation = None
        engine = coordinator = None
        published = False

        async def settle(awaitable):
            task = asyncio.ensure_future(awaitable)
            while True:
                try:
                    return await asyncio.shield(task)
                except asyncio.CancelledError:
                    if task.cancelled():
                        raise

        def preparation_done(task):
            try:
                task.result()
                record['preparation_state'] = 'completed'
            except BaseException as exc:
                record.update(preparation_state='cancelled' if isinstance(exc, asyncio.CancelledError) else 'failed',
                              preparation_error=type(exc).__name__)
            record['preparation_terminal_at'] = time.monotonic()

        try:
            plan = None
            if policy != 'no_handoff':
                manifests = self._remote_artifact_client.preparation_manifests(self._ieee_artifact_identities)
                manager = self._stack.residency_manager
                view = files.preparation_snapshot(manifests=manifests,
                    limits={tier: int(manager.tier_capacities[StorageTier(tier)].total_bytes)
                            for tier in files.roots})
                plan = self._stack.plan_ieee_owned_preparation(mode='handoff', native_snapshot=None,
                    file_snapshot=view, identities=self._ieee_artifact_identities,
                    adapter_int_ids={a: InferenceEngine._lora_int_id(a) for a in self._ieee_artifact_identities},
                    profiles=profiles, costs=profiles.new_replica(),
                    expected_clock_id=local_monotonic_clock_id(), received_at=time.monotonic(),
                    activation_id=activation_id)
                record['plan_sha256'] = plan['plan_sha256']
            # Both coroutines are owned before yielding. Initialization is
            # shielded: cancellation must join it, never abandon a new worker.
            record['state'] = 'initializing'
            startup = asyncio.create_task(self.engine_factory(device_id=device_id))
            if plan is not None:
                preparation = asyncio.create_task(self._run_ieee_file_preparation_plan(
                    plan=plan, target_engine=None, target_replica=activation_id,
                    activation_id=activation_id, activation_ready=initialized,
                    delayed=policy == 'delayed'))
                preparation.add_done_callback(preparation_done)
                record['preparation_state'] = 'pending'
            else:
                record['preparation_state'] = 'disabled'
            engine, coordinator = await asyncio.shield(startup)
            profiles.validate_runtime(engine.model_cfg)
            if self._service_profiles is not None:
                self._service_profiles.validate_runtime(engine.model_cfg)
            observed = await engine.ieee_gpu_reference(operation='source_snapshot')
            if native_activation_layout(observed) != layout:
                raise ValueError('actual initialized GPU layout differs from frozen measurements')
            # Install before adapter work; adoption moves, not doubles, the
            # future native allowance. A lost acknowledgement retains it.
            if not hasattr(self, '_ieee_host_activation_ids'):
                self._ieee_host_activation_ids = {}
            self._ieee_host_activation_ids[id(engine)] = activation_id
            await self._attach_ieee_file_pressure(engine)
            instance_id = self.instance_pool.add_instance(engine, coordinator, owns_engine=True,
                owns_coordinator=True, device_id=device_id, instance_id=activation_id)
            published = True
            slot = self.instance_pool.get_slot(instance_id)
            if preparation is not None and not preparation.done():
                self._ieee_file_plan_engines[preparation] = engine
            record.update(state='runtime_ready', engine_ready_at=time.monotonic(),
                          native_owner_id=observed['owner_id'])
            initialized.set_result(slot)
            await self._notify_dispatch_capacity_changed(wake_all=True)
            return dict(event_type='physical_scale_up', instance_id=instance_id,
                device_id=device_id, runtime_kind='dedicated', activation_id=activation_id,
                activation_kind=activation_kind, handoff_plan_sha256=record['plan_sha256'],
                engine_activation_ms=1000*(record['engine_ready_at']-record['trigger_at']),
                preparation_state=record['preparation_state'])
        except BaseException as exc:
            record.update(state='cancelled' if isinstance(exc, asyncio.CancelledError) else 'failed',
                          error_type=type(exc).__name__)
            if preparation is not None:
                preparation.cancel()
                await settle(asyncio.gather(preparation, return_exceptions=True))
            if not initialized.done():
                initialized.cancel()
            if startup is not None and engine is None:
                # The factory may still own a process. Only a successful join
                # gives us a runtime we can retire; failure is not exit proof.
                try:
                    engine, coordinator = await settle(startup)
                except BaseException as failure:
                    record.update(state='startup_ownership_unresolved', startup_error=type(failure).__name__)
                    raise
            if engine is not None:
                if published:
                    self.instance_pool.remove_instance(activation_id)
                domain = getattr(self, '_shared_file_pressure', None)
                member = domain.members.get(id(engine)) if domain is not None else None
                if member is not None and member['state'] == 'attached':
                    await settle(domain.retire(engine))
                await settle(engine.shutdown())
                self._retire_ieee_host_budget(engine)
            # Unadopted bytes never enabled native adapter allocation. Startup
            # and file readers above have joined; adopted bytes use pidfd only.
            if activation_id in files.host_budget_snapshot()['activation_reservations']:
                files.cancel_activation_host(activation_id=activation_id)
            raise

    def _handle_pending_scale_up_task_done(self, task: asyncio.Task) -> None:
        tasks = getattr(self, "_pending_scale_up_tasks", None)
        if tasks is not None:
            tasks.discard(task)
        try:
            task.result()
        except asyncio.CancelledError:
            pass
        except Exception as exc:
            if getattr(self, '_routing_policy', None) == 'ieee_confirmed':
                self._ieee_scale_failure = exc
            print(f"    [WARN] Background scale-up task failed: {exc}", flush=True)

    async def _execute_background_scale_up(
        self,
        *,
        result: ScenarioResult,
        coord_enabled: bool,
        decision_snapshot: Any,
        current_instances: int,
        request_index: int,
        completed_request_count: int,
        queue_visible_request_count: Optional[int],
        arrived_request_count: Optional[int],
        handoff_plan: Optional[Dict[str, Any]],
        reserved_device_id: Optional[int],
        pending_sequence_id: Optional[int],
    ) -> None:
        try:
            scale_event = await self._add_dedicated_instance_slot(
                coord_enabled,
                handoff_plan=handoff_plan,
                reserved_device_id=reserved_device_id,
                activation_kind='natural_scaleout',
            )
            if not scale_event:
                return
            self._register_scale_up_event(
                result,
                decision=decision_snapshot,
                current_instances=current_instances,
                request_index=request_index,
                completed_request_count=completed_request_count,
                queue_visible_request_count=queue_visible_request_count,
                submitted_request_count=queue_visible_request_count,
                arrived_request_count=arrived_request_count,
                scale_event=scale_event,
            )
        finally:
            if reserved_device_id is not None:
                pending_device_ids = getattr(self, "_pending_scale_up_device_ids", None)
                if pending_device_ids is not None:
                    pending_device_ids.discard(int(reserved_device_id))
            if pending_sequence_id is not None:
                pending_sequences = getattr(self, "_pending_scale_up_sequences", None)
                if pending_sequences is not None:
                    pending_sequences.discard(int(pending_sequence_id))

    def _schedule_background_scale_up_instance_pool(
        self,
        *,
        result: ScenarioResult,
        coord_enabled: bool,
        decision: Any,
        current_instances: int,
        pending_scale_up_instances: int,
        request_index: int,
        completed_request_count: int,
        queue_visible_request_count: Optional[int],
        arrived_request_count: Optional[int],
        target_instances: Optional[int] = None,
        runtime_handoff_plans: Optional[List[Dict[str, Any]]] = None,
        startup_parallelism_limit: Optional[int] = None,
    ) -> int:
        if self.instance_pool is None:
            return 0
        max_instances = max(
            1,
            int(getattr(self.instance_pool, "max_instances", current_instances) or current_instances),
        )
        effective_instances = max(0, int(current_instances or 0)) + max(
            0, int(pending_scale_up_instances or 0)
        )
        if effective_instances >= max_instances:
            return 0
        desired_instances = (
            effective_instances + 1
            if target_instances is None
            else min(
                max_instances,
                max(effective_instances + 1, int(target_instances or 0)),
            )
        )
        create_count = max(0, desired_instances - effective_instances)
        if create_count <= 0:
            return 0
        startup_parallelism = max(1, int(startup_parallelism_limit or 1))
        available_startup_slots = max(
            0,
            startup_parallelism - max(0, int(pending_scale_up_instances or 0)),
        )
        if available_startup_slots <= 0:
            return 0
        create_count = min(create_count, available_startup_slots)
        if runtime_handoff_plans:
            consume_plan = getattr(self._stack, "consume_scaleup_gpu_plan", None) if self._stack is not None else None
            if callable(consume_plan):
                try:
                    consume_plan()
                except Exception:
                    pass
        tasks = getattr(self, "_pending_scale_up_tasks", None)
        if tasks is None:
            tasks = set()
            self._pending_scale_up_tasks = tasks
        pending_device_ids = getattr(self, "_pending_scale_up_device_ids", None)
        if pending_device_ids is None:
            pending_device_ids = set()
            self._pending_scale_up_device_ids = pending_device_ids
        pending_sequences = getattr(self, "_pending_scale_up_sequences", None)
        if pending_sequences is None:
            pending_sequences = set()
            self._pending_scale_up_sequences = pending_sequences
        scheduled = 0
        decision_snapshot = SimpleNamespace(
            reason=str(getattr(decision, "reason", "") or ""),
            target_instances=int(
                getattr(decision, "target_instances", desired_instances) or desired_instances
            ),
        )
        for idx in range(create_count):
            raw_handoff_plan = (
                runtime_handoff_plans[idx]
                if runtime_handoff_plans and idx < len(runtime_handoff_plans)
                else None
            )
            handoff_plan = dict(raw_handoff_plan or {})
            reserved_device_id = self._select_dedicated_device_id()
            if reserved_device_id is None:
                break
            pending_sequence_id = int(
                getattr(self, "_next_pending_scale_up_sequence", 0) or 0
            )
            self._next_pending_scale_up_sequence = pending_sequence_id + 1
            pending_sequences.add(pending_sequence_id)
            pending_device_ids.add(int(reserved_device_id))
            if handoff_plan:
                handoff_plan["_pending_scaleup_sequence"] = pending_sequence_id
            task = asyncio.create_task(
                self._execute_background_scale_up(
                    result=result,
                    coord_enabled=coord_enabled,
                    decision_snapshot=decision_snapshot,
                    current_instances=current_instances,
                    request_index=request_index,
                    completed_request_count=completed_request_count,
                    queue_visible_request_count=queue_visible_request_count,
                    arrived_request_count=arrived_request_count,
                    handoff_plan=handoff_plan,
                    reserved_device_id=reserved_device_id,
                    pending_sequence_id=pending_sequence_id,
                )
            )
            tasks.add(task)
            task.add_done_callback(self._handle_pending_scale_up_task_done)
            scheduled += 1
        return scheduled

    async def _wait_for_pending_scale_up_tasks(self) -> None:
        while True:
            tasks = list(getattr(self, "_pending_scale_up_tasks", set()) or [])
            if not tasks:
                if getattr(self, '_ieee_scale_failure', None) is not None:
                    raise RuntimeError('IEEE activation failed; no blind control-loop retry') from self._ieee_scale_failure
                return
            await asyncio.gather(*tasks, return_exceptions=True)
            if self._pending_scale_up_count() <= 0:
                if getattr(self, '_ieee_scale_failure', None) is not None:
                    raise RuntimeError('IEEE activation failed; no blind control-loop retry') from self._ieee_scale_failure
                return

    async def _ensure_min_instances(self, coord_enabled: bool) -> None:
        if self.instance_pool is None:
            return
        if hasattr(self, '_ieee_initial_deployment'):
            if getattr(self, '_ieee_scale_failure', None) is not None:
                raise RuntimeError('IEEE initial activation failed') from self._ieee_scale_failure
            pending = sum(not task.done() for task in self._ieee_initial_tasks)
            if self.instance_pool.count() + pending < self.instance_pool.min_instances:
                raise RuntimeError('IEEE initial pool lost an owned activation')
            return  # First ready may serve while other initial runtimes load.
        while self.instance_pool.count() < self.instance_pool.min_instances:
            use_dedicated = (
                self._instance_mode in ("dedicated", "auto")
                and getattr(self, "engine_factory", None) is not None
            )
            if use_dedicated:
                added = await self._add_dedicated_instance_slot(coord_enabled)
                # When auto/dedicated mode explicitly asks for a new physical runtime,
                # do not silently fall back to a shared slot. That would make the
                # instance count diverge from the actual runtime count and corrupt
                # scale-out metrics.
                if not added:
                    break
            else:
                added = await self._add_shared_instance_slot(coord_enabled)
                if not added:
                    break

    async def _scale_up_instance_pool(
        self,
        coord_enabled: bool,
        *,
        target_instances: Optional[int] = None,
        runtime_handoff_plans: Optional[List[Dict[str, Any]]] = None,
    ) -> Any:
        if self.instance_pool is None or self.instance_pool.count() >= self.instance_pool.max_instances:
            return None if target_instances is None and runtime_handoff_plans is None else []
        legacy_return_shape = target_instances is None and runtime_handoff_plans is None
        desired_instances = (
            self.instance_pool.count() + 1
            if target_instances is None
            else min(
                self.instance_pool.max_instances,
                max(self.instance_pool.count() + 1, int(target_instances or 0)),
            )
        )
        create_count = max(0, desired_instances - self.instance_pool.count())
        if create_count <= 0:
            return None if legacy_return_shape else []
        use_dedicated = (
            self._instance_mode in ("dedicated", "auto")
            and getattr(self, "engine_factory", None) is not None
        )
        scale_events: List[Dict[str, Any]] = []
        if runtime_handoff_plans:
            consume_plan = getattr(self._stack, "consume_scaleup_gpu_plan", None) if self._stack is not None else None
            if callable(consume_plan):
                try:
                    consume_plan()
                except Exception:
                    pass
        if use_dedicated:
            for idx in range(create_count):
                handoff_plan = runtime_handoff_plans[idx] if runtime_handoff_plans and idx < len(runtime_handoff_plans) else None
                try:
                    scale_event = await self._add_dedicated_instance_slot(
                        coord_enabled,
                        handoff_plan=handoff_plan,
                        activation_kind='natural_scaleout',
                    )
                except TypeError:
                    if getattr(self, '_routing_policy', None) == 'ieee_confirmed':
                        raise  # Never restart a partly-created IEEE runtime as a legacy retry.
                    scale_event = await self._add_dedicated_instance_slot(coord_enabled)
                if not scale_event:
                    break
                scale_events.append(scale_event)
            if legacy_return_shape:
                return scale_events[0] if scale_events else None
            return scale_events
        if self._instance_mode != "dedicated":
            for _ in range(create_count):
                scale_event = await self._add_shared_instance_slot(coord_enabled)
                if not scale_event:
                    break
                scale_events.append(scale_event)
            if legacy_return_shape:
                return scale_events[0] if scale_events else None
            return scale_events
        return None if legacy_return_shape else []

    def _register_scale_up_event(
        self,
        result: ScenarioResult,
        *,
        decision: Any,
        current_instances: int,
        request_index: int,
        completed_request_count: Optional[int] = None,
        queue_visible_request_count: Optional[int] = None,
        submitted_request_count: Optional[int] = None,
        arrived_request_count: Optional[int] = None,
        scale_event: Dict[str, Any],
    ) -> None:
        effective_queue_visible_request_count = (
            queue_visible_request_count
            if queue_visible_request_count is not None
            else arrived_request_count
            if arrived_request_count is not None
            else submitted_request_count
        )
        event = {
            "timestamp": time.time(),
            "event_type": scale_event.get("event_type", "scale_up"),
            "reason": getattr(decision, "reason", "") or "rps/queue",
            "current_instances": current_instances,
            "target_instances": getattr(decision, "target_instances", current_instances),
            "actual_instances": self.instance_pool.count() if self.instance_pool else getattr(decision, "target_instances", current_instances),
            "request_index": request_index,
            "instance_id": scale_event.get("instance_id"),
            "device_id": scale_event.get("device_id"),
            "runtime_kind": scale_event.get("runtime_kind"),
        }
        if effective_queue_visible_request_count is not None:
            event["queue_visible_request_count"] = max(
                0, int(effective_queue_visible_request_count or 0)
            )
        if submitted_request_count is not None:
            event["submitted_request_count"] = max(
                0, int(submitted_request_count or 0)
            )
        if completed_request_count is not None:
            event["completed_request_count"] = max(
                0, int(completed_request_count or 0)
            )
        if arrived_request_count is not None:
            event["arrived_request_count"] = max(
                0, int(arrived_request_count or 0)
            )
        for key in (
            "cold_start_latency_ms",
            "runtime_startup_latency_ms",
            "warmed_adapters",
            "activation_id", "activation_kind", "handoff_plan_sha256",
            "engine_activation_ms", "preparation_state",
        ):
            if key in scale_event:
                event[key] = scale_event.get(key)
        if getattr(self, '_routing_policy', None) == 'ieee_confirmed':
            handoff_plan, preload_budget = {}, {}  # Never attach a stale legacy prefix to a real IEEE epoch.
        else:
            handoff_plan = dict(scale_event.get("handoff_plan") or getattr(self, "_last_scale_up_handoff_plan", {}) or {})
            preload_budget = dict(scale_event.get("preload_budget") or getattr(self, "_last_scale_up_preload_budget", {}) or {})
        if handoff_plan:
            planned_adapters = list(handoff_plan.get("planned_adapters", []) or [])
            ordered_handoff_adapters = list(
                handoff_plan.get("ordered_handoff_adapters", []) or []
            )
            event["planned_adapters"] = planned_adapters
            event["ordered_handoff_adapters"] = ordered_handoff_adapters
            event["warmup_plan_adapter_count"] = len(planned_adapters)
            for key in (
                "queue_at_ready_request_count",
                "queue_at_ready_adapter_count",
                "first_service_request_count",
                "first_service_adapter_count",
                "first_service_scanned_request_count",
                "initial_admission_request_budget",
                "projected_arrived_request_count",
                "incumbent_started_request_count",
                "configured_max_concurrent_loads",
                "effective_initial_warmup_parallelism",
            ):
                if key in handoff_plan:
                    event[key] = int(handoff_plan.get(key, 0) or 0)
            for key in ("bootstrap_latency_ms", "plan_load_latency_ms", "ready_delay_ms"):
                if key in handoff_plan:
                    event[key] = float(handoff_plan.get(key, 0.0) or 0.0)
        if preload_budget:
            if preload_budget.get("mode") is not None:
                event["budget_mode"] = str(preload_budget.get("mode") or "")
            for key in (
                "capacity_bytes",
                "exact_prefix_bytes",
                "live_hotset_bytes",
                "recent_working_set_bytes",
                "target_headroom_bytes",
            ):
                if key in preload_budget:
                    event[key] = int(preload_budget.get(key, 0) or 0)
        result.scale_up_events.append(event)
        result.scale_up_events.sort(
            key=lambda item: int(
                item.get(
                    "queue_visible_request_count",
                    item.get(
                        "arrived_request_count",
                        item.get("submitted_request_count", item.get("request_index", 0)),
                    ),
                )
                or 0
            )
        )
        self._live_scale_up_events = result.scale_up_events
        self._last_live_scale_up_completed_at = time.perf_counter()
        instance_id = event.get("instance_id")
        if instance_id and event.get("runtime_kind") == "dedicated":
            self._scaleup_runtime_instance_ids.add(str(instance_id))

    def _request_scaleup_affected(
        self,
        *,
        slot: Optional[Any],
        adapter_id: Optional[str],
        cache_tier: Optional[str],
    ) -> bool:
        if slot is None or not adapter_id:
            return False
        instance_id = getattr(slot, "instance_id", None)
        if not instance_id or instance_id not in self._scaleup_runtime_instance_ids:
            return False
        return str(cache_tier or "remote").lower() != "gpu"

    def _begin_scaleup_runtime_request_labels(
        self,
        *,
        slot: Optional[Any],
        adapter_id: Optional[str],
        cache_tier: Optional[str],
    ) -> Dict[str, Any]:
        labels = {
            "on_scaleup_runtime": False,
            "scaleup_affected": False,
            "scaleup_first_service": False,
            "scaleup_planned_adapter_match": False,
        }
        if slot is None:
            return labels
        instance_id = str(getattr(slot, "instance_id", None) or "")
        if not instance_id or instance_id not in getattr(self, "_scaleup_runtime_instance_ids", set()):
            return labels

        labels["on_scaleup_runtime"] = True
        if not adapter_id:
            return labels

        cache_tier_name = str(cache_tier or "remote").lower()
        labels["scaleup_affected"] = cache_tier_name != "gpu"

        handoff_plan = self._scaleup_runtime_handoff_plan(instance_id)
        planned_adapters = {
            str(item)
            for item in list(handoff_plan.get("planned_adapters", []) or [])
            if item
        }
        labels["scaleup_planned_adapter_match"] = str(adapter_id) in planned_adapters

        ordinals = getattr(self, "_scaleup_runtime_lora_request_ordinals", None)
        if ordinals is None:
            ordinals = {}
            self._scaleup_runtime_lora_request_ordinals = ordinals
        lora_ordinal = max(0, int(ordinals.get(instance_id, 0) or 0))
        request_budget = max(
            0, int(handoff_plan.get("first_service_request_count", 0) or 0)
        )
        labels["scaleup_first_service"] = request_budget > 0 and lora_ordinal < request_budget
        ordinals[instance_id] = lora_ordinal + 1
        return labels

    async def _scale_down_one_instance(
        self,
        require_idle: bool = False,
        *,
        min_idle_s: Optional[float] = None,
    ) -> Optional[Dict[str, Any]]:
        if self.instance_pool is None or self.instance_pool.count() <= self.instance_pool.min_instances:
            return None
        if require_idle:
            candidate = self._select_scale_down_candidate_slot(min_idle_s=min_idle_s)
            if candidate is None:
                return None
            slots = [candidate]
        else:
            candidate = self._select_scale_down_candidate_slot(min_idle_s=0.0)
            if candidate is None:
                return None
            slots = [candidate]
        if not slots:
            return None
        selected_slot = slots[-1]
        if (
            int(getattr(selected_slot, "active_requests", 0) or 0) > 0
            or int(getattr(selected_slot, "load_queue_depth", 0) or 0) > 0
            or max(0, int(getattr(selected_slot, "runtime_forwarding_active", 0) or 0)) > 0
        ):
            return None
        removed = self.instance_pool.remove_instance(selected_slot.instance_id)
        await self._cleanup_removed_slot(
            removed,
            removal_reason="scale_down",
        )
        if removed is None:
            return None
        return {
            "event_type": "physical_scale_down" if getattr(removed, "owns_engine", False) else "logical_scale_down",
            "instance_id": removed.instance_id,
            "device_id": getattr(removed, "device_id", None),
            "runtime_kind": "dedicated" if getattr(removed, "owns_engine", False) else "shared",
            "scale_down_min_idle_s": (
                max(0.0, float(min_idle_s))
                if min_idle_s is not None
                else None
            ),
        }

    async def _cleanup_extra_instances(self) -> None:
        if self.instance_pool is None:
            return
        slots = [s.instance_id for s in self.instance_pool.get_slots() if s.instance_id != self._primary_instance_id]
        for instance_id in reversed(slots):
            removed = self.instance_pool.remove_instance(instance_id)
            await self._cleanup_removed_slot(
                removed,
                removal_reason="cleanup_extra_instances",
            )

    # ------------------------------------------------------------------
    # Phase 1: preload
    # ------------------------------------------------------------------

    async def preload(self):
        if getattr(self, '_initial_runtime_pending', False):
            # Disabling handoff/preload does not disable runtime activation.
            await self._preload_full_stack()
            return
        if self.baseline_type in ("cold_start", "slora_style", "serverlessllm",
                                   "backbone_only", "lru_nvme"):
            return
        if not self.preload_cfg.get("enabled", True):
            # Elastic-only/readiness-only variants still need the stack's
            # registry and autoscaler, but must not create any initial tier or
            # handoff state that would contaminate the ablation.
            if self._stack is not None:
                self._stack._ensure_registered()
            return
        # faaslora_full + transformers: 子进程内做 preload，主进程跳过（避免未 init 的 engine 被 warmup 调用）
        if self.baseline_type == "faaslora_full" and getattr(self.engine, "backend", "") == "transformers":
            print("    Preload: done in subprocess.")
            return

        if self._stack is not None:
            await self._preload_full_stack()
            return

        min_h = self.preload_cfg.get("min_hotness", 0.4)
        # Clean stale nvme_cache to ensure adapters match current model
        if self.nvme_dir.exists():
            shutil.rmtree(self.nvme_dir, ignore_errors=True)
        self.nvme_dir.mkdir(parents=True, exist_ok=True)

        hot = {a: i for a, i in self.adapter_info.items()
               if i.get("hotness", 0) >= min_h}
        print(f"    Preloading {len(hot)} hot adapters (hotness ? {min_h}) ...")
        total_io = 0.0

        for aid, info in sorted(hot.items(), key=lambda x: -x[1].get("hotness", 0)):
            dst = self.nvme_dir / aid
            if self._remote_artifact_client is None and not (self.remote_dir / aid).exists():
                continue
            if dst.exists():
                self._nvme_cache[aid] = str(dst)
                continue
            ok, io_ms = await self._materialize_remote_adapter_async(aid, dst)
            if ok:
                self._nvme_cache[aid] = str(dst)
                total_io += io_ms
        if self.instance_pool is not None:
            for slot in self.instance_pool.get_slots():
                self._prime_slot_cache_view(slot, include_gpu=self._slot_should_include_gpu(slot))

        # GPU warmup
        if self.baseline_type in ("faaslora_no_coord", "faaslora_full"):
            await self._warmup_gpu()

        print(f"    Preload done  total_io={total_io:.0f}ms  "
              f"nvme_cached={len(self._nvme_cache)}")

    def _require_ieee_full_qualification(self):
        # No configuration switch bypasses this remaining integration gate.
        # Initial activation can be tested independently, but is not sufficient
        # to qualify joint replacement, measured profiles or physical accounting.
        raise RuntimeError('IEEE Full preparation execution is not qualified: '
            'legacy priority/warmup is forbidden; use measured planning and owned movement')

    async def _start_ieee_initial_deployment(self):
        """Start the initial physical pool through the same owner as scale-out.

        Return on first ready, not last ready. External arrival origin is never
        changed here. Pending initial members remain owned by the live control
        and shutdown paths, and retain their initial category after business t0.
        """
        if (not getattr(self, '_initial_runtime_pending', False)
                or self.instance_pool is None or self.instance_pool.count()
                or getattr(self, '_ieee_initial_tasks', None)
                or self._routing_policy != 'ieee_confirmed'
                or self.engine_factory is None):
            raise ValueError('IEEE initial deployment requires an empty owned pending pool')
        devices = []
        try:
            for _ in range(self.instance_pool.min_instances):
                device = self._select_dedicated_device_id()
                if device is None:
                    raise ValueError('insufficient physical devices for the initial pool')
                self._pending_scale_up_device_ids.add(device)
                devices.append(device)
        except BaseException:
            self._pending_scale_up_device_ids.difference_update(devices)
            raise
        from faaslora.clock import local_monotonic_clock_id
        record = self._ieee_initial_deployment = dict(state='initializing',
            trigger_at=time.monotonic(), clock_id=local_monotonic_clock_id(),
            devices=list(devices), ready_events=[], failures=[])

        async def activate(device):
            try:
                event = await self._add_dedicated_instance_slot(self._coordination_enabled,
                    reserved_device_id=device, activation_kind='initial')
                if event is None:
                    raise RuntimeError('initial physical activation returned no runtime')
                record['ready_events'].append(event)
                return event
            except BaseException as exc:
                # Never reuse a failed startup's device merely because its
                # controller task is terminal. Actual exit proof is separate.
                self._failed_runtime_device_ids.add(device)
                record['failures'].append(dict(device_id=device, error_type=type(exc).__name__))
                record['state'] = 'cancelled' if isinstance(exc, asyncio.CancelledError) else 'failed'
                raise
            finally:
                self._pending_scale_up_device_ids.discard(device)

        self._ieee_initial_tasks = [asyncio.create_task(activate(device)) for device in devices]
        for task in self._ieee_initial_tasks:
            self._pending_scale_up_tasks.add(task)
            task.add_done_callback(self._handle_pending_scale_up_task_done)
        try:
            done, _ = await asyncio.wait(self._ieee_initial_tasks,
                                        return_when=asyncio.FIRST_COMPLETED)
            # Surface every already-finished failure; do not pick a lucky
            # successful sibling to conceal an incomplete initial pool.
            for task in self._ieee_initial_tasks:
                if task in done:
                    task.result()
            first = record['ready_events'][0]
            slot = self.instance_pool.get_slot(first['instance_id'])
            if slot is None:
                raise RuntimeError('initial ready event has no owned pool member')
            self._primary_instance_id = slot.instance_id
            self.engine, self.coordinator = slot.engine, slot.coordinator
            self._initial_runtime_pending = False
            record.update(state='serving', first_ready_at=time.monotonic(),
                          primary_instance_id=slot.instance_id)
        except BaseException as exc:
            record.update(state='cancelled' if isinstance(exc, asyncio.CancelledError) else 'failed',
                          error_type=type(exc).__name__)
            # The caller owns the pool even after failure. Join each startup's
            # existing cancellation fence, then retire any published siblings.
            cleanup = asyncio.create_task(self._shutdown_instance_pool())
            while True:
                try:
                    await asyncio.shield(cleanup)
                    break
                except asyncio.CancelledError:
                    if cleanup.cancelled():
                        raise
            raise

    async def _preload_full_stack(self):
        """C1 完整：三层级联预加载 远端→硬盘(NVMe)→内存(HOST)→GPU，最热在 GPU、次热在内存、再次在硬盘。"""
        if getattr(self, '_routing_policy', None) == 'ieee_confirmed':
            self._require_ieee_full_qualification()
            await self._start_ieee_initial_deployment()
            return
        await self._stack.start()
        if self.nvme_dir.exists():
            if not self._stack.residency_manager._delete_path(str(self.nvme_dir)):
                raise RuntimeError('initial NVMe reset conflicts with live physical ownership')
        self.nvme_dir.mkdir(parents=True, exist_ok=True)
        host_dir = getattr(self._stack, "host_dir", None)
        if host_dir and host_dir.exists():
            if not self._stack.residency_manager._delete_path(str(host_dir)):
                raise RuntimeError('initial HOST reset conflicts with live physical ownership')
        if host_dir:
            host_dir.mkdir(parents=True, exist_ok=True)

        async def copy_fn(aid: str, src: str, dst: str):
            src_path = Path(src)
            remote_src = (self._stack.remote_dir / aid).resolve()
            if src_path.resolve() == remote_src:
                ok, io_ms = await self._materialize_remote_adapter_async(
                    aid, Path(dst)
                )
            else:
                target_tier = self._stack._path_tier_hint(dst)
                if target_tier not in ('host', 'nvme'):
                    raise ValueError('preload copy destination is outside managed tiers')
                started = time.perf_counter()
                if self.model_cfg.get('ieee_gpu_references', False):
                    receipt = await self._materialize_confirmed_source_async(
                        aid, src_path, StorageTier(target_tier))
                    ok = receipt['state'] == 'published' and receipt['target_path'] == str(Path(dst).resolve())
                else:
                    copied = self._stack.residency_manager._materialize_into_tier_dir(
                        aid, str(src_path), StorageTier(target_tier))
                    ok = copied == str(dst)
                io_ms = (time.perf_counter() - started) * 1000
            return ok, io_ms

        self._stack._ensure_registered()
        total_io = 0.0

        # Stage 1: Remote → NVMe (disk)
        capacity_nvme = int(self.preload_cfg.get("nvme_capacity_mb", 20480) * 1024 * 1024)
        plan_nvme = self._stack.preloading_planner.generate_preloading_plan(
            target_tier=StorageTier.NVME,
            capacity_bytes=capacity_nvme,
            scaling_event={"type": "initial", "target_tier": "nvme", "capacity_bytes": capacity_nvme},
        )
        for aid in plan_nvme.selected_artifacts:
            src = self._stack.remote_dir / aid
            dst = self._stack.nvme_dir / aid
            if self._remote_artifact_client is None and not src.exists():
                continue
            ok, io_ms = await copy_fn(aid, str(src), str(dst))
            if ok:
                self._stack._nvme_paths[aid] = str(dst)
                self._stack.registry.update_artifact(aid, {"storage_path": str(dst)})
                await self._stack.residency_manager.admit_artifact(aid, StorageTier.NVME)
                total_io += io_ms
        self._nvme_cache = dict(self._stack._nvme_paths)
        if self.instance_pool is not None:
            for slot in self.instance_pool.get_slots():
                self._prime_slot_cache_view(slot, include_gpu=False)
        print(f"    Stage 1 (remote→NVMe): {len(plan_nvme.selected_artifacts)} adapters, total_io={total_io:.0f}ms")

        if not bool(getattr(self, "_hierarchical_residency_enabled", True)):
            # Mechanism 1 in the paper stops at hit-aware NVMe preparation plus
            # scale-out handoff.  HOST/GPU tier planning and online migration
            # belong to Mechanism 2 and must not leak into this cumulative row.
            preferred_gpu_adapters = self._scale_up_warmup_preferred_gpu_adapters()
            preload_capacity_bytes = self._scale_up_preload_capacity_bytes(
                preferred_gpu_adapters
            )
            plan_id = None
            if bool(getattr(self, "_scale_up_handoff_enabled", True)):
                plan_id = await self._stack.trigger_scaling_preload(
                    preload_capacity_bytes,
                    preferred_gpu_adapters=preferred_gpu_adapters,
                )
            print(
                "    Mechanism-1 boundary: NVMe preparation + scale-out "
                f"handoff only (plan_id={plan_id or 'none'}); HOST/GPU "
                "hierarchical migration disabled."
            )
            print(
                f"    Preload done  total_io={total_io:.0f}ms  "
                f"nvme={len(self._nvme_cache)}  host=0"
            )
            return

        # Stage 2: NVMe → HOST (memory)
        capacity_host = int(self.preload_cfg.get("host_capacity_mb", 4096) * 1024 * 1024)
        plan_host = self._stack.preloading_planner.generate_preloading_plan(
            target_tier=StorageTier.HOST,
            capacity_bytes=capacity_host,
            scaling_event={"type": "initial", "target_tier": "host", "capacity_bytes": capacity_host},
        )
        for aid in plan_host.selected_artifacts:
            src_path = self._stack._nvme_paths.get(aid)
            if not src_path or not Path(src_path).exists():
                continue
            dst = self._stack.host_dir / aid
            ok, io_ms = await copy_fn(aid, src_path, str(dst))
            if ok:
                self._stack._host_paths[aid] = str(dst)
                self._stack.registry.update_artifact(aid, {"storage_path": str(dst)})
                await self._stack.residency_manager.admit_artifact(aid, StorageTier.HOST)
                total_io += io_ms
        print(f"    Stage 2 (NVMe→HOST): {len(plan_host.selected_artifacts)} adapters")

        # Stage 3: HOST/NVMe → GPU (warmup hottest)
        warmup_h = self.preload_cfg.get("gpu_warmup_hotness", 0.6)
        async def gen_fn(prompt: str, path: str, aid: str):
            if hasattr(self.engine, "load_lora_to_gpu_and_measure"):
                load_ms, ok = await self.engine.load_lora_to_gpu_and_measure(path, aid)
                if ok:
                    self._stack.registry.update_artifact(
                        aid, {"last_load_time_ms": load_ms, "predicted_load_time_ms": load_ms},
                    )
                return load_ms, 0.0, 0
            ttft, _, _ = await self.engine.generate(
                prompt, path, aid, max_tokens=4, input_tokens=10, temperature=0.0
            )
            return ttft, 0.0, 0

        n = await self._stack.warmup_gpu(warmup_h, gen_fn)
        for aid in set(self._stack._host_paths) | set(self._stack._nvme_paths):
            if self.adapter_info.get(aid, {}).get("hotness", 0) >= warmup_h:
                self._gpu_warmed.add(aid)
        if self.instance_pool is not None:
            for slot in self.instance_pool.get_slots():
                self._prime_slot_cache_view(slot, include_gpu=self._slot_should_include_gpu(slot))
        print(f"    Stage 3 (→GPU warmup): {n} adapters (hotness>={warmup_h})")

        preferred_gpu_adapters = self._scale_up_warmup_preferred_gpu_adapters()
        preload_capacity_bytes = self._scale_up_preload_capacity_bytes(preferred_gpu_adapters)
        preload_budget = dict(getattr(self, "_last_scale_up_preload_budget", {}) or {})
        plan_id = None
        if bool(getattr(self, "_scale_up_handoff_enabled", True)):
            plan_id = await self._stack.trigger_scaling_preload(
                preload_capacity_bytes,
                preferred_gpu_adapters=preferred_gpu_adapters,
            )
        if plan_id:
            print(
                f"    Scale-up preload triggered (plan_id={plan_id}, "
                f"mode={preload_budget.get('mode', 'unknown')}, "
                f"budget={preload_capacity_bytes / (1024.0 * 1024.0):.1f}MB, "
                f"prefix={float(preload_budget.get('exact_prefix_bytes', 0) or 0) / (1024.0 * 1024.0):.1f}MB, "
                f"live_hotset={float(preload_budget.get('live_hotset_bytes', 0) or 0) / (1024.0 * 1024.0):.1f}MB, "
                f"working_set={float(preload_budget.get('recent_working_set_bytes', 0) or 0) / (1024.0 * 1024.0):.1f}MB, "
                f"headroom={float(preload_budget.get('target_headroom_bytes', 0) or 0) / (1024.0 * 1024.0):.1f}MB)"
            )
        print(f"    Preload done  total_io={total_io:.0f}ms  nvme={len(self._nvme_cache)}  host={len(getattr(self._stack, '_host_paths', {}))}")

    async def _warmup_engine_hot_set(
        self,
        engine: Any,
        coordinator: Optional[Any] = None,
        planned_aids: Optional[Collection[str]] = None,
    ) -> set:
        """对新加入的实例 engine 做与主实例相同的热点 warmup（HOST/NVMe→GPU）。"""
        if self._stack is None:
            return set()
        paths = getattr(self._stack, "_host_paths", {}) or getattr(self._stack, "_nvme_paths", None)
        if not paths:
            return set()
        if planned_aids is None:
            planned_aids = list(getattr(self._stack, "consume_scaleup_gpu_plan", lambda: [])())
        else:
            planned_aids = list(planned_aids)
        hot_aids: List[str] = []
        if planned_aids:
            # Keep execution aligned with the instance-scoped scale-up plan. When a
            # live frontier has already been selected under the current budget,
            # appending every globally hot adapter widens cold-start work beyond the
            # plan and breaks the causal link between scale-up ranking, budget, and
            # observed warmup coverage.
            ordered = []
            seen = set()
            for aid in planned_aids:
                if aid in seen:
                    continue
                seen.add(aid)
                ordered.append(aid)
            hot_aids = ordered
        if not hot_aids or not hasattr(engine, "load_lora_to_gpu_and_measure"):
            return set()
        warmed: set = set()
        admission_rejects: List[str] = []
        warmup_failures: List[str] = []
        for aid in hot_aids:
            path = getattr(self._stack, "_host_paths", {}).get(aid) or getattr(self._stack, "_nvme_paths", {}).get(aid)
            if not path:
                continue
            tier = "host" if aid in getattr(self._stack, "_host_paths", {}) else "nvme"
            size_mb = float(self.adapter_info.get(aid, {}).get("size_mb", 30.0))
            if (
                coordinator is not None
                and getattr(coordinator, "effective_capacity_admission_enabled", False)
                and getattr(coordinator, "evaluate_gpu_admission", None)
            ):
                decision = coordinator.evaluate_gpu_admission(
                    aid,
                    size_mb,
                    tier=tier,
                    utility_override=1.0,
                )
                if not decision.get("admit", False):
                    admission_rejects.append(
                        f"{aid}(cap={float(decision.get('effective_capacity_mb', 0.0) or 0.0):.1f}MB,"
                        f" pressure={float(decision.get('pressure', 0.0) or 0.0):.2f},"
                        f" utility={float(decision.get('utility', 0.0) or 0.0):.2f})"
                    )
                    continue
            try:
                load_ms, ok = await engine.load_lora_to_gpu_and_measure(path, aid)
                if ok and self._stack.registry is not None:
                    self._stack.registry.update_artifact(
                        aid, {"last_load_time_ms": load_ms, "predicted_load_time_ms": load_ms}
                    )
                    if coordinator is not None and getattr(coordinator, "_residency_manager", None) is None:
                        await coordinator._mark_resident(aid, size_mb)
                    warmed.add(aid)
            except Exception as exc:
                warmup_failures.append(f"{aid}: {exc}")
        if admission_rejects:
            sample = ", ".join(admission_rejects[:3]) + ("..." if len(admission_rejects) > 3 else "")
            print(
                f"    [Warmup] admission rejected {len(admission_rejects)} adapters ({sample})",
                flush=True,
            )
        if warmup_failures:
            sample = ", ".join(warmup_failures[:3]) + ("..." if len(warmup_failures) > 3 else "")
            print(
                f"    [Warmup] load failed for {len(warmup_failures)} adapters ({sample})",
                flush=True,
            )
        return warmed

    async def _warmup_gpu(self):
        """Warm hot LoRA adapters into GPU VRAM via a short inference call."""
        warmup_h = self.preload_cfg.get("gpu_warmup_hotness", 0.6)
        hot_adapters = [(aid, path) for aid, path in self._nvme_cache.items()
                        if self.adapter_info[aid].get("hotness", 0) >= warmup_h]
        print(f"    GPU warmup: loading {len(hot_adapters)} hot LoRA adapters "
              f"(hotness >= {warmup_h}) into GPU memory ...")

        for aid, local_path in hot_adapters:
            h = self.adapter_info[aid].get("hotness", 0)
            try:
                ttft, _, _ = await self.engine.generate(
                    "Hi", local_path, aid, max_tokens=4, input_tokens=10, temperature=0.0
                )
                self._gpu_warmed.add(aid)
                self.coordinator._resident_loras[aid] = self.adapter_info[aid].get("size_mb", 30)
                self._mark_slot_adapter_tier(
                    self.instance_pool.get_slot(self._primary_instance_id) if self.instance_pool else None,
                    aid,
                    "gpu",
                )
                print(f"      OK {aid} (hotness={h:.2f}) -> GPU ready  [{ttft:.0f}ms]")
            except Exception as exc:
                print(f"      FAIL {aid} warmup error: {exc}")

    # ------------------------------------------------------------------
    # Phase 2: run workload
    # ------------------------------------------------------------------

    def _configure_external_replay(self, supplied=None):
        self._external_replay = None
        launch_receipt = os.environ.get('FAASLORA_TC_LAUNCH_RECEIPT')
        if launch_receipt:
            context = json.loads(Path(launch_receipt).read_text()).get('external_replay')
            if context is not None:
                if context['tiny_witness'] or int(self.wl_cfg.get('multi_cycle_phases', 1)) != 1:
                    raise ValueError('model replay requires a continuous full-trace origin')
                if supplied is None or supplied.context != context:
                    raise RuntimeError('external ingress must start before model initialization')
                frozen = supplied.plan
                if [t.request_id for t in self.traces] != [e.request_id for e in frozen.entries]:
                    raise ValueError('service request map differs from external replay')
                supplied.raise_if_failed()
                self._external_replay = supplied
                self._external_replay_offsets = {e.request_id: e.offset_s for e in frozen.entries}
        if supplied is not None and self._external_replay is None:
            raise ValueError('supplied replay is not bound to this guarded launch')

    async def run(self) -> Tuple[ScenarioResult, Dict]:
        # 按场景设置 transformers 后端 GPU 内最多 LoRA 数（贴近真实系统）
        coord_enabled = (
            self.baseline_type == "faaslora_full" and self._coordination_enabled
        )
        if self.engine.backend == "transformers":
            self.engine.set_hf_max_adapters_for_scenario(
                self.baseline_type, self.coord_cfg, self.engine.model_cfg
            )
        self._assert_clean_gpu_environment(context="scenario_start", force=True)
        await self._attach_ieee_file_pressure(self.engine)
        await self._ensure_min_instances(coord_enabled)
        concurrency = self.wl_cfg.get("concurrency", 8)
        max_tokens  = self.wl_cfg.get("max_tokens", 128)
        temperature = self.wl_cfg.get("temperature", 0.7)
        # E1: 多周期
        multi_cycle_phases = int(self.wl_cfg.get("multi_cycle_phases", 1))
        idle_between_s = float(self.wl_cfg.get("idle_between_phases_s", 2.0))

        result = ScenarioResult(
            scenario_name=self.name,
            baseline_type=self.baseline_type,
            total=len(self.traces),
            ttft_slo_ms=self._ttft_slo_ms,
        )
        self._live_scale_eval_last_at = 0.0
        self._live_scale_overrides = None
        self._live_last_print_time = 0.0
        self._live_last_print_completed = -1
        self._run_started_at = time.perf_counter()
        self._begin_instance_lifecycle_tracking()
        self._dispatch_admitted_requests = 0
        self._dispatch_admission_condition = None
        self._runtime_slot_capacity_condition = None
        request_plan_cache = self._prepare_request_execution_plan_cache(
            self.engine,
            self.traces,
            max_tokens,
        )
        replay_t0 = (self._external_replay.context['replay_t0_s']
                     if self._external_replay is not None else time.perf_counter())

        async def run_one(
            i: int,
            trace: RequestTrace,
            *,
            arrival_released_at: Optional[float] = None,
        ):
            scheduled_offset_s = self._scheduled_offset(trace)
            scheduled_arrival_at = replay_t0 + scheduled_offset_s
            if arrival_released_at is None:
                await self._await_trace_arrival(trace, replay_t0)
                arrival_released_at = time.perf_counter()
            arrival_release_lateness_ms = max(
                0.0,
                (float(arrival_released_at) - float(scheduled_arrival_at)) * 1000.0,
            )
            if self._external_replay is None:
                self._observe_live_arrived_lora(getattr(trace, "adapter_id", None))
                self._observe_live_waiting_trace(trace)
            if self._external_replay is None and trace.adapter_id and self._stack is not None:
                # Eq. (4) observes arrivals, including requests waiting for
                # admission or a remote fetch. Backend retries do not come here.
                self._stack.record_arrival(trace.adapter_id)
            # Let the dispatcher keep releasing due trace arrivals before this
            # request starts the heavier dispatch/runtime path on the shared
            # control loop.
            await asyncio.sleep(0)
            out = None
            try:
                admission_start_at = time.perf_counter()
                await self._acquire_dispatch_admission()
                admitted_at = time.perf_counter()
                dispatch_window_wait_ms = max(
                    0.0,
                    (admitted_at - arrival_released_at) * 1000.0,
                )
                dispatch_admission_wait_ms = max(
                    0.0,
                    (admitted_at - scheduled_arrival_at) * 1000.0,
                )
                try:
                    request_plan = request_plan_cache.get(
                        str(getattr(trace, "request_id", "") or "")
                    )
                    out = await self._exec_request(
                        trace,
                        max_tokens,
                        temperature,
                        request_plan=request_plan,
                        dispatch_admission_wait_ms=dispatch_admission_wait_ms,
                        dispatch_window_wait_ms=dispatch_window_wait_ms,
                        arrival_release_lateness_ms=arrival_release_lateness_ms,
                        scheduled_arrival_offset_s=scheduled_offset_s,
                        admission_start_offset_s=max(0.0, admission_start_at - replay_t0),
                        admitted_offset_s=max(0.0, admitted_at - replay_t0),
                        arrival_released_offset_s=max(0.0, arrival_released_at - replay_t0),
                    )
                    if self._external_replay is not None:
                        out.arrival_contract = 'external_frozen_trace_v1'
                        out.external_arrival_timing = dict(self._external_replay.records[trace.request_id])
                    return out
                finally:
                    self._release_live_started_lora(getattr(trace, "adapter_id", None))
                    await self._release_dispatch_admission()
            finally:
                self._release_live_waiting_trace(trace)
                self._release_live_arrived_lora(getattr(trace, "adapter_id", None))
                deployment = getattr(self, '_physical_deployment', None)
                if deployment is not None:
                    failure = sys.exc_info()[0]
                    deployment.terminal(trace.request_id, at=time.monotonic(), result=out,
                        error_type=failure.__name__ if failure is not None else None,
                        interrupted=failure is not None and issubclass(failure, asyncio.CancelledError))

        if multi_cycle_phases <= 1:
            # substrate_v2: 连续到达 + 共享等待队列；控制面按周期观察在线队列。
            t0 = time.perf_counter()
            all_raw, _tb1 = await self._run_continuous_observed(
                traces=list(self.traces),
                trace_start_index=0,
                replay_t0=replay_t0,
                run_one_fn=run_one,
                completed_before_window=0,
                total_requests=len(self.traces),
                result=result,
                coord_enabled=coord_enabled,
                request_plans=request_plan_cache,
            )
            elapsed = time.perf_counter() - t0
            result.requests.extend(all_raw)
            await self._wait_for_pending_scale_up_tasks()
            if self.baseline_type in ("faaslora_full", "faaslora_no_coord"):
                if self._should_trigger_scale_down():
                    warm_size = self._get_dynamic_warm_pool_size()
                    await self._trigger_scale_down_all_instances(warm_pool_size=warm_size)
                scale_down_event = await self._scale_down_one_instance()
                if scale_down_event:
                    result.scale_down_events += 1
                    result.scale_down_event_log.append({
                        "timestamp": time.time(),
                        "request_index": len(all_raw),
                        "queue_visible_request_count": len(all_raw),
                        "arrived_request_count": len(all_raw),
                        **scale_down_event,
                    })
        else:
            # E1: 多周期 scale-up → 请求 → scale-down → 再 scale-up
            phase_chunks = []
            step = max(1, len(self.traces) // multi_cycle_phases)
            for p in range(multi_cycle_phases):
                start = p * step
                end = len(self.traces) if p == multi_cycle_phases - 1 else (p + 1) * step
                phase_chunks.append(self.traces[start:end])
            total_elapsed = 0.0
            for phase_idx, phase_traces in enumerate(phase_chunks):
                if not phase_traces:
                    continue
                print(f"    [Phase {phase_idx + 1}/{multi_cycle_phases}] {len(phase_traces)} requests ...", flush=True)
                prev_warm_hits = self._warm_pool_hits_total() if self.instance_pool else self.coordinator.get_summary_metrics().get("warm_pool_hits", 0)
                t0 = time.perf_counter()
                global_offset = sum(len(phase_chunks[k]) for k in range(phase_idx))
                phase_raw, _tb1 = await self._run_continuous_observed(
                    traces=list(phase_traces),
                    trace_start_index=global_offset,
                    replay_t0=replay_t0,
                    run_one_fn=run_one,
                    completed_before_window=global_offset,
                    total_requests=len(self.traces),
                    result=result,
                    coord_enabled=coord_enabled,
                    phase_label=f"phase{phase_idx + 1}",
                    request_plans=request_plan_cache,
                )
                phase_elapsed = time.perf_counter() - t0
                total_elapsed += phase_elapsed
                result.requests.extend(phase_raw)
                await self._wait_for_pending_scale_up_tasks()
                phase_ok = [r for r in phase_raw if not isinstance(r, Exception) and getattr(r, "success", True)]
                phase_ttft = sum(getattr(r, "ttft_ms", 0) for r in phase_ok) / len(phase_ok) if phase_ok else 0.0
                after_warm_hits = self._warm_pool_hits_total() if self.instance_pool else self.coordinator.get_summary_metrics().get("warm_pool_hits", 0)
                phase_warm_hits = after_warm_hits - prev_warm_hits
                result.multi_cycle_phase_results.append({
                    "phase": phase_idx,
                    "completed": len(phase_ok),
                    "total": len(phase_traces),
                    "elapsed_sec": phase_elapsed,
                    "avg_ttft_ms": phase_ttft,
                    "warm_pool_hits": phase_warm_hits,
                })
                if phase_idx < multi_cycle_phases - 1:
                    if self._should_trigger_scale_down():
                        warm_size = self._get_dynamic_warm_pool_size()
                        warm_pool = await self._trigger_scale_down_all_instances(warm_pool_size=warm_size)
                        result.warm_pool_retained_after_phase.append(len(warm_pool))
                    else:
                        result.warm_pool_retained_after_phase.append(0)
                    scale_down_event = await self._scale_down_one_instance()
                    if scale_down_event:
                        result.scale_down_events += 1
                        result.scale_down_event_log.append({
                            "timestamp": time.time(),
                            "request_index": global_offset + len(phase_raw),
                            "queue_visible_request_count": global_offset + len(phase_raw),
                            "arrived_request_count": global_offset + len(phase_raw),
                            **scale_down_event,
                        })
                    if idle_between_s > 0:
                        await asyncio.sleep(idle_between_s)
            elapsed = total_elapsed

        await self._cancel_runtime_gpu_forward_tasks()
        coord_views = self._coordinator_metric_views()
        coord_m = _merge_coordinator_metrics(coord_views) if coord_views else {}
        result.aggregate(elapsed, coord_m)
        self._attach_control_path_background_metrics(result)
        await self._cleanup_extra_instances()
        return result, coord_m

    @staticmethod
    @staticmethod
    def _make_isolated_cmd(cmd: list) -> list:
        """Return the command as-is.

        We previously wrapped with systemd-run --scope, but on systemd 249 the
        scope cgroup appears to have an undocumented short memory-pressure
        duration (< 30 s), causing oomd to kill the subprocess even when 114 GB
        of RAM is available.  The subprocess already sets oom_score_adj=900 at
        startup so that, should systemd-oomd fire for the shared session cgroup,
        it kills the subprocess (highest oom_score) rather than the main process.
        """
        return cmd

    def run_sync_backbone_only(self) -> Tuple[ScenarioResult, Dict]:
        """backbone_only + transformers: 直接内联推理，避免子进程被 systemd-oomd 误杀。"""
        max_tokens = self.wl_cfg.get("max_tokens", 128)
        temperature = self.wl_cfg.get("temperature", 0.7)
        top_p = self.wl_cfg.get("top_p", 0.9)
        model_path = self.engine.model_cfg.get("name", "")
        result = ScenarioResult(
            scenario_name=self.name,
            baseline_type=self.baseline_type,
            total=len(self.traces),
            ttft_slo_ms=self._ttft_slo_ms,
        )
        self._live_last_print_time = 0.0
        self._live_last_print_completed = -1
        self._run_started_at = time.perf_counter()
        self._begin_instance_lifecycle_tracking()
        request_plans = [
            self._prepare_request_execution_plan(self.engine, trace, max_tokens)
            for trace in self.traces
        ]
        inline_max_input_len = int(self.engine.model_cfg.get("max_input_len", 0) or 0)
        inline_max_output_cap = int(
            self.engine.model_cfg.get("max_output_tokens_cap", 0) or 0
        )

        requests_data = [
            {
                "prompt": request_plans[i].prompt,
                "max_tokens": request_plans[i].max_tokens,
                "temperature": temperature,
                "top_p": top_p,
            }
            for i, t in enumerate(self.traces)
        ]

        try:
            _scripts_dir = str(REPO_ROOT / "scripts")
            if _scripts_dir not in sys.path:
                sys.path.insert(0, _scripts_dir)
            from run_transformers_subprocess import run_backbone_inline
            inline_t0 = time.perf_counter()
            inline_ret = run_backbone_inline(
                model_path=model_path,
                requests=requests_data,
                max_input_len=inline_max_input_len,
                max_output_cap=inline_max_output_cap,
                return_stats=True,
            )
            inline_elapsed = time.perf_counter() - inline_t0
            if isinstance(inline_ret, tuple) and len(inline_ret) == 2:
                out_list, inline_stats = inline_ret
            else:
                out_list, inline_stats = inline_ret, {}
            if len(out_list) != len(self.traces):
                raise RuntimeError(
                    f"Backbone inline returned {len(out_list)} results, expected {len(self.traces)}"
                )
        except Exception as e:
            import traceback
            traceback.print_exc()
            print(f"    [WARN] Backbone inline inference failed ({e}).", flush=True)
            out_list = None

        if out_list is not None and len(out_list) == len(self.traces):
            for i, trace in enumerate(self.traces):
                request_plan = request_plans[i]
                burst_phase = getattr(trace, "_burst_phase", "normal")
                row = out_list[i]
                vllm_ttft = row["ttft_ms"]
                tpot = row["tpot_ms"]
                out_tokens = row["output_tokens"]
                cost = _calc_cost(self.cost_model, request_plan.input_tokens, out_tokens)
                result.requests.append(RequestResult(
                    request_id=trace.request_id,
                    adapter_id=None,
                    is_burst=trace.is_burst,
                    burst_phase=burst_phase,
                    cache_hit=False,
                    cache_tier=_BACKBONE_CACHE_TIER,
                    lora_io_ms=0.0,
                    vllm_ttft_ms=vllm_ttft,
                    ttft_ms=vllm_ttft,
                    contention_ms=0.0,
                    defer_ms=0.0,
                    tpot_ms=tpot,
                    e2e_ms=vllm_ttft + (out_tokens - 1) * tpot,
                    input_tokens=request_plan.input_tokens,
                    output_tokens=out_tokens,
                    cost_usd=cost,
                    success=True,
                ))
            elapsed = float(
                inline_stats.get("serving_elapsed_sec")
                or inline_stats.get("total_elapsed_sec")
                or inline_elapsed
            )
        else:
            # Fallback: in-process with truncated prompts
            print("    Running inference in-process with profile-aligned token budgeting.", flush=True)
            t0 = time.perf_counter()
            for i, trace in enumerate(self.traces):
                request_plan = request_plans[i]
                burst_phase = getattr(trace, "_burst_phase", "normal")
                try:
                    output_tokens_hint = max(0, int(request_plan.max_tokens or 0))
                    self.coordinator.notify_batch_start(
                        request_plan.input_tokens,
                        output_tokens_hint,
                    )
                    t_start = time.perf_counter()
                    vllm_ttft, tpot, out_tokens = self.engine._sync_generate_transformers(
                        request_plan.prompt, None, None, request_plan.max_tokens, temperature, top_p,
                    )
                    t_end = time.perf_counter()
                    self.coordinator.notify_batch_end(
                        request_plan.input_tokens,
                        output_tokens_hint,
                    )
                    e2e_ms = (t_end - t_start) * 1000.0
                    cost = _calc_cost(self.cost_model, request_plan.input_tokens, out_tokens)
                    result.requests.append(RequestResult(
                        request_id=trace.request_id,
                        adapter_id=None,
                        is_burst=trace.is_burst,
                        burst_phase=burst_phase,
                        cache_hit=False,
                        cache_tier=_BACKBONE_CACHE_TIER,
                        lora_io_ms=0.0,
                        vllm_ttft_ms=vllm_ttft,
                        ttft_ms=vllm_ttft,
                        contention_ms=0.0,
                        defer_ms=0.0,
                        tpot_ms=tpot,
                        e2e_ms=e2e_ms,
                        input_tokens=request_plan.input_tokens,
                        output_tokens=out_tokens,
                        cost_usd=cost,
                        success=True,
                    ))
                except Exception as exc:
                    result.requests.append(RequestResult(
                        request_id=trace.request_id,
                        adapter_id=None,
                        is_burst=trace.is_burst,
                        burst_phase=burst_phase,
                        cache_hit=False,
                        cache_tier=_BACKBONE_CACHE_TIER,
                        lora_io_ms=0.0,
                        vllm_ttft_ms=0.0,
                        ttft_ms=0.0,
                        contention_ms=0.0,
                        defer_ms=0.0,
                        tpot_ms=0.0,
                        e2e_ms=0.0,
                        input_tokens=request_plan.input_tokens,
                        output_tokens=0,
                        cost_usd=0.0,
                        success=False,
                        error=str(exc),
                    ))
                if (i + 1) % 5 == 0 or (i + 1) == len(self.traces):
                    self._emit_live_snapshot(
                        completed=i + 1,
                        total=len(self.traces),
                        replay_t0=t0,
                        failed=sum(1 for req in result.requests if not getattr(req, "success", True)),
                        force=True,
                        queue_visible_override=i + 1,
                        arrived_override=i + 1,
                        results_view=result.requests,
                        scale_up_count=len(result.scale_up_events),
                        scale_down_count=result.scale_down_events,
                    )
            elapsed = time.perf_counter() - t0

        coord_m = self._current_coord_metrics()
        result.aggregate(elapsed, coord_m)
        self._attach_control_path_background_metrics(result)
        return result, coord_m

