async def main_async(*args, **kwargs):
    """Accept and preserve arrived work while existing startup runs in parallel."""
    if os.environ.get('FAASLORA_TC_EXTERNAL_REPLAY') != '1':
        return await _main_async_impl(*args, **kwargs)
    from scripts.ieee_tc_preflight import verify_current_service
    from faaslora.datasets.workload_generator import FrozenReplayPlan, ExternalReplayIngress
    from faaslora.metrics.metrics_collector import PhysicalGPUDeployment
    identity = verify_current_service()
    receipt_path = Path(os.environ['FAASLORA_TC_LAUNCH_RECEIPT'])
    context = json.loads(receipt_path.read_text())['external_replay']
    if context['tiny_witness']:
        raise ValueError('a tiny replay witness cannot authorize model initialization')
    plan = FrozenReplayPlan.load(context['plan']['source_path'], profile=context['plan']['profile'])
    deployment = PhysicalGPUDeployment(root=receipt_path.parent/'physical_deployment',
        plan=plan, context=context)
    with (receipt_path.parent/'service_ingress.jsonl').open('x') as log:
        def emit(event):
            log.write(json.dumps(event, separators=(',', ':'))+'\n')
            log.flush()
        emit({'event': 'service_ingress_identity', **identity})
        ingress = ExternalReplayIngress(plan, context, emit=emit)
        work = None
        try:
            # Header/clock/input verification completes BEFORE any startup path.
            await ingress.start()
            work = asyncio.create_task(_main_async_impl(*args, **kwargs,
                external_replay=ingress, physical_deployment=deployment))
            await asyncio.wait({work, ingress.background_task}, return_when=asyncio.FIRST_COMPLETED)
            ingress.raise_if_failed()
            result = await work
            ingress.raise_if_failed()
            if not ingress.complete:
                raise RuntimeError('model run ended before complete external offered input')
            return result
        finally:
            if work is not None:
                if not work.done():
                    work.cancel()
                await asyncio.gather(work, return_exceptions=True)
            try:
                await ingress.close()
            finally:
                # Also preserve partial requests and open leases on failure;
                # never derive return from request completion or a vanished slot.
                deployment.finalize()


def main():
    parser = argparse.ArgumentParser(
        description="FaaSLoRA Complete Experiment Runner",
        formatter_class=argparse.RawTextHelpFormatter,
    )
    parser.add_argument("--config", default="configs/experiments.yaml",
                        help="Path to experiment config YAML (default: configs/experiments.yaml)")
    parser.add_argument("--quick", action="store_true",
                        help="Quick mode: run only 30 requests for fast validation")
    parser.add_argument("--scenario", default=None,
                        help="Run a single scenario only, e.g. faaslora_full")
    parser.add_argument("--num-adapters", type=int, default=None,
                        help="Override adapter scale for this run (e.g. 100, 300, 1000)")
    parser.add_argument("--preset", default=None,
                        help="Run a named matrix preset from config, e.g. auto100 or shared300")
    parser.add_argument("--model-profile", default=None,
                        help="Override selected model profile from config, e.g. qwen_14b_tp2_v2_publicmix")
    parser.add_argument("--dataset-profile", default=None,
                        help="Override selected dataset profile from config, e.g. azure_sharegpt_rep500")
    parser.add_argument("--workload-profile", default=None,
                        help="Override selected workload profile from config, e.g. qwen_14b_tp2_a500_main")
    parser.add_argument("--backend", choices=["vllm", "sglang", "transformers"], default=None,
                        help="Override backend for this run and apply matching backend profile")
    parser.add_argument("--full-stack", action="store_true",
                        help="Use full FaaSLoRA stack (default: on for faaslora_* scenarios)")
    parser.add_argument("--no-full-stack", action="store_true",
                        help="Disable full stack (use legacy preload path for faaslora_*)")
    args = parser.parse_args()

    cfg_path = args.config
    if not Path(cfg_path).is_absolute():
        cfg_path = str(REPO_ROOT / cfg_path)
    if not Path(cfg_path).exists():
        print(f"ERROR: config not found: {cfg_path}")
        sys.exit(1)

    os.chdir(REPO_ROOT)
    use_full_stack = getattr(args, "full_stack", False) or not getattr(args, "no_full_stack", False)
    asyncio.run(
        main_async(
            cfg_path,
            quick=args.quick,
            only_scenario=args.scenario,
            use_full_stack=use_full_stack,
            adapter_count_override=args.num_adapters,
            backend_override=args.backend,
            preset_name=args.preset,
            model_profile_override=args.model_profile,
            dataset_profile_override=args.dataset_profile,
            workload_profile_override=args.workload_profile,
        )
    )


if __name__ == "__main__":
    main()
